import React, { useState, useCallback, useEffect } from 'react';
import type { Session } from '@supabase/supabase-js';
import { InterviewStatus, InterviewConfig, TranscriptionEntry, FeedbackEntry } from './types';
import { supabase } from './services/supabaseClient';
import WelcomeScreen from './components/WelcomeScreen';
import InterviewScreen from './components/InterviewScreen';
import EndScreen from './components/EndScreen';
import AuthScreen from './components/AuthScreen';
import ProfileScreen from './components/ProfileScreen';

const App: React.FC = () => {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [interviewStatus, setInterviewStatus] = useState<InterviewStatus>(InterviewStatus.NotStarted);
  const [interviewConfig, setInterviewConfig] = useState<InterviewConfig | null>(null);
  const [isPracticeMode, setIsPracticeMode] = useState(false);
  const [finalTranscription, setFinalTranscription] = useState<TranscriptionEntry[]>([]);
  const [finalFeedback, setFinalFeedback] = useState<FeedbackEntry[]>([]);
  const [currentView, setCurrentView] = useState<'interview' | 'profile'>('interview');

  useEffect(() => {
    if (!supabase) {
      console.warn("Supabase client not initialized.");
      setLoading(false);
      return;
    }

    setLoading(true);
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setLoading(false);
    }).catch(err => {
      console.error("Error getting session:", err);
      setLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (_event === 'SIGNED_OUT') {
        // Reset app state on logout
        setInterviewStatus(InterviewStatus.NotStarted);
        setInterviewConfig(null);
        setFinalTranscription([]);
        setFinalFeedback([]);
        setCurrentView('interview');
      }
    });

    return () => subscription.unsubscribe();
  }, []);


  const handleStartInterview = useCallback((selectedConfig: InterviewConfig, practiceMode: boolean) => {
    setInterviewConfig(selectedConfig);
    setIsPracticeMode(practiceMode);
    setInterviewStatus(InterviewStatus.InProgress);
  }, []);

  const handleEndInterview = useCallback((transcription: TranscriptionEntry[], feedback: FeedbackEntry[]) => {
    if (isPracticeMode) {
      setInterviewStatus(InterviewStatus.NotStarted);
      setInterviewConfig(null);
    } else {
      setFinalTranscription(transcription);
      setFinalFeedback(feedback);
      setInterviewStatus(InterviewStatus.Finished);
    }
  }, [isPracticeMode]);

  const handleRestart = useCallback(() => {
    setInterviewStatus(InterviewStatus.NotStarted);
    setInterviewConfig(null);
    setFinalTranscription([]);
    setFinalFeedback([]);
    setIsPracticeMode(false);
    setCurrentView('interview');
  }, []);

  const handleLogout = async () => {
    if (supabase) {
      await supabase.auth.signOut();
    }
  };

  const renderContent = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-brand-blue"></div>
          <p className="mt-4 text-lg">Loading...</p>
        </div>
      );
    }

    if (!session) {
      return <AuthScreen />;
    }

    if (currentView === 'profile') {
      return <ProfileScreen session={session} onBack={() => setCurrentView('interview')} />;
    }

    switch (interviewStatus) {
      case InterviewStatus.InProgress:
        // Safely check if interviewConfig is present before rendering
        if (!interviewConfig) return <WelcomeScreen onStart={handleStartInterview} />;
        return <InterviewScreen onEnd={handleEndInterview} config={interviewConfig} isPracticeMode={isPracticeMode} />;
      case InterviewStatus.Finished:
        // Safely check if interviewConfig is present before rendering
        if (!interviewConfig) return <WelcomeScreen onStart={handleStartInterview} />;
        return <EndScreen onRestart={handleRestart} transcription={finalTranscription} feedback={finalFeedback} config={interviewConfig} userEmail={session.user.email || ''} />;
      case InterviewStatus.NotStarted:
      default:
        return <WelcomeScreen onStart={handleStartInterview} />;
    }
  };

  return (
    <div className="min-h-screen bg-dark-bg flex flex-col items-center justify-center p-4">
       <header className="w-full max-w-6xl p-4 flex justify-between items-center">
        <div className="text-left">
            <h1 className="text-3xl md:text-4xl font-bold text-white flex items-center justify-center gap-3">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-brand-blue" viewBox="0 0 24 24" fill="currentColor">
                <path d="M19 9l1.25-2.75L23 5l-2.75-1.25L19 1l-1.25 2.75L15 5l2.75 1.25L19 9zm-7.5 2.5L9 4 6.5 11.5 0 14l6.5 2.5L9 24l2.5-7.5L18 14l-6.5-2.5z"/>
            </svg>
            prepareAI
            </h1>
            <p className="text-gray-400 mt-1">Powered by DevJs</p>
        </div>
        {session && (
          <div className="text-right">
            <p className="text-gray-300 text-sm truncate max-w-[200px] md:max-w-xs">{session.user.email}</p>
            <div className="flex gap-4 justify-end items-center">
                <button onClick={() => setCurrentView('profile')} className="text-brand-blue hover:underline font-semibold text-sm">
                    Profile
                </button>
                <button onClick={handleLogout} className="text-brand-red hover:underline font-semibold text-sm">
                  Log out
                </button>
            </div>
          </div>
        )}
      </header>
      <main className="w-full flex-grow flex items-center justify-center">
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from 'https://esm.sh/@google/genai@0.2.1'
import { corsHeaders } from '../_shared/cors.ts'

// In a real monorepo, these interfaces would be in a shared package.
interface TranscriptionEntry {
  speaker: 'user' | 'ai';
  text: string;
}

interface FeedbackEntry {
  userText: string;
  feedbackText: string;
}

interface InterviewConfig {
  name: string;
  description: string;
  systemInstruction: string;
}

interface InterviewReport {
  overallSummary: string;
  keyStrengths: string[];
  areasForImprovement: string[];
  actionableAdvice: string[];
  skillRatings: {
    skillName: string;
    rating: number;
    justification: string;
  }[];
}

interface SuggestedResource {
    title: string;
    uri: string;
}

// Access Deno global with type assertion to avoid TS errors in environments where Deno types are not fully configured.
const deno = Deno as any;

deno.serve(async (req: Request) => {
  // Handle CORS preflight requests
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const { transcription, feedback, config } = await req.json() as {
      transcription: TranscriptionEntry[];
      feedback: FeedbackEntry[];
      config: InterviewConfig;
    };

    // Initialize AI client with environment variable.
    // This must be set in your Supabase project's Function settings.
    const apiKey = deno.env.get('GEMINI_API_KEY');
    if (!apiKey) {
      throw new Error("GEMINI_API_KEY is not set in environment variables.");
    }
    const ai = new GoogleGenAI({ apiKey });
    const model = 'gemini-3-pro-preview';

    // 1. Generate the main report
    const transcriptText = transcription.map(e => `${e.speaker.toUpperCase()}: ${e.text}`).join('\n');
    const feedbackText = feedback.map(f => `On the answer "${f.userText}", the feedback was: "${f.feedbackText}"`).join('\n');

    const summaryPrompt = `You are an expert career coach providing feedback for a job interview simulation. The user was interviewed for the role of: ${config.name}. Here is the full transcript:\n${transcriptText}\n\nHere is the turn-by-turn feedback provided:\n${feedbackText}\n\nBased on all of this information, provide a comprehensive performance review as a JSON object. Analyze the candidate's performance and provide ratings for their skills. Include 'Communication' and 3 other skills relevant to the role: ${config.name}.`;

    const schema = {
        type: Type.OBJECT,
        properties: {
          overallSummary: { type: Type.STRING, description: "A brief, high-level overview of the candidate's performance." },
          keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING }, description: "An array of 2-3 specific strengths the candidate demonstrated." },
          areasForImprovement: { type: Type.ARRAY, items: { type: Type.STRING }, description: "An array of 2-3 specific areas where the candidate could improve." },
          actionableAdvice: { type: Type.ARRAY, items: { type: Type.STRING }, description: "An array of concrete, actionable steps the candidate can take to improve." },
          skillRatings: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                skillName: { type: Type.STRING, description: "Name of the skill assessed." },
                rating: { type: Type.INTEGER, description: "A numerical rating from 1 to 10." },
                justification: { type: Type.STRING, description: "A brief sentence justifying the rating." },
              },
              required: ['skillName', 'rating', 'justification'],
            },
            description: "An array of skill assessments."
          }
        },
        required: ['overallSummary', 'keyStrengths', 'areasForImprovement', 'actionableAdvice', 'skillRatings']
    };

    const summaryResult = await ai.models.generateContent({
      model,
      contents: summaryPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
      },
    });

    const reportData: InterviewReport = JSON.parse(summaryResult.text.trim());

    // 2. Generate suggested resources
    const resourcesPrompt = `Based on the following interview performance review, find 3 relevant and recent online articles or resources to help the candidate improve. Focus on their "Areas for Improvement".

    Areas for Improvement:
    - ${reportData.areasForImprovement.join('\n- ')}

    Actionable Advice:
    - ${reportData.actionableAdvice.join('\n- ')}`;

    const resourcesResult = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: resourcesPrompt,
      config: {
        tools: [{googleSearch: {}}],
      },
    });

    const groundingChunks = resourcesResult.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const fetchedResources: SuggestedResource[] = groundingChunks
      .map((chunk: any) => chunk.web)
      .filter((web: any) => web && web.uri && web.title)
      .slice(0, 3)
      .map((web: any) => ({ uri: web.uri, title: web.title }));

    // 3. Return the generated data to the client
    return new Response(JSON.stringify({ report: reportData, resources: fetchedResources }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 200,
    });

  } catch (error: any) {
    console.error(error);
    return new Response(JSON.stringify({ error: error.message }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 500,
    });
  }
})

