import React, { useEffect, useState } from 'react';
import { GoogleGenAI, Type } from '@google/genai';
import { supabase } from '../services/supabaseClient';
import type { TranscriptionEntry, FeedbackEntry, InterviewConfig, SuggestedResource, InterviewReport } from '../types';

interface EndScreenProps {
  onRestart: () => void;
  transcription: TranscriptionEntry[];
  feedback: FeedbackEntry[];
  config: InterviewConfig;
  userEmail: string;
}

const LANGUAGES = [
  "English", "Spanish", "French", "German", "Chinese (Simplified)", 
  "Japanese", "Korean", "Hindi", "Portuguese", "Russian", "Arabic", "Italian", "Dutch", "Turkish", "Polish"
];

interface UiLabels {
  performanceDashboard: string;
  overallSummary: string;
  keyStrengths: string;
  areasForImprovement: string;
  actionableAdvice: string;
  learningResources: string;
  tryAnotherInterview: string;
  reportReady: string;
  reportReadySubtext: string;
  generatedFor: string;
}

const DEFAULT_LABELS: UiLabels = {
  performanceDashboard: "Performance Dashboard",
  overallSummary: "Overall Summary",
  keyStrengths: "Key Strengths",
  areasForImprovement: "Areas for Improvement",
  actionableAdvice: "Actionable Advice",
  learningResources: "Learning Resources",
  tryAnotherInterview: "Try Another Interview",
  reportReady: "Report Ready!",
  reportReadySubtext: "Here is your personalized feedback and performance analysis.",
  generatedFor: "Interview Report for",
};

const SkillMeter: React.FC<{ skill: string; rating: number; justification: string }> = ({ skill, rating, justification }) => {
  const percentage = Math.max(rating * 10, 5); // Ensure a minimum width for visibility
  let color = 'bg-brand-red';
  if (rating > 4) color = 'bg-brand-yellow';
  if (rating > 7) color = 'bg-brand-green';

  return (
    <div className="group" title={justification}>
      <div className="flex justify-between items-center mb-1">
        <p className="font-semibold text-gray-200">{skill}</p>
        <p className={`font-bold text-lg text-white`}>{rating}/10</p>
      </div>
      <div className="w-full bg-gray-700 rounded-full h-2.5">
        <div className={`${color} h-2.5 rounded-full transition-all duration-500 ease-out`} style={{ width: `${percentage}%` }}></div>
      </div>
      <p className="text-xs text-gray-400 mt-1 italic opacity-0 group-hover:opacity-100 transition-opacity truncate">{justification}</p>
    </div>
  );
};

const FeedbackCard: React.FC<{ title: string; items: string[]; icon: React.ReactNode; color: 'green' | 'yellow' | 'blue'}> = ({title, items, icon, color}) => {
  const colorClasses = {
    green: 'border-brand-green text-brand-green',
    yellow: 'border-brand-yellow text-brand-yellow',
    blue: 'border-brand-blue text-brand-blue',
  };
  return (
    <div className="bg-black/20 p-4 rounded-lg h-full">
      <div className={`flex items-center gap-3 mb-3 border-b-2 pb-2 ${colorClasses[color]}`}>
        {icon}
        <h4 className="text-lg font-semibold">{title}</h4>
      </div>
      <ul className="space-y-2 list-disc list-inside text-gray-300 text-sm">
        {items.map((item, i) => <li key={i}>{item}</li>)}
      </ul>
    </div>
  );
};

const EndScreen: React.FC<EndScreenProps> = ({ onRestart, transcription, feedback, config, userEmail }) => {
  const [report, setReport] = useState<InterviewReport | null>(null);
  const [resources, setResources] = useState<SuggestedResource[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Translation State
  const [currentLanguage, setCurrentLanguage] = useState("English");
  const [translations, setTranslations] = useState<Record<string, { report: InterviewReport; labels: UiLabels }>>({});
  const [isTranslating, setIsTranslating] = useState(false);

  useEffect(() => {
    const generateAndSaveReport = async () => {
      try {
        if (!process.env.API_KEY) {
            throw new Error("API_KEY is not configured.");
        }
        if (!userEmail) {
            throw new Error("User email is not available.");
        }

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // Step 1: Generate the main report
        const transcriptText = transcription.map(e => `${e.speaker.toUpperCase()}: ${e.text}`).join('\n');
        const feedbackText = feedback.map(f => `On the answer "${f.userText}", the feedback was: "${f.feedbackText}"`).join('\n');
        const summaryPrompt = `You are an expert career coach providing feedback for a job interview simulation. The user was interviewed for the role of: ${config.name}. Here is the full transcript:\n${transcriptText}\n\nHere is the turn-by-turn feedback provided:\n${feedbackText}\n\nBased on all of this information, provide a comprehensive performance review as a JSON object. Analyze the candidate's performance and provide ratings for their skills. Include 'Communication' and 3 other skills relevant to the role: ${config.name}.`;

        const schema = {
            type: Type.OBJECT,
            properties: {
                overallSummary: { type: Type.STRING, description: "A brief, high-level overview of the candidate's performance." },
                keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING }, description: "An array of 2-3 specific strengths the candidate demonstrated." },
                areasForImprovement: { type: Type.ARRAY, items: { type: Type.STRING }, description: "An array of 2-3 specific areas where the candidate could improve." },
                actionableAdvice: { type: Type.ARRAY, items: { type: Type.STRING }, description: "An array of concrete, actionable steps the candidate can take to improve." },
                skillRatings: {
                    type: Type.ARRAY,
                    description: "An array of skill assessments.",
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            skillName: { type: Type.STRING, description: "Name of the skill assessed." },
                            rating: { type: Type.INTEGER, description: "A numerical rating from 1 to 10." },
                            justification: { type: Type.STRING, description: "A brief sentence justifying the rating." },
                        },
                        required: ['skillName', 'rating', 'justification'],
                    },
                }
            },
            required: ['overallSummary', 'keyStrengths', 'areasForImprovement', 'actionableAdvice', 'skillRatings']
        };

        const summaryResult = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: summaryPrompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: schema,
            },
        });

        const receivedReport: InterviewReport = JSON.parse(summaryResult.text.trim());

        // Step 2: Generate suggested resources
        const resourcesPrompt = `Based on the following interview performance review, find 3 relevant and recent online articles or resources to help the candidate improve. Focus on their "Areas for Improvement".

        Areas for Improvement:
        - ${receivedReport.areasForImprovement.join('\n- ')}

        Actionable Advice:
        - ${receivedReport.actionableAdvice.join('\n- ')}`;

        const resourcesResult = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: resourcesPrompt,
            config: {
                tools: [{googleSearch: {}}],
            },
        });

        const groundingChunks = resourcesResult.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
        const receivedResources: SuggestedResource[] = groundingChunks
            .map((chunk: any) => chunk.web)
            .filter((web: any) => web && web.uri && web.title)
            .slice(0, 3)
            .map((web: any) => ({ uri: web.uri, title: web.title }));

        // The report is now ready to be displayed
        setReport(receivedReport);
        setResources(receivedResources);

        // Step 3: Save the complete interview record to the database.
        if (supabase) {
            const { error: saveError } = await supabase.from('interviews').insert([
                {
                    user_email: userEmail,
                    config: config,
                    transcription: transcription,
                    feedback: feedback,
                    report: receivedReport,
                    resources: receivedResources,
                }
            ]);

            if (saveError) {
                // Log this error for debugging, but don't show it to the user
                // as they have already received their report successfully.
                console.error("Error saving interview to database:", saveError);
            }
        }

      } catch (err) {
        console.error("Error generating report:", err);
        const errorMessage = err instanceof Error ? err.message : "An unknown error occurred.";
        setError(`Sorry, we couldn't generate your interview report. Error: ${errorMessage}`);
      } finally {
        setIsLoading(false);
      }
    };

    if (transcription.length > 0) {
        generateAndSaveReport();
    } else {
        setError("No interview data was recorded, a report cannot be generated.");
        setIsLoading(false);
    }
  }, [transcription, feedback, config, userEmail]);

  const handleLanguageChange = async (e: React.ChangeEvent<HTMLSelectElement>) => {
    const targetLang = e.target.value;
    if (targetLang === currentLanguage) return;

    setCurrentLanguage(targetLang);

    if (targetLang === "English") return;
    if (translations[targetLang]) return; // Already cached

    if (!report) return;

    setIsTranslating(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `You are a professional translator.
Translate the following interview report content into ${targetLang}.
Also translate the UI labels provided below into ${targetLang}.

Input Data:
${JSON.stringify({
  report: report,
  uiLabels: DEFAULT_LABELS
})}

Response must be a valid JSON object with the same structure: { report: ..., uiLabels: ... }.
Do not translate the 'skillName' if it is a standard technical term (like 'React', 'Java'), but translate generic skills (like 'Communication').
`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: { responseMimeType: 'application/json' }
        });

        const translatedData = JSON.parse(response.text);
        setTranslations(prev => ({
            ...prev,
            [targetLang]: translatedData
        }));

    } catch (err) {
        console.error("Translation failed:", err);
        // If translation fails, we might want to alert the user or fallback silently.
        // For now, staying on the selected language but showing English data is a fallback, 
        // but let's reset to English to indicate failure visually or handle it in UI.
        alert("Failed to translate report. Please try again.");
        setCurrentLanguage("English");
    } finally {
        setIsTranslating(false);
    }
  };

  const activeReport = currentLanguage === "English" ? report : (translations[currentLanguage]?.report || report);
  const activeLabels = currentLanguage === "English" ? DEFAULT_LABELS : (translations[currentLanguage]?.labels || DEFAULT_LABELS);

  return (
    <div className="w-full max-w-6xl bg-light-bg rounded-lg shadow-xl p-8 flex flex-col">
      {report && (
        <div className="mb-6 flex justify-end">
             <div className="flex items-center gap-2">
                <label htmlFor="language-select" className="text-sm text-gray-400">Translate to:</label>
                <select
                    id="language-select"
                    value={currentLanguage}
                    onChange={handleLanguageChange}
                    disabled={isTranslating}
                    className="bg-gray-700 text-white text-sm rounded-lg p-2 focus:ring-2 focus:ring-brand-blue outline-none border border-gray-600 disabled:opacity-50"
                >
                    {LANGUAGES.map(lang => (
                        <option key={lang} value={lang}>{lang}</option>
                    ))}
                </select>
                {isTranslating && <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>}
            </div>
        </div>
      )}

      {activeLabels && (
          <div className="mb-6 bg-brand-green/20 border border-brand-green text-center p-4 rounded-lg">
            <p className="font-semibold text-lg">{activeLabels.reportReady}</p>
            <p className="text-gray-300">{activeLabels.reportReadySubtext}</p>
          </div>
      )}

      <h2 className="text-3xl font-bold mb-6 text-center">{activeLabels.generatedFor} {config.name}</h2>

      {isLoading && (
        <div className="flex flex-col items-center justify-center text-center py-10">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-brand-blue"></div>
          <p className="mt-4 text-lg">Generating your personalized feedback dashboard...</p>
        </div>
      )}

      {error && (
        <div className="w-full bg-red-900/50 border border-brand-red rounded-lg p-6 text-center">
          <h3 className="text-xl font-bold mb-2 text-brand-red">Report Generation Failed</h3>
          <p className="text-gray-200">{error}</p>
        </div>
      )}

      {!isLoading && !error && activeReport && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-black/20 p-6 rounded-lg">
                <h3 className="text-2xl font-semibold mb-6 border-b-2 border-brand-blue pb-2">{activeLabels.performanceDashboard}</h3>
                {isTranslating ? (
                    <div className="h-40 flex items-center justify-center">
                        <p className="text-gray-400 animate-pulse">Translating dashboard...</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-6">
                        {activeReport.skillRatings.map((skill) => <SkillMeter key={skill.skillName} skill={skill.skillName} rating={skill.rating} justification={skill.justification} />)}
                    </div>
                )}
            </div>
             <div className="bg-black/20 p-6 rounded-lg">
                <h3 className="text-2xl font-semibold mb-4">{activeLabels.overallSummary}</h3>
                {isTranslating ? <p className="text-gray-400 animate-pulse">Translating...</p> : <p className="text-gray-300 leading-relaxed">{activeReport.overallSummary}</p>}
            </div>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <FeedbackCard title={activeLabels.keyStrengths} items={isTranslating ? ["..."] : activeReport.keyStrengths} color="green" icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 10h4.764a2 2 0 011.789 2.894l-3.5 7A2 2 0 0115.263 21h-4.017c-.163 0-.326-.02-.485-.06L7 18.734V6a2 2 0 012-2h4a2 2 0 012 2v4z" /></svg>} />
                <FeedbackCard title={activeLabels.areasForImprovement} items={isTranslating ? ["..."] : activeReport.areasForImprovement} color="yellow" icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 12a4 4 0 10-8 0 4 4 0 008 0zm0 0v1.5a2.5 2.5 0 005 0V12a9 9 0 10-9 9m4.5-1.206a8.959 8.959 0 01-4.5 1.207" /></svg>} />
                <FeedbackCard title={activeLabels.actionableAdvice} items={isTranslating ? ["..."] : activeReport.actionableAdvice} color="blue" icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" /></svg>} />
            </div>
          </div>
