          overallSummary: { type: Type.STRING, description: "A brief, high-level overview of the candidate's performance." },
          keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING }, description: "An array of 2-3 specific strengths the candidate demonstrated." },
          areasForImprovement: { type: Type.ARRAY, items: { type: Type.STRING }, description: "An array of 2-3 specific areas where the candidate could improve." },
          actionableAdvice: { type: Type.ARRAY, items: { type: Type.STRING }, description: "An array of concrete, actionable steps the candidate can take to improve." },
          skillRatings: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                skillName: { type: Type.STRING, description: "Name of the skill assessed." },
                rating: { type: Type.INTEGER, description: "A numerical rating from 1 to 10." },
                justification: { type: Type.STRING, description: "A brief sentence justifying the rating." },
              },
              required: ['skillName', 'rating', 'justification'],
            },
            description: "An array of skill assessments."
          }
        },
        required: ['overallSummary', 'keyStrengths', 'areasForImprovement', 'actionableAdvice', 'skillRatings']
    };

    const summaryResult = await ai.models.generateContent({
      model,
      contents: summaryPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
      },
    });

    const reportData: InterviewReport = JSON.parse(summaryResult.text.trim());

    // 2. Generate suggested resources
    const resourcesPrompt = `Based on the following interview performance review, find 3 relevant and recent online articles or resources to help the candidate improve. Focus on their "Areas for Improvement".

    Areas for Improvement:
    - ${reportData.areasForImprovement.join('\n- ')}

    Actionable Advice:
    - ${reportData.actionableAdvice.join('\n- ')}`;

    const resourcesResult = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: resourcesPrompt,
      config: {
        tools: [{googleSearch: {}}],
      },
    });

    const groundingChunks = resourcesResult.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const fetchedResources: SuggestedResource[] = groundingChunks
      .map((chunk: any) => chunk.web)
      .filter((web: any) => web && web.uri && web.title)
      .slice(0, 3)
      .map((web: any) => ({ uri: web.uri, title: web.title }));

    // 3. Return the generated data to the client
    return new Response(JSON.stringify({ report: reportData, resources: fetchedResources }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 200,
    });

  } catch (error: any) {
    console.error(error);
    return new Response(JSON.stringify({ error: error.message }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 500,
    });
  }
})

import React, { useEffect, useState } from 'react';
import { GoogleGenAI, Type } from '@google/genai';
import { supabase } from '../services/supabaseClient';
import type { TranscriptionEntry, FeedbackEntry, InterviewConfig, SuggestedResource, InterviewReport } from '../types';

interface EndScreenProps {
  onRestart: () => void;
  transcription: TranscriptionEntry[];
  feedback: FeedbackEntry[];
  config: InterviewConfig;
  userEmail: string;
  userId: string;
}

const LANGUAGES = [
  "English", "Spanish", "French", "German", "Chinese (Simplified)", 
  "Japanese", "Korean", "Hindi", "Portuguese", "Russian", "Arabic", "Italian", "Dutch", "Turkish", "Polish"
];

interface UiLabels {
  performanceDashboard: string;
  overallSummary: string;
  keyStrengths: string;
  areasForImprovement: string;
  actionableAdvice: string;
  learningResources: string;
  tryAnotherInterview: string;
  reportReady: string;
  reportReadySubtext: string;
  generatedFor: string;
}

const DEFAULT_LABELS: UiLabels = {
  performanceDashboard: "Performance Dashboard",
  overallSummary: "Overall Summary",
  keyStrengths: "Key Strengths",
  areasForImprovement: "Areas for Improvement",
  actionableAdvice: "Actionable Advice",
  learningResources: "Learning Resources",
  tryAnotherInterview: "Try Another Interview",
  reportReady: "Report Ready!",
  reportReadySubtext: "Here is your personalized feedback and performance analysis.",
  generatedFor: "Interview Report for",
};

const SkillMeter: React.FC<{ skill: string; rating: number; justification: string }> = ({ skill, rating, justification }) => {
  const percentage = Math.max(rating * 10, 5); // Ensure a minimum width for visibility
  let color = 'bg-brand-red';
  if (rating > 4) color = 'bg-brand-yellow';
  if (rating > 7) color = 'bg-brand-green';

  return (
    <div className="group" title={justification}>
      <div className="flex justify-between items-center mb-1">
        <p className="font-semibold text-gray-200">{skill}</p>
        <p className={`font-bold text-lg text-white`}>{rating}/10</p>
      </div>
      <div className="w-full bg-gray-700 rounded-full h-2.5">
        <div className={`${color} h-2.5 rounded-full transition-all duration-500 ease-out`} style={{ width: `${percentage}%` }}></div>
      </div>
      <p className="text-xs text-gray-400 mt-1 italic opacity-0 group-hover:opacity-100 transition-opacity truncate">{justification}</p>
    </div>
  );
};

const FeedbackCard: React.FC<{ title: string; items: string[]; icon: React.ReactNode; color: 'green' | 'yellow' | 'blue'}> = ({title, items, icon, color}) => {
  const colorClasses = {
    green: 'border-brand-green text-brand-green',
    yellow: 'border-brand-yellow text-brand-yellow',
    blue: 'border-brand-blue text-brand-blue',
  };
  return (
    <div className="bg-black/20 p-4 rounded-lg h-full">
      <div className={`flex items-center gap-3 mb-3 border-b-2 pb-2 ${colorClasses[color]}`}>
        {icon}
        <h4 className="text-lg font-semibold">{title}</h4>
      </div>
      <ul className="space-y-2 list-disc list-inside text-gray-300 text-sm">
        {items.map((item, i) => <li key={i}>{item}</li>)}
      </ul>
    </div>
  );
};

const EndScreen: React.FC<EndScreenProps> = ({ onRestart, transcription, feedback, config, userEmail, userId }) => {
  const [report, setReport] = useState<InterviewReport | null>(null);
  const [resources, setResources] = useState<SuggestedResource[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Translation State
  const [currentLanguage, setCurrentLanguage] = useState("English");
  const [translations, setTranslations] = useState<Record<string, { report: InterviewReport; labels: UiLabels }>>({});
  const [isTranslating, setIsTranslating] = useState(false);

  useEffect(() => {
    const generateAndSaveReport = async () => {
      try {
        if (!process.env.API_KEY) {
            throw new Error("API_KEY is not configured.");
        }
        if (!userId) {
            throw new Error("User ID is not available.");
        }

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // Step 1: Generate the main report
        const transcriptText = transcription.map(e => `${e.speaker.toUpperCase()}: ${e.text}`).join('\n');
        const feedbackText = feedback.map(f => `On the answer "${f.userText}", the feedback was: "${f.feedbackText}"`).join('\n');
        const summaryPrompt = `You are an expert career coach providing feedback for a job interview simulation. The user was interviewed for the role of: ${config.name}. Here is the full transcript:\n${transcriptText}\n\nHere is the turn-by-turn feedback provided:\n${feedbackText}\n\nBased on all of this information, provide a comprehensive performance review as a JSON object. Analyze the candidate's performance and provide ratings for their skills. Include 'Communication' and 3 other skills relevant to the role: ${config.name}.`;

        const schema = {
            type: Type.OBJECT,
            properties: {
                overallSummary: { type: Type.STRING, description: "A brief, high-level overview of the candidate's performance." },
                keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING }, description: "An array of 2-3 specific strengths the candidate demonstrated." },
                areasForImprovement: { type: Type.ARRAY, items: { type: Type.STRING }, description: "An array of 2-3 specific areas where the candidate could improve." },
                actionableAdvice: { type: Type.ARRAY, items: { type: Type.STRING }, description: "An array of concrete, actionable steps the candidate can take to improve." },
                skillRatings: {
                    type: Type.ARRAY,
                    description: "An array of skill assessments.",
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            skillName: { type: Type.STRING, description: "Name of the skill assessed." },
                            rating: { type: Type.INTEGER, description: "A numerical rating from 1 to 10." },
                            justification: { type: Type.STRING, description: "A brief sentence justifying the rating." },
                        },
                        required: ['skillName', 'rating', 'justification'],
                    },
                }
            },
            required: ['overallSummary', 'keyStrengths', 'areasForImprovement', 'actionableAdvice', 'skillRatings']
        };

        const summaryResult = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: summaryPrompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: schema,
            },
        });

        const receivedReport: InterviewReport = JSON.parse(summaryResult.text.trim());

        // Step 2: Generate suggested resources
        const resourcesPrompt = `Based on the following interview performance review, find 3 relevant and recent online articles or resources to help the candidate improve. Focus on their "Areas for Improvement".

        Areas for Improvement:
        - ${receivedReport.areasForImprovement.join('\n- ')}

        Actionable Advice:
        - ${receivedReport.actionableAdvice.join('\n- ')}`;

        const resourcesResult = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: resourcesPrompt,
            config: {
                tools: [{googleSearch: {}}],
            },
        });

        const groundingChunks = resourcesResult.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
        const receivedResources: SuggestedResource[] = groundingChunks
            .map((chunk: any) => chunk.web)
            .filter((web: any) => web && web.uri && web.title)
            .slice(0, 3)
            .map((web: any) => ({ uri: web.uri, title: web.title }));

        // The report is now ready to be displayed
        setReport(receivedReport);
        setResources(receivedResources);

        // Step 3: Save the complete interview record to the database.
        if (supabase) {
            const { error: saveError } = await supabase.from('interviews').insert([
                {
                    user_id: userId,
                    user_email: userEmail,
                    config: config,
                    transcription: transcription,
                    feedback: feedback,
                    report: receivedReport,
                    resources: receivedResources,
                }
            ]);

            if (saveError) {
                // Log this error for debugging, but don't show it to the user
                // as they have already received their report successfully.
                console.error("Error saving interview to database:", saveError);
            }
        }

      } catch (err) {
        console.error("Error generating report:", err);
        const errorMessage = err instanceof Error ? err.message : "An unknown error occurred.";
        setError(`Sorry, we couldn't generate your interview report. Error: ${errorMessage}`);
      } finally {
        setIsLoading(false);
      }
    };

    if (transcription.length > 0) {
        generateAndSaveReport();
    } else {
        setError("No interview data was recorded, a report cannot be generated.");
        setIsLoading(false);
    }
  }, [transcription, feedback, config, userEmail, userId]);

  const handleLanguageChange = async (e: React.ChangeEvent<HTMLSelectElement>) => {
    const targetLang = e.target.value;
    if (targetLang === currentLanguage) return;

    setCurrentLanguage(targetLang);

    if (targetLang === "English") return;
    if (translations[targetLang]) return; // Already cached

    if (!report) return;

    setIsTranslating(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `You are a professional translator.
Translate the following interview report content into ${targetLang}.
Also translate the UI labels provided below into ${targetLang}.

Input Data:
${JSON.stringify({
  report: report,
  uiLabels: DEFAULT_LABELS
})}

Response must be a valid JSON object with the same structure: { report: ..., uiLabels: ... }.
Do not translate the 'skillName' if it is a standard technical term (like 'React', 'Java'), but translate generic skills (like 'Communication').
`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: { responseMimeType: 'application/json' }
        });

        const translatedData = JSON.parse(response.text);
        setTranslations(prev => ({
            ...prev,
            [targetLang]: translatedData
        }));

    } catch (err) {
        console.error("Translation failed:", err);
        // If translation fails, we might want to alert the user or fallback silently.
        // For now, staying on the selected language but showing English data is a fallback, 
        // but let's reset to English to indicate failure visually or handle it in UI.
        alert("Failed to translate report. Please try again.");
        setCurrentLanguage("English");
    } finally {
        setIsTranslating(false);
    }
  };

  const activeReport = currentLanguage === "English" ? report : (translations[currentLanguage]?.report || report);
  const activeLabels = currentLanguage === "English" ? DEFAULT_LABELS : (translations[currentLanguage]?.labels || DEFAULT_LABELS);

  return (
    <div className="w-full max-w-6xl bg-light-bg rounded-lg shadow-xl p-8 flex flex-col">
      {report && (
        <div className="mb-6 flex justify-end">
             <div className="flex items-center gap-2">
                <label htmlFor="language-select" className="text-sm text-gray-400">Translate to:</label>
                <select
                    id="language-select"
                    value={currentLanguage}
                    onChange={handleLanguageChange}
                    disabled={isTranslating}
                    className="bg-gray-700 text-white text-sm rounded-lg p-2 focus:ring-2 focus:ring-brand-blue outline-none border border-gray-600 disabled:opacity-50"
                >
                    {LANGUAGES.map(lang => (
                        <option key={lang} value={lang}>{lang}</option>
                    ))}
                </select>
                {isTranslating && <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>}
            </div>
        </div>
      )}

      {activeLabels && (
          <div className="mb-6 bg-brand-green/20 border border-brand-green text-center p-4 rounded-lg">
            <p className="font-semibold text-lg">{activeLabels.reportReady}</p>
            <p className="text-gray-300">{activeLabels.reportReadySubtext}</p>
          </div>
      )}

      <h2 className="text-3xl font-bold mb-6 text-center">{activeLabels.generatedFor} {config.name}</h2>

      {isLoading && (
        <div className="flex flex-col items-center justify-center text-center py-10">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-brand-blue"></div>
          <p className="mt-4 text-lg">Generating your personalized feedback dashboard...</p>
        </div>
      )}

      {error && (
        <div className="w-full bg-red-900/50 border border-brand-red rounded-lg p-6 text-center">
          <h3 className="text-xl font-bold mb-2 text-brand-red">Report Generation Failed</h3>
          <p className="text-gray-200">{error}</p>
        </div>
      )}

      {!isLoading && !error && activeReport && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-black/20 p-6 rounded-lg">
                <h3 className="text-2xl font-semibold mb-6 border-b-2 border-brand-blue pb-2">{activeLabels.performanceDashboard}</h3>
                {isTranslating ? (
                    <div className="h-40 flex items-center justify-center">
                        <p className="text-gray-400 animate-pulse">Translating dashboard...</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-6">
                        {activeReport.skillRatings.map((skill) => <SkillMeter key={skill.skillName} skill={skill.skillName} rating={skill.rating} justification={skill.justification} />)}
                    </div>
                )}
            </div>
             <div className="bg-black/20 p-6 rounded-lg">
                <h3 className="text-2xl font-semibold mb-4">{activeLabels.overallSummary}</h3>
                {isTranslating ? <p className="text-gray-400 animate-pulse">Translating...</p> : <p className="text-gray-300 leading-relaxed">{activeReport.overallSummary}</p>}
            </div>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <FeedbackCard title={activeLabels.keyStrengths} items={isTranslating ? ["..."] : activeReport.keyStrengths} color="green" icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 10h4.764a2 2 0 011.789 2.894l-3.5 7A2 2 0 0115.263 21h-4.017c-.163 0-.326-.02-.485-.06L7 18.734V6a2 2 0 012-2h4a2 2 0 012 2v4z" /></svg>} />
                <FeedbackCard title={activeLabels.areasForImprovement} items={isTranslating ? ["..."] : activeReport.areasForImprovement} color="yellow" icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 12a4 4 0 10-8 0 4 4 0 008 0zm0 0v1.5a2.5 2.5 0 005 0V12a9 9 0 10-9 9m4.5-1.206a8.959 8.959 0 01-4.5 1.207" /></svg>} />
                <FeedbackCard title={activeLabels.actionableAdvice} items={isTranslating ? ["..."] : activeReport.actionableAdvice} color="blue" icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" /></svg>} />
            </div>
          </div>
          <div className="lg:col-span-1 bg-black/20 p-6 rounded-lg">
            <h3 className="text-2xl font-semibold mb-4 border-b-2 border-brand-green pb-2">{activeLabels.learningResources}</h3>
            {resources.length > 0 ? (
              <ul className="space-y-4">
                {resources.map((res, index) => (
                  <li key={index}>
                    <a href={res.uri} target="_blank" rel="noopener noreferrer" className="text-brand-yellow hover:underline font-semibold block">
                      {res.title}
                    </a>
                    <p className="text-gray-400 text-sm truncate">{res.uri}</p>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-gray-400 italic">No specific resources found, but keep practicing!</p>
            )}
          </div>
        </div>
      )}

      <div className="mt-8 text-center">
        <button
          onClick={onRestart}
          className="bg-brand-green hover:bg-green-600 text-white font-bold py-3 px-8 rounded-lg transition-transform transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-green-500/50"
        >
          {activeLabels.tryAnotherInterview}
        </button>
      </div>
    </div>
  );
};

export default EndScreen;

import React, { useState, useCallback, useEffect } from 'react';
import type { Session } from '@supabase/supabase-js';
import { InterviewStatus, InterviewConfig, TranscriptionEntry, FeedbackEntry } from './types';
import { supabase } from './services/supabaseClient';
import WelcomeScreen from './components/WelcomeScreen';
import InterviewScreen from './components/InterviewScreen';
import EndScreen from './components/EndScreen';
import AuthScreen from './components/AuthScreen';
import ProfileScreen from './components/ProfileScreen';

const App: React.FC = () => {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [interviewStatus, setInterviewStatus] = useState<InterviewStatus>(InterviewStatus.NotStarted);
  const [interviewConfig, setInterviewConfig] = useState<InterviewConfig | null>(null);
  const [isPracticeMode, setIsPracticeMode] = useState(false);
  const [finalTranscription, setFinalTranscription] = useState<TranscriptionEntry[]>([]);
  const [finalFeedback, setFinalFeedback] = useState<FeedbackEntry[]>([]);
  const [currentView, setCurrentView] = useState<'interview' | 'profile'>('interview');

  useEffect(() => {
    if (!supabase) {
      console.warn("Supabase client not initialized.");
      setLoading(false);
      return;
    }

    setLoading(true);
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setLoading(false);
    }).catch(err => {
      console.error("Error getting session:", err);
      setLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (_event === 'SIGNED_OUT') {
        // Reset app state on logout
        setInterviewStatus(InterviewStatus.NotStarted);
        setInterviewConfig(null);
        setFinalTranscription([]);
        setFinalFeedback([]);
        setCurrentView('interview');
      }
    });

    return () => subscription.unsubscribe();
  }, []);


  const handleStartInterview = useCallback((selectedConfig: InterviewConfig, practiceMode: boolean) => {
    setInterviewConfig(selectedConfig);
    setIsPracticeMode(practiceMode);
    setInterviewStatus(InterviewStatus.InProgress);
  }, []);

  const handleEndInterview = useCallback((transcription: TranscriptionEntry[], feedback: FeedbackEntry[]) => {
    if (isPracticeMode) {
      setInterviewStatus(InterviewStatus.NotStarted);
      setInterviewConfig(null);
    } else {
      setFinalTranscription(transcription);
      setFinalFeedback(feedback);
      setInterviewStatus(InterviewStatus.Finished);
    }
  }, [isPracticeMode]);

  const handleRestart = useCallback(() => {
    setInterviewStatus(InterviewStatus.NotStarted);
    setInterviewConfig(null);
    setFinalTranscription([]);
    setFinalFeedback([]);
    setIsPracticeMode(false);
    setCurrentView('interview');
  }, []);

  const handleLogout = async () => {
    if (supabase) {
      await supabase.auth.signOut();
    }
  };

  const renderContent = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-brand-blue"></div>
          <p className="mt-4 text-lg">Loading...</p>
        </div>
      );
    }

    if (!session) {
      return <AuthScreen />;
    }

    if (currentView === 'profile') {
      return <ProfileScreen session={session} onBack={() => setCurrentView('interview')} />;
    }

    switch (interviewStatus) {
      case InterviewStatus.InProgress:
        // Safely check if interviewConfig is present before rendering
        if (!interviewConfig) return <WelcomeScreen onStart={handleStartInterview} />;
        return <InterviewScreen onEnd={handleEndInterview} config={interviewConfig} isPracticeMode={isPracticeMode} />;
      case InterviewStatus.Finished:
        // Safely check if interviewConfig is present before rendering
        if (!interviewConfig) return <WelcomeScreen onStart={handleStartInterview} />;
        return <EndScreen 
          onRestart={handleRestart} 
          transcription={finalTranscription} 
          feedback={finalFeedback} 
          config={interviewConfig} 
          userEmail={session.user.email || ''} 
          userId={session.user.id}
        />;
      case InterviewStatus.NotStarted:
      default:
        return <WelcomeScreen onStart={handleStartInterview} />;
    }
  };

  return (
    <div className="min-h-screen bg-dark-bg flex flex-col items-center justify-center p-4">
       <header className="w-full max-w-6xl p-4 flex justify-between items-center">
        <div className="text-left">
            <h1 className="text-3xl md:text-4xl font-bold text-white flex items-center justify-center gap-3">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-brand-blue" viewBox="0 0 24 24" fill="currentColor">
                <path d="M19 9l1.25-2.75L23 5l-2.75-1.25L19 1l-1.25 2.75L15 5l2.75 1.25L19 9zm-7.5 2.5L9 4 6.5 11.5 0 14l6.5 2.5L9 24l2.5-7.5L18 14l-6.5-2.5z"/>
            </svg>
            prepareAI
            </h1>
            <p className="text-gray-400 mt-1">Powered by DevJs</p>
        </div>
        {session && (
          <div className="text-right">
            <p className="text-gray-300 text-sm truncate max-w-[200px] md:max-w-xs">{session.user.email}</p>
            <div className="flex gap-4 justify-end items-center">
                <button onClick={() => setCurrentView('profile')} className="text-brand-blue hover:underline font-semibold text-sm">
                    Profile
                </button>
                <button onClick={handleLogout} className="text-brand-red hover:underline font-semibold text-sm">
                  Log out
                </button>
            </div>
          </div>
        )}
      </header>
      <main className="w-full flex-grow flex items-center justify-center">
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import type { Session } from '@supabase/supabase-js';
import { supabase } from '../services/supabaseClient';
import type { InterviewConfig } from '../types';

interface Profile {
  full_name: string;
  pronouns: string;
}

interface InterviewHistoryItem {
  id: string;
  created_at: string;
  config: InterviewConfig;
}

interface ProfileScreenProps {
  session: Session;
  onBack: () => void;
}

const ProfileScreen: React.FC<ProfileScreenProps> = ({ session, onBack }) => {
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<Profile>({ full_name: '', pronouns: '' });
  const [interviews, setInterviews] = useState<InterviewHistoryItem[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchProfileData = useCallback(async () => {
    if (!supabase || !session.user) return;
    try {
      setLoading(true);
      setError(null);

      // Fetch profile
      const { data: profileData, error: profileError } = await supabase
        .from('profiles')
        .select('full_name, pronouns')
        .eq('id', session.user.id)
        .single();

      if (profileError) {
        // PGRST116: JSON object requested, multiple (or no) rows returned.
        // 42P01: undefined_table (table does not exist)
        if (profileError.code !== 'PGRST116' && profileError.code !== '42P01') {
            throw profileError;
        }
        if (profileError.code === '42P01') {
            console.warn("Profiles table not found in Supabase. Profile features limited.");
        }
      }

      if (profileData) {
        setProfile({
            full_name: profileData.full_name || '',
            pronouns: profileData.pronouns || ''
        });
      }

      // Fetch interview history
      const { data: interviewData, error: interviewError } = await supabase
        .from('interviews')
        .select('id, created_at, config')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false })
        .limit(10);

      if (interviewError) {
        if (interviewError.code !== '42P01') {
            throw interviewError;
        }
        console.warn("Interviews table not found in Supabase. History unavailable.");
      }

      setInterviews(interviewData || []);

    } catch (err: any) {
      console.error("Error fetching profile data:", err);
      setError(err.message || 'Failed to fetch data.');
    } finally {
      setLoading(false);
    }
  }, [session.user]);

  useEffect(() => {
    fetchProfileData();
  }, [fetchProfileData]);

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase || !session.user) return;
    try {
      setLoading(true);
      const { error } = await supabase.from('profiles').upsert({
        id: session.user.id,
        full_name: profile.full_name,
        pronouns: profile.pronouns,
        updated_at: new Date().toISOString(),
      });
      if (error) throw error;
      setIsEditing(false);
    } catch (err: any) {
      if (err.code === '42P01') {
          setError('Profile saving is currently unavailable (Database table missing).');
      } else {
          setError(err.message || 'Failed to update profile.');
      }
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center text-center">
        <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-brand-blue"></div>
        <p className="mt-4 text-lg">Loading Profile...</p>
      </div>
    );
  }

  return (
    <div className="w-full max-w-4xl bg-light-bg rounded-lg shadow-xl p-8">
       <div className="flex justify-between items-center mb-6 border-b border-gray-700 pb-4">
        <h2 className="text-3xl font-bold">Your Profile</h2>
        <button onClick={onBack} className="text-brand-blue hover:underline font-semibold">
          &larr; Back to Interview
        </button>
      </div>

      {error && (
        <div className="w-full bg-red-900/50 border border-brand-red rounded-lg p-4 text-center mb-6">
          <p className="text-gray-200">{error}</p>
        </div>
      )}

      {/* Profile Details */}
      <div className="bg-black/20 p-6 rounded-lg mb-8">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-2xl font-semibold">Profile Details</h3>
          {!isEditing && (
            <button onClick={() => setIsEditing(true)} className="bg-gray-600 hover:bg-gray-500 text-white font-bold py-2 px-4 rounded-lg text-sm">
              Edit Profile
            </button>
          )}
        </div>
        {isEditing ? (
          <form onSubmit={handleUpdateProfile} className="space-y-4">
            <div>
              <label htmlFor="full_name" className="block text-sm font-medium text-gray-300 mb-1">Full Name</label>
              <input
                id="full_name"
                type="text"
                value={profile.full_name}
                onChange={(e) => setProfile({ ...profile, full_name: e.target.value })}
                className="w-full bg-gray-700 text-white px-4 py-2 rounded-lg border border-gray-600 focus:outline-none focus:ring-2 focus:ring-brand-blue"
              />
            </div>
            <div>
              <label htmlFor="pronouns" className="block text-sm font-medium text-gray-300 mb-1">Pronouns</label>
              <input
                id="pronouns"
                type="text"
                value={profile.pronouns}
                onChange={(e) => setProfile({ ...profile, pronouns: e.target.value })}
                placeholder="e.g., she/her, he/him, they/them"
                className="w-full bg-gray-700 text-white px-4 py-2 rounded-lg border border-gray-600 focus:outline-none focus:ring-2 focus:ring-brand-blue"
              />
            </div>
            <div className="flex gap-4">
              <button type="submit" className="bg-brand-green hover:bg-green-600 text-white font-bold py-2 px-6 rounded-lg">
                Save Changes
              </button>
              <button type="button" onClick={() => setIsEditing(false)} className="bg-gray-700 hover:bg-gray-600 text-white font-bold py-2 px-4 rounded-lg">
                Cancel
              </button>
            </div>
          </form>
        ) : (
          <div className="space-y-3">
            <p><span className="font-semibold text-gray-400">Email:</span> {session.user.email}</p>
            <p><span className="font-semibold text-gray-400">Full Name:</span> {profile.full_name || <span className="italic text-gray-500">Not set</span>}</p>
            <p><span className="font-semibold text-gray-400">Pronouns:</span> {profile.pronouns || <span className="italic text-gray-500">Not set</span>}</p>
          </div>
        )}
      </div>

      {/* Interview History */}
      <div className="bg-black/20 p-6 rounded-lg">
         <h3 className="text-2xl font-semibold mb-4">Interview History</h3>
         <div className="space-y-4 max-h-96 overflow-y-auto">
            {interviews.length > 0 ? (
                interviews.map(interview => (
                    <div key={interview.id} className="bg-gray-700 p-4 rounded-lg flex justify-between items-center">
                        <div>
                            <p className="font-bold text-white">{interview.config.name}</p>
                            <p className="text-sm text-gray-400">
                                {new Date(interview.created_at).toLocaleString()}
                            </p>
                        </div>
                        <button className="text-brand-yellow hover:underline text-sm font-semibold cursor-not-allowed opacity-50" title="Feature coming soon">
                            View Report
                        </button>
                    </div>
                ))
            ) : (
                <p className="text-gray-400 italic text-center py-4">No past interviews found.</p>
            )}
         </div>
      </div>
    </div>
  );
};

export default ProfileScreen;

