export default ProfileScreen;

import React, { useState, useEffect, useCallback } from 'react';
import type { Session } from '@supabase/supabase-js';
import { supabase } from '../services/supabaseClient';
import type { InterviewConfig } from '../types';

interface Profile {
  full_name: string;
  pronouns: string;
}

interface InterviewHistoryItem {
  id: string;
  created_at: string;
  config: InterviewConfig;
}

interface ProfileScreenProps {
  session: Session;
  onBack: () => void;
}

const ProfileScreen: React.FC<ProfileScreenProps> = ({ session, onBack }) => {
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<Profile>({ full_name: '', pronouns: '' });
  const [interviews, setInterviews] = useState<InterviewHistoryItem[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchProfileData = useCallback(async () => {
    if (!supabase || !session.user) return;
    try {
      setLoading(true);
      setError(null);

      // Fetch profile
      const { data: profileData, error: profileError } = await supabase
        .from('profiles')
        .select('full_name, pronouns')
        .eq('id', session.user.id)
        .single();

      if (profileError) {
        // PGRST116: JSON object requested, multiple (or no) rows returned. (No profile found)
        // 42P01: undefined_table (table does not exist)
        if (profileError.code === '42P01' || (profileError.message && profileError.message.includes('profiles'))) {
             throw new Error("Missing Database Table");
        }

        if (profileError.code !== 'PGRST116') {
            throw profileError;
        }
      }

      if (profileData) {
        setProfile({
            full_name: profileData.full_name || '',
            pronouns: profileData.pronouns || ''
        });
      }

      // Fetch interview history
      const { data: interviewData, error: interviewError } = await supabase
        .from('interviews')
        .select('id, created_at, config')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false })
        .limit(10);

      if (interviewError) {
        if (interviewError.code === '42P01') {
             console.warn("Interviews table missing.");
             // If profiles was fine but interviews is missing, we still want to alert the user essentially
             throw new Error("Missing Database Table");
        } else {
             throw interviewError;
        }
      }

      setInterviews(interviewData || []);

    } catch (err: any) {
      console.error("Error fetching profile data:", err);
      if (err.message === "Missing Database Table" || (err.message && (err.message.includes('schema cache') || err.message.includes('profiles') || err.message.includes('interviews')))) {
          setError("Database Setup Required");
      } else {
          setError(err.message || 'Failed to fetch data.');
      }
    } finally {
      setLoading(false);
    }
  }, [session.user]);

  useEffect(() => {
    fetchProfileData();
  }, [fetchProfileData]);

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase || !session.user) return;
    try {
      setLoading(true);
      const { error } = await supabase.from('profiles').upsert({
        id: session.user.id,
        full_name: profile.full_name,
        pronouns: profile.pronouns,
        updated_at: new Date().toISOString(),
      });
      if (error) throw error;
      setIsEditing(false);
    } catch (err: any) {
      if (err.code === '42P01' || err.message?.includes('profiles')) {
          setError('Database Setup Required');
      } else {
          setError(err.message || 'Failed to update profile.');
      }
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center text-center">
        <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-brand-blue"></div>
        <p className="mt-4 text-lg">Loading Profile...</p>
      </div>
    );
  }

  return (
    <div className="w-full max-w-4xl bg-light-bg rounded-lg shadow-xl p-8">
       <div className="flex justify-between items-center mb-6 border-b border-gray-700 pb-4">
        <h2 className="text-3xl font-bold">Your Profile</h2>
        <button onClick={onBack} className="text-brand-blue hover:underline font-semibold">
          &larr; Back to Interview
        </button>
      </div>

      {error === "Database Setup Required" ? (
        <div className="w-full bg-brand-blue/20 border border-brand-blue rounded-lg p-6 text-center mb-6">
          <h3 className="text-xl font-bold mb-2 text-brand-blue">Database Setup Required</h3>
          <p className="text-gray-200 mb-4">
            To use the profile and history features, you need to create the necessary tables in your Supabase project.
          </p>
          <div className="bg-black/50 p-4 rounded text-left overflow-x-auto mb-4">
            <code className="text-sm text-green-400 whitespace-pre">
              {`-- Run this in your Supabase SQL Editor:
create table if not exists public.profiles (
  id uuid references auth.users on delete cascade not null primary key,
  updated_at timestamp with time zone,
  full_name text,
  pronouns text
);
alter table public.profiles enable row level security;
create policy "Public profiles are viewable by everyone." on public.profiles for select using (true);
create policy "Users can insert their own profile." on public.profiles for insert with check (auth.uid() = id);
create policy "Users can update own profile." on public.profiles for update using (auth.uid() = id);

create table if not exists public.interviews (
  id uuid default gen_random_uuid() primary key,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  user_id uuid references auth.users on delete cascade not null,
  user_email text,
  config jsonb not null,
  transcription jsonb,
  feedback jsonb,
  report jsonb,
  resources jsonb
);
alter table public.interviews enable row level security;
create policy "Users can view their own interviews." on public.interviews for select using (auth.uid() = user_id);
create policy "Users can insert their own interviews." on public.interviews for insert with check (auth.uid() = user_id);`}
            </code>
          </div>
          <p className="text-gray-400 text-sm">
             Copy the code above, go to your Supabase Dashboard &gt; SQL Editor, paste it, and click "Run".
          </p>
          <button onClick={fetchProfileData} className="mt-4 bg-brand-blue hover:bg-blue-600 text-white font-bold py-2 px-6 rounded-lg">
             I've Run the Script, Retry
          </button>
        </div>
      ) : error && (
        <div className="w-full bg-red-900/50 border border-brand-red rounded-lg p-4 text-center mb-6">
          <p className="text-gray-200">{error}</p>
        </div>
      )}

      {/* Profile Details */}
      {error !== "Database Setup Required" && (
      <div className="bg-black/20 p-6 rounded-lg mb-8">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-2xl font-semibold">Profile Details</h3>
          {!isEditing && (
            <button onClick={() => setIsEditing(true)} className="bg-gray-600 hover:bg-gray-500 text-white font-bold py-2 px-4 rounded-lg text-sm">
              Edit Profile
            </button>
