          <div className={`absolute w-64 h-64 bg-brand-blue/20 rounded-full blur-3xl transition-opacity duration-1000 ${status === 'speaking' ? 'opacity-100 scale-125' : 'opacity-30 scale-100'}`} />

          {/* Avatar Circle */}
          <div className="relative z-10">
              <div className={`w-32 h-32 rounded-full bg-gradient-to-br from-gray-700 to-gray-900 border-4 border-gray-600 flex items-center justify-center shadow-2xl transition-all duration-300 ${status === 'speaking' ? 'border-brand-blue scale-105 shadow-brand-blue/50' : ''} ${status === 'thinking' ? 'border-brand-yellow shadow-brand-yellow/50' : ''}`}>
                  {/* Robot/AI Icon */}
                  <svg xmlns="http://www.w3.org/2000/svg" className={`h-16 w-16 text-gray-300 transition-colors duration-300 ${status === 'speaking' ? 'text-brand-blue' : ''} ${status === 'thinking' ? 'text-brand-yellow' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
