import React, { useState, useEffect, useCallback } from 'react';
import type { Session } from '@supabase/supabase-js';
import { supabase } from '../services/supabaseClient';
import type { InterviewConfig } from '../types';

interface Profile {
  full_name: string;
  pronouns: string;
}

interface InterviewHistoryItem {
  id: string;
  created_at: string;
  config: InterviewConfig;
}

interface ProfileScreenProps {
  session: Session;
  onBack: () => void;
}

const ProfileScreen: React.FC<ProfileScreenProps> = ({ session, onBack }) => {
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<Profile>({ full_name: '', pronouns: '' });
  const [interviews, setInterviews] = useState<InterviewHistoryItem[]>([]);
  const [isEditing, setIsEditing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchProfileData = useCallback(async () => {
    if (!supabase || !session.user) return;
    try {
      setLoading(true);
      setError(null);

      // Fetch profile
      const { data: profileData, error: profileError } = await supabase
        .from('profiles')
        .select('full_name, pronouns')
        .eq('id', session.user.id)
        .single();

      if (profileError) {
        // PGRST116: JSON object requested, multiple (or no) rows returned. (No profile found)
        // 42P01: undefined_table (table does not exist)
        if (profileError.code === '42P01' || (profileError.message && profileError.message.includes('profiles'))) {
             throw new Error("Missing Database Table");
        }

        if (profileError.code !== 'PGRST116') {
            throw profileError;
        }
      }

      if (profileData) {
        setProfile({
            full_name: profileData.full_name || '',
            pronouns: profileData.pronouns || ''
        });
      }

      // Fetch interview history
      const { data: interviewData, error: interviewError } = await supabase
        .from('interviews')
        .select('id, created_at, config')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false })
        .limit(10);

      if (interviewError) {
        if (interviewError.code === '42P01') {
             console.warn("Interviews table missing.");
             // If profiles was fine but interviews is missing, we still want to alert the user essentially
             throw new Error("Missing Database Table");
        } else {
             throw interviewError;
        }
      }

      setInterviews(interviewData || []);

    } catch (err: any) {
      console.error("Error fetching profile data:", err);
      if (err.message === "Missing Database Table" || (err.message && (err.message.includes('schema cache') || err.message.includes('profiles') || err.message.includes('interviews')))) {
          setError("Database Setup Required");
      } else {
          setError(err.message || 'Failed to fetch data.');
      }
    } finally {
      setLoading(false);
    }
  }, [session.user]);

  useEffect(() => {
    fetchProfileData();
  }, [fetchProfileData]);

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase || !session.user) return;
    try {
      setLoading(true);
      const { error } = await supabase.from('profiles').upsert({
        id: session.user.id,
        full_name: profile.full_name,
        pronouns: profile.pronouns,
        updated_at: new Date().toISOString(),
      });
      if (error) throw error;
      setIsEditing(false);
    } catch (err: any) {
      if (err.code === '42P01' || err.message?.includes('profiles')) {
          setError('Database Setup Required');
      } else {
          setError(err.message || 'Failed to update profile.');
      }
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center text-center">
        <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-brand-blue"></div>
        <p className="mt-4 text-lg">Loading Profile...</p>
