      {/* Profile Details */}
      {error !== "Database Setup Required" && (
      <div className="bg-black/20 p-6 rounded-lg mb-8">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-2xl font-semibold">Profile Details</h3>
          {!isEditing && (
            <button onClick={() => setIsEditing(true)} className="bg-gray-600 hover:bg-gray-500 text-white font-bold py-2 px-4 rounded-lg text-sm">
              Edit Profile
            </button>
          )}
        </div>
        {isEditing ? (
          <form onSubmit={handleUpdateProfile} className="space-y-4">
