              <label htmlFor="full_name" className="block text-sm font-medium text-gray-300 mb-1">Full Name</label>
              <input
                id="full_name"
                type="text"
                value={profile.full_name}
                onChange={(e) => setProfile({ ...profile, full_name: e.target.value })}
