const InterviewScreen: React.FC<InterviewScreenProps> = ({ onEnd, config, isPracticeMode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const { transcription, aiStatus, isConnecting, error, endInterview, feedback, aiAudioStream, retry } = useInterview(config);

  const [isRecording, setIsRecording] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const screenStreamRef = useRef<MediaStream | null>(null);

  const [elapsedTime, setElapsedTime] = useState(0);
  const timerIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    if (!isConnecting && !error) {
      timerIntervalRef.current = window.setInterval(() => {
        setElapsedTime(prevTime => prevTime + 1);
      }, 1000);
    }

    return () => {
      if (timerIntervalRef.current) {
        clearInterval(timerIntervalRef.current);
      }
    };
  }, [isConnecting, error]);

  const formatTime = (totalSeconds: number) => {
    const minutes = Math.floor(totalSeconds / 60).toString().padStart(2, '0');
    const seconds = (totalSeconds % 60).toString().padStart(2, '0');
    return `${minutes}:${seconds}`;
  };

  const downloadRecording = useCallback(() => {
    if (recordedChunksRef.current.length === 0) return;
    const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.style.display = 'none';
    a.href = url;
    a.download = `interview-recording-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-')}.webm`;
    document.body.appendChild(a);
    a.click();
    window.URL.revokeObjectURL(url);
    document.body.removeChild(a);
    recordedChunksRef.current = [];
  }, []);

  const stopAndSaveRecording = useCallback(() => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
        mediaRecorderRef.current.stop();
    }
    if (screenStreamRef.current) {
        screenStreamRef.current.getTracks().forEach(track => track.stop());
        screenStreamRef.current = null;
    }
  }, []);

  const startRecording = useCallback(async () => {
    if (!videoRef.current?.srcObject || !aiAudioStream || !(videoRef.current.srcObject instanceof MediaStream)) {
        alert("Could not start recording: camera or AI audio stream not available.");
        return;
    }

    try {
        // 1. Get screen sharing stream, requesting system audio as well.
        // The user's browser will prompt them to share their entire screen, a window, or a tab.
        const screenAndSystemAudioStream = await navigator.mediaDevices.getDisplayMedia({ video: true, audio: true });
        screenStreamRef.current = screenAndSystemAudioStream;

        // 2. Get existing user media stream (for microphone)
        const userMediaStream = videoRef.current.srcObject as MediaStream;

        // 3. Combine streams for recording
        const videoTracks = screenAndSystemAudioStream.getVideoTracks();
        const audioTracks = [...userMediaStream.getAudioTracks()]; // Start with user's microphone

        // If the user chose to share system audio, use it to capture the AI's voice.
        if (screenAndSystemAudioStream.getAudioTracks().length > 0) {
            audioTracks.push(...screenAndSystemAudioStream.getAudioTracks());
        } else {
            // Fallback for browsers/cases where system audio isn't shared: use the AI audio stream directly.
            audioTracks.push(...aiAudioStream.getAudioTracks());
        }

        const combinedStream = new MediaStream([...videoTracks, ...audioTracks]);

        recordedChunksRef.current = [];
        const options = { mimeType: 'video/webm; codecs=vp9,opus' };
        const recorder = new MediaRecorder(combinedStream, MediaRecorder.isTypeSupported(options.mimeType) ? options : undefined);
        mediaRecorderRef.current = recorder;

        recorder.ondataavailable = (event) => {
            if (event.data.size > 0) {
                recordedChunksRef.current.push(event.data);
            }
        };

        recorder.onstop = () => {
            downloadRecording();
            setIsRecording(false);
            setIsSaving(false);
        };

        // Handle user stopping screen share via browser UI
        screenAndSystemAudioStream.getVideoTracks()[0].onended = () => {
            if (mediaRecorderRef.current?.state === 'recording') {
                stopAndSaveRecording();
                setIsSaving(true);
            }
        };

        recorder.start();
        setIsRecording(true);

    } catch (err) {
        console.error("Screen sharing failed:", err);
        setIsRecording(false);
        setIsSaving(false);
    }
  }, [aiAudioStream, downloadRecording, stopAndSaveRecording]);

  const handleRecordingButtonClick = useCallback(() => {
    if (isRecording) {
      setIsSaving(true);
      stopAndSaveRecording();
    } else {
      startRecording();
    }
  }, [isRecording, startRecording, stopAndSaveRecording]);

  const handleEndClick = useCallback(() => {
    if (timerIntervalRef.current) {
      clearInterval(timerIntervalRef.current);
    }
    if (isRecording) {
      stopAndSaveRecording();
    }
    endInterview();
    onEnd(transcription, feedback);
  }, [isRecording, stopAndSaveRecording, endInterview, onEnd, transcription, feedback]);


  useEffect(() => {
    const setupCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        console.error("Error accessing camera:", err);
      }
    };
    setupCamera();
  }, []);

  if (isConnecting) {
    return (
      <div className="flex flex-col items-center justify-center text-center h-64">
        <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-brand-blue mb-4"></div>
        <p className="text-lg text-gray-200">Connecting to AI Interviewer...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="w-full max-w-2xl bg-red-900/50 border border-brand-red rounded-lg shadow-xl p-8 text-center flex flex-col items-center justify-center mx-auto mt-10">
        <h2 className="text-2xl font-bold mb-4 text-brand-red">Connection Error</h2>
        <p className="text-gray-200 mb-6">{error}</p>
        <div className="flex gap-4">
            <button 
                onClick={retry} 
                className="bg-brand-blue hover:bg-blue-600 text-white font-bold py-2 px-6 rounded-lg transition-transform transform hover:scale-105 shadow-lg"
            >
                Retry Connection
            </button>
            <button 
                onClick={() => onEnd(transcription, feedback)} 
                className="bg-gray-700 hover:bg-gray-600 text-white font-bold py-2 px-6 rounded-lg transition-transform transform hover:scale-105 shadow-lg border border-gray-600"
            >
                End Interview
            </button>
        </div>
      </div>
    );
  }

  return (
    <div className="relative w-full max-w-6xl h-[80vh] bg-light-bg rounded-xl shadow-2xl overflow-hidden border border-gray-800">
      {/* Ambient Background Animation */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none select-none">
          <div className="absolute top-[-10%] left-[-10%] w-[600px] h-[600px] bg-brand-blue/20 rounded-full mix-blend-screen filter blur-3xl opacity-20 animate-blob"></div>
          <div className="absolute top-[-10%] right-[-10%] w-[600px] h-[600px] bg-brand-purple/20 rounded-full mix-blend-screen filter blur-3xl opacity-20 animate-blob" style={{ animationDelay: '2s' }}></div>
          <div className="absolute bottom-[-20%] left-[20%] w-[600px] h-[600px] bg-brand-green/20 rounded-full mix-blend-screen filter blur-3xl opacity-20 animate-blob" style={{ animationDelay: '4s' }}></div>
      </div>

      <div className="relative z-10 w-full h-full grid grid-cols-1 lg:grid-cols-5 gap-6 p-4">
        {/* Left Column: AI Avatar and User Video */}
        <div className="lg:col-span-3 flex flex-col gap-4 h-full min-h-0">

          {/* AI Avatar Section */}
          <div className="flex-1 relative bg-black/40 rounded-lg overflow-hidden border border-gray-700/50 backdrop-blur-sm flex items-center justify-center min-h-0 shadow-inner">
             <AiAvatar status={aiStatus} />
             <div className="absolute bottom-4 left-4 z-10">
                <AiStatusIndicator status={aiStatus} />
             </div>
          </div>

          {/* User Video Section */}
          <div className="flex-1 relative bg-black rounded-lg overflow-hidden shadow-lg border border-gray-700/50 flex items-center justify-center min-h-0">
            <video ref={videoRef} autoPlay muted className="w-full h-full object-cover transform -scale-x-100"></video>
            <div className="absolute top-4 left-4 z-10">
              {isRecording && <RecordingIndicator />}
            </div>
            <div className="absolute top-4 right-4 z-10 bg-black/50 backdrop-blur-md text-white font-mono text-lg px-3 py-1 rounded-lg tabular-nums border border-white/10">
              {formatTime(elapsedTime)}
            </div>
          </div>
        </div>

        {/* Right Column: Transcript and Feedback */}
        <div className="lg:col-span-2 flex flex-col h-full min-h-0">
          <div className="flex-1 flex flex-col min-h-0 bg-black/20 rounded-lg p-4 backdrop-blur-md border border-white/5">
            <div className="flex items-center gap-3 mb-3 flex-shrink-0 border-b border-gray-700/50 pb-2">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 8h2a2 2 0 012 2v6a2 2 0 01-2 2h-2v4l-4-4H9a2 2 0 01-2-2V4a2 2 0 012-2h8a2 2 0 012 2v4z" /></svg>
              <h3 className="text-xl font-semibold text-gray-300">Interview Transcript</h3>
            </div>
            <div className="flex-1 overflow-y-auto mb-4 custom-scrollbar">
                <TranscriptionLog transcription={transcription} />
            </div>

            <div className="flex items-center gap-3 mb-3 flex-shrink-0 border-b border-gray-700/50 pb-2">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" /></svg>
              <h3 className="text-xl font-semibold text-gray-300">AI Feedback</h3>
            </div>
            <div className="h-40 bg-black/30 rounded-lg overflow-y-auto flex-shrink-0 custom-scrollbar border border-gray-700/30">
                <FeedbackLog feedback={feedback} />
            </div>
          </div>
          <div className="mt-4 flex flex-col gap-2 flex-shrink-0">
            {!isPracticeMode && (
              <button
                onClick={handleRecordingButtonClick}
                disabled={!aiAudioStream || isSaving}
                className={`w-full font-bold py-3 px-6 rounded-lg transition-all transform hover:scale-105 shadow-lg backdrop-blur-sm ${
                  isRecording
                    ? 'bg-brand-yellow hover:bg-yellow-500 text-black animate-pulse'
                    : 'bg-gray-600 hover:bg-gray-500 text-white disabled:bg-gray-800 disabled:cursor-not-allowed disabled:transform-none'
                }`}
              >
                {isRecording ? (isSaving ? 'Saving...' : 'Stop & Save Recording') : 'Record Interview'}
              </button>
            )}
            <button
              onClick={handleEndClick}
              disabled={isSaving}
              className="w-full bg-brand-red hover:bg-red-600 text-white font-bold py-3 px-6 rounded-lg transition-all transform hover:scale-105 flex-shrink-0 disabled:opacity-50 shadow-lg backdrop-blur-sm"
            >
              {isSaving ? 'Finishing Up...' : isPracticeMode ? 'End Practice' : 'End Interview'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

