  uiLabels: DEFAULT_LABELS
})}

Response must be a valid JSON object with the same structure: { report: ..., uiLabels: ... }.
Do not translate the 'skillName' if it is a standard technical term (like 'React', 'Java'), but translate generic skills (like 'Communication').
`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: { responseMimeType: 'application/json' }
        });

        const translatedData = JSON.parse(response.text);
        setTranslations(prev => ({
            ...prev,
            [targetLang]: translatedData
        }));

    } catch (err) {
        console.error("Translation failed:", err);
        alert("Failed to translate report. Please try again.");
        setCurrentLanguage("English");
    } finally {
        setIsTranslating(false);
    }
  };

  const activeReport = currentLanguage === "English" ? report : (translations[currentLanguage]?.report || report);
  const activeLabels = currentLanguage === "English" ? DEFAULT_LABELS : (translations[currentLanguage]?.labels || DEFAULT_LABELS);

  return (
    <div className="w-full max-w-6xl bg-light-bg rounded-lg shadow-xl p-8 flex flex-col">
      {report && (
        <div className="mb-6 flex justify-end">
             <div className="flex items-center gap-2">
                <label htmlFor="language-select" className="text-sm text-gray-400">Translate to:</label>
                <select
                    id="language-select"
                    value={currentLanguage}
                    onChange={handleLanguageChange}
                    disabled={isTranslating}
                    className="bg-gray-700 text-white text-sm rounded-lg p-2 focus:ring-2 focus:ring-brand-blue outline-none border border-gray-600 disabled:opacity-50"
                >
                    {LANGUAGES.map(lang => (
                        <option key={lang} value={lang}>{lang}</option>
                    ))}
                </select>
                {isTranslating && <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>}
            </div>
        </div>
      )}

      {activeLabels && (
          <div className="mb-6 bg-brand-green/20 border border-brand-green text-center p-4 rounded-lg">
            <p className="font-semibold text-lg">{activeLabels.reportReady}</p>
            <p className="text-gray-300">{activeLabels.reportReadySubtext}</p>
          </div>
      )}

      <h2 className="text-3xl font-bold mb-6 text-center">{activeLabels.generatedFor} {config.name}</h2>

      {isLoading && (
        <div className="flex flex-col items-center justify-center text-center py-10">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-brand-blue"></div>
          <p className="mt-4 text-lg">Generating your personalized feedback dashboard...</p>
        </div>
      )}

      {error && (
        <div className="w-full bg-red-900/50 border border-brand-red rounded-lg p-6 text-center">
          <h3 className="text-xl font-bold mb-2 text-brand-red">Report Generation Failed</h3>
          <p className="text-gray-200">{error}</p>
        </div>
      )}

      {!isLoading && !error && activeReport && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-black/20 p-6 rounded-lg">
                <h3 className="text-2xl font-semibold mb-6 border-b-2 border-brand-blue pb-2">{activeLabels.performanceDashboard}</h3>
                {isTranslating ? (
                    <div className="h-40 flex items-center justify-center">
                        <p className="text-gray-400 animate-pulse">Translating dashboard...</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-6">
                        {activeReport.skillRatings.map((skill) => <SkillMeter key={skill.skillName} skill={skill.skillName} rating={skill.rating} justification={skill.justification} />)}
                    </div>
                )}
            </div>
             <div className="bg-black/20 p-6 rounded-lg">
                <h3 className="text-2xl font-semibold mb-4">{activeLabels.overallSummary}</h3>
                {isTranslating ? <p className="text-gray-400 animate-pulse">Translating...</p> : <p className="text-gray-300 leading-relaxed">{activeReport.overallSummary}</p>}
            </div>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <FeedbackCard title={activeLabels.keyStrengths} items={isTranslating ? ["..."] : activeReport.keyStrengths} color="green" icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 10h4.764a2 2 0 011.789 2.894l-3.5 7A2 2 0 0115.263 21h-4.017c-.163 0-.326-.02-.485-.06L7 18.734V6a2 2 0 012-2h4a2 2 0 012 2v4z" /></svg>} />
                <FeedbackCard title={activeLabels.areasForImprovement} items={isTranslating ? ["..."] : activeReport.areasForImprovement} color="yellow" icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 12a4 4 0 10-8 0 4 4 0 008 0zm0 0v1.5a2.5 2.5 0 005 0V12a9 9 0 10-9 9m4.5-1.206a8.959 8.959 0 01-4.5 1.207" /></svg>} />
                <FeedbackCard title={activeLabels.actionableAdvice} items={isTranslating ? ["..."] : activeReport.actionableAdvice} color="blue" icon={<svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" /></svg>} />
            </div>
          </div>
          <div className="lg:col-span-1 bg-black/20 p-6 rounded-lg">
            <h3 className="text-2xl font-semibold mb-4 border-b-2 border-brand-green pb-2">{activeLabels.learningResources}</h3>
            {resources.length > 0 ? (
              <ul className="space-y-4">
                {resources.map((res, index) => (
                  <li key={index}>
                    <a href={res.uri} target="_blank" rel="noopener noreferrer" className="text-brand-yellow hover:underline font-semibold block">
                      {res.title}
                    </a>
                    <p className="text-gray-400 text-sm truncate">{res.uri}</p>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-gray-400 italic">No specific resources found, but keep practicing!</p>
            )}
          </div>
        </div>
      )}

      <div className="mt-8 text-center">
        <button
          onClick={onRestart}
          className="bg-brand-green hover:bg-green-600 text-white font-bold py-3 px-8 rounded-lg transition-transform transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-green-500/50"
        >
          {isHistoryView ? "Back to History" : activeLabels.tryAnotherInterview}
        </button>
      </div>
    </div>
  );
};

export default EndScreen;

import React, { useState, useEffect, useCallback } from 'react';
import type { Session } from '@supabase/supabase-js';
import { supabase } from '../services/supabaseClient';
import type { InterviewConfig, TranscriptionEntry, FeedbackEntry, InterviewReport, SuggestedResource } from '../types';
import EndScreen from './EndScreen';

interface Profile {
  full_name: string;
  pronouns: string;
}

interface InterviewHistoryItem {
  id: string;
  created_at: string;
  config: InterviewConfig;
  transcription: TranscriptionEntry[];
  feedback: FeedbackEntry[];
  report: InterviewReport | null;
  resources: SuggestedResource[] | null;
}

interface ProfileScreenProps {
  session: Session;
  onBack: () => void;
}

const ProfileScreen: React.FC<ProfileScreenProps> = ({ session, onBack }) => {
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<Profile>({ full_name: '', pronouns: '' });
  const [interviews, setInterviews] = useState<InterviewHistoryItem[]>([]);
  const [selectedInterview, setSelectedInterview] = useState<InterviewHistoryItem | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchProfileData = useCallback(async () => {
    if (!supabase || !session.user) {
        setLoading(false);
        return;
    }
    setLoading(true);
    setError(null);

    try {
      // 1. Fetch profile (independently)
      try {
        const { data: profileData, error: profileError } = await supabase
          .from('profiles')
          .select('full_name, pronouns')
          .eq('id', session.user.id)
          .maybeSingle(); 

        if (profileError) throw profileError;

        if (profileData) {
          setProfile({
              full_name: profileData.full_name || '',
              pronouns: profileData.pronouns || ''
          });
        }
      } catch (profileErr: any) {
         console.warn("Profile fetch warning:", profileErr);
         // Continue to fetch history even if profile fetch has issues (non-critical)
      }

      // 2. Fetch interview history
      const { data: interviewData, error: interviewError } = await supabase
        .from('interviews')
        .select('id, created_at, config, transcription, feedback, report, resources')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false })
        .limit(10);

      if (interviewError) throw interviewError;

      setInterviews(interviewData || []);

    } catch (err: any) {
      console.error("Error fetching history:", err);

      const errorMessage = err.message || JSON.stringify(err);

      // Check for specific Supabase/Postgres errors
      if (err.code === '42P01') { // undefined_table
         setError("Database tables not found. Please run the setup script found in the README.");
      } else if (err.code === '42703') { // undefined_column
         setError("Database schema mismatch. The 'interviews' table is missing columns (e.g., 'config'). Please recreate the table using the script in the README.");
      } else if (errorMessage.includes('does not exist')) {
         setError("Database configuration error. Please check the README for setup instructions.");
      } else {
         setError(`Failed to load interview history: ${errorMessage}`);
      }
    } finally {
      setLoading(false);
    }
  }, [session.user]);

  useEffect(() => {
    fetchProfileData();
  }, [fetchProfileData]);

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase || !session.user) return;
    try {
      setLoading(true);
      const { error } = await supabase.from('profiles').upsert({
        id: session.user.id,
        full_name: profile.full_name,
        pronouns: profile.pronouns,
        updated_at: new Date().toISOString(),
      });
      if (error) throw error;
      setIsEditing(false);
    } catch (err: any) {
      console.error("Error updating profile:", err);
      setError(`Failed to update profile: ${err.message || 'Unknown error'}`);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center text-center py-12">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-brand-blue"></div>
        <p className="mt-4 text-gray-300">Loading...</p>
      </div>
    );
  }

  // If an interview is selected, show the EndScreen populated with historical data
  if (selectedInterview) {
    return (
      <div className="w-full max-w-6xl mx-auto flex flex-col gap-4">
        <div className="flex justify-start">
          <button 
            onClick={() => setSelectedInterview(null)} 
            className="text-brand-blue hover:text-blue-400 flex items-center gap-2 font-semibold transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
            </svg>
            Back to Profile
          </button>
        </div>
        <EndScreen
          onRestart={() => setSelectedInterview(null)}
          transcription={selectedInterview.transcription || []}
          feedback={selectedInterview.feedback || []}
          config={selectedInterview.config}
          userEmail={session.user.email || ''}
          userId={session.user.id}
          existingReport={selectedInterview.report || undefined}
          existingResources={selectedInterview.resources || undefined}
          isHistoryView={true}
        />
      </div>
    );
  }

  return (
    <div className="w-full max-w-4xl mx-auto bg-light-bg rounded-xl shadow-2xl overflow-hidden border border-gray-800">
       <div className="flex justify-between items-center p-6 border-b border-gray-700 bg-black/20">
        <h2 className="text-2xl font-bold text-white">Your Profile</h2>
        <button onClick={onBack} className="text-gray-400 hover:text-brand-blue transition-colors flex items-center gap-2">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
          </svg>
          Back
        </button>
      </div>

      <div className="p-8 space-y-8">
        {error && (
            <div className="bg-red-500/10 border border-red-500/50 rounded-lg p-4 flex items-center gap-3 text-red-200">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                </svg>
                <p>{error}</p>
            </div>
        )}

        {/* Profile Info */}
        <div className="flex flex-col md:flex-row gap-8 items-start">
            <div className="w-full md:w-1/3 flex flex-col items-center">
                <div className="w-32 h-32 rounded-full bg-gradient-to-br from-brand-blue to-brand-purple flex items-center justify-center text-4xl font-bold text-white shadow-lg mb-4">
                    {profile.full_name ? profile.full_name.charAt(0).toUpperCase() : session.user.email?.charAt(0).toUpperCase()}
                </div>
                <p className="text-gray-400 text-sm">{session.user.email}</p>
            </div>

            <div className="w-full md:w-2/3 bg-black/20 rounded-xl p-6 border border-gray-700/50">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-semibold text-gray-200">Personal Information</h3>
                    {!isEditing && (
                        <button onClick={() => setIsEditing(true)} className="text-brand-blue hover:text-blue-400 text-sm font-semibold">
                            Edit
                        </button>
                    )}
                </div>

                {isEditing ? (
                    <form onSubmit={handleUpdateProfile} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-400 mb-1">Full Name</label>
                            <input
                                type="text"
                                value={profile.full_name}
                                onChange={(e) => setProfile({ ...profile, full_name: e.target.value })}
                                className="w-full bg-gray-700/50 border border-gray-600 rounded-lg px-4 py-2 text-white focus:ring-2 focus:ring-brand-blue focus:border-transparent outline-none transition-all"
                                placeholder="Enter your name"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-400 mb-1">Pronouns</label>
                            <input
                                type="text"
                                value={profile.pronouns}
                                onChange={(e) => setProfile({ ...profile, pronouns: e.target.value })}
                                className="w-full bg-gray-700/50 border border-gray-600 rounded-lg px-4 py-2 text-white focus:ring-2 focus:ring-brand-blue focus:border-transparent outline-none transition-all"
                                placeholder="e.g. they/them"
                            />
                        </div>
                        <div className="flex justify-end gap-3 mt-6">
                             <button type="button" onClick={() => setIsEditing(false)} className="px-4 py-2 text-sm font-medium text-gray-400 hover:text-white transition-colors">
                                Cancel
                            </button>
                            <button type="submit" className="px-6 py-2 bg-brand-blue hover:bg-blue-600 text-white text-sm font-bold rounded-lg transition-colors shadow-lg">
                                Save Changes
                            </button>
                        </div>
                    </form>
                ) : (
                    <div className="space-y-4">
                         <div className="grid grid-cols-3 gap-4 border-b border-gray-700/50 pb-4">
                            <span className="text-gray-500 text-sm">Full Name</span>
                            <span className="col-span-2 text-gray-200 font-medium">{profile.full_name || '-'}</span>
                         </div>
                         <div className="grid grid-cols-3 gap-4">
                            <span className="text-gray-500 text-sm">Pronouns</span>
                            <span className="col-span-2 text-gray-200 font-medium">{profile.pronouns || '-'}</span>
                         </div>
                    </div>
                )}
            </div>
        </div>

        {/* History Section */}
        <div>
             <h3 className="text-xl font-semibold text-gray-200 mb-4">Recent Interviews</h3>
             <div className="bg-black/20 rounded-xl border border-gray-700/50 overflow-hidden">
                {interviews.length > 0 ? (
                    <div className="divide-y divide-gray-700/50">
                        {interviews.map((interview) => (
                            <div 
                                key={interview.id} 
                                onClick={() => setSelectedInterview(interview)}
                                className="p-4 hover:bg-white/5 transition-colors flex justify-between items-center group cursor-pointer"
                            >
                                <div>
                                    <p className="font-bold text-white text-lg group-hover:text-brand-blue transition-colors">{interview.config?.name || 'Untitled Interview'}</p>
                                    <p className="text-sm text-gray-400">{new Date(interview.created_at).toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' })}</p>
                                </div>
                                <span className="flex items-center gap-2 text-gray-500 group-hover:text-brand-blue transition-colors text-sm">
                                    View Report &rarr;
                                </span>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="p-8 text-center text-gray-500">
                        <p>{error ? "Could not load history." : "No interview history available yet."}</p>
                        {!error && <button onClick={onBack} className="mt-4 text-brand-blue hover:underline text-sm">Start your first interview</button>}
                    </div>
                )}
             </div>
        </div>
      </div>
    </div>
  );
};

export default ProfileScreen;

import React, { useState, useCallback, useEffect } from 'react';
import type { Session } from '@supabase/supabase-js';
import { InterviewStatus, InterviewConfig, TranscriptionEntry, FeedbackEntry } from './types';
import { supabase } from './services/supabaseClient';
import WelcomeScreen from './components/WelcomeScreen';
import InterviewScreen from './components/InterviewScreen';
import EndScreen from './components/EndScreen';
import AuthScreen from './components/AuthScreen';
import ProfileScreen from './components/ProfileScreen';

const App: React.FC = () => {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [interviewStatus, setInterviewStatus] = useState<InterviewStatus>(InterviewStatus.NotStarted);
  const [interviewConfig, setInterviewConfig] = useState<InterviewConfig | null>(null);
  const [isPracticeMode, setIsPracticeMode] = useState(false);
  const [finalTranscription, setFinalTranscription] = useState<TranscriptionEntry[]>([]);
  const [finalFeedback, setFinalFeedback] = useState<FeedbackEntry[]>([]);
  const [currentView, setCurrentView] = useState<'interview' | 'profile'>('interview');
  const [isDesktop, setIsDesktop] = useState(true);

  // Check for desktop screen size
  useEffect(() => {
    const checkScreenSize = () => {
      setIsDesktop(window.innerWidth >= 1024);
    };

    // Initial check
    checkScreenSize();

    window.addEventListener('resize', checkScreenSize);
    return () => window.removeEventListener('resize', checkScreenSize);
  }, []);

  useEffect(() => {
    if (!supabase) {
      console.warn("Supabase client not initialized.");
      setLoading(false);
      return;
    }

    setLoading(true);
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setLoading(false);
    }).catch(err => {
      console.error("Error getting session:", err);
      setLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (_event === 'SIGNED_OUT') {
        // Reset app state on logout
        setInterviewStatus(InterviewStatus.NotStarted);
        setInterviewConfig(null);
        setFinalTranscription([]);
        setFinalFeedback([]);
        setCurrentView('interview');
      }
    });

    return () => subscription.unsubscribe();
  }, []);


  const handleStartInterview = useCallback((selectedConfig: InterviewConfig, practiceMode: boolean) => {
    setInterviewConfig(selectedConfig);
    setIsPracticeMode(practiceMode);
    setInterviewStatus(InterviewStatus.InProgress);
  }, []);

  const handleEndInterview = useCallback((transcription: TranscriptionEntry[], feedback: FeedbackEntry[]) => {
    if (isPracticeMode) {
      setInterviewStatus(InterviewStatus.NotStarted);
      setInterviewConfig(null);
    } else {
      setFinalTranscription(transcription);
      setFinalFeedback(feedback);
      setInterviewStatus(InterviewStatus.Finished);
    }
  }, [isPracticeMode]);

  const handleRestart = useCallback(() => {
    setInterviewStatus(InterviewStatus.NotStarted);
    setInterviewConfig(null);
    setFinalTranscription([]);
    setFinalFeedback([]);
    setIsPracticeMode(false);
    setCurrentView('interview');
  }, []);

  const handleLogout = async () => {
    if (supabase) {
      await supabase.auth.signOut();
    }
  };

  const renderContent = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-brand-blue"></div>
          <p className="mt-4 text-lg">Loading...</p>
        </div>
      );
    }

    if (!session) {
      return <AuthScreen />;
    }

    if (currentView === 'profile') {
      return <ProfileScreen session={session} onBack={() => setCurrentView('interview')} />;
    }

    switch (interviewStatus) {
      case InterviewStatus.InProgress:
        // Safely check if interviewConfig is present before rendering
        if (!interviewConfig) return <WelcomeScreen onStart={handleStartInterview} />;
        return <InterviewScreen onEnd={handleEndInterview} config={interviewConfig} isPracticeMode={isPracticeMode} />;
      case InterviewStatus.Finished:
        // Safely check if interviewConfig is present before rendering
        if (!interviewConfig) return <WelcomeScreen onStart={handleStartInterview} />;
        return <EndScreen 
          onRestart={handleRestart} 
          transcription={finalTranscription} 
          feedback={finalFeedback} 
          config={interviewConfig} 
          userEmail={session.user.email || ''} 
          userId={session.user.id}
        />;
      case InterviewStatus.NotStarted:
      default:
        return <WelcomeScreen onStart={handleStartInterview} />;
    }
  };

  if (!isDesktop) {
    return (
        <div className="min-h-screen bg-dark-bg flex flex-col items-center justify-center p-6 text-center">
            <div className="w-full max-w-md bg-light-bg rounded-xl shadow-2xl p-8 border border-gray-700">
                <div className="w-20 h-20 bg-brand-blue/10 rounded-full flex items-center justify-center mx-auto mb-6">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-brand-blue" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                    </svg>
                </div>
                <h1 className="text-2xl font-bold text-white mb-3">Desktop Only</h1>
                <p className="text-gray-300 mb-6 leading-relaxed">
                    For the best interview practice experience, please access <strong>prepareAI</strong> on a desktop or laptop computer.
                </p>
