const RegistrationScreen: React.FC<RegistrationScreenProps> = ({ onSwitchToLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase) return;

    setError(null);
    setMessage(null);
    setLoading(true);
    try {
      const { data, error } = await supabase.auth.signUp({ email, password });
      if (error) throw error;
      if (data.user && data.user.identities && data.user.identities.length === 0) {
        // This can happen if the user already exists but is not confirmed.
        setError('User already exists. Please try logging in or check your email for a confirmation link.');
      } else {
        setMessage('Registration successful! Please check your email for a confirmation link.');
      }
    } catch (error: any) {
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleSignup = async () => {
    if (!supabase) return;
    setError(null);
    setMessage(null);
    setLoading(true);

    // Determine the correct redirect URL.
    const getRedirectUrl = () => {
        if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
            return window.location.origin;
        }
        return 'https://prepare-ai-six.vercel.app';
    };

    const redirectUrl = getRedirectUrl();

    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: redirectUrl,
          queryParams: {
            access_type: 'offline',
            prompt: 'consent',
          },
        },
      });
      if (error) throw error;
    } catch (error: any) {
      console.error("Google Signup Error:", error);
      setError(error.message);
      setLoading(false);
    }
  };

  return (
    <div className="w-full bg-light-bg rounded-lg shadow-xl p-8 flex flex-col items-center">
      <h2 className="text-2xl font-bold mb-4 text-center">Create an Account</h2>
      <p className="text-gray-300 mb-6 text-center">
        Get started with your personalized interview practice.
      </p>
      <form onSubmit={handleRegister} className="w-full space-y-4">
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="Email address"
          className="w-full bg-gray-700 text-white px-4 py-3 rounded-lg border border-gray-600 focus:outline-none focus:ring-2 focus:ring-brand-blue"
          required
        />
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          placeholder="Password (at least 6 characters)"
          className="w-full bg-gray-700 text-white px-4 py-3 rounded-lg border border-gray-600 focus:outline-none focus:ring-2 focus:ring-brand-blue"
          minLength={6}
          required
        />
        {error && (
            <div className="w-full bg-brand-red/10 border border-brand-red rounded p-3 text-sm">
                <p className="text-brand-red font-semibold">Error:</p>
                <p className="text-gray-300">{error}</p>
                {(error.includes('redirect') || error.toLowerCase().includes('google')) && (
                    <p className="text-xs text-gray-400 mt-2">
                        <strong>Action Required:</strong> Please ensure 
                        <code className="bg-black/30 p-1 rounded mx-1 text-white">https://prepare-ai-six.vercel.app</code>
                        is added to your <strong>Redirect URLs</strong> in the Supabase Dashboard (under Authentication &gt; URL Configuration).
                    </p>
                )}
            </div>
        )}
        {message && <p className="text-brand-green text-sm">{message}</p>}
        <button
          type="submit"
          disabled={loading}
          className="w-full bg-brand-green hover:bg-green-600 text-white font-bold py-3 rounded-lg transition-transform transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-green-500/50 disabled:bg-gray-600 disabled:cursor-not-allowed"
        >
          {loading ? 'Registering...' : 'Sign Up'}
        </button>
      </form>

      <div className="flex items-center w-full my-6">
        <div className="flex-grow h-px bg-gray-600"></div>
        <span className="px-4 text-gray-400 text-sm">OR</span>
        <div className="flex-grow h-px bg-gray-600"></div>
      </div>

      <button
        type="button"
        onClick={handleGoogleSignup}
        disabled={loading}
        className="w-full bg-white hover:bg-gray-100 text-gray-900 font-bold py-3 px-4 rounded-lg transition-transform transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-gray-500/50 flex items-center justify-center gap-3 disabled:opacity-70 disabled:cursor-not-allowed"
      >
        <svg className="w-5 h-5" viewBox="0 0 24 24">
          <path
            d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
            fill="#4285F4"
          />
          <path
            d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
            fill="#34A853"
          />
          <path
            d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
            fill="#FBBC05"
          />
          <path
            d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
            fill="#EA4335"
          />
        </svg>
        Sign up with Google
      </button>

      <p className="text-gray-400 mt-6 text-sm">
        Already have an account?{' '}
        <button onClick={onSwitchToLogin} className="text-brand-blue hover:underline font-semibold">
          Log in
        </button>
      </p>
    </div>
  );
};

export default RegistrationScreen;

import React, { useState, useCallback, useEffect } from 'react';
import type { Session } from '@supabase/supabase-js';
import { InterviewStatus, InterviewConfig, TranscriptionEntry, FeedbackEntry } from './types';
import { supabase } from './services/supabaseClient';
import WelcomeScreen from './components/WelcomeScreen';
import InterviewScreen from './components/InterviewScreen';
import EndScreen from './components/EndScreen';
import AuthScreen from './components/AuthScreen';
import ProfileScreen from './components/ProfileScreen';

const App: React.FC = () => {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [interviewStatus, setInterviewStatus] = useState<InterviewStatus>(InterviewStatus.NotStarted);
  const [interviewConfig, setInterviewConfig] = useState<InterviewConfig | null>(null);
  const [isPracticeMode, setIsPracticeMode] = useState(false);
  const [finalTranscription, setFinalTranscription] = useState<TranscriptionEntry[]>([]);
  const [finalFeedback, setFinalFeedback] = useState<FeedbackEntry[]>([]);
  const [currentView, setCurrentView] = useState<'interview' | 'profile'>('interview');
  const [isDesktop, setIsDesktop] = useState(true);

  // Check for desktop screen size
  useEffect(() => {
    const checkScreenSize = () => {
      setIsDesktop(window.innerWidth >= 1024);
    };

    // Initial check
    checkScreenSize();

    window.addEventListener('resize', checkScreenSize);
    return () => window.removeEventListener('resize', checkScreenSize);
  }, []);

  useEffect(() => {
    if (!supabase) {
      console.warn("Supabase client not initialized.");
      setLoading(false);
      return;
    }

    setLoading(true);
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setLoading(false);
    }).catch(err => {
      console.error("Error getting session:", err);
      setLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (_event === 'SIGNED_OUT') {
        // Reset app state on logout
        setInterviewStatus(InterviewStatus.NotStarted);
        setInterviewConfig(null);
        setFinalTranscription([]);
        setFinalFeedback([]);
        setCurrentView('interview');
      }
    });

    return () => subscription.unsubscribe();
  }, []);


  const handleStartInterview = useCallback((selectedConfig: InterviewConfig, practiceMode: boolean) => {
    setInterviewConfig(selectedConfig);
    setIsPracticeMode(practiceMode);
    setInterviewStatus(InterviewStatus.InProgress);
  }, []);

  const handleEndInterview = useCallback((transcription: TranscriptionEntry[], feedback: FeedbackEntry[]) => {
    if (isPracticeMode) {
      setInterviewStatus(InterviewStatus.NotStarted);
      setInterviewConfig(null);
    } else {
      setFinalTranscription(transcription);
      setFinalFeedback(feedback);
      setInterviewStatus(InterviewStatus.Finished);
    }
  }, [isPracticeMode]);

  const handleRestart = useCallback(() => {
    setInterviewStatus(InterviewStatus.NotStarted);
    setInterviewConfig(null);
    setFinalTranscription([]);
    setFinalFeedback([]);
    setIsPracticeMode(false);
    setCurrentView('interview');
  }, []);

  const handleLogout = async () => {
    if (supabase) {
      await supabase.auth.signOut();
    }
  };

  const renderContent = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-brand-blue"></div>
          <p className="mt-6 text-lg font-medium text-gray-300">Initializing Experience...</p>
        </div>
      );
    }

    if (!session) {
      return <AuthScreen />;
    }

    if (currentView === 'profile') {
      return <ProfileScreen session={session} onBack={() => setCurrentView('interview')} />;
    }

    switch (interviewStatus) {
      case InterviewStatus.InProgress:
        // Safely check if interviewConfig is present before rendering
        if (!interviewConfig) return <WelcomeScreen onStart={handleStartInterview} />;
        return <InterviewScreen onEnd={handleEndInterview} config={interviewConfig} isPracticeMode={isPracticeMode} />;
      case InterviewStatus.Finished:
        // Safely check if interviewConfig is present before rendering
        if (!interviewConfig) return <WelcomeScreen onStart={handleStartInterview} />;
        return <EndScreen 
          onRestart={handleRestart} 
          transcription={finalTranscription} 
          feedback={finalFeedback} 
          config={interviewConfig} 
          userEmail={session.user.email || ''} 
          userId={session.user.id}
        />;
      case InterviewStatus.NotStarted:
      default:
        return <WelcomeScreen onStart={handleStartInterview} />;
    }
  };

  if (!isDesktop) {
    return (
        <div className="min-h-screen bg-dark-bg flex flex-col items-center justify-center p-6 text-center relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-blue-900/40 via-dark-bg to-dark-bg -z-10"></div>
            <div className="glass-panel w-full max-w-md rounded-2xl p-8 border border-white/10 shadow-2xl backdrop-blur-xl">
                <div className="w-20 h-20 bg-brand-blue/20 rounded-full flex items-center justify-center mx-auto mb-6 ring-4 ring-brand-blue/10">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-brand-blue" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                    </svg>
                </div>
                <h1 className="text-2xl font-bold text-white mb-3 tracking-tight">Desktop Experience</h1>
                <p className="text-gray-300 mb-6 leading-relaxed">
                    For the most immersive AI interview practice, please access <strong>prepareAI</strong> on a desktop or laptop computer.
                </p>
                <div className="bg-black/30 rounded-lg p-4 text-sm text-gray-400 border border-white/5">
                    <p>Mobile devices are not currently supported to ensure optimal camera and screen performance.</p>
                </div>
            </div>
        </div>
    );
  }

  return (
    <div className="min-h-screen relative flex flex-col items-center">
       {/* Global Background Elements */}
       <div className="fixed inset-0 overflow-hidden pointer-events-none -z-10">
          <div className="absolute -top-40 -left-40 w-96 h-96 bg-brand-blue/30 rounded-full mix-blend-screen filter blur-[100px] opacity-30 animate-blob"></div>
          <div className="absolute top-20 right-20 w-80 h-80 bg-brand-purple/30 rounded-full mix-blend-screen filter blur-[100px] opacity-30 animate-blob animation-delay-2000"></div>
          <div className="absolute -bottom-40 left-1/2 w-96 h-96 bg-brand-green/20 rounded-full mix-blend-screen filter blur-[100px] opacity-30 animate-blob animation-delay-4000"></div>
          <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10"></div>
       </div>

       <header className="w-full sticky top-0 z-50 backdrop-blur-xl bg-dark-bg/60 border-b border-white/5 shadow-lg">
         <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
            <div className="flex items-center gap-3">
                <div className="relative">
                  <div className="absolute inset-0 bg-brand-blue blur-lg opacity-40 rounded-full"></div>
                  <svg xmlns="http://www.w3.org/2000/svg" className="relative h-8 w-8 text-white" viewBox="0 0 24 24" fill="currentColor">
                      <path d="M19 9l1.25-2.75L23 5l-2.75-1.25L19 1l-1.25 2.75L15 5l2.75 1.25L19 9zm-7.5 2.5L9 4 6.5 11.5 0 14l6.5 2.5L9 24l2.5-7.5L18 14l-6.5-2.5z"/>
                  </svg>
                </div>
                <div>
                  <h1 className="text-2xl font-extrabold text-white tracking-tight leading-none">
                    prepare<span className="text-brand-blue">AI</span>
                  </h1>
                  <p className="text-[10px] uppercase tracking-widest text-gray-400 font-semibold">By DevJs</p>
                </div>
            </div>

            {session && (
              <div className="flex items-center gap-6">
                <div className="text-right hidden sm:block">
                  <p className="text-gray-300 text-sm font-medium">{session.user.email}</p>
                </div>
                <div className="h-6 w-px bg-gray-700 hidden sm:block"></div>
                <div className="flex gap-4">
                    <button 
                      onClick={() => setCurrentView('profile')} 
                      className="text-gray-300 hover:text-brand-blue font-medium text-sm transition-colors relative group"
                    >
                        Profile
                        <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-brand-blue transition-all group-hover:w-full"></span>
                    </button>
                    <button 
                      onClick={handleLogout} 
                      className="text-gray-300 hover:text-brand-red font-medium text-sm transition-colors relative group"
                    >
                      Log out
                      <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-brand-red transition-all group-hover:w-full"></span>
                    </button>
                </div>
              </div>
            )}
         </div>
      </header>

      <main className="w-full max-w-7xl mx-auto p-6 flex-grow flex items-center justify-center animate-fade-in">
        {renderContent()}
      </main>

      <footer className="w-full py-6 text-center text-gray-500 text-xs">
         &copy; {new Date().getFullYear()} prepareAI. All rights reserved.
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { supabase } from '../services/supabaseClient';

interface LoginScreenProps {
  onSwitchToRegister: () => void;
}

const LoginScreen: React.FC<LoginScreenProps> = ({ onSwitchToRegister }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [view, setView] = useState<'login' | 'forgotPassword'>('login');

  useEffect(() => {
    // Parse URL for OAuth errors
    const handleAuthRedirectErrors = () => {
      const hashParams = new URLSearchParams(window.location.hash.substring(1));
      const searchParams = new URLSearchParams(window.location.search);
      const errorDescription = hashParams.get('error_description') || searchParams.get('error_description');

      if (errorDescription) {
        setError(decodeURIComponent(errorDescription).replace(/\+/g, ' '));
        window.history.replaceState(null, '', window.location.pathname);
      }
    };

    handleAuthRedirectErrors();
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase) return;
    setError(null);
    setMessage(null);
    setLoading(true);
    try {
      const { error } = await supabase.auth.signInWithPassword({ email, password });
      if (error) throw error;
    } catch (error: any) {
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    if (!supabase) return;
    setError(null);
    setLoading(true);

    const getRedirectUrl = () => {
        if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
            return window.location.origin;
        }
        return 'https://prepare-ai-six.vercel.app';
    };

    const redirectUrl = getRedirectUrl();

    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: redirectUrl,
          queryParams: {
            access_type: 'offline',
            prompt: 'consent',
          },
        },
      });
      if (error) throw error;
    } catch (error: any) {
      console.error("Google Login Error:", error);
      setError(error.message);
      setLoading(false);
    }
  };

  const handlePasswordReset = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase) return;
    setError(null);
    setMessage(null);
    setLoading(true);
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(email);
      if (error) throw error;
      setMessage('Password reset link sent! Please check your email.');
    } catch (error: any) {
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  if (view === 'forgotPassword') {
    return (
      <div className="glass-panel w-full max-w-md rounded-2xl p-8 shadow-2xl animate-fade-in relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-brand-yellow to-brand-red"></div>
        <h2 className="text-3xl font-bold mb-2 text-center text-white">Reset Password</h2>
        <p className="text-gray-400 mb-8 text-center text-sm">
          Enter your email to receive a recovery link.
        </p>
        <form onSubmit={handlePasswordReset} className="w-full space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 ml-1">Email</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="name@company.com"
              className="w-full bg-black/20 text-white px-4 py-3 rounded-xl border border-white/10 focus:outline-none focus:ring-2 focus:ring-brand-blue focus:border-transparent transition-all"
              required
            />
          </div>
          {error && <p className="text-brand-red text-sm bg-brand-red/10 p-3 rounded border border-brand-red/20">{error}</p>}
          {message && <p className="text-brand-green text-sm bg-brand-green/10 p-3 rounded border border-brand-green/20">{message}</p>}
          <button
            type="submit"
            disabled={loading}
            className="w-full bg-brand-yellow hover:bg-yellow-400 text-black font-bold py-3.5 rounded-xl transition-all shadow-lg hover:shadow-brand-yellow/20 focus:ring-4 focus:ring-brand-yellow/30 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? 'Sending...' : 'Send Reset Link'}
          </button>
        </form>
        <p className="text-gray-400 mt-8 text-sm text-center">
          Remembered your password?{' '}
          <button 
            onClick={() => {
              setView('login');
              setError(null);
              setMessage(null);
            }} 
            className="text-brand-blue hover:text-blue-300 font-semibold transition-colors">
            Back to Login
          </button>
        </p>
      </div>
    );
  }

  return (
    <div className="glass-panel w-full max-w-md rounded-2xl p-8 shadow-2xl animate-fade-in relative overflow-hidden">
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-brand-blue to-brand-purple"></div>
      <h2 className="text-3xl font-bold mb-2 text-center text-white">Welcome Back</h2>
      <p className="text-gray-400 mb-8 text-center text-sm">
        Log in to continue your interview practice.
      </p>
      <form onSubmit={handleLogin} className="w-full space-y-5">
        <div className="space-y-1">
            <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 ml-1">Email</label>
            <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="name@company.com"
            className="w-full bg-black/20 text-white px-4 py-3 rounded-xl border border-white/10 focus:outline-none focus:ring-2 focus:ring-brand-blue focus:border-transparent transition-all"
            required
            />
        </div>
        <div className="space-y-1">
            <div className="flex justify-between items-center ml-1">
                <label className="text-xs font-semibold uppercase tracking-wider text-gray-500">Password</label>
                <button
                    type="button"
                    onClick={() => {
                        setView('forgotPassword');
                        setError(null);
                        setMessage(null);
                    }}
                    className="text-xs text-brand-blue hover:text-blue-300 transition-colors"
                >
                    Forgot Password?
                </button>
            </div>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              className="w-full bg-black/20 text-white px-4 py-3 rounded-xl border border-white/10 focus:outline-none focus:ring-2 focus:ring-brand-blue focus:border-transparent transition-all"
              required
            />
        </div>

        {error && (
            <div className="w-full bg-brand-red/10 border border-brand-red/30 rounded-lg p-3 text-sm">
                <p className="text-brand-red font-semibold">Login Error</p>
                <p className="text-gray-300 text-xs mt-1">{error}</p>
                {(error.includes('redirect') || error.toLowerCase().includes('google')) && (
                    <p className="text-[10px] text-gray-400 mt-2 p-2 bg-black/20 rounded">
                        Ensure <code>https://prepare-ai-six.vercel.app</code> is in Supabase Redirect URLs.
                    </p>
                )}
            </div>
        )}

        <button
          type="submit"
          disabled={loading}
          className="w-full bg-brand-blue hover:bg-blue-500 text-white font-bold py-3.5 rounded-xl transition-all shadow-lg hover:shadow-brand-blue/25 focus:ring-4 focus:ring-brand-blue/30 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {loading ? 'Logging in...' : 'Log In'}
        </button>
      </form>

      <div className="flex items-center w-full my-6">
        <div className="flex-grow h-px bg-gray-700"></div>
        <span className="px-4 text-gray-500 text-xs font-medium uppercase">Or continue with</span>
        <div className="flex-grow h-px bg-gray-700"></div>
      </div>

      <button
        type="button"
        onClick={handleGoogleLogin}
        disabled={loading}
        className="w-full bg-white hover:bg-gray-100 text-gray-900 font-bold py-3.5 px-4 rounded-xl transition-all focus:outline-none focus:ring-4 focus:ring-gray-500/30 flex items-center justify-center gap-3 disabled:opacity-70 disabled:cursor-not-allowed"
      >
