const AiStatusIndicator: React.FC<{ status: string }> = ({ status }) => {
  let text = 'Connecting...';
  let colorClass = 'text-gray-400';
  let dotClass = 'bg-gray-400';

  if (status === 'listening') {
    text = 'Listening';
    colorClass = 'text-brand-blue';
    dotClass = 'bg-brand-blue';
  } else if (status === 'speaking') {
    text = 'Speaking';
    colorClass = 'text-brand-green';
    dotClass = 'bg-brand-green';
  } else if (status === 'thinking') {
    text = 'Thinking';
    colorClass = 'text-brand-yellow';
    dotClass = 'bg-brand-yellow';
  }

  return (
    <div className="flex items-center gap-3 px-4 py-2 bg-black/60 backdrop-blur-md rounded-full border border-white/10 shadow-lg">
      <span className={`relative flex h-3 w-3`}>
        {status !== 'connecting' && <span className={`animate-ping absolute inline-flex h-full w-full rounded-full ${dotClass} opacity-75`}></span>}
        <span className={`relative inline-flex rounded-full h-3 w-3 ${dotClass}`}></span>
      </span>
      <span className={`text-xs font-bold uppercase tracking-wider ${colorClass}`}>{text}</span>
    </div>
  );
};

