        </div>

        <div className="flex flex-col md:flex-row gap-8 flex-1 overflow-hidden">
             {/* Inputs */}
             <div className="md:w-1/3 flex flex-col gap-4">
                 <div>
                    <label className="block text-sm font-semibold text-gray-400 mb-1">Applying for Role</label>
