                        placeholder="e.g. UX Designer"
                    />
                </div>
                 <div>
                    <label className="block text-sm font-semibold text-gray-400 mb-1">Company Name</label>
                    <input 
                        type="text" 
                        value={company} 
                        onChange={(e) => setCompany(e.target.value)} 
                        className="w-full bg-black/30 border border-white/10 rounded-lg p-3 text-white focus:ring-2 focus:ring-brand-green outline-none"
                        placeholder="e.g. Acme Corp"
                    />
