                <div className="flex-1">
                    <label className="block text-sm font-semibold text-gray-400 mb-1">Why you? (Keywords/Background)</label>
                    <textarea 
                        value={background} 
                        onChange={(e) => setBackground(e.target.value)} 
                        className="w-full h-full bg-black/30 border border-white/10 rounded-lg p-3 text-white focus:ring-2 focus:ring-brand-green outline-none resize-none"
                        placeholder="5 years exp, passion for clean design, award winner..."
