    }
  }, [session.user]);

  useEffect(() => {
    fetchProfileData();
  }, [fetchProfileData]);

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase || !session.user) return;
    try {
      setLoading(true);
      const { error } = await supabase.from('profiles').upsert({
        id: session.user.id,
        full_name: profile.full_name,
        pronouns: profile.pronouns,
        avatar_url: profile.avatar_url,
        updated_at: new Date().toISOString(),
      });
      if (error) throw error;
      setIsEditingProfile(false);
    } catch (err: any) {
      console.error("Error updating profile:", err);
      setError(`Failed to update profile: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleAvatarUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    if (!event.target.files || event.target.files.length === 0 || !supabase) return;
    setUploadingAvatar(true);
    try {
        const file = event.target.files[0];
        const fileExt = file.name.split('.').pop();
        const fileName = `${session.user.id}.${fileExt}`;
        const filePath = `${fileName}`;

        const { error: uploadError } = await supabase.storage
            .from('avatars')
            .upload(filePath, file, { upsert: true });

        if (uploadError) throw uploadError;

        const { data: { publicUrl } } = supabase.storage
            .from('avatars')
            .getPublicUrl(filePath);

        setProfile(prev => ({ ...prev, avatar_url: publicUrl }));

        await supabase.from('profiles').upsert({
            id: session.user.id,
            avatar_url: publicUrl,
            updated_at: new Date().toISOString(),
        });

    } catch (error: any) {
        alert('Error uploading avatar: ' + error.message);
    } finally {
        setUploadingAvatar(false);
    }
  };

  // --- Document Management Functions ---

  const handleOpenDoc = (doc: DocViewerState) => {
      setViewingDoc(doc);
      setEditTitle(doc.title);
      setEditContent(doc.content);
      setIsEditingDoc(false);
  };

  const handleCloseDoc = () => {
      setViewingDoc(null);
      setIsEditingDoc(false);
  };

  const handleDownloadDoc = () => {
      if (!viewingDoc) return;

      if (viewingDoc.type === 'cv') {
          // Download CV via Print Window
          const printWindow = window.open('', '', 'width=800,height=900');
          if (printWindow) {
              printWindow.document.write(`
                <html>
                  <head>
                    <title>${viewingDoc.title}</title>
                    <style>
                      body { margin: 0; padding: 0; background: white; -webkit-print-color-adjust: exact; font-family: sans-serif; }
                      @page { size: A4; margin: 0; }
                      @media print {
                        body { -webkit-print-color-adjust: exact; }
                      }
                    </style>
                  </head>
                  <body>
                    ${viewingDoc.content}
                  </body>
                </html>
              `);
              printWindow.document.close();
              printWindow.focus();
              printWindow.print();
          }
      } else {
          // Download Letter as .txt
          const element = document.createElement("a");
          const file = new Blob([viewingDoc.content], {type: 'text/plain'});
          element.href = URL.createObjectURL(file);
          element.download = `${viewingDoc.title.replace(/\s+/g, '_')}.txt`;
          document.body.appendChild(element);
          element.click();
          document.body.removeChild(element);
      }
  };

  const handleDeleteDoc = async () => {
      if (!viewingDoc || !supabase) return;
      if (!window.confirm("Are you sure you want to delete this document? This cannot be undone.")) return;

      try {
          const table = viewingDoc.type === 'cv' ? 'cvs' : 'motivation_letters';
          const { error } = await supabase.from(table).delete().eq('id', viewingDoc.id);

          if (error) throw error;

          // Update local state
          if (viewingDoc.type === 'cv') {
              setSavedCVs(prev => prev.filter(cv => cv.id !== viewingDoc.id));
          } else {
              setSavedLetters(prev => prev.filter(letter => letter.id !== viewingDoc.id));
          }
          handleCloseDoc();
      } catch (err: any) {
          alert("Error deleting document: " + err.message);
      }
  };

  const handleSaveDocUpdates = async () => {
      if (!viewingDoc || !supabase) return;
      setIsSavingDoc(true);

      try {
          const table = viewingDoc.type === 'cv' ? 'cvs' : 'motivation_letters';

          const updates = {
              title: editTitle,
              content: editContent,
              // for CVs, we strictly rely on content (HTML) string updates here, not the JSON data payload
          };

          const { error } = await supabase.from(table).update(updates).eq('id', viewingDoc.id);
          if (error) throw error;

          // Update local state list
          if (viewingDoc.type === 'cv') {
              setSavedCVs(prev => prev.map(cv => cv.id === viewingDoc.id ? { ...cv, ...updates } : cv));
          } else {
              setSavedLetters(prev => prev.map(l => l.id === viewingDoc.id ? { ...l, ...updates } : l));
          }

          // Update viewing doc state
          setViewingDoc(prev => prev ? { ...prev, title: editTitle, content: editContent } : null);
          setIsEditingDoc(false);

      } catch (err: any) {
          alert("Failed to update: " + err.message);
      } finally {
          setIsSavingDoc(false);
      }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-[50vh]">
        <div className="w-12 h-12 border-4 border-brand-blue border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  // Render Interview Report View
  if (selectedInterview) {
    return (
      <div className="w-full max-w-7xl mx-auto space-y-6">
        <button onClick={() => setSelectedInterview(null)} className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors font-medium">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" /></svg>
            Back to Dashboard
        </button>
        <EndScreen
          onRestart={() => setSelectedInterview(null)}
          transcription={selectedInterview.transcription || []}
          feedback={selectedInterview.feedback || []}
          config={selectedInterview.config}
          userEmail={session.user.email || ''}
          userId={session.user.id}
          existingReport={selectedInterview.report || undefined}
          existingResources={selectedInterview.resources || undefined}
          isHistoryView={true}
        />
      </div>
    );
  }

  // Render Saved Document Modal
  if (viewingDoc) {
      return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4 animate-fade-in">
            <div className="bg-white text-black w-full max-w-4xl max-h-[90vh] rounded-2xl overflow-hidden flex flex-col shadow-2xl relative">

                {/* Modal Header */}
                <div className="p-4 bg-gray-100 border-b flex justify-between items-center shrink-0">
                    <div className="flex-1 mr-4">
                        {isEditingDoc ? (
                            <input 
                                type="text" 
                                value={editTitle}
                                onChange={(e) => setEditTitle(e.target.value)}
                                className="w-full px-3 py-1.5 border border-gray-300 rounded focus:ring-2 focus:ring-brand-blue outline-none font-bold text-lg"
                                placeholder="Document Title"
                            />
                        ) : (
                            <h3 className="font-bold text-lg truncate">{viewingDoc.title}</h3>
                        )}
                    </div>
                    <button onClick={handleCloseDoc} className="p-2 hover:bg-gray-200 rounded-full transition-colors text-gray-600">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                {/* Modal Body */}
                <div className="flex-1 overflow-y-auto p-8 custom-scrollbar bg-gray-50">
                    {isEditingDoc ? (
                         viewingDoc.type === 'cv' ? (
                            <div className="h-full flex flex-col gap-2">
                                <label className="text-sm font-semibold text-gray-500">HTML Source Code (Edit cautiously)</label>
                                <textarea 
                                    value={editContent}
                                    onChange={(e) => setEditContent(e.target.value)}
                                    className="flex-1 w-full p-4 font-mono text-sm border rounded-lg bg-white focus:ring-2 focus:ring-brand-blue outline-none resize-none"
                                />
                            </div>
                         ) : (
                            <textarea 
                                value={editContent}
                                onChange={(e) => setEditContent(e.target.value)}
                                className="w-full h-full p-6 font-serif text-lg leading-relaxed border rounded-lg bg-white focus:ring-2 focus:ring-brand-green outline-none resize-none"
                            />
                         )
                    ) : (
                        viewingDoc.type === 'cv' ? (
                            <div className="resume-preview shadow-lg bg-white mx-auto max-w-[210mm] origin-top" dangerouslySetInnerHTML={{ __html: viewingDoc.content }} />
                        ) : (
                            <div className="whitespace-pre-wrap font-serif text-lg leading-relaxed max-w-3xl mx-auto bg-white p-8 shadow-sm">{viewingDoc.content}</div>
                        )
                    )}
                </div>

                {/* Modal Footer (Actions) */}
                <div className="p-4 bg-white border-t flex justify-between items-center shrink-0">
                    <div className="flex items-center gap-2">
                         {!isEditingDoc && (
                             <button onClick={handleDeleteDoc} className="flex items-center gap-2 px-4 py-2 text-red-500 hover:bg-red-50 rounded-lg font-medium transition-colors border border-transparent hover:border-red-100">
                                 <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                 Delete
                             </button>
                         )}
                    </div>

                    <div className="flex items-center gap-3">
                         {isEditingDoc ? (
                             <>
                                <button 
                                    onClick={() => { setIsEditingDoc(false); setEditTitle(viewingDoc.title); setEditContent(viewingDoc.content); }}
                                    className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg font-medium"
                                >
                                    Cancel
                                </button>
                                <button 
                                    onClick={handleSaveDocUpdates}
                                    disabled={isSavingDoc}
                                    className={`px-6 py-2 rounded-lg font-bold text-white shadow-md transition-all ${viewingDoc.type === 'cv' ? 'bg-brand-purple hover:bg-purple-600' : 'bg-brand-green hover:bg-green-600'}`}
                                >
                                    {isSavingDoc ? 'Saving...' : 'Save Changes'}
                                </button>
                             </>
                         ) : (
                             <>
                                <button 
                                    onClick={handleDownloadDoc}
                                    className="flex items-center gap-2 px-4 py-2 text-gray-700 hover:bg-gray-100 rounded-lg font-medium transition-colors border border-gray-200"
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                    Download
                                </button>
                                <button 
                                    onClick={() => setIsEditingDoc(true)}
                                    className={`flex items-center gap-2 px-6 py-2 rounded-lg font-bold text-white shadow-md transition-all ${viewingDoc.type === 'cv' ? 'bg-brand-purple hover:bg-purple-600' : 'bg-brand-green hover:bg-green-600'}`}
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                                    Edit
                                </button>
                             </>
                         )}
                    </div>
                </div>
            </div>
        </div>
      );
  }

  return (
    <div className="w-full max-w-5xl mx-auto space-y-8 animate-fade-in pb-12">
      <div className="flex items-center gap-3">
          <button onClick={onBack} className="p-2 rounded-lg hover:bg-white/10 transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
          </button>
          <h2 className="text-3xl font-bold text-white">Your Profile</h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {/* User Card */}
          <div className="glass-panel p-8 rounded-2xl flex flex-col items-center text-center h-fit">
              <div className="relative group">
                  <div className="w-32 h-32 rounded-full bg-gradient-to-br from-brand-blue to-brand-purple flex items-center justify-center text-5xl font-bold text-white shadow-xl mb-6 ring-4 ring-white/10 overflow-hidden">
                      {profile.avatar_url ? (
                          <img src={profile.avatar_url} alt="Profile" className="w-full h-full object-cover" />
                      ) : (
                          <span>{profile.full_name ? profile.full_name.charAt(0).toUpperCase() : session.user.email?.charAt(0).toUpperCase()}</span>
                      )}
                  </div>
                  <label className="absolute inset-0 rounded-full bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer">
                      <span className="text-xs font-bold text-white">{uploadingAvatar ? '...' : 'Change'}</span>
                      <input type="file" accept="image/*" className="hidden" onChange={handleAvatarUpload} disabled={uploadingAvatar} />
                  </label>
              </div>

              {isEditingProfile ? (
                  <form onSubmit={handleUpdateProfile} className="w-full space-y-4">
                      <input
                          type="text"
                          value={profile.full_name}
                          onChange={(e) => setProfile({ ...profile, full_name: e.target.value })}
                          className="w-full bg-black/20 border border-white/10 rounded-lg px-4 py-2 text-white focus:ring-2 focus:ring-brand-blue outline-none"
                          placeholder="Full Name"
                      />
                      <input
                          type="text"
                          value={profile.pronouns}
                          onChange={(e) => setProfile({ ...profile, pronouns: e.target.value })}
                          className="w-full bg-black/20 border border-white/10 rounded-lg px-4 py-2 text-white focus:ring-2 focus:ring-brand-blue outline-none"
                          placeholder="Pronouns"
                      />
                      <div className="flex gap-2 justify-center pt-2">
                          <button type="button" onClick={() => setIsEditingProfile(false)} className="px-4 py-2 text-sm text-gray-400 hover:text-white">Cancel</button>
                          <button type="submit" className="px-4 py-2 bg-brand-blue rounded-lg text-sm font-bold text-white shadow-lg">Save</button>
                      </div>
                  </form>
              ) : (
                  <>
                    <h3 className="text-xl font-bold text-white mb-1">{profile.full_name || 'Anonymous User'}</h3>
                    <p className="text-gray-400 text-sm mb-2">{session.user.email}</p>
                    {profile.pronouns && <span className="px-3 py-1 rounded-full bg-white/5 text-xs text-gray-300 border border-white/10">{profile.pronouns}</span>}
                    <button onClick={() => setIsEditingProfile(true)} className="mt-6 text-brand-blue hover:text-blue-300 text-sm font-semibold transition-colors">Edit Profile</button>
                  </>
              )}
          </div>

          {/* Tabs & Content */}
          <div className="md:col-span-2 space-y-6">
              <div className="flex gap-4 border-b border-white/10 pb-2 overflow-x-auto">
                  <button 
                    onClick={() => setActiveTab('history')}
                    className={`pb-2 text-sm font-bold transition-colors whitespace-nowrap ${activeTab === 'history' ? 'text-brand-blue border-b-2 border-brand-blue' : 'text-gray-400 hover:text-white'}`}
                  >
                      Session History
                  </button>
                  <button 
                    onClick={() => setActiveTab('cvs')}
                    className={`pb-2 text-sm font-bold transition-colors whitespace-nowrap ${activeTab === 'cvs' ? 'text-brand-purple border-b-2 border-brand-purple' : 'text-gray-400 hover:text-white'}`}
                  >
                      Saved CVs
                  </button>
                  <button 
                    onClick={() => setActiveTab('letters')}
                    className={`pb-2 text-sm font-bold transition-colors whitespace-nowrap ${activeTab === 'letters' ? 'text-brand-green border-b-2 border-brand-green' : 'text-gray-400 hover:text-white'}`}
                  >
                      Motivation Letters
                  </button>
              </div>

              {error && <p className="text-red-400 bg-red-500/10 p-4 rounded-xl border border-red-500/20">{error}</p>}

              <div className="space-y-4 min-h-[300px]">
                  {/* HISTORY TAB */}
                  {activeTab === 'history' && (
                      interviews.length > 0 ? interviews.map((interview) => (
                          <div 
                            key={interview.id} 
                            onClick={() => setSelectedInterview(interview)}
                            className="glass-panel p-6 rounded-xl hover:bg-white/5 transition-all cursor-pointer group border border-white/5 hover:border-brand-blue/30 relative overflow-hidden"
                          >
                              <div className="absolute inset-y-0 left-0 w-1 bg-gradient-to-b from-brand-blue to-brand-purple opacity-0 group-hover:opacity-100 transition-opacity"></div>
                              <div className="flex justify-between items-center">
                                  <div>
                                      <h4 className="text-lg font-bold text-white group-hover:text-brand-blue transition-colors mb-1">{interview.config?.name || 'Session'}</h4>
                                      <p className="text-sm text-gray-500">{new Date(interview.created_at).toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
                                  </div>
                                  <div className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center group-hover:bg-brand-blue/20 transition-colors">
                                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400 group-hover:text-brand-blue" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" /></svg>
                                  </div>
                              </div>
                          </div>
                      )) : (
                          <div className="glass-panel p-10 rounded-xl text-center">
                              <p className="text-gray-400 mb-4">No sessions recorded yet.</p>
                              <button onClick={onBack} className="bg-white text-black font-bold py-2 px-6 rounded-lg hover:bg-gray-200 transition-colors">Start Practice</button>
                          </div>
                      )
                  )}

                  {/* CVs TAB */}
                  {activeTab === 'cvs' && (
                      savedCVs.length > 0 ? savedCVs.map((cv) => (
                          <div 
                            key={cv.id} 
                            onClick={() => handleOpenDoc({ id: cv.id, type: 'cv', content: cv.content, title: cv.title, originalData: cv.data })}
                            className="glass-panel p-6 rounded-xl hover:bg-white/5 transition-all cursor-pointer group border border-white/5 hover:border-brand-purple/30 relative overflow-hidden"
                          >
                              <div className="absolute inset-y-0 left-0 w-1 bg-brand-purple opacity-0 group-hover:opacity-100 transition-opacity"></div>
                              <div className="flex justify-between items-center">
                                  <div>
                                      <h4 className="text-lg font-bold text-white group-hover:text-brand-purple transition-colors mb-1">{cv.title}</h4>
                                      <p className="text-sm text-gray-500">{new Date(cv.created_at).toLocaleDateString()}</p>
                                  </div>
                                  <button className="text-xs bg-white/10 hover:bg-brand-purple/50 px-3 py-1 rounded text-white transition-colors">View / Edit</button>
                              </div>
                          </div>
                      )) : (
                          <div className="glass-panel p-10 rounded-xl text-center">
                              <p className="text-gray-400">No saved resumes found.</p>
                          </div>
                      )
                  )}

                  {/* LETTERS TAB */}
                  {activeTab === 'letters' && (
                      savedLetters.length > 0 ? savedLetters.map((letter) => (
                          <div 
                            key={letter.id} 
                            onClick={() => handleOpenDoc({ id: letter.id, type: 'letter', content: letter.content, title: letter.company })}
                            className="glass-panel p-6 rounded-xl hover:bg-white/5 transition-all cursor-pointer group border border-white/5 hover:border-brand-green/30 relative overflow-hidden"
                          >
                              <div className="absolute inset-y-0 left-0 w-1 bg-brand-green opacity-0 group-hover:opacity-100 transition-opacity"></div>
                              <div className="flex justify-between items-center">
                                  <div>
                                      <h4 className="text-lg font-bold text-white group-hover:text-brand-green transition-colors mb-1">{letter.company}</h4>
                                      <p className="text-sm text-gray-300">{letter.job_title}</p>
                                      <p className="text-xs text-gray-500 mt-1">{new Date(letter.created_at).toLocaleDateString()}</p>
                                  </div>
                                  <button className="text-xs bg-white/10 hover:bg-brand-green/50 px-3 py-1 rounded text-white transition-colors">View / Edit</button>
                              </div>
                          </div>
                      )) : (
                          <div className="glass-panel p-10 rounded-xl text-center">
                              <p className="text-gray-400">No saved cover letters found.</p>
                          </div>
                      )
                  )}
              </div>
          </div>
      </div>
    </div>
  );
};

export default ProfileScreen;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Session } from '@supabase/supabase-js';
import { supabase } from '../services/supabaseClient';
import type { InterviewConfig, TranscriptionEntry, FeedbackEntry, InterviewReport, SuggestedResource, SavedCV, SavedLetter } from '../types';
import EndScreen from './EndScreen';

interface Profile {
  full_name: string;
  pronouns: string;
  avatar_url: string;
}

interface InterviewHistoryItem {
  id: string;
  created_at: string;
  config: InterviewConfig;
  transcription: TranscriptionEntry[];
  feedback: FeedbackEntry[];
  report: InterviewReport | null;
  resources: SuggestedResource[] | null;
}

interface ProfileScreenProps {
  session: Session;
  onBack: () => void;
}

type TabView = 'history' | 'cvs' | 'letters';

// Extended type to handle viewing/editing
interface DocViewerState {
  id: string;
  type: 'cv' | 'letter';
  content: string;
  title: string;
  originalData?: any; 
}

const ProfileScreen: React.FC<ProfileScreenProps> = ({ session, onBack }) => {
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<Profile>({ full_name: '', pronouns: '', avatar_url: '' });
  const [interviews, setInterviews] = useState<InterviewHistoryItem[]>([]);
  const [savedCVs, setSavedCVs] = useState<SavedCV[]>([]);
  const [savedLetters, setSavedLetters] = useState<SavedLetter[]>([]);

  const [selectedInterview, setSelectedInterview] = useState<InterviewHistoryItem | null>(null);

  // Document Viewing/Editing State
  const [viewingDoc, setViewingDoc] = useState<DocViewerState | null>(null);
  const [isEditingDoc, setIsEditingDoc] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editContent, setEditContent] = useState('');
  const [isSavingDoc, setIsSavingDoc] = useState(false);

  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [activeTab, setActiveTab] = useState<TabView>('history');
  const [error, setError] = useState<string | null>(null);
  const [uploadingAvatar, setUploadingAvatar] = useState(false);

  const fetchProfileData = useCallback(async () => {
    if (!supabase || !session.user) {
        setLoading(false);
        return;
    }
    setLoading(true);
    setError(null);

    try {
      try {
        const { data, error } = await supabase
          .from('profiles')
          .select('full_name, pronouns, avatar_url')
          .eq('id', session.user.id)
          .maybeSingle(); 

        if (error) {
            if (error.code === '42703') {
                console.warn("Database missing avatar_url column. Falling back to basic profile.");
                const { data: basicData, error: basicError } = await supabase
                    .from('profiles')
                    .select('full_name, pronouns')
                    .eq('id', session.user.id)
                    .maybeSingle();

                if (basicError) throw basicError;
                if (basicData) {
                    setProfile({ 
                        full_name: basicData.full_name || '', 
                        pronouns: basicData.pronouns || '',
                        avatar_url: '' 
                    });
                }
            } else {
                throw error;
            }
        } else if (data) {
             setProfile({ 
                full_name: data.full_name || '', 
                pronouns: data.pronouns || '',
                avatar_url: data.avatar_url || ''
            });
        }
      } catch (profileErr) { console.warn("Profile fetch warning:", profileErr); }

      const { data: interviewData } = await supabase
        .from('interviews')
        .select('*')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false })
        .limit(10);
      setInterviews(interviewData || []);

      const { data: cvData } = await supabase
        .from('cvs')
        .select('*')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false });
      setSavedCVs(cvData || []);

      const { data: letterData } = await supabase
        .from('motivation_letters')
        .select('*')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false });
      setSavedLetters(letterData || []);

    } catch (err: any) {
      console.error("Error fetching data:", err);
      setError("Failed to load data. Please try again.");
    } finally {
      setLoading(false);
    }
  }, [session.user]);

  useEffect(() => {
    fetchProfileData();
  }, [fetchProfileData]);

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase || !session.user) return;
    try {
      setLoading(true);
      const { error } = await supabase.from('profiles').upsert({
        id: session.user.id,
        full_name: profile.full_name,
        pronouns: profile.pronouns,
        avatar_url: profile.avatar_url,
        updated_at: new Date().toISOString(),
      });
      if (error) throw error;
      setIsEditingProfile(false);
    } catch (err: any) {
      console.error("Error updating profile:", err);
      setError(`Failed to update profile: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleAvatarUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    if (!event.target.files || event.target.files.length === 0 || !supabase) return;
    setUploadingAvatar(true);
    try {
        const file = event.target.files[0];
        const fileExt = file.name.split('.').pop();
        const fileName = `${session.user.id}.${fileExt}`;
        const filePath = `${fileName}`;

        const { error: uploadError } = await supabase.storage
            .from('avatars')
            .upload(filePath, file, { upsert: true });

        if (uploadError) throw uploadError;

        const { data: { publicUrl } } = supabase.storage
            .from('avatars')
            .getPublicUrl(filePath);

        setProfile(prev => ({ ...prev, avatar_url: publicUrl }));

        await supabase.from('profiles').upsert({
            id: session.user.id,
            avatar_url: publicUrl,
            updated_at: new Date().toISOString(),
        });

    } catch (error: any) {
        if (error.message && (error.message.includes("Bucket not found") || error.statusCode === '404')) {
            alert("Configuration Error: The 'avatars' storage bucket does not exist. Please run the STORAGE SETUP SQL script found in README.md.");
        } else {
            alert('Error uploading avatar: ' + error.message);
        }
    } finally {
        setUploadingAvatar(false);
    }
  };

  // --- Document Management Functions ---

  const handleOpenDoc = (doc: DocViewerState) => {
      setViewingDoc(doc);
      setEditTitle(doc.title);
      setEditContent(doc.content);
      setIsEditingDoc(false);
  };

  const handleCloseDoc = () => {
      setViewingDoc(null);
      setIsEditingDoc(false);
  };

  const handleDownloadDoc = () => {
      if (!viewingDoc) return;

      if (viewingDoc.type === 'cv') {
          // Download CV via Print Window
          const printWindow = window.open('', '', 'width=800,height=900');
          if (printWindow) {
              printWindow.document.write(`
                <html>
                  <head>
                    <title>${viewingDoc.title}</title>
                    <style>
                      body { margin: 0; padding: 0; background: white; -webkit-print-color-adjust: exact; font-family: sans-serif; }
                      @page { size: A4; margin: 0; }
                      @media print {
                        body { -webkit-print-color-adjust: exact; }
                      }
                    </style>
                  </head>
                  <body>
                    ${viewingDoc.content}
                  </body>
                </html>
              `);
              printWindow.document.close();
              printWindow.focus();
              printWindow.print();
          }
      } else {
          // Download Letter as .txt
          const element = document.createElement("a");
          const file = new Blob([viewingDoc.content], {type: 'text/plain'});
          element.href = URL.createObjectURL(file);
          element.download = `${viewingDoc.title.replace(/\s+/g, '_')}.txt`;
          document.body.appendChild(element);
          element.click();
          document.body.removeChild(element);
      }
  };

  const handleDeleteDoc = async () => {
      if (!viewingDoc || !supabase) return;
      if (!window.confirm("Are you sure you want to delete this document? This cannot be undone.")) return;

      try {
          const table = viewingDoc.type === 'cv' ? 'cvs' : 'motivation_letters';
          const { error } = await supabase.from(table).delete().eq('id', viewingDoc.id);

          if (error) throw error;

          // Update local state
          if (viewingDoc.type === 'cv') {
              setSavedCVs(prev => prev.filter(cv => cv.id !== viewingDoc.id));
          } else {
              setSavedLetters(prev => prev.filter(letter => letter.id !== viewingDoc.id));
          }
          handleCloseDoc();
      } catch (err: any) {
          alert("Error deleting document: " + err.message);
      }
  };

  const handleSaveDocUpdates = async () => {
      if (!viewingDoc || !supabase) return;
      setIsSavingDoc(true);

      try {
          const table = viewingDoc.type === 'cv' ? 'cvs' : 'motivation_letters';

          const updates = {
              title: editTitle,
              content: editContent,
              // for CVs, we strictly rely on content (HTML) string updates here, not the JSON data payload
          };

          const { error } = await supabase.from(table).update(updates).eq('id', viewingDoc.id);
          if (error) throw error;

          // Update local state list
          if (viewingDoc.type === 'cv') {
              setSavedCVs(prev => prev.map(cv => cv.id === viewingDoc.id ? { ...cv, ...updates } : cv));
          } else {
              setSavedLetters(prev => prev.map(l => l.id === viewingDoc.id ? { ...l, ...updates } : l));
          }

          // Update viewing doc state
          setViewingDoc(prev => prev ? { ...prev, title: editTitle, content: editContent } : null);
          setIsEditingDoc(false);

      } catch (err: any) {
          alert("Failed to update: " + err.message);
      } finally {
          setIsSavingDoc(false);
      }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-[50vh]">
        <div className="w-12 h-12 border-4 border-brand-blue border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  // Render Interview Report View
  if (selectedInterview) {
    return (
      <div className="w-full max-w-7xl mx-auto space-y-6">
        <button onClick={() => setSelectedInterview(null)} className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors font-medium">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" /></svg>
            Back to Dashboard
        </button>
        <EndScreen
          onRestart={() => setSelectedInterview(null)}
          transcription={selectedInterview.transcription || []}
          feedback={selectedInterview.feedback || []}
          config={selectedInterview.config}
          userEmail={session.user.email || ''}
          userId={session.user.id}
          existingReport={selectedInterview.report || undefined}
          existingResources={selectedInterview.resources || undefined}
          isHistoryView={true}
        />
      </div>
    );
  }

  // Render Saved Document Modal
  if (viewingDoc) {
      return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4 animate-fade-in">
            <div className="bg-white text-black w-full max-w-4xl max-h-[90vh] rounded-2xl overflow-hidden flex flex-col shadow-2xl relative">

                {/* Modal Header */}
                <div className="p-4 bg-gray-100 border-b flex justify-between items-center shrink-0">
                    <div className="flex-1 mr-4">
                        {isEditingDoc ? (
                            <input 
                                type="text" 
                                value={editTitle}
                                onChange={(e) => setEditTitle(e.target.value)}
                                className="w-full px-3 py-1.5 border border-gray-300 rounded focus:ring-2 focus:ring-brand-blue outline-none font-bold text-lg"
                                placeholder="Document Title"
                            />
                        ) : (
                            <h3 className="font-bold text-lg truncate">{viewingDoc.title}</h3>
                        )}
                    </div>
                    <button onClick={handleCloseDoc} className="p-2 hover:bg-gray-200 rounded-full transition-colors text-gray-600">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                {/* Modal Body */}
                <div className="flex-1 overflow-y-auto p-8 custom-scrollbar bg-gray-50">
                    {isEditingDoc ? (
                         viewingDoc.type === 'cv' ? (
                            <div className="h-full flex flex-col gap-2">
                                <label className="text-sm font-semibold text-gray-500">HTML Source Code (Edit cautiously)</label>
                                <textarea 
                                    value={editContent}
                                    onChange={(e) => setEditContent(e.target.value)}
                                    className="flex-1 w-full p-4 font-mono text-sm border rounded-lg bg-white focus:ring-2 focus:ring-brand-blue outline-none resize-none"
                                />
                            </div>
                         ) : (
                            <textarea 
                                value={editContent}
                                onChange={(e) => setEditContent(e.target.value)}
                                className="w-full h-full p-6 font-serif text-lg leading-relaxed border rounded-lg bg-white focus:ring-2 focus:ring-brand-green outline-none resize-none"
                            />
                         )
                    ) : (
                        viewingDoc.type === 'cv' ? (
                            <div className="resume-preview shadow-lg bg-white mx-auto max-w-[210mm] origin-top" dangerouslySetInnerHTML={{ __html: viewingDoc.content }} />
                        ) : (
                            <div className="whitespace-pre-wrap font-serif text-lg leading-relaxed max-w-3xl mx-auto bg-white p-8 shadow-sm">{viewingDoc.content}</div>
                        )
                    )}
                </div>

                {/* Modal Footer (Actions) */}
                <div className="p-4 bg-white border-t flex justify-between items-center shrink-0">
                    <div className="flex items-center gap-2">
                         {!isEditingDoc && (
                             <button onClick={handleDeleteDoc} className="flex items-center gap-2 px-4 py-2 text-red-500 hover:bg-red-50 rounded-lg font-medium transition-colors border border-transparent hover:border-red-100">
                                 <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                 Delete
                             </button>
                         )}
                    </div>

                    <div className="flex items-center gap-3">
                         {isEditingDoc ? (
                             <>
                                <button 
                                    onClick={() => { setIsEditingDoc(false); setEditTitle(viewingDoc.title); setEditContent(viewingDoc.content); }}
                                    className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg font-medium"
                                >
                                    Cancel
                                </button>
                                <button 
                                    onClick={handleSaveDocUpdates}
                                    disabled={isSavingDoc}
                                    className={`px-6 py-2 rounded-lg font-bold text-white shadow-md transition-all ${viewingDoc.type === 'cv' ? 'bg-brand-purple hover:bg-purple-600' : 'bg-brand-green hover:bg-green-600'}`}
                                >
                                    {isSavingDoc ? 'Saving...' : 'Save Changes'}
                                </button>
                             </>
                         ) : (
                             <>
                                <button 
                                    onClick={handleDownloadDoc}
                                    className="flex items-center gap-2 px-4 py-2 text-gray-700 hover:bg-gray-100 rounded-lg font-medium transition-colors border border-gray-200"
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                    Download
                                </button>
                                <button 
                                    onClick={() => setIsEditingDoc(true)}
                                    className={`flex items-center gap-2 px-6 py-2 rounded-lg font-bold text-white shadow-md transition-all ${viewingDoc.type === 'cv' ? 'bg-brand-purple hover:bg-purple-600' : 'bg-brand-green hover:bg-green-600'}`}
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                                    Edit
                                </button>
                             </>
                         )}
                    </div>
                </div>
            </div>
        </div>
      );
  }

  return (
    <div className="w-full max-w-5xl mx-auto space-y-8 animate-fade-in pb-12">
      <div className="flex items-center gap-3">
          <button onClick={onBack} className="p-2 rounded-lg hover:bg-white/10 transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
          </button>
          <h2 className="text-3xl font-bold text-white">Your Profile</h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {/* User Card */}
          <div className="glass-panel p-8 rounded-2xl flex flex-col items-center text-center h-fit">
              <div className="relative group">
                  <div className="w-32 h-32 rounded-full bg-gradient-to-br from-brand-blue to-brand-purple flex items-center justify-center text-5xl font-bold text-white shadow-xl mb-6 ring-4 ring-white/10 overflow-hidden">
                      {profile.avatar_url ? (
                          <img src={profile.avatar_url} alt="Profile" className="w-full h-full object-cover" />
                      ) : (
                          <span>{profile.full_name ? profile.full_name.charAt(0).toUpperCase() : session.user.email?.charAt(0).toUpperCase()}</span>
                      )}
                  </div>
                  <label className="absolute inset-0 rounded-full bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer">
                      <span className="text-xs font-bold text-white">{uploadingAvatar ? '...' : 'Change'}</span>
                      <input type="file" accept="image/*" className="hidden" onChange={handleAvatarUpload} disabled={uploadingAvatar} />
                  </label>
              </div>

              {isEditingProfile ? (
                  <form onSubmit={handleUpdateProfile} className="w-full space-y-4">
                      <input
                          type="text"
                          value={profile.full_name}
                          onChange={(e) => setProfile({ ...profile, full_name: e.target.value })}
                          className="w-full bg-black/20 border border-white/10 rounded-lg px-4 py-2 text-white focus:ring-2 focus:ring-brand-blue outline-none"
                          placeholder="Full Name"
                      />
                      <input
                          type="text"
                          value={profile.pronouns}
                          onChange={(e) => setProfile({ ...profile, pronouns: e.target.value })}
                          className="w-full bg-black/20 border border-white/10 rounded-lg px-4 py-2 text-white focus:ring-2 focus:ring-brand-blue outline-none"
                          placeholder="Pronouns"
                      />
                      <div className="flex gap-2 justify-center pt-2">
                          <button type="button" onClick={() => setIsEditingProfile(false)} className="px-4 py-2 text-sm text-gray-400 hover:text-white">Cancel</button>
                          <button type="submit" className="px-4 py-2 bg-brand-blue rounded-lg text-sm font-bold text-white shadow-lg">Save</button>
                      </div>
                  </form>
              ) : (
                  <>
                    <h3 className="text-xl font-bold text-white mb-1">{profile.full_name || 'Anonymous User'}</h3>
                    <p className="text-gray-400 text-sm mb-2">{session.user.email}</p>
                    {profile.pronouns && <span className="px-3 py-1 rounded-full bg-white/5 text-xs text-gray-300 border border-white/10">{profile.pronouns}</span>}
                    <button onClick={() => setIsEditingProfile(true)} className="mt-6 text-brand-blue hover:text-blue-300 text-sm font-semibold transition-colors">Edit Profile</button>
                  </>
              )}
          </div>

          {/* Tabs & Content */}
          <div className="md:col-span-2 space-y-6">
              <div className="flex gap-4 border-b border-white/10 pb-2 overflow-x-auto">
                  <button 
                    onClick={() => setActiveTab('history')}
                    className={`pb-2 text-sm font-bold transition-colors whitespace-nowrap ${activeTab === 'history' ? 'text-brand-blue border-b-2 border-brand-blue' : 'text-gray-400 hover:text-white'}`}
                  >
                      Session History
                  </button>
                  <button 
                    onClick={() => setActiveTab('cvs')}
                    className={`pb-2 text-sm font-bold transition-colors whitespace-nowrap ${activeTab === 'cvs' ? 'text-brand-purple border-b-2 border-brand-purple' : 'text-gray-400 hover:text-white'}`}
                  >
                      Saved CVs
                  </button>
                  <button 
                    onClick={() => setActiveTab('letters')}
                    className={`pb-2 text-sm font-bold transition-colors whitespace-nowrap ${activeTab === 'letters' ? 'text-brand-green border-b-2 border-brand-green' : 'text-gray-400 hover:text-white'}`}
                  >
                      Motivation Letters
                  </button>
              </div>

              {error && <p className="text-red-400 bg-red-500/10 p-4 rounded-xl border border-red-500/20">{error}</p>}

              <div className="space-y-4 min-h-[300px]">
                  {/* HISTORY TAB */}
                  {activeTab === 'history' && (
                      interviews.length > 0 ? interviews.map((interview) => (
                          <div 
                            key={interview.id} 
                            onClick={() => setSelectedInterview(interview)}
                            className="glass-panel p-6 rounded-xl hover:bg-white/5 transition-all cursor-pointer group border border-white/5 hover:border-brand-blue/30 relative overflow-hidden"
                          >
                              <div className="absolute inset-y-0 left-0 w-1 bg-gradient-to-b from-brand-blue to-brand-purple opacity-0 group-hover:opacity-100 transition-opacity"></div>
                              <div className="flex justify-between items-center">
                                  <div>
                                      <h4 className="text-lg font-bold text-white group-hover:text-brand-blue transition-colors mb-1">{interview.config?.name || 'Session'}</h4>
                                      <p className="text-sm text-gray-500">{new Date(interview.created_at).toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
                                  </div>
                                  <div className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center group-hover:bg-brand-blue/20 transition-colors">
                                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400 group-hover:text-brand-blue" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" /></svg>
                                  </div>
                              </div>
                          </div>
                      )) : (
                          <div className="glass-panel p-10 rounded-xl text-center">
                              <p className="text-gray-400 mb-4">No sessions recorded yet.</p>
                              <button onClick={onBack} className="bg-white text-black font-bold py-2 px-6 rounded-lg hover:bg-gray-200 transition-colors">Start Practice</button>
                          </div>
                      )
                  )}

                  {/* CVs TAB */}
                  {activeTab === 'cvs' && (
                      savedCVs.length > 0 ? savedCVs.map((cv) => (
                          <div 
                            key={cv.id} 
                            onClick={() => handleOpenDoc({ id: cv.id, type: 'cv', content: cv.content, title: cv.title, originalData: cv.data })}
                            className="glass-panel p-6 rounded-xl hover:bg-white/5 transition-all cursor-pointer group border border-white/5 hover:border-brand-purple/30 relative overflow-hidden"
                          >
                              <div className="absolute inset-y-0 left-0 w-1 bg-brand-purple opacity-0 group-hover:opacity-100 transition-opacity"></div>
                              <div className="flex justify-between items-center">
                                  <div>
                                      <h4 className="text-lg font-bold text-white group-hover:text-brand-purple transition-colors mb-1">{cv.title}</h4>
                                      <p className="text-sm text-gray-500">{new Date(cv.created_at).toLocaleDateString()}</p>
                                  </div>
                                  <button className="text-xs bg-white/10 hover:bg-brand-purple/50 px-3 py-1 rounded text-white transition-colors">View / Edit</button>
                              </div>
                          </div>
                      )) : (
                          <div className="glass-panel p-10 rounded-xl text-center">
                              <p className="text-gray-400">No saved resumes found.</p>
                          </div>
                      )
                  )}

                  {/* LETTERS TAB */}
                  {activeTab === 'letters' && (
                      savedLetters.length > 0 ? savedLetters.map((letter) => (
                          <div 
                            key={letter.id} 
                            onClick={() => handleOpenDoc({ id: letter.id, type: 'letter', content: letter.content, title: letter.company })}
                            className="glass-panel p-6 rounded-xl hover:bg-white/5 transition-all cursor-pointer group border border-white/5 hover:border-brand-green/30 relative overflow-hidden"
                          >
                              <div className="absolute inset-y-0 left-0 w-1 bg-brand-green opacity-0 group-hover:opacity-100 transition-opacity"></div>
                              <div className="flex justify-between items-center">
                                  <div>
                                      <h4 className="text-lg font-bold text-white group-hover:text-brand-green transition-colors mb-1">{letter.company}</h4>
                                      <p className="text-sm text-gray-300">{letter.job_title}</p>
                                      <p className="text-xs text-gray-500 mt-1">{new Date(letter.created_at).toLocaleDateString()}</p>
                                  </div>
                                  <button className="text-xs bg-white/10 hover:bg-brand-green/50 px-3 py-1 rounded text-white transition-colors">View / Edit</button>
                              </div>
                          </div>
                      )) : (
                          <div className="glass-panel p-10 rounded-xl text-center">
                              <p className="text-gray-400">No saved cover letters found.</p>
                          </div>
                      )
                  )}
              </div>
          </div>
      </div>
    </div>
  );
};

export default ProfileScreen;

import React, { useState, useCallback, useEffect } from 'react';
import type { Session } from '@supabase/supabase-js';
import { InterviewStatus, InterviewConfig, TranscriptionEntry, FeedbackEntry, SavedCV } from './types';
import { supabase } from './services/supabaseClient';
import Dashboard from './components/WelcomeScreen'; // Renamed WelcomeScreen to behave as Dashboard
import InterviewSetup from './components/InterviewSetup';
import InterviewScreen from './components/InterviewScreen';
import EndScreen from './components/EndScreen';
import AuthScreen from './components/AuthScreen';
import ProfileScreen from './components/ProfileScreen';
import CVBuilder from './components/CVBuilder';
import MotivationLetter from './components/MotivationLetter';

type AppView = 'dashboard' | 'interview-setup' | 'cv-builder' | 'motivation-letter' | 'profile';

const App: React.FC = () => {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [interviewStatus, setInterviewStatus] = useState<InterviewStatus>(InterviewStatus.NotStarted);
  const [interviewConfig, setInterviewConfig] = useState<InterviewConfig | null>(null);
  const [isPracticeMode, setIsPracticeMode] = useState(false);
  const [finalTranscription, setFinalTranscription] = useState<TranscriptionEntry[]>([]);
  const [finalFeedback, setFinalFeedback] = useState<FeedbackEntry[]>([]);
  const [currentView, setCurrentView] = useState<AppView>('dashboard');
  const [isDesktop, setIsDesktop] = useState(true);

  // State for CV Editing
  const [editingCV, setEditingCV] = useState<SavedCV | null>(null);

  // Check for desktop screen size
  useEffect(() => {
    const checkScreenSize = () => {
      setIsDesktop(window.innerWidth >= 1024);
    };

    // Initial check
    checkScreenSize();

    window.addEventListener('resize', checkScreenSize);
    return () => window.removeEventListener('resize', checkScreenSize);
  }, []);

  useEffect(() => {
    if (!supabase) {
      console.warn("Supabase client not initialized.");
      setLoading(false);
      return;
    }

    setLoading(true);
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setLoading(false);
    }).catch(err => {
      console.error("Error getting session:", err);
      setLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (_event === 'SIGNED_OUT') {
        // Reset app state on logout
        setInterviewStatus(InterviewStatus.NotStarted);
        setInterviewConfig(null);
        setFinalTranscription([]);
        setFinalFeedback([]);
        setCurrentView('dashboard');
        setEditingCV(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);


  const handleStartInterview = useCallback((selectedConfig: InterviewConfig, practiceMode: boolean) => {
    setInterviewConfig(selectedConfig);
    setIsPracticeMode(practiceMode);
    setInterviewStatus(InterviewStatus.InProgress);
  }, []);

  const handleEndInterview = useCallback((transcription: TranscriptionEntry[], feedback: FeedbackEntry[]) => {
    if (isPracticeMode) {
      setInterviewStatus(InterviewStatus.NotStarted);
      setInterviewConfig(null);
      setCurrentView('dashboard');
    } else {
      setFinalTranscription(transcription);
      setFinalFeedback(feedback);
      setInterviewStatus(InterviewStatus.Finished);
    }
  }, [isPracticeMode]);

  const handleRestart = useCallback(() => {
    setInterviewStatus(InterviewStatus.NotStarted);
    setInterviewConfig(null);
    setFinalTranscription([]);
    setFinalFeedback([]);
    setIsPracticeMode(false);
    setCurrentView('dashboard');
  }, []);

  const handleEditCV = useCallback((cv: SavedCV) => {
      setEditingCV(cv);
      setCurrentView('cv-builder');
  }, []);

  const handleLogout = async () => {
    if (supabase) {
      await supabase.auth.signOut();
    }
  };

  const renderContent = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-brand-blue"></div>
          <p className="mt-6 text-lg font-medium text-gray-300">Initializing Experience...</p>
        </div>
      );
    }

    if (!session) {
      return <AuthScreen />;
    }

    // Active Interview overrides everything
    if (interviewStatus === InterviewStatus.InProgress) {
        if (!interviewConfig) return <Dashboard onNavigate={setCurrentView} userName={session.user.email} />;
        return <InterviewScreen onEnd={handleEndInterview} config={interviewConfig} isPracticeMode={isPracticeMode} />;
    }

    if (interviewStatus === InterviewStatus.Finished) {
         if (!interviewConfig) return <Dashboard onNavigate={setCurrentView} userName={session.user.email} />;
         return <EndScreen 
           onRestart={handleRestart} 
           transcription={finalTranscription} 
           feedback={finalFeedback} 
           config={interviewConfig} 
           userEmail={session.user.email || ''} 
           userId={session.user.id}
         />;
    }

    // Main Navigation
    switch (currentView) {
      case 'interview-setup':
        return <InterviewSetup onStart={handleStartInterview} onBack={() => setCurrentView('dashboard')} />;
      case 'cv-builder':
        return <CVBuilder 
            onBack={() => { setCurrentView('dashboard'); setEditingCV(null); }} 
            initialData={editingCV?.data}
            cvId={editingCV?.id}
        />;
      case 'motivation-letter':
        return <MotivationLetter onBack={() => setCurrentView('dashboard')} />;
      case 'profile':
        return <ProfileScreen session={session} onBack={() => setCurrentView('dashboard')} onEditCV={handleEditCV} />;
      case 'dashboard':
      default:
        return <Dashboard onNavigate={setCurrentView} userName={session.user.email} />;
    }
  };

  if (!isDesktop) {
    return (
        <div className="min-h-screen bg-dark-bg flex flex-col items-center justify-center p-6 text-center relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-blue-900/40 via-dark-bg to-dark-bg -z-10"></div>
            <div className="glass-panel w-full max-w-md rounded-2xl p-8 border border-white/10 shadow-2xl backdrop-blur-xl">
                <div className="w-20 h-20 bg-brand-blue/20 rounded-full flex items-center justify-center mx-auto mb-6 ring-4 ring-brand-blue/10">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-brand-blue" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                    </svg>
                </div>
                <h1 className="text-2xl font-bold text-white mb-3 tracking-tight">Desktop Experience</h1>
                <p className="text-gray-300 mb-6 leading-relaxed">
                    For the most immersive AI interview practice, please access <strong>prepareAI</strong> on a desktop or laptop computer.
                </p>
                <div className="bg-black/30 rounded-lg p-4 text-sm text-gray-400 border border-white/5">
                    <p>Mobile devices are not currently supported to ensure optimal camera and screen performance.</p>
                </div>
            </div>
        </div>
    );
  }

  return (
    <div className="min-h-screen relative flex flex-col items-center">
       {/* Global Background Elements */}
       <div className="fixed inset-0 overflow-hidden pointer-events-none -z-10">
          <div className="absolute -top-40 -left-40 w-96 h-96 bg-brand-blue/30 rounded-full mix-blend-screen filter blur-[100px] opacity-30 animate-blob"></div>
          <div className="absolute top-20 right-20 w-80 h-80 bg-brand-purple/30 rounded-full mix-blend-screen filter blur-[100px] opacity-30 animate-blob animation-delay-2000"></div>
          <div className="absolute -bottom-40 left-1/2 w-96 h-96 bg-brand-green/20 rounded-full mix-blend-screen filter blur-[100px] opacity-30 animate-blob animation-delay-4000"></div>
          <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10"></div>
       </div>

       <header className="w-full sticky top-0 z-50 backdrop-blur-xl bg-dark-bg/60 border-b border-white/5 shadow-lg">
         <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
            <div className="flex items-center gap-3 cursor-pointer" onClick={() => setCurrentView('dashboard')}>
                <div className="relative">
                  <div className="absolute inset-0 bg-brand-blue blur-lg opacity-40 rounded-full"></div>
                  <svg xmlns="http://www.w3.org/2000/svg" className="relative h-8 w-8 text-white" viewBox="0 0 24 24" fill="currentColor">
                      <path d="M19 9l1.25-2.75L23 5l-2.75-1.25L19 1l-1.25 2.75L15 5l2.75 1.25L19 9zm-7.5 2.5L9 4 6.5 11.5 0 14l6.5 2.5L9 24l2.5-7.5L18 14l-6.5-2.5z"/>
                  </svg>
                </div>
                <div>
                  <h1 className="text-2xl font-extrabold text-white tracking-tight leading-none">
                    prepare<span className="text-brand-blue">AI</span>
                  </h1>
                  <p className="text-[10px] uppercase tracking-widest text-gray-400 font-semibold">By DevJs</p>
                </div>
            </div>

            {session && (
              <div className="flex items-center gap-6">
                <div className="text-right hidden sm:block">
                  <p className="text-gray-300 text-sm font-medium">{session.user.email}</p>
                </div>
                <div className="h-6 w-px bg-gray-700 hidden sm:block"></div>
                <div className="flex gap-4">
                    <button 
                      onClick={() => setCurrentView('profile')} 
                      className={`text-sm font-medium transition-colors relative group ${currentView === 'profile' ? 'text-brand-blue' : 'text-gray-300 hover:text-brand-blue'}`}
                    >
                        Profile
                        <span className={`absolute -bottom-1 left-0 h-0.5 bg-brand-blue transition-all ${currentView === 'profile' ? 'w-full' : 'w-0 group-hover:w-full'}`}></span>
                    </button>
                    <button 
                      onClick={handleLogout} 
                      className="text-gray-300 hover:text-brand-red font-medium text-sm transition-colors relative group"
                    >
                      Log out
                      <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-brand-red transition-all group-hover:w-full"></span>
                    </button>
                </div>
              </div>
            )}
         </div>
      </header>

      <main className="w-full max-w-7xl mx-auto p-6 flex-grow flex items-center justify-center animate-fade-in">
        {renderContent()}
      </main>

      <footer className="w-full py-6 text-center text-gray-500 text-xs">
         &copy; {new Date().getFullYear()} prepareAI. All rights reserved.
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { supabase } from '../services/supabaseClient';

interface CVBuilderProps {
  onBack: () => void;
  initialData?: any;
  cvId?: string;
}

const CVBuilder: React.FC<CVBuilderProps> = ({ onBack, initialData, cvId }) => {
  const [personalInfo, setPersonalInfo] = useState({
    fullName: '',
    email: '',
    phone: '',
    linkedin: '',
    location: '',
    photo: null as string | null
  });
  const [targetRole, setTargetRole] = useState('');
  const [experience, setExperience] = useState('');
  const [education, setEducation] = useState('');
  const [skills, setSkills] = useState('');

  const [generatedCV, setGeneratedCV] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [zoom, setZoom] = useState(0.65); 
  const previewRef = useRef<HTMLDivElement>(null);

  const [currentCvId, setCurrentCvId] = useState<string | undefined>(cvId);

  useEffect(() => {
    if (initialData) {
        setPersonalInfo(initialData.personalInfo || {
            fullName: '', email: '', phone: '', linkedin: '', location: '', photo: null
        });
        setTargetRole(initialData.targetRole || '');
        setExperience(initialData.experience || '');
        setEducation(initialData.education || '');
        setSkills(initialData.skills || '');

        // If we are editing an existing CV, we might want to regenerate to see the preview
        // OR we can assume the user needs to click generate. 
        // ideally if we stored the 'content' we could pass it in props to show preview immediately.
        // For now, let's trigger generation if we have data so the user sees something, 
        // OR simpler: Just let them click generate. They are here to edit anyway.
        // Better UX: If we have content, show it. But CVBuilder props only pass initialData (the inputs).
        // Let's rely on user clicking Generate for now to keep things simple and ensure WYSIWYG based on inputs.
    }
  }, [initialData]);

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPersonalInfo(prev => ({ ...prev, photo: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!process.env.API_KEY) {
        alert("API Key missing");
        return;
    }
    setIsGenerating(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const photoInstruction = personalInfo.photo 
            ? "The user has provided a profile photo. Include an <img src='{{PHOTO_SRC}}' alt='Profile Photo' class='profile-photo' /> in the header or sidebar. Style it to be circular or rounded-square, max width 100px, with appropriate margins."
            : "Do not include a photo.";

        const prompt = `
          You are an expert Resume Writer. Create a professional, ATS-optimized resume for the following candidate.

          STRICT REQUIREMENT: The resume MUST fit on a single A4 page.
          - Prioritize a compact, high-density layout.
          - Use a 10pt or 11pt font size for body text.
          - Reduce margins and padding where appropriate (e.g. 15-20px margins).
          - Be concise with bullet points. 

          CANDIDATE PROFILE:
          Name: ${personalInfo.fullName}
          Contact: ${personalInfo.email} | ${personalInfo.phone} | ${personalInfo.location}
          Links: ${personalInfo.linkedin}
          Target Role: ${targetRole}

          ${photoInstruction}

          EXPERIENCE NOTES:
          ${experience}

          EDUCATION NOTES:
          ${education}

          SKILLS LIST:
          ${skills}

          INSTRUCTIONS:
          1. Return ONLY the HTML code for the resume. 
          2. Use modern, clean, professional inline CSS styles. 
          3. The container div should have a white background, black text (#000000), and simulate an A4 page (width: 100%; height: 100%; box-sizing: border-box;).
          4. Font MUST be 'Helvetica', 'Arial', sans-serif. ensure text is crisp and high contrast.
          5. Structure: 
             - Header (Name, Contact, Photo if applicable).
             - Professional Summary (Keep it short, max 3 lines).
             - Skills (Consider a sidebar or multi-column grid to save vertical space).
             - Experience (Rewrite notes into strong, concise STAR-method bullet points).
             - Education.
          6. Do not include markdown code blocks (like \`\`\`html). Just return the raw HTML string.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
        });

        let cleanHtml = response.text || '';
        // Cleanup potential markdown formatting
        cleanHtml = cleanHtml.replace(/^```html\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '');

        // Inject photo if available
        if (personalInfo.photo) {
            cleanHtml = cleanHtml.replace('{{PHOTO_SRC}}', personalInfo.photo);
        }

        setGeneratedCV(cleanHtml);
    } catch (error) {
        console.error(error);
        alert("Failed to generate CV. Please try again.");
    } finally {
        setIsGenerating(false);
    }
  };

  const handleSave = async () => {
      if (!generatedCV) return;
      if (!supabase) {
          alert("Database connection not available.");
          return;
      }

      setIsSaving(true);
      try {
          const { data: { user } } = await supabase.auth.getUser();
          if (!user) {
              alert("You must be logged in to save.");
              return;
          }

          const payload = {
              title: `${targetRole || 'Resume'} - ${new Date().toLocaleDateString()}`,
              content: generatedCV,
              data: { personalInfo, targetRole, experience, education, skills }
          };

          if (currentCvId) {
              const { error } = await supabase.from('cvs').update(payload).eq('id', currentCvId);
              if (error) throw error;
              alert("Resume updated successfully!");
          } else {
              const { data, error } = await supabase.from('cvs').insert({ ...payload, user_id: user.id }).select();
              if (error) throw error;
              if (data && data[0]) {
                  setCurrentCvId(data[0].id);
              }
              alert("Resume saved successfully to your profile!");
          }

      } catch (err: any) {
          console.error("Error saving CV:", err);
          alert("Failed to save resume: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const handlePrint = () => {
    if (!previewRef.current) return;
    const printWindow = window.open('', '', 'width=800,height=900');
    if (printWindow) {
      printWindow.document.write(`
        <html>
          <head>
            <title>Resume - ${personalInfo.fullName || 'Candidate'}</title>
            <style>
              body { margin: 0; padding: 0; background: white; -webkit-print-color-adjust: exact; font-family: sans-serif; }
              @page { size: A4; margin: 0; }
              @media print {
                body { -webkit-print-color-adjust: exact; }
              }
            </style>
          </head>
          <body>
            ${generatedCV}
          </body>
        </html>
      `);
      printWindow.document.close();
      printWindow.focus();
      printWindow.print();
    }
  };

  return (
    <div className="w-full max-w-[1600px] h-[90vh] flex flex-col glass-panel rounded-2xl overflow-hidden animate-fade-in shadow-2xl">
        {/* Header */}
        <div className="h-16 border-b border-white/10 bg-black/20 flex items-center justify-between px-6 shrink-0 backdrop-blur-md">
            <div className="flex items-center gap-4">
                <button onClick={onBack} className="p-2 rounded-lg hover:bg-white/10 transition-colors text-gray-400 hover:text-white">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" /></svg>
                </button>
                <h2 className="text-xl font-bold text-white tracking-tight">{currentCvId ? 'Edit Resume' : 'AI Resume Builder'}</h2>
            </div>
            <div className="flex items-center gap-3">
                 {generatedCV && (
                    <>
                        <button 
                            onClick={handleSave}
                            disabled={isSaving}
                            className="flex items-center gap-2 px-4 py-2 bg-brand-green/20 hover:bg-brand-green/30 border border-brand-green/50 rounded-lg text-sm font-medium transition-colors text-brand-green"
                        >
                            {isSaving ? 'Saving...' : (currentCvId ? 'Update Profile' : 'Save to Profile')}
                        </button>
                        <button 
                            onClick={handlePrint}
                            className="flex items-center gap-2 px-4 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-sm font-medium transition-colors text-white"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                            Print / PDF
                        </button>
                    </>
                 )}
                 <button 
                    onClick={handleGenerate}
                    disabled={isGenerating || !personalInfo.fullName}
                    className="flex items-center gap-2 px-6 py-2 bg-gradient-to-r from-brand-purple to-purple-600 hover:from-purple-500 hover:to-purple-700 rounded-lg text-sm font-bold text-white shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                 >
                    {isGenerating ? (
                        <>
                         <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                         Generating...
                        </>
                    ) : (
                        <>
                         <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                         Generate Resume
                        </>
                    )}
                 </button>
            </div>
        </div>

        {/* Main Content */}
        <div className="flex-1 flex flex-col lg:flex-row overflow-hidden bg-black/40">

            {/* Input Panel (Left) */}
            <div className="lg:w-[400px] xl:w-[450px] flex flex-col border-r border-white/5 bg-black/20 overflow-y-auto custom-scrollbar p-6 space-y-8">

                {/* Personal Info Section */}
                <div className="space-y-4">
                    <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-brand-blue"></span>
                        Personal Details
                    </h3>
                    <div className="flex items-center gap-4 mb-2">
                        <div className="w-16 h-16 rounded-full bg-white/5 border border-white/10 flex items-center justify-center overflow-hidden shrink-0">
                            {personalInfo.photo ? (
                                <img src={personalInfo.photo} alt="Preview" className="w-full h-full object-cover" />
                            ) : (
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                            )}
                        </div>
                        <div>
                             <label className="block text-xs text-gray-400 mb-1 cursor-pointer hover:text-white transition-colors">
                                 Upload Photo
                                 <input type="file" accept="image/*" className="hidden" onChange={handlePhotoUpload} />
                             </label>
                             <p className="text-[10px] text-gray-600">Recommended: Square JPG/PNG</p>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 gap-4">
                        <input 
                            type="text" 
                            placeholder="Full Name" 
                            value={personalInfo.fullName}
                            onChange={(e) => setPersonalInfo({...personalInfo, fullName: e.target.value})}
                            className="bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple focus:border-brand-purple outline-none transition-all"
                        />
                         <div className="grid grid-cols-2 gap-3">
                            <input 
                                type="text" 
                                placeholder="Email" 
                                value={personalInfo.email}
                                onChange={(e) => setPersonalInfo({...personalInfo, email: e.target.value})}
                                className="bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none"
                            />
                            <input 
                                type="text" 
                                placeholder="Phone" 
                                value={personalInfo.phone}
                                onChange={(e) => setPersonalInfo({...personalInfo, phone: e.target.value})}
                                className="bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none"
                            />
                        </div>
                        <input 
                            type="text" 
                            placeholder="Location (City, Country)" 
                            value={personalInfo.location}
                            onChange={(e) => setPersonalInfo({...personalInfo, location: e.target.value})}
                            className="bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none"
                        />
                        <input 
                            type="text" 
                            placeholder="LinkedIn / Portfolio URL" 
                            value={personalInfo.linkedin}
                            onChange={(e) => setPersonalInfo({...personalInfo, linkedin: e.target.value})}
                            className="bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none"
                        />
                    </div>
                </div>

                {/* Target Role */}
                <div className="space-y-4">
                     <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-brand-purple"></span>
                        Target Role
                    </h3>
                    <input 
                        type="text" 
                        placeholder="e.g. Senior Frontend Engineer" 
                        value={targetRole}
                        onChange={(e) => setTargetRole(e.target.value)}
                        className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none"
                    />
                </div>

                {/* Experience */}
                <div className="space-y-4">
                     <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-brand-green"></span>
                        Professional Experience
                    </h3>
                    <textarea 
                        placeholder="Paste your work history here. Don't worry about formatting.&#10;&#10;e.g.&#10;Google - Software Engineer (2020-Present)&#10;- Built a scalable API&#10;- Led a team of 5" 
                        value={experience}
                        onChange={(e) => setExperience(e.target.value)}
                        className="w-full h-40 bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none resize-none custom-scrollbar leading-relaxed"
                    />
                </div>

                 {/* Education */}
                 <div className="space-y-4">
                     <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-brand-yellow"></span>
                        Education
                    </h3>
                    <textarea 
                        placeholder="e.g.&#10;Stanford University&#10;BS Computer Science, 2018" 
                        value={education}
                        onChange={(e) => setEducation(e.target.value)}
                        className="w-full h-24 bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none resize-none custom-scrollbar"
                    />
                </div>

                {/* Skills */}
                <div className="space-y-4">
                     <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-brand-red"></span>
                        Skills
                    </h3>
                    <textarea 
                        placeholder="e.g. JavaScript, React, Node.js, Project Management, Agile" 
                        value={skills}
                        onChange={(e) => setSkills(e.target.value)}
                        className="w-full h-24 bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none resize-none custom-scrollbar"
                    />
                </div>
            </div>

            {/* Preview Panel (Right) */}
            <div className="flex-1 bg-[#1a1a1a] p-8 overflow-y-auto flex justify-center items-start custom-scrollbar relative">

                {/* Zoom Controls */}
                {generatedCV && (
                    <div className="absolute top-6 right-6 z-10 flex items-center gap-2 bg-black/60 backdrop-blur-md p-1.5 rounded-lg border border-white/10 shadow-lg">
                        <button onClick={() => setZoom(z => Math.max(0.3, z - 0.1))} className="p-1.5 hover:bg-white/10 rounded text-white transition-colors" title="Zoom Out">
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" /></svg>
                        </button>
                        <span className="text-xs font-mono text-gray-300 w-12 text-center select-none">{Math.round(zoom * 100)}%</span>
                        <button onClick={() => setZoom(z => Math.min(2, z + 0.1))} className="p-1.5 hover:bg-white/10 rounded text-white transition-colors" title="Zoom In">
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                        </button>
                    </div>
                )}

                {generatedCV ? (
                     <div 
                        style={{ transform: `scale(${zoom})`, transformOrigin: 'top center' }}
                        className="transition-transform duration-200 ease-out origin-top"
                    >
                         <div 
                            ref={previewRef}
                            className="w-[210mm] min-h-[297mm] bg-white text-black shadow-2xl p-[15mm] box-border resume-preview"
                            dangerouslySetInnerHTML={{ __html: generatedCV }}
                        />
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center h-full text-gray-500 opacity-60">
                        <div className="w-24 h-32 border-2 border-dashed border-gray-600 rounded-lg flex items-center justify-center mb-4">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                            </svg>
                        </div>
                        <p className="text-lg font-medium">Your resume preview will appear here</p>
                        <p className="text-sm">Fill in the details on the left and click Generate</p>
                    </div>
                )}
            </div>
        </div>
    </div>
  );
};

export default CVBuilder;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Session } from '@supabase/supabase-js';
import { supabase } from '../services/supabaseClient';
import type { InterviewConfig, TranscriptionEntry, FeedbackEntry, InterviewReport, SuggestedResource, SavedCV, SavedLetter } from '../types';
import EndScreen from './EndScreen';

interface Profile {
  full_name: string;
  pronouns: string;
  avatar_url: string;
}

interface InterviewHistoryItem {
  id: string;
  created_at: string;
  config: InterviewConfig;
  transcription: TranscriptionEntry[];
  feedback: FeedbackEntry[];
  report: InterviewReport | null;
  resources: SuggestedResource[] | null;
}

interface ProfileScreenProps {
  session: Session;
  onBack: () => void;
  onEditCV: (cv: SavedCV) => void;
}

type TabView = 'history' | 'cvs' | 'letters';

// Extended type to handle viewing/editing
interface DocViewerState {
  id: string;
  type: 'cv' | 'letter';
  content: string;
  title: string;
  originalData?: any; 
}

const ProfileScreen: React.FC<ProfileScreenProps> = ({ session, onBack, onEditCV }) => {
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<Profile>({ full_name: '', pronouns: '', avatar_url: '' });
  const [interviews, setInterviews] = useState<InterviewHistoryItem[]>([]);
  const [savedCVs, setSavedCVs] = useState<SavedCV[]>([]);
  const [savedLetters, setSavedLetters] = useState<SavedLetter[]>([]);

  const [selectedInterview, setSelectedInterview] = useState<InterviewHistoryItem | null>(null);

  // Document Viewing/Editing State
  const [viewingDoc, setViewingDoc] = useState<DocViewerState | null>(null);
  const [isEditingDoc, setIsEditingDoc] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editContent, setEditContent] = useState('');
  const [isSavingDoc, setIsSavingDoc] = useState(false);

  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [activeTab, setActiveTab] = useState<TabView>('history');
  const [error, setError] = useState<string | null>(null);
  const [uploadingAvatar, setUploadingAvatar] = useState(false);

  const fetchProfileData = useCallback(async () => {
    if (!supabase || !session.user) {
        setLoading(false);
        return;
    }
    setLoading(true);
    setError(null);

    try {
      try {
        const { data, error } = await supabase
          .from('profiles')
          .select('full_name, pronouns, avatar_url')
          .eq('id', session.user.id)
          .maybeSingle(); 

        if (error) {
            if (error.code === '42703') {
                console.warn("Database missing avatar_url column. Falling back to basic profile.");
                const { data: basicData, error: basicError } = await supabase
                    .from('profiles')
                    .select('full_name, pronouns')
                    .eq('id', session.user.id)
                    .maybeSingle();

                if (basicError) throw basicError;
                if (basicData) {
                    setProfile({ 
                        full_name: basicData.full_name || '', 
                        pronouns: basicData.pronouns || '',
                        avatar_url: '' 
                    });
                }
            } else {
                throw error;
            }
        } else if (data) {
             setProfile({ 
                full_name: data.full_name || '', 
                pronouns: data.pronouns || '',
                avatar_url: data.avatar_url || ''
            });
        }
      } catch (profileErr) { console.warn("Profile fetch warning:", profileErr); }

      const { data: interviewData } = await supabase
        .from('interviews')
        .select('*')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false })
        .limit(10);
      setInterviews(interviewData || []);

      const { data: cvData } = await supabase
        .from('cvs')
        .select('*')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false });
      setSavedCVs(cvData || []);

      const { data: letterData } = await supabase
        .from('motivation_letters')
        .select('*')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false });
      setSavedLetters(letterData || []);

    } catch (err: any) {
      console.error("Error fetching data:", err);
      setError("Failed to load data. Please try again.");
    } finally {
      setLoading(false);
    }
  }, [session.user]);

  useEffect(() => {
    fetchProfileData();
  }, [fetchProfileData]);

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase || !session.user) return;
    try {
      setLoading(true);
      const { error } = await supabase.from('profiles').upsert({
        id: session.user.id,
        full_name: profile.full_name,
        pronouns: profile.pronouns,
        avatar_url: profile.avatar_url,
        updated_at: new Date().toISOString(),
      });
      if (error) throw error;
      setIsEditingProfile(false);
    } catch (err: any) {
      console.error("Error updating profile:", err);
      setError(`Failed to update profile: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleAvatarUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    if (!event.target.files || event.target.files.length === 0 || !supabase) return;
    setUploadingAvatar(true);
    try {
        const file = event.target.files[0];
        const fileExt = file.name.split('.').pop();
        const fileName = `${session.user.id}.${fileExt}`;
        const filePath = `${fileName}`;

        const { error: uploadError } = await supabase.storage
            .from('avatars')
            .upload(filePath, file, { upsert: true });

        if (uploadError) throw uploadError;

        const { data: { publicUrl } } = supabase.storage
            .from('avatars')
            .getPublicUrl(filePath);

        setProfile(prev => ({ ...prev, avatar_url: publicUrl }));

        await supabase.from('profiles').upsert({
            id: session.user.id,
            avatar_url: publicUrl,
            updated_at: new Date().toISOString(),
        });

    } catch (error: any) {
        if (error.message && (error.message.includes("Bucket not found") || error.statusCode === '404')) {
            alert("Configuration Error: The 'avatars' storage bucket does not exist. Please run the STORAGE SETUP SQL script found in README.md.");
        } else {
            alert('Error uploading avatar: ' + error.message);
        }
    } finally {
        setUploadingAvatar(false);
    }
  };

  // --- Document Management Functions ---

  const handleOpenDoc = (doc: DocViewerState) => {
      setViewingDoc(doc);
      setEditTitle(doc.title);
      setEditContent(doc.content);
      setIsEditingDoc(false);
  };

  const handleCloseDoc = () => {
      setViewingDoc(null);
      setIsEditingDoc(false);
  };

  const handleDownloadDoc = () => {
      if (!viewingDoc) return;

      if (viewingDoc.type === 'cv') {
          // Download CV via Print Window
          const printWindow = window.open('', '', 'width=800,height=900');
          if (printWindow) {
              printWindow.document.write(`
                <html>
                  <head>
                    <title>${viewingDoc.title}</title>
                    <style>
                      body { margin: 0; padding: 0; background: white; -webkit-print-color-adjust: exact; font-family: sans-serif; }
                      @page { size: A4; margin: 0; }
                      @media print {
                        body { -webkit-print-color-adjust: exact; }
                      }
                    </style>
                  </head>
                  <body>
                    ${viewingDoc.content}
                  </body>
                </html>
              `);
              printWindow.document.close();
              printWindow.focus();
              printWindow.print();
          }
      } else {
          // Download Letter as .txt
          const element = document.createElement("a");
          const file = new Blob([viewingDoc.content], {type: 'text/plain'});
          element.href = URL.createObjectURL(file);
          element.download = `${viewingDoc.title.replace(/\s+/g, '_')}.txt`;
          document.body.appendChild(element);
          element.click();
          document.body.removeChild(element);
      }
  };

  const handleDeleteDoc = async () => {
      if (!viewingDoc || !supabase) return;
      if (!window.confirm("Are you sure you want to delete this document? This cannot be undone.")) return;

      try {
          const table = viewingDoc.type === 'cv' ? 'cvs' : 'motivation_letters';
          const { error } = await supabase.from(table).delete().eq('id', viewingDoc.id);

          if (error) throw error;

          // Update local state
          if (viewingDoc.type === 'cv') {
              setSavedCVs(prev => prev.filter(cv => cv.id !== viewingDoc.id));
          } else {
              setSavedLetters(prev => prev.filter(letter => letter.id !== viewingDoc.id));
          }
          handleCloseDoc();
      } catch (err: any) {
          alert("Error deleting document: " + err.message);
      }
  };

  const handleEditClick = () => {
    if (viewingDoc?.type === 'cv') {
        const fullCV = savedCVs.find(c => c.id === viewingDoc.id);
        if (fullCV) {
            onEditCV(fullCV);
            return;
        }
    }
    // For letters, or fallback, toggle in-place editor
    setIsEditingDoc(true);
  };

  const handleSaveDocUpdates = async () => {
      if (!viewingDoc || !supabase) return;
      setIsSavingDoc(true);

      try {
          const table = viewingDoc.type === 'cv' ? 'cvs' : 'motivation_letters';

          const updates = {
              title: editTitle,
              content: editContent,
              // for CVs, we strictly rely on content (HTML) string updates here, not the JSON data payload
          };

          const { error } = await supabase.from(table).update(updates).eq('id', viewingDoc.id);
          if (error) throw error;

          // Update local state list
          if (viewingDoc.type === 'cv') {
              setSavedCVs(prev => prev.map(cv => cv.id === viewingDoc.id ? { ...cv, ...updates } : cv));
          } else {
              setSavedLetters(prev => prev.map(l => l.id === viewingDoc.id ? { ...l, ...updates } : l));
          }

          // Update viewing doc state
          setViewingDoc(prev => prev ? { ...prev, title: editTitle, content: editContent } : null);
          setIsEditingDoc(false);

      } catch (err: any) {
          alert("Failed to update: " + err.message);
      } finally {
          setIsSavingDoc(false);
      }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-[50vh]">
        <div className="w-12 h-12 border-4 border-brand-blue border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  // Render Interview Report View
  if (selectedInterview) {
    return (
      <div className="w-full max-w-7xl mx-auto space-y-6">
        <button onClick={() => setSelectedInterview(null)} className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors font-medium">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" /></svg>
            Back to Dashboard
        </button>
        <EndScreen
          onRestart={() => setSelectedInterview(null)}
          transcription={selectedInterview.transcription || []}
          feedback={selectedInterview.feedback || []}
          config={selectedInterview.config}
          userEmail={session.user.email || ''}
          userId={session.user.id}
          existingReport={selectedInterview.report || undefined}
          existingResources={selectedInterview.resources || undefined}
          isHistoryView={true}
        />
      </div>
    );
  }

  // Render Saved Document Modal
  if (viewingDoc) {
      return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4 animate-fade-in">
            <div className="bg-white text-black w-full max-w-4xl max-h-[90vh] rounded-2xl overflow-hidden flex flex-col shadow-2xl relative">

                {/* Modal Header */}
                <div className="p-4 bg-gray-100 border-b flex justify-between items-center shrink-0">
                    <div className="flex-1 mr-4">
                        {isEditingDoc ? (
                            <input 
                                type="text" 
                                value={editTitle}
                                onChange={(e) => setEditTitle(e.target.value)}
                                className="w-full px-3 py-1.5 border border-gray-300 rounded focus:ring-2 focus:ring-brand-blue outline-none font-bold text-lg"
                                placeholder="Document Title"
                            />
                        ) : (
                            <h3 className="font-bold text-lg truncate">{viewingDoc.title}</h3>
                        )}
                    </div>
                    <button onClick={handleCloseDoc} className="p-2 hover:bg-gray-200 rounded-full transition-colors text-gray-600">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                {/* Modal Body */}
                <div className="flex-1 overflow-y-auto p-8 custom-scrollbar bg-gray-50">
                    {isEditingDoc ? (
                         viewingDoc.type === 'cv' ? (
                            <div className="h-full flex flex-col gap-2">
                                <label className="text-sm font-semibold text-gray-500">HTML Source Code (Edit cautiously)</label>
                                <textarea 
                                    value={editContent}
                                    onChange={(e) => setEditContent(e.target.value)}
                                    className="flex-1 w-full p-4 font-mono text-sm border rounded-lg bg-white focus:ring-2 focus:ring-brand-blue outline-none resize-none"
                                />
                            </div>
                         ) : (
                            <textarea 
                                value={editContent}
                                onChange={(e) => setEditContent(e.target.value)}
                                className="w-full h-full p-6 font-serif text-lg leading-relaxed border rounded-lg bg-white focus:ring-2 focus:ring-brand-green outline-none resize-none"
                            />
                         )
                    ) : (
                        viewingDoc.type === 'cv' ? (
                            <div className="resume-preview shadow-lg bg-white mx-auto max-w-[210mm] origin-top" dangerouslySetInnerHTML={{ __html: viewingDoc.content }} />
                        ) : (
                            <div className="whitespace-pre-wrap font-serif text-lg leading-relaxed max-w-3xl mx-auto bg-white p-8 shadow-sm">{viewingDoc.content}</div>
                        )
                    )}
                </div>

                {/* Modal Footer (Actions) */}
                <div className="p-4 bg-white border-t flex justify-between items-center shrink-0">
                    <div className="flex items-center gap-2">
                         {!isEditingDoc && (
                             <button onClick={handleDeleteDoc} className="flex items-center gap-2 px-4 py-2 text-red-500 hover:bg-red-50 rounded-lg font-medium transition-colors border border-transparent hover:border-red-100">
                                 <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                 Delete
                             </button>
                         )}
                    </div>

                    <div className="flex items-center gap-3">
                         {isEditingDoc ? (
                             <>
                                <button 
                                    onClick={() => { setIsEditingDoc(false); setEditTitle(viewingDoc.title); setEditContent(viewingDoc.content); }}
                                    className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg font-medium"
                                >
                                    Cancel
                                </button>
                                <button 
                                    onClick={handleSaveDocUpdates}
                                    disabled={isSavingDoc}
                                    className={`px-6 py-2 rounded-lg font-bold text-white shadow-md transition-all ${viewingDoc.type === 'cv' ? 'bg-brand-purple hover:bg-purple-600' : 'bg-brand-green hover:bg-green-600'}`}
                                >
                                    {isSavingDoc ? 'Saving...' : 'Save Changes'}
                                </button>
                             </>
                         ) : (
                             <>
                                <button 
                                    onClick={handleDownloadDoc}
                                    className="flex items-center gap-2 px-4 py-2 text-gray-700 hover:bg-gray-100 rounded-lg font-medium transition-colors border border-gray-200"
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                    Download
                                </button>
                                <button 
                                    onClick={handleEditClick}
                                    className={`flex items-center gap-2 px-6 py-2 rounded-lg font-bold text-white shadow-md transition-all ${viewingDoc.type === 'cv' ? 'bg-brand-purple hover:bg-purple-600' : 'bg-brand-green hover:bg-green-600'}`}
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                                    Edit
                                </button>
                             </>
                         )}
                    </div>
                </div>
            </div>
        </div>
      );
  }

  return (
    <div className="w-full max-w-5xl mx-auto space-y-8 animate-fade-in pb-12">
      <div className="flex items-center gap-3">
          <button onClick={onBack} className="p-2 rounded-lg hover:bg-white/10 transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
          </button>
          <h2 className="text-3xl font-bold text-white">Your Profile</h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {/* User Card */}
          <div className="glass-panel p-8 rounded-2xl flex flex-col items-center text-center h-fit">
              <div className="relative group">
                  <div className="w-32 h-32 rounded-full bg-gradient-to-br from-brand-blue to-brand-purple flex items-center justify-center text-5xl font-bold text-white shadow-xl mb-6 ring-4 ring-white/10 overflow-hidden">
                      {profile.avatar_url ? (
                          <img src={profile.avatar_url} alt="Profile" className="w-full h-full object-cover" />
                      ) : (
                          <span>{profile.full_name ? profile.full_name.charAt(0).toUpperCase() : session.user.email?.charAt(0).toUpperCase()}</span>
                      )}
                  </div>
                  <label className="absolute inset-0 rounded-full bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer">
                      <span className="text-xs font-bold text-white">{uploadingAvatar ? '...' : 'Change'}</span>
