import React, { useState, useEffect } from 'react';
import { supabase } from '../services/supabaseClient';

interface RegistrationScreenProps {
  onSwitchToLogin: () => void;
  inviteToken?: string | null;
}

const RegistrationScreen: React.FC<RegistrationScreenProps> = ({ onSwitchToLogin, inviteToken }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  // If invite token is present, check validity and pre-fill email
  useEffect(() => {
      const checkInvite = async () => {
          if (!inviteToken || !supabase) return;
          const { data, error } = await supabase.from('invites').select('email').eq('token', inviteToken).eq('status', 'pending').maybeSingle();
          if (data) {
              setEmail(data.email);
          } else {
              setError("Invalid or expired invite link. You can still sign up as a normal user.");
          }
      };
      checkInvite();
  }, [inviteToken]);

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase) return;

    setError(null);
    setMessage(null);
    setLoading(true);
    try {
      const { data, error } = await supabase.auth.signUp({ 
          email, 
          password,
          options: {
              data: {
                  invite_token: inviteToken // Metadata to handle role assignment via Trigger (advanced) or manual update
              }
          }
      });
      if (error) throw error;

      if (data.user) {
         // Post-Registration Logic: Apply Role if Token Valid
         if (inviteToken) {
            const { data: inviteData } = await supabase.from('invites').select('*').eq('token', inviteToken).eq('status', 'pending').single();
            if (inviteData && inviteData.email === email) {
                // Update Profile Role
                await supabase.from('profiles').update({ role: 'candidate' }).eq('id', data.user.id);
                // Mark Invite Accepted
                await supabase.from('invites').update({ status: 'accepted' }).eq('id', inviteData.id);
            }
         }

         if (data.user.identities && data.user.identities.length === 0) {
            setError('User already exists. Please try logging in.');
         } else {
            setMessage('Registration successful! Please check your email for a confirmation link.');
         }
      }
    } catch (error: any) {
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleSignup = async () => {
    if (!supabase) return;
    // Note: OAuth signup with invite token requires more complex backend logic (Triggers) 
    // to match the email after authentication. Simple version here ignores token for OAuth.

    setError(null);
    setMessage(null);
    setLoading(true);

    const getRedirectUrl = () => {
        if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
            return window.location.origin;
        }
        return 'https://prepare-ai-six.vercel.app';
    };

    const redirectUrl = getRedirectUrl();

    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: redirectUrl,
          queryParams: {
            access_type: 'offline',
            prompt: 'consent',
          },
        },
      });
      if (error) throw error;
    } catch (error: any) {
      console.error("Google Signup Error:", error);
      setError(error.message);
      setLoading(false);
    }
  };

  return (
    <div className="glass-panel w-full max-w-md rounded-2xl p-8 shadow-2xl animate-fade-in relative overflow-hidden">
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-brand-green to-brand-blue"></div>
      <h2 className="text-3xl font-bold mb-2 text-center text-white">
          {inviteToken ? 'Candidate Registration' : 'Create Account'}
      </h2>
      <p className="text-gray-400 mb-8 text-center text-sm">
        {inviteToken ? 'Accept your interview invitation.' : 'Start your journey to interview mastery.'}
      </p>
      <form onSubmit={handleRegister} className="w-full space-y-5">
        <div className="space-y-1">
            <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 ml-1">Email</label>
            <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="name@company.com"
            className="w-full bg-black/20 text-white px-4 py-3 rounded-xl border border-white/10 focus:outline-none focus:ring-2 focus:ring-brand-green focus:border-transparent transition-all"
            required
            readOnly={!!inviteToken} // Lock email if invite token is present
            />
        </div>
        <div className="space-y-1">
            <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 ml-1">Password</label>
            <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="At least 6 characters"
            className="w-full bg-black/20 text-white px-4 py-3 rounded-xl border border-white/10 focus:outline-none focus:ring-2 focus:ring-brand-green focus:border-transparent transition-all"
            minLength={6}
            required
            />
        </div>

        {error && (
            <div className="w-full bg-brand-red/10 border border-brand-red/30 rounded-lg p-3 text-sm">
                <p className="text-brand-red font-semibold">Error</p>
                <p className="text-gray-300 text-xs mt-1">{error}</p>
                 {(error.includes('redirect') || error.toLowerCase().includes('google')) && (
                    <p className="text-[10px] text-gray-400 mt-2 p-2 bg-black/20 rounded">
                        Ensure <code>https://prepare-ai-six.vercel.app</code> is in Supabase Redirect URLs.
                    </p>
                )}
            </div>
        )}
        {message && <p className="text-brand-green text-sm bg-brand-green/10 p-3 rounded border border-brand-green/20">{message}</p>}

        <button
          type="submit"
          disabled={loading}
          className="w-full bg-brand-green hover:bg-green-500 text-white font-bold py-3.5 rounded-xl transition-all shadow-lg hover:shadow-brand-green/25 focus:ring-4 focus:ring-brand-green/30 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {loading ? 'Creating Account...' : (inviteToken ? 'Accept & Join' : 'Sign Up')}
        </button>
      </form>

      {!inviteToken && (
          <>
            <div className="flex items-center w-full my-6">
                <div className="flex-grow h-px bg-gray-700"></div>
                <span className="px-4 text-gray-500 text-xs font-medium uppercase">Or sign up with</span>
                <div className="flex-grow h-px bg-gray-700"></div>
            </div>

            <button
                type="button"
                onClick={handleGoogleSignup}
                disabled={loading}
                className="w-full bg-white hover:bg-gray-100 text-gray-900 font-bold py-3.5 px-4 rounded-xl transition-all focus:outline-none focus:ring-4 focus:ring-gray-500/30 flex items-center justify-center gap-3 disabled:opacity-70 disabled:cursor-not-allowed"
            >
                <svg className="w-5 h-5" viewBox="0 0 24 24">
                <path
                    d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                    fill="#4285F4"
                />
                <path
                    d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                    fill="#34A853"
                />
                <path
                    d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
                    fill="#FBBC05"
                />
                <path
                    d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
                    fill="#EA4335"
                />
                </svg>
                Google
            </button>
          </>
      )}

      <p className="text-gray-400 mt-8 text-sm text-center">
        Already have an account?{' '}
        <button onClick={onSwitchToLogin} className="text-brand-blue hover:text-blue-300 font-semibold transition-colors">
          Log in
        </button>
      </p>
    </div>
  );
};

export default RegistrationScreen;

# prepareAI

**Powered by DevJs**

## About The Project

prepareAI is an advanced, interactive platform designed to help you ace your job interviews. Powered by Google's cutting-edge Gemini API, this application provides a realistic, real-time interview experience using your camera and microphone.

## Key Features

- **Realistic AI Interviewer** & **Live Feedback**.
- **Role-Based Access Control**:
  - **Admin**: Full control over users and system.
  - **Interviewer**: Can invite candidates and manage their group.
  - **Candidate**: Restricted access, can only join via invite link.
  - **User**: Free tier with limited sessions (1 free session).
- **CV & Portfolio Builder**.

## Database Setup (Required)

To use the profile, history, document saving, admin features, and roles, you must set up the database tables in your Supabase project.

1.  Open your project in the **Supabase Dashboard**.
2.  Go to the **SQL Editor**.
3.  Copy and Run the SQL script below:

```sql
-- 1. Create a table for public profiles with Roles
create table if not exists profiles (
  id uuid references auth.users not null primary key,
  updated_at timestamp with time zone,
  full_name text,
  pronouns text,
  avatar_url text,
  is_admin boolean default false, -- Legacy column, synced with role='admin'
  role text default 'user',

  constraint full_name_length check (char_length(full_name) >= 3),
  constraint allowed_roles check (role in ('user', 'admin', 'interviewer', 'candidate'))
);

-- Set up Row Level Security (RLS)
alter table profiles enable row level security;

create policy "Public profiles are viewable by everyone." on profiles for select using ( true );
create policy "Users can insert their own profile." on profiles for insert with check ( auth.uid() = id );
create policy "Users can update own profile." on profiles for update using ( auth.uid() = id );

-- HELPER FUNCTION FOR ADMIN CHECK (Prevents Infinite Recursion)
CREATE OR REPLACE FUNCTION is_admin()
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
AS $$
  SELECT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = auth.uid()
    AND (is_admin = true OR role = 'admin')
  );
$$;

-- 2. Create Invites Table
CREATE TABLE if not exists invites (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  interviewer_id uuid REFERENCES auth.users NOT NULL,
  email text NOT NULL,
  token uuid DEFAULT gen_random_uuid() NOT NULL,
  status text DEFAULT 'pending' CHECK (status IN ('pending', 'accepted')),
  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

alter table invites enable row level security;
create policy "Interviewers can manage invites" on invites for all using (auth.uid() = interviewer_id);
create policy "Public can view invites by token" on invites for select using (true);

-- 3. Create a table for interviews
create table if not exists interviews (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references auth.users not null,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  config jsonb not null,
  transcription jsonb not null,
  feedback jsonb not null,
  report jsonb,
  resources jsonb
);

alter table interviews enable row level security;
create policy "Users can view their own interviews." on interviews for select using ( auth.uid() = user_id );
create policy "Users can insert their own interviews." on interviews for insert with check ( auth.uid() = user_id );

-- 4. Create Tables for CVs, Letters, Portfolios (Standard)
create table if not exists cvs (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references auth.users not null,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  title text not null,
  content text not null,
  data jsonb
);
alter table cvs enable row level security;
create policy "Users can view their own CVs." on cvs for select using ( auth.uid() = user_id );
create policy "Users can insert/update/delete their own CVs." on cvs for all using ( auth.uid() = user_id );

create table if not exists motivation_letters (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references auth.users not null,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  title text not null,
  job_title text,
  company text,
  content text not null
);
alter table motivation_letters enable row level security;
create policy "Users can view their own letters." on motivation_letters for select using ( auth.uid() = user_id );
create policy "Users can insert/update/delete their own letters." on motivation_letters for all using ( auth.uid() = user_id );

create table if not exists portfolios (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references auth.users not null,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  title text not null,
  content text not null,
  data jsonb
);
alter table portfolios enable row level security;
create policy "Users can view their own portfolios." on portfolios for select using ( auth.uid() = user_id );
create policy "Users can insert/update/delete their own portfolios." on portfolios for all using ( auth.uid() = user_id );

-- STORAGE SETUP
insert into storage.buckets (id, name, public) values ('avatars', 'avatars', true) on conflict (id) do nothing;
create policy "Avatar images are publicly accessible." on storage.objects for select using ( bucket_id = 'avatars' );
create policy "Authenticated users can upload avatars." on storage.objects for insert with check ( bucket_id = 'avatars' and auth.role() = 'authenticated' );
create policy "Users can update their own avatars." on storage.objects for update using ( bucket_id = 'avatars' and auth.uid() = owner ) with check ( bucket_id = 'avatars' and auth.uid() = owner );

-- ADMIN POLICIES
create policy "Admins can view all profiles" on profiles for select using ( is_admin() = true );
create policy "Admins can view all interviews" on interviews for select using ( is_admin() = true );
create policy "Admins can view all cvs" on cvs for select using ( is_admin() = true );
create policy "Admins can view all portfolios" on portfolios for select using ( is_admin() = true );
create policy "Admins can view all letters" on motivation_letters for select using ( is_admin() = true );
```

