import React, { useState, useEffect } from 'react';
import { supabase } from '../services/supabaseClient';

interface RegistrationScreenProps {
  onSwitchToLogin: () => void;
  inviteToken?: string | null;
}

const RegistrationScreen: React.FC<RegistrationScreenProps> = ({ onSwitchToLogin, inviteToken }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  // If invite token is present, check validity and pre-fill email
  useEffect(() => {
      const checkInvite = async () => {
          if (!inviteToken || !supabase) return;
          const { data, error } = await supabase.from('invites').select('email').eq('token', inviteToken).eq('status', 'pending').maybeSingle();
          if (data) {
              setEmail(data.email);
          } else {
              setError("Invalid or expired invite link. You can still sign up as a normal user.");
          }
      };
      checkInvite();
  }, [inviteToken]);

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase) return;

    setError(null);
    setMessage(null);
    setLoading(true);
    try {
      const { data, error } = await supabase.auth.signUp({ 
          email, 
          password,
          options: {
              data: {
                  invite_token: inviteToken // Metadata to handle role assignment via Trigger (advanced) or manual update
              }
          }
      });
      if (error) throw error;

      if (data.user) {
         // Post-Registration Logic: Apply Role if Token Valid
         if (inviteToken) {
            const { data: inviteData } = await supabase.from('invites').select('*').eq('token', inviteToken).eq('status', 'pending').single();
            if (inviteData && inviteData.email === email) {
                // Update Profile Role
                await supabase.from('profiles').update({ role: 'candidate' }).eq('id', data.user.id);
                // Mark Invite Accepted AND Link Candidate ID
                await supabase.from('invites').update({ 
                    status: 'accepted',
                    candidate_id: data.user.id 
                }).eq('id', inviteData.id);
            }
         }

         if (data.user.identities && data.user.identities.length === 0) {
            setError('User already exists. Please try logging in.');
         } else {
            setMessage('Registration successful! Please check your email for a confirmation link.');
         }
      }
    } catch (error: any) {
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleSignup = async () => {
    if (!supabase) return;
    // Note: OAuth signup with invite token requires more complex backend logic (Triggers) 
    // to match the email after authentication. Simple version here ignores token for OAuth.

    setError(null);
    setMessage(null);
    setLoading(true);

    const getRedirectUrl = () => {
        if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
            return window.location.origin;
        }
        return 'https://prepare-ai-six.vercel.app';
    };

    const redirectUrl = getRedirectUrl();

    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: redirectUrl,
          queryParams: {
            access_type: 'offline',
            prompt: 'consent',
          },
        },
      });
      if (error) throw error;
    } catch (error: any) {
      console.error("Google Signup Error:", error);
      setError(error.message);
      setLoading(false);
    }
  };

  return (
    <div className="glass-panel w-full max-w-md rounded-2xl p-8 shadow-2xl animate-fade-in relative overflow-hidden">
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-brand-green to-brand-blue"></div>
      <h2 className="text-3xl font-bold mb-2 text-center text-white">
          {inviteToken ? 'Candidate Registration' : 'Create Account'}
      </h2>
      <p className="text-gray-400 mb-8 text-center text-sm">
        {inviteToken ? 'Accept your interview invitation.' : 'Start your journey to interview mastery.'}
      </p>
      <form onSubmit={handleRegister} className="w-full space-y-5">
        <div className="space-y-1">
            <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 ml-1">Email</label>
            <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="name@company.com"
            className="w-full bg-black/20 text-white px-4 py-3 rounded-xl border border-white/10 focus:outline-none focus:ring-2 focus:ring-brand-green focus:border-transparent transition-all"
            required
            readOnly={!!inviteToken} // Lock email if invite token is present
            />
        </div>
        <div className="space-y-1">
            <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 ml-1">Password</label>
            <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="At least 6 characters"
            className="w-full bg-black/20 text-white px-4 py-3 rounded-xl border border-white/10 focus:outline-none focus:ring-2 focus:ring-brand-green focus:border-transparent transition-all"
            minLength={6}
            required
            />
        </div>

        {error && (
            <div className="w-full bg-brand-red/10 border border-brand-red/30 rounded-lg p-3 text-sm">
                <p className="text-brand-red font-semibold">Error</p>
                <p className="text-gray-300 text-xs mt-1">{error}</p>
                 {(error.includes('redirect') || error.toLowerCase().includes('google')) && (
                    <p className="text-[10px] text-gray-400 mt-2 p-2 bg-black/20 rounded">
                        Ensure <code>https://prepare-ai-six.vercel.app</code> is in Supabase Redirect URLs.
                    </p>
                )}
            </div>
        )}
        {message && <p className="text-brand-green text-sm bg-brand-green/10 p-3 rounded border border-brand-green/20">{message}</p>}

        <button
          type="submit"
          disabled={loading}
          className="w-full bg-brand-green hover:bg-green-500 text-white font-bold py-3.5 rounded-xl transition-all shadow-lg hover:shadow-brand-green/25 focus:ring-4 focus:ring-brand-green/30 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {loading ? 'Creating Account...' : (inviteToken ? 'Accept & Join' : 'Sign Up')}
        </button>
      </form>

      {!inviteToken && (
          <>
            <div className="flex items-center w-full my-6">
                <div className="flex-grow h-px bg-gray-700"></div>
                <span className="px-4 text-gray-500 text-xs font-medium uppercase">Or sign up with</span>
                <div className="flex-grow h-px bg-gray-700"></div>
            </div>

            <button
                type="button"
                onClick={handleGoogleSignup}
                disabled={loading}
                className="w-full bg-white hover:bg-gray-100 text-gray-900 font-bold py-3.5 px-4 rounded-xl transition-all focus:outline-none focus:ring-4 focus:ring-gray-500/30 flex items-center justify-center gap-3 disabled:opacity-70 disabled:cursor-not-allowed"
            >
                <svg className="w-5 h-5" viewBox="0 0 24 24">
                <path
                    d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
                    fill="#4285F4"
                />
                <path
                    d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
                    fill="#34A853"
                />
                <path
                    d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
                    fill="#FBBC05"
                />
                <path
                    d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
                    fill="#EA4335"
                />
                </svg>
                Google
            </button>
          </>
      )}

      <p className="text-gray-400 mt-8 text-sm text-center">
        Already have an account?{' '}
        <button onClick={onSwitchToLogin} className="text-brand-blue hover:text-blue-300 font-semibold transition-colors">
          Log in
        </button>
      </p>
    </div>
  );
};

export default RegistrationScreen;

import React, { useEffect, useState } from 'react';
import { supabase } from '../services/supabaseClient';
import type { Invite, DomainKey, LevelKey, PersonaKey, InterviewReport, SuggestedResource, TranscriptionEntry, FeedbackEntry, InterviewConfig } from '../types';
import { domains, personas } from '../types';
import EndScreen from './EndScreen';

interface InterviewerDashboardProps {
  onBack: () => void;
  userId: string;
}

// Extends Invite to include candidate progress
interface ExtendedInvite extends Invite {
    interviewData?: {
        id: string;
        created_at: string;
        report: InterviewReport;
        resources: SuggestedResource[];
        transcription: TranscriptionEntry[];
        feedback: FeedbackEntry[];
        config: InterviewConfig;
    } | null;
}

const InterviewerDashboard: React.FC<InterviewerDashboardProps> = ({ onBack, userId }) => {
  const [invites, setInvites] = useState<ExtendedInvite[]>([]);
  const [newEmail, setNewEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [creating, setCreating] = useState(false);

  // Report Viewing State
  const [selectedReportInvite, setSelectedReportInvite] = useState<ExtendedInvite | null>(null);

  // Configuration State
  const [selectedDomain, setSelectedDomain] = useState<DomainKey>('software-engineering');
  const [selectedLevel, setSelectedLevel] = useState<LevelKey>('junior');
  const [selectedPersona, setSelectedPersona] = useState<PersonaKey>('friendly');
  const [selectedTechnology, setSelectedTechnology] = useState<string>('');

  const fetchInvites = async () => {
      if (!supabase) return;
      setLoading(true);

      // 1. Fetch Invites
      const { data: invitesData, error } = await supabase
        .from('invites')
        .select('*')
        .eq('interviewer_id', userId)
        .order('created_at', { ascending: false });

      if (error) {
          console.error("Error fetching invites", error);
          setLoading(false);
          return;
      }

      // 2. Fetch Interview Data for accepted invites
      const acceptedCandidateIds = invitesData
        .filter(inv => inv.status === 'accepted' && inv.candidate_id)
        .map(inv => inv.candidate_id);

      let interviewsMap: Record<string, any> = {};

      if (acceptedCandidateIds.length > 0) {
          const { data: interviewData } = await supabase
            .from('interviews')
            .select('*')
            .in('user_id', acceptedCandidateIds)
            .order('created_at', { ascending: false }); // Get latest first

          if (interviewData) {
              // Map latest interview to candidate_id
              interviewData.forEach(intrv => {
                  if (!interviewsMap[intrv.user_id]) {
                      interviewsMap[intrv.user_id] = intrv;
                  }
              });
          }
      }

      // 3. Merge Data
      const mergedInvites = invitesData.map(inv => ({
          ...inv,
          interviewData: inv.candidate_id ? interviewsMap[inv.candidate_id] : null
      }));

      setInvites(mergedInvites);
      setLoading(false);
  };

  useEffect(() => {
    fetchInvites();
  }, [userId]);

  const handleCreateInvite = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!newEmail || !supabase) return;

      const isSoftwareEngineering = selectedDomain === 'software-engineering';
      if (isSoftwareEngineering && !selectedTechnology) {
          alert("Please select a technology stack for Software Engineering.");
          return;
      }

      setCreating(true);

      // Build Config
      const baseConfig = domains[selectedDomain].levels[selectedLevel];
      let systemInstruction = baseConfig.systemInstruction;

      if (isSoftwareEngineering && domains['software-engineering'].technologies) {
          const techName = domains['software-engineering'].technologies[selectedTechnology];
          systemInstruction = systemInstruction.replace(/{technology}/g, techName);
      }

      const personaModifier = personas[selectedPersona].modifier;
      systemInstruction = `${systemInstruction} In terms of your personality as an interviewer, please adhere to the following: ${personaModifier}`;

      const finalConfig = {
          ...baseConfig,
          systemInstruction,
          name: `${baseConfig.name} (${personas[selectedPersona].name})`
      };

      // Generate invite link (token created by DB default)
      const { data, error } = await supabase.from('invites').insert({
          interviewer_id: userId,
          email: newEmail,
          config: finalConfig,
      }).select();

      if (error) {
          alert("Failed to invite: " + error.message);
      } else if (data && data[0]) {
          setNewEmail('');
          fetchInvites();
      }
      setCreating(false);
  };

  const getInviteLink = (token: string) => {
      const baseUrl = window.location.origin + window.location.pathname;
      const cleanBase = baseUrl.endsWith('/') ? baseUrl.slice(0, -1) : baseUrl;
      return `${cleanBase}/#invite=${token}`;
  };

  const copyToClipboard = (text: string) => {
      navigator.clipboard.writeText(text);
      alert("Invite link copied!");
  };

  // If viewing a report, render EndScreen
  if (selectedReportInvite && selectedReportInvite.interviewData) {
      return (
          <div className="w-full max-w-7xl mx-auto space-y-6 animate-fade-in pb-12">
              <button onClick={() => setSelectedReportInvite(null)} className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors font-medium mb-4">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" /></svg>
                Back to Candidate List
              </button>

              <div className="flex items-center gap-4 mb-6">
                  <div className="w-12 h-12 rounded-full bg-brand-purple flex items-center justify-center text-xl font-bold text-white">
                      {selectedReportInvite.email.charAt(0).toUpperCase()}
                  </div>
                  <div>
                      <h2 className="text-2xl font-bold text-white">{selectedReportInvite.email}</h2>
                      <p className="text-gray-400">Interview Role: <span className="text-brand-purple">{selectedReportInvite.interviewData.config.name}</span></p>
                  </div>
              </div>

              <EndScreen
                onRestart={() => setSelectedReportInvite(null)} // Acts as close
                transcription={selectedReportInvite.interviewData.transcription}
                feedback={selectedReportInvite.interviewData.feedback}
                config={selectedReportInvite.interviewData.config}
                userEmail={selectedReportInvite.email}
                userId={selectedReportInvite.candidate_id || ''}
                existingReport={selectedReportInvite.interviewData.report}
                existingResources={selectedReportInvite.interviewData.resources}
                isHistoryView={true}
              />
          </div>
      );
  }

  return (
