const InterviewScreen: React.FC<InterviewScreenProps> = ({ onEnd, config, isPracticeMode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const { transcription, aiStatus, isConnecting, error, endInterview, feedback, aiAudioStream, retry, suspendAudio, resumeAudio } = useInterview(config);

  const [isRecording, setIsRecording] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const screenStreamRef = useRef<MediaStream | null>(null);
  const [elapsedTime, setElapsedTime] = useState(0);
  const timerIntervalRef = useRef<number | null>(null);

  // Fullscreen State
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [sessionStarted, setSessionStarted] = useState(false);

  // Handle Fullscreen Logic & Auto-Suspend
  useEffect(() => {
      const handleFullscreenChange = () => {
          const isFs = !!document.fullscreenElement;
          setIsFullscreen(isFs);
          if (isFs) {
              resumeAudio();
          } else {
              suspendAudio();
          }
      };

      document.addEventListener('fullscreenchange', handleFullscreenChange);

      // Initial suspend until user starts session (via fullscreen)
      if (!sessionStarted || !document.fullscreenElement) {
          suspendAudio();
      }

      return () => {
          document.removeEventListener('fullscreenchange', handleFullscreenChange);
      };
  }, [resumeAudio, suspendAudio, sessionStarted]);

  const handleStartSession = async () => {
      if (containerRef.current) {
          try {
              await containerRef.current.requestFullscreen();
              setSessionStarted(true);
              resumeAudio();
          } catch (err) {
              console.error("Failed to enter fullscreen:", err);
              // Fallback for environments where fullscreen might fail or be blocked
              setSessionStarted(true);
              resumeAudio();
          }
      }
  };

  useEffect(() => {
    if (!isConnecting && !error && isFullscreen && sessionStarted) {
      timerIntervalRef.current = window.setInterval(() => {
        setElapsedTime(prevTime => prevTime + 1);
      }, 1000);
    } else {
        if (timerIntervalRef.current) {
            clearInterval(timerIntervalRef.current);
            timerIntervalRef.current = null;
        }
    }
    return () => {
      if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
    };
  }, [isConnecting, error, isFullscreen, sessionStarted]);

  const formatTime = (totalSeconds: number) => {
    const minutes = Math.floor(totalSeconds / 60).toString().padStart(2, '0');
    const seconds = (totalSeconds % 60).toString().padStart(2, '0');
    return `${minutes}:${seconds}`;
  };

  const downloadRecording = useCallback(() => {
    if (recordedChunksRef.current.length === 0) return;
    const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.style.display = 'none';
    a.href = url;
    a.download = `prepareAI-session-${new Date().toISOString().slice(0, 10)}.webm`;
    document.body.appendChild(a);
    a.click();
    window.URL.revokeObjectURL(url);
    document.body.removeChild(a);
    recordedChunksRef.current = [];
  }, []);

  const stopAndSaveRecording = useCallback(() => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
        mediaRecorderRef.current.stop();
    }
    if (screenStreamRef.current) {
        screenStreamRef.current.getTracks().forEach(track => track.stop());
        screenStreamRef.current = null;
    }
  }, []);

  const startRecording = useCallback(async () => {
    if (!videoRef.current?.srcObject || !aiAudioStream || !(videoRef.current.srcObject instanceof MediaStream)) {
        alert("Recording unavailable: Waiting for streams.");
        return;
    }
    try {
        const screenAndSystemAudioStream = await navigator.mediaDevices.getDisplayMedia({ video: true, audio: true });
        screenStreamRef.current = screenAndSystemAudioStream;
        const userMediaStream = videoRef.current.srcObject as MediaStream;
        const videoTracks = screenAndSystemAudioStream.getVideoTracks();
        const audioTracks = [...userMediaStream.getAudioTracks()]; 
        if (screenAndSystemAudioStream.getAudioTracks().length > 0) {
            audioTracks.push(...screenAndSystemAudioStream.getAudioTracks());
        } else {
            audioTracks.push(...aiAudioStream.getAudioTracks());
        }
        const combinedStream = new MediaStream([...videoTracks, ...audioTracks]);
        recordedChunksRef.current = [];
        const options = { mimeType: 'video/webm; codecs=vp9,opus' };
        const recorder = new MediaRecorder(combinedStream, MediaRecorder.isTypeSupported(options.mimeType) ? options : undefined);
        mediaRecorderRef.current = recorder;
        recorder.ondataavailable = (event) => {
            if (event.data.size > 0) recordedChunksRef.current.push(event.data);
        };
        recorder.onstop = () => {
            downloadRecording();
            setIsRecording(false);
            setIsSaving(false);
        };
        screenAndSystemAudioStream.getVideoTracks()[0].onended = () => {
            if (mediaRecorderRef.current?.state === 'recording') {
                stopAndSaveRecording();
                setIsSaving(true);
            }
        };
        recorder.start();
        setIsRecording(true);
    } catch (err: any) {
        console.error("Recording failed:", err);
        let errorMsg = "Could not start recording.";
        if (err.name === 'NotAllowedError') {
            errorMsg = "Screen recording permission was denied. Please allow screen sharing to record your session.";
        } else if (err.name === 'NotFoundError') {
             errorMsg = "No screen recording source found.";
        } else if (err.message && err.message.includes("display-capture")) {
            errorMsg = "Screen recording is disabled in this environment (Permission Policy).";
        }
        alert(errorMsg);
        setIsRecording(false);
        setIsSaving(false);
    }
  }, [aiAudioStream, downloadRecording, stopAndSaveRecording]);

  const handleRecordingButtonClick = useCallback(() => {
    if (isRecording) {
      setIsSaving(true);
      stopAndSaveRecording();
    } else {
      startRecording();
    }
  }, [isRecording, startRecording, stopAndSaveRecording]);

  const handleEndClick = useCallback(() => {
    if (document.fullscreenElement) {
        document.exitFullscreen().catch(e => console.log(e));
    }
    if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
    if (isRecording) stopAndSaveRecording();
    endInterview();
    onEnd(transcription, feedback);
  }, [isRecording, stopAndSaveRecording, endInterview, onEnd, transcription, feedback]);

  useEffect(() => {
    const setupCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
        if (videoRef.current) videoRef.current.srcObject = stream;
      } catch (err) {
        console.error("Error accessing camera:", err);
      }
    };
    setupCamera();
  }, []);

  if (isConnecting) {
    return (
      <div className="flex flex-col items-center justify-center h-[60vh] animate-fade-in">
        <div className="relative">
            <div className="absolute inset-0 bg-brand-blue blur-xl opacity-20 animate-pulse"></div>
            <div className="relative w-24 h-24 border-4 border-t-brand-blue border-r-transparent border-b-brand-blue border-l-transparent rounded-full animate-spin"></div>
        </div>
        <p className="mt-8 text-xl font-light text-gray-300 tracking-wide">Establishing Neural Link...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="w-full max-w-lg mx-auto mt-20 p-8 glass-panel rounded-2xl text-center border border-red-500/30 shadow-[0_0_50px_rgba(234,67,53,0.1)]">
        <div className="w-16 h-16 bg-red-500/10 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-brand-red" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
        </div>
        <h2 className="text-2xl font-bold mb-2 text-white">Connection Interrupted</h2>
        <p className="text-gray-400 mb-8">{error}</p>
        <div className="flex justify-center gap-4">
            <button onClick={retry} className="bg-white text-black hover:bg-gray-200 font-bold py-3 px-8 rounded-xl transition-colors">Retry</button>
            <button onClick={() => onEnd(transcription, feedback)} className="bg-transparent border border-gray-600 hover:bg-gray-800 text-white font-bold py-3 px-8 rounded-xl transition-colors">Abort</button>
        </div>
      </div>
    );
  }

  return (
    <div ref={containerRef} className="w-full h-[85vh] max-h-[900px] glass-panel rounded-2xl overflow-hidden flex flex-col shadow-2xl animate-fade-in border border-white/5 relative">

      {/* Start / Fullscreen Overlay */}
      {!sessionStarted && (
          <div className="absolute inset-0 z-50 bg-black/95 flex flex-col items-center justify-center p-8 text-center animate-fade-in">
                <div className="w-20 h-20 bg-brand-blue/20 rounded-full flex items-center justify-center mb-6 animate-pulse">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-brand-blue" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg>
                </div>
                <h2 className="text-4xl font-bold text-white mb-4 tracking-tight">Ready to Begin?</h2>
                <p className="text-gray-400 mb-10 max-w-md text-lg leading-relaxed">
                    To ensure a distraction-free environment and realistic experience, the interview will take place in <span className="text-white font-semibold">Fullscreen Mode</span>.
                </p>
                <button 
                    onClick={handleStartSession}
                    className="px-8 py-4 bg-brand-blue hover:bg-blue-600 text-white font-bold text-lg rounded-xl shadow-lg hover:shadow-brand-blue/30 transition-all transform hover:-translate-y-1"
                >
                    Enter Studio & Start
                </button>
          </div>
      )}

      {/* Paused Overlay */}
      {sessionStarted && !isFullscreen && (
          <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-xl flex flex-col items-center justify-center p-8 text-center animate-fade-in">
               <div className="w-16 h-16 bg-yellow-500/20 rounded-full flex items-center justify-center mb-6 text-yellow-500">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 9v6m4-6v6m7-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
               </div>
               <h2 className="text-3xl font-bold text-white mb-3">Session Paused</h2>
               <p className="text-gray-400 mb-8 max-w-md">You exited fullscreen mode. Please return to resume your interview.</p>
               <button 
                    onClick={handleStartSession}
                    className="px-8 py-3 bg-white text-black hover:bg-gray-200 font-bold rounded-xl transition-colors"
                >
                    Resume Session
               </button>
          </div>
      )}

      {/* Top Bar Info */}
      <div className="h-16 bg-black/40 border-b border-white/5 flex items-center justify-between px-6 shrink-0">
          <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                 <div className={`w-2 h-2 rounded-full ${sessionStarted && isFullscreen ? 'bg-brand-green animate-pulse' : 'bg-yellow-500'}`}></div>
                 <span className="text-xs font-mono text-gray-300 tracking-widest uppercase">{sessionStarted && isFullscreen ? 'Live Session' : 'Standby'}</span>
              </div>
              <div className="h-4 w-px bg-gray-700"></div>
              <span className="text-sm text-gray-300 font-medium">{config.name}</span>
          </div>
          <div className="font-mono text-xl text-white tracking-widest">{formatTime(elapsedTime)}</div>
      </div>

      <div className="flex-1 flex flex-col lg:flex-row overflow-hidden">

        {/* Main Viewport (Avatar + Video) */}
        <div className="lg:w-3/5 bg-gradient-to-b from-gray-900 to-black relative flex flex-col">

           {/* AI Container */}
           <div className="flex-1 relative flex items-center justify-center border-b border-white/5">
                <AiAvatar status={aiStatus} />
                <div className="absolute top-4 left-4">
                    <AiStatusIndicator status={aiStatus} />
                </div>
           </div>

           {/* User PIP (Picture in Picture) style or Split */}
           <div className="h-48 lg:h-64 relative bg-black border-t border-white/10 group">
                <video ref={videoRef} autoPlay muted className="w-full h-full object-cover transform -scale-x-100 opacity-80 group-hover:opacity-100 transition-opacity"></video>
                <div className="absolute top-3 left-3 bg-black/60 px-2 py-1 rounded text-xs text-white font-mono border border-white/10">YOU</div>
                {isRecording && (
                    <div className="absolute top-3 right-3 flex items-center gap-2 bg-red-500/20 border border-red-500/50 px-3 py-1 rounded-full">
                        <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></div>
                        <span className="text-xs font-bold text-red-500 uppercase">Rec</span>
                    </div>
                )}
           </div>
        </div>

        {/* Sidebar (Chat & Feedback) */}
        <div className="lg:w-2/5 flex flex-col border-l border-white/5 bg-black/20 backdrop-blur-sm">

            {/* Transcript Area */}
            <div className="flex-1 flex flex-col min-h-0">
                <div className="p-3 bg-white/5 border-b border-white/5 flex items-center justify-between">
                    <span className="text-xs font-bold text-gray-400 uppercase tracking-wider">Live Transcript</span>
                </div>
                <TranscriptionLog transcription={transcription} />
            </div>

            {/* Feedback Area (Collapsible or Fixed Height) */}
            <div className="h-1/3 min-h-[150px] border-t border-white/10 flex flex-col bg-black/20">
                 <div className="p-3 bg-white/5 border-b border-white/5 flex items-center justify-between">
                    <span className="text-xs font-bold text-gray-400 uppercase tracking-wider">Analysis Stream</span>
                </div>
                <FeedbackLog feedback={feedback} />
            </div>
        </div>
      </div>

      {/* Bottom Control Bar */}
      <div className="h-20 bg-black/60 border-t border-white/5 flex items-center justify-center gap-6 backdrop-blur-md shrink-0 px-4">
          {!isPracticeMode && (
              <button 
                onClick={handleRecordingButtonClick}
                disabled={!aiAudioStream || isSaving}
                className={`flex items-center gap-2 px-6 py-3 rounded-full font-bold transition-all ${
                    isRecording 
                    ? 'bg-red-500/20 text-red-400 border border-red-500/50 hover:bg-red-500/30' 
                    : 'bg-white/10 text-white hover:bg-white/20 border border-white/10'
                } disabled:opacity-50`}
              >
                 <div className={`w-3 h-3 rounded-full ${isRecording ? 'bg-red-500 animate-pulse' : 'bg-gray-400'}`}></div>
                 {isRecording ? (isSaving ? 'Saving...' : 'Stop Recording') : 'Record Session'}
              </button>
          )}

          <button 
            onClick={handleEndClick}
            disabled={isSaving}
            className="flex items-center gap-2 px-8 py-3 rounded-full bg-brand-red hover:bg-red-600 text-white font-bold shadow-lg hover:shadow-red-500/30 transition-all transform hover:-translate-y-0.5 disabled:opacity-50 disabled:transform-none"
          >
             <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M3 5a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM3 10a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM3 15a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1z" clipRule="evenodd" /></svg>
             {isSaving ? 'Finalizing...' : 'End Interview'}
          </button>
      </div>
    </div>
  );
};

export default InterviewScreen;

import React, { useEffect, useState } from 'react';
import { supabase } from '../services/supabaseClient';
import type { Invite, DomainKey, LevelKey, PersonaKey, InterviewReport, SuggestedResource, TranscriptionEntry, FeedbackEntry, InterviewConfig } from '../types';
import { domains, personas } from '../types';
import EndScreen from './EndScreen';

interface InterviewerDashboardProps {
  onBack: () => void;
  userId: string;
}

// Extends Invite to include candidate progress
interface ExtendedInvite extends Invite {
    interviewData?: {
        id: string;
        created_at: string;
        report: InterviewReport;
        resources: SuggestedResource[];
        transcription: TranscriptionEntry[];
        feedback: FeedbackEntry[];
        config: InterviewConfig;
    } | null;
}

const InterviewerDashboard: React.FC<InterviewerDashboardProps> = ({ onBack, userId }) => {
  const [invites, setInvites] = useState<ExtendedInvite[]>([]);
  const [newEmail, setNewEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [creating, setCreating] = useState(false);

  // Report Viewing State
  const [selectedReportInvite, setSelectedReportInvite] = useState<ExtendedInvite | null>(null);

  // Configuration State
  const [selectedDomain, setSelectedDomain] = useState<DomainKey>('software-engineering');
  const [selectedLevel, setSelectedLevel] = useState<LevelKey>('junior');
  const [selectedPersona, setSelectedPersona] = useState<PersonaKey>('friendly');
  const [selectedTechnology, setSelectedTechnology] = useState<string>('');

  const fetchInvites = async () => {
      if (!supabase) return;
      setLoading(true);

      // 1. Fetch Invites
      const { data: invitesData, error } = await supabase
        .from('invites')
        .select('*')
        .eq('interviewer_id', userId)
        .order('created_at', { ascending: false });

      if (error) {
          console.error("Error fetching invites", error);
          setLoading(false);
          return;
      }

      // 2. Fetch Interview Data for accepted invites
      const acceptedCandidateIds = invitesData
        .filter(inv => inv.status === 'accepted' && inv.candidate_id)
        .map(inv => inv.candidate_id);

      let interviewsMap: Record<string, any> = {};

      if (acceptedCandidateIds.length > 0) {
          const { data: interviewData } = await supabase
            .from('interviews')
            .select('*')
            .in('user_id', acceptedCandidateIds)
            .order('created_at', { ascending: false }); // Get latest first

          if (interviewData) {
              // Map latest interview to candidate_id
              interviewData.forEach(intrv => {
                  if (!interviewsMap[intrv.user_id]) {
                      interviewsMap[intrv.user_id] = intrv;
                  }
              });
          }
      }

      // 3. Merge Data
      const mergedInvites = invitesData.map(inv => ({
          ...inv,
          interviewData: inv.candidate_id ? interviewsMap[inv.candidate_id] : null
      }));

      setInvites(mergedInvites);
      setLoading(false);
  };

  useEffect(() => {
    fetchInvites();
  }, [userId]);

  const handleCreateInvite = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!newEmail || !supabase) return;

      const isSoftwareEngineering = selectedDomain === 'software-engineering';
      if (isSoftwareEngineering && !selectedTechnology) {
          alert("Please select a technology stack for Software Engineering.");
          return;
      }

      setCreating(true);

      // Build Config
      const baseConfig = domains[selectedDomain].levels[selectedLevel];
      let systemInstruction = baseConfig.systemInstruction;

      if (isSoftwareEngineering && domains['software-engineering'].technologies) {
          const techName = domains['software-engineering'].technologies[selectedTechnology];
          systemInstruction = systemInstruction.replace(/{technology}/g, techName);
      }

      const personaModifier = personas[selectedPersona].modifier;
      systemInstruction = `${systemInstruction} In terms of your personality as an interviewer, please adhere to the following: ${personaModifier}`;

      const finalConfig = {
          ...baseConfig,
          systemInstruction,
          name: `${baseConfig.name} (${personas[selectedPersona].name})`
      };

      // Generate invite link (token created by DB default)
      const { data, error } = await supabase.from('invites').insert({
          interviewer_id: userId,
          email: newEmail,
          config: finalConfig,
      }).select();

      if (error) {
          alert("Failed to invite: " + error.message);
      } else if (data && data[0]) {
          setNewEmail('');
          fetchInvites();
      }
      setCreating(false);
  };

  const handleDeleteInvite = async (inviteId: string) => {
      if (!supabase) return;
      if (!window.confirm("Are you sure you want to remove this candidate? This will delete the invitation and they will no longer be able to access the assigned interview.")) return;

      const { error } = await supabase.from('invites').delete().eq('id', inviteId);

      if (error) {
          console.error("Error deleting invite:", error);
          alert("Failed to remove candidate: " + error.message);
      } else {
          setInvites(prev => prev.filter(i => i.id !== inviteId));
      }
  };

  const getInviteLink = (token: string) => {
      const baseUrl = window.location.origin + window.location.pathname;
      const cleanBase = baseUrl.endsWith('/') ? baseUrl.slice(0, -1) : baseUrl;
      return `${cleanBase}/#invite=${token}`;
  };

  const copyToClipboard = (text: string) => {
      navigator.clipboard.writeText(text);
      alert("Invite link copied!");
  };

  // If viewing a report, render EndScreen
  if (selectedReportInvite && selectedReportInvite.interviewData) {
      return (
          <div className="w-full max-w-7xl mx-auto space-y-6 animate-fade-in pb-12">
              <button onClick={() => setSelectedReportInvite(null)} className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors font-medium mb-4">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" /></svg>
                Back to Candidate List
              </button>

              <div className="flex items-center gap-4 mb-6">
                  <div className="w-12 h-12 rounded-full bg-brand-purple flex items-center justify-center text-xl font-bold text-white">
                      {selectedReportInvite.email.charAt(0).toUpperCase()}
                  </div>
                  <div>
                      <h2 className="text-2xl font-bold text-white">{selectedReportInvite.email}</h2>
                      <p className="text-gray-400">Interview Role: <span className="text-brand-purple">{selectedReportInvite.interviewData.config.name}</span></p>
                  </div>
              </div>

              <EndScreen
                onRestart={() => setSelectedReportInvite(null)} // Acts as close
                transcription={selectedReportInvite.interviewData.transcription}
                feedback={selectedReportInvite.interviewData.feedback}
                config={selectedReportInvite.interviewData.config}
                userEmail={selectedReportInvite.email}
                userId={selectedReportInvite.candidate_id || ''}
                existingReport={selectedReportInvite.interviewData.report}
                existingResources={selectedReportInvite.interviewData.resources}
                isHistoryView={true}
              />
          </div>
      );
  }

  return (
    <div className="w-full max-w-6xl mx-auto space-y-8 animate-fade-in pb-12">
      <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-2 rounded-lg hover:bg-white/10 transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
            </button>
            <h2 className="text-3xl font-bold text-white">Interviewer Dashboard</h2>
          </div>
          <div className="px-3 py-1 bg-brand-purple/20 border border-brand-purple/50 rounded-full text-brand-purple text-xs font-bold uppercase tracking-wider">
              Recruiter Access
          </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Invite Form */}
          <div className="glass-panel p-6 rounded-xl h-fit">
              <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                  <span className="w-1.5 h-6 bg-brand-purple rounded-full"></span>
                  Assign Interview
              </h3>
              <form onSubmit={handleCreateInvite} className="space-y-4">
                  <div>
                      <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Candidate Email</label>
                      <input 
                        type="email" 
                        required 
                        value={newEmail}
                        onChange={(e) => setNewEmail(e.target.value)}
                        className="w-full bg-black/30 border border-white/10 rounded-lg p-3 text-white focus:ring-1 focus:ring-brand-purple outline-none"
                        placeholder="candidate@example.com"
                      />
                  </div>

                  {/* Config Selectors */}
                  <div className="space-y-3 pt-2 border-t border-white/10">
                      <div>
                          <label className="block text-xs font-semibold text-gray-400 mb-1">Role / Domain</label>
                          <select 
                            value={selectedDomain} 
                            onChange={(e) => { setSelectedDomain(e.target.value as DomainKey); setSelectedTechnology(''); }}
                            className="w-full bg-black/30 border border-white/10 rounded-lg p-2 text-sm text-white focus:border-brand-purple outline-none"
                          >
                              {Object.keys(domains).map(key => (
                                  <option key={key} value={key}>{domains[key as DomainKey].name}</option>
                              ))}
                          </select>
                      </div>

                      {selectedDomain === 'software-engineering' && (
                          <div>
                              <label className="block text-xs font-semibold text-gray-400 mb-1">Tech Stack</label>
                              <select 
                                value={selectedTechnology} 
                                onChange={(e) => setSelectedTechnology(e.target.value)}
                                className="w-full bg-black/30 border border-white/10 rounded-lg p-2 text-sm text-white focus:border-brand-purple outline-none"
                              >
                                  <option value="">-- Select Technology --</option>
                                  {Object.entries(domains['software-engineering'].technologies || {}).map(([key, name]) => (
                                      <option key={key} value={key}>{name}</option>
                                  ))}
                              </select>
                          </div>
                      )}

                      <div>
                          <label className="block text-xs font-semibold text-gray-400 mb-1">Difficulty Level</label>
                          <select 
                            value={selectedLevel} 
                            onChange={(e) => setSelectedLevel(e.target.value as LevelKey)}
                            className="w-full bg-black/30 border border-white/10 rounded-lg p-2 text-sm text-white focus:border-brand-purple outline-none"
                          >
                              <option value="junior">Junior</option>
                              <option value="mid-level">Mid-Level</option>
                              <option value="senior">Senior</option>
                          </select>
                      </div>

                      <div>
                          <label className="block text-xs font-semibold text-gray-400 mb-1">Interviewer Persona</label>
                          <select 
                            value={selectedPersona} 
                            onChange={(e) => setSelectedPersona(e.target.value as PersonaKey)}
                            className="w-full bg-black/30 border border-white/10 rounded-lg p-2 text-sm text-white focus:border-brand-purple outline-none"
                          >
                              {Object.keys(personas).map(key => (
                                  <option key={key} value={key}>{personas[key as PersonaKey].name}</option>
                              ))}
                          </select>
                      </div>
                  </div>

                  <button 
                    type="submit" 
                    disabled={creating}
                    className="w-full bg-gradient-to-r from-brand-purple to-purple-600 hover:from-purple-500 hover:to-purple-700 text-white font-bold py-3 rounded-lg transition-all shadow-lg hover:shadow-brand-purple/20 disabled:opacity-50 mt-4"
                  >
                      {creating ? 'Creating...' : 'Generate Invite Link'}
                  </button>
              </form>
          </div>

          {/* Invites List */}
          <div className="lg:col-span-2 glass-panel rounded-xl overflow-hidden min-h-[500px] flex flex-col">
              <div className="p-6 border-b border-white/5 bg-black/20">
                  <h3 className="text-xl font-bold text-white">Manage Candidates</h3>
              </div>
              <div className="overflow-x-auto flex-1 custom-scrollbar">
                   <table className="w-full text-sm text-left text-gray-400">
                      <thead className="text-xs text-gray-500 uppercase bg-black/40 sticky top-0">
                          <tr>
                              <th className="px-6 py-3">Candidate</th>
                              <th className="px-6 py-3">Assigned Role</th>
                              <th className="px-6 py-3">Status</th>
                              <th className="px-6 py-3">Action</th>
                          </tr>
                      </thead>
                      <tbody>
                          {invites.map((invite) => {
                              const link = getInviteLink(invite.token);
                              return (
                                <tr key={invite.id} className="border-b border-white/5 hover:bg-white/5 transition-colors">
                                    <td className="px-6 py-4">
                                        <div className="font-medium text-white">{invite.email}</div>
                                        <div className="text-xs text-gray-500">{new Date(invite.created_at).toLocaleDateString()}</div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="text-white font-medium truncate max-w-[200px]">
                                            {invite.config ? invite.config.name : 'Not Configured'}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={`px-2 py-0.5 rounded text-xs uppercase font-bold ${invite.status === 'accepted' ? 'bg-green-500/10 text-green-500' : 'bg-yellow-500/10 text-yellow-500'}`}>
                                            {invite.status}
                                        </span>
                                        {invite.interviewData && (
                                            <span className="ml-2 px-2 py-0.5 rounded text-xs uppercase font-bold bg-blue-500/10 text-blue-500">
                                                Completed
                                            </span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-3">
                                            {invite.interviewData ? (
                                                <button
                                                    onClick={() => setSelectedReportInvite(invite)}
                                                    className="bg-brand-green/20 hover:bg-brand-green/30 border border-brand-green/30 text-brand-green px-3 py-1.5 rounded text-xs font-bold transition-colors"
                                                >
                                                    View Report
                                                </button>
                                            ) : (
                                                <button 
                                                    onClick={() => copyToClipboard(link)}
                                                    className="bg-brand-purple/10 hover:bg-brand-purple/20 border border-brand-purple/30 text-brand-purple px-3 py-1.5 rounded text-xs font-bold flex items-center gap-2 transition-colors"
                                                >
                                                    Copy Link
                                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" /></svg>
                                                </button>
                                            )}

                                            <button 
                                                onClick={() => handleDeleteInvite(invite.id)}
                                                className="p-1.5 text-gray-500 hover:text-red-500 hover:bg-red-500/10 rounded-lg transition-colors group"
                                                title="Delete Invite"
                                            >
                                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                                                </svg>
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                              );
                          })}
                          {invites.length === 0 && !loading && (
                              <tr><td colSpan={4} className="px-6 py-12 text-center italic text-gray-500">No candidates invited yet.</td></tr>
                          )}
                      </tbody>
                  </table>
              </div>
          </div>
      </div>
    </div>
  );
};

