import React, { useState } from 'react';
import { supabase } from '../services/supabaseClient';
import type { SubscriptionTier } from '../types';

interface PricingScreenProps {
  onBack: () => void;
  currentTier: SubscriptionTier;
  userId: string;
  onUpgrade: (newTier: SubscriptionTier) => void;
}

const PricingScreen: React.FC<PricingScreenProps> = ({ onBack, currentTier, userId, onUpgrade }) => {
  const [loading, setLoading] = useState(false);

  const handleSubscribe = async (tier: SubscriptionTier) => {
    if (tier === currentTier) return;
    setLoading(true);

    try {
        // Mock Payment Process - In a real app, this would redirect to Stripe
        await new Promise(resolve => setTimeout(resolve, 1500)); 

        // Update User Profile with new Tier
        // If Recruiter, we also change the role to 'interviewer'
        const updates: any = { 
            subscription_tier: tier,
            subscription_status: 'active'
        };

        if (tier === 'recruiter') {
            updates.role = 'interviewer';
        } else if (tier === 'pro' && currentTier === 'recruiter') {
            // Downgrade logic from recruiter - reverts to user
            updates.role = 'user';
        } else if (tier === 'free') {
             updates.role = 'user';
        }

        if (supabase) {
            const { error } = await supabase.from('profiles').update(updates).eq('id', userId);
            if (error) throw error;
        }

        onUpgrade(tier);
        alert(`Successfully subscribed to ${tier.charAt(0).toUpperCase() + tier.slice(1)} Plan!`);
    } catch (error: any) {
        console.error("Subscription error:", error);
        alert("Failed to process subscription. Please try again.");
    } finally {
        setLoading(false);
    }
  };

  const PlanCard = ({ tier, price, name, features, popular = false }: { tier: SubscriptionTier, price: string, name: string, features: string[], popular?: boolean }) => {
      const isCurrent = currentTier === tier;

      return (
        <div className={`relative glass-panel rounded-2xl p-8 flex flex-col h-full border ${popular ? 'border-brand-purple shadow-[0_0_30px_rgba(168,85,247,0.2)]' : 'border-white/10'} transition-transform hover:-translate-y-2 duration-300`}>
             {popular && (
                 <div className="absolute -top-4 left-1/2 transform -translate-x-1/2 bg-brand-purple text-white px-4 py-1 rounded-full text-xs font-bold uppercase tracking-wider shadow-lg">
                     Most Popular
                 </div>
             )}
             <h3 className={`text-xl font-bold mb-2 ${popular ? 'text-brand-purple' : 'text-white'}`}>{name}</h3>
             <div className="flex items-baseline gap-1 mb-6">
                 <span className="text-4xl font-extrabold text-white">{price}</span>
                 {price !== 'Free' && <span className="text-gray-400 text-sm">/month</span>}
             </div>

             <ul className="space-y-4 mb-8 flex-1">
                 {features.map((feature, idx) => (
                     <li key={idx} className="flex items-start gap-3 text-sm text-gray-300">
                         <svg className={`w-5 h-5 flex-shrink-0 ${popular ? 'text-brand-purple' : 'text-brand-green'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                         </svg>
                         {feature}
                     </li>
                 ))}
             </ul>

             <button
                onClick={() => handleSubscribe(tier)}
                disabled={loading || isCurrent}
                className={`w-full py-3 rounded-xl font-bold transition-all shadow-lg ${
                    isCurrent 
                    ? 'bg-white/10 text-gray-400 cursor-default' 
                    : popular 
                        ? 'bg-gradient-to-r from-brand-purple to-purple-600 hover:shadow-brand-purple/30 text-white' 
                        : 'bg-white text-black hover:bg-gray-200'
                }`}
             >
                 {loading && !isCurrent ? 'Processing...' : (isCurrent ? 'Current Plan' : (tier === 'free' ? 'Downgrade' : 'Upgrade'))}
             </button>
        </div>
      );
  };

  return (
    <div className="w-full max-w-6xl mx-auto animate-fade-in pb-12">
       <button onClick={onBack} className="mb-8 flex items-center gap-2 text-gray-400 hover:text-white transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" /></svg>
            Back to Dashboard
       </button>

       <div className="text-center mb-16">
           <h1 className="text-4xl font-bold text-white mb-4">Choose Your Path to Success</h1>
           <p className="text-xl text-gray-400 max-w-2xl mx-auto">Unlock advanced AI interview features or streamline your hiring process with our dedicated plans.</p>
       </div>

       <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <PlanCard 
                tier="free"
                name="Starter"
                price="Free"
                features={[
                    "1 Full AI Interview Session",
                    "Basic Performance Report",
                    "Standard CV Builder Access",
                    "Limited Feedback"
                ]}
            />
            <PlanCard 
                tier="pro"
                name="Pro Candidate"
                price="$15"
                popular={true}
                features={[
                    "Unlimited AI Interview Sessions",
                    "Advanced Behavioral Analysis",
                    "Unlimited CV & Portfolio Builds",
                    "Priority AI Processing",
                    "Deep Feedback & Action Plans",
                    "Access to all Domain Roles"
                ]}
            />
            <PlanCard 
                tier="recruiter"
                name="Recruiter / Enterprise"
                price="$49"
                features={[
                    "Everything in Pro",
                    "Invite & Manage Candidates",
                    "View Candidate Reports",
                    "Custom Interview Configuration",
                    "Team Dashboard Access",
                    "Dedicated Support"
                ]}
            />
       </div>
    </div>
  );
};

