export default App;

import React, { useEffect, useState } from 'react';
import { supabase } from '../services/supabaseClient';
import type { UserProfile, Role } from '../types';

interface AdminDashboardProps {
  onBack: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onBack }) => {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalUsers: 0,
    totalInterviews: 0,
    totalCVs: 0,
    totalPortfolios: 0,
  });
  const [users, setUsers] = useState<any[]>([]); // Using any for extended profile with email
  const [recentInterviews, setRecentInterviews] = useState<any[]>([]);

  const fetchUsers = async () => {
    // Fetch Users with Role data and Email
    const { data: userData } = await supabase
      .from('profiles')
      .select('id, full_name, email, is_admin, role, updated_at')
      .order('updated_at', { ascending: false })
      .limit(50);

    setUsers(userData || []);
  };

  useEffect(() => {
    const fetchData = async () => {
      if (!supabase) return;
      setLoading(true);
      try {
        // Fetch Stats
        const { count: userCount } = await supabase.from('profiles').select('*', { count: 'exact', head: true });
        const { count: interviewCount } = await supabase.from('interviews').select('*', { count: 'exact', head: true });
        const { count: cvCount } = await supabase.from('cvs').select('*', { count: 'exact', head: true });
        const { count: pfCount } = await supabase.from('portfolios').select('*', { count: 'exact', head: true });

        setStats({
          totalUsers: userCount || 0,
          totalInterviews: interviewCount || 0,
          totalCVs: cvCount || 0,
          totalPortfolios: pfCount || 0,
        });

        await fetchUsers();

        // Fetch Recent Activity (Interviews)
        const { data: interviewData } = await supabase
          .from('interviews')
          .select('id, created_at, config')
          .order('created_at', { ascending: false })
          .limit(5);

        setRecentInterviews(interviewData || []);

      } catch (error) {
        console.error("Admin fetch error:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleRoleChange = async (userId: string, newRole: Role) => {
      if (!supabase) return;
      // Optimistic update
      setUsers(prev => prev.map(u => u.id === userId ? { ...u, role: newRole, is_admin: newRole === 'admin' } : u));

      try {
          const updates: any = { role: newRole };
          if (newRole === 'admin') updates.is_admin = true;
          else updates.is_admin = false;

          const { error } = await supabase.from('profiles').update(updates).eq('id', userId);
          if (error) throw error;
      } catch (err: any) {
          alert("Failed to update role: " + err.message);
          fetchUsers(); // Revert on error
      }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-[50vh]">
        <div className="w-12 h-12 border-4 border-brand-blue border-t-transparent rounded-full animate-spin"></div>
        <p className="mt-4 text-gray-400">Loading Dashboard...</p>
      </div>
    );
  }

  return (
    <div className="w-full max-w-7xl mx-auto space-y-8 animate-fade-in pb-12">

      {/* Header */}
      <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-2 rounded-lg hover:bg-white/10 transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
            </button>
            <h2 className="text-3xl font-bold text-white">Admin Dashboard</h2>
          </div>
          <div className="px-3 py-1 bg-brand-red/20 border border-brand-red/50 rounded-full text-brand-red text-xs font-bold uppercase tracking-wider">
              Super Admin
          </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="glass-panel p-6 rounded-xl border-l-4 border-l-brand-blue">
              <p className="text-gray-400 text-sm uppercase font-semibold">Total Users</p>
              <h3 className="text-3xl font-bold text-white mt-1">{stats.totalUsers}</h3>
          </div>
          <div className="glass-panel p-6 rounded-xl border-l-4 border-l-brand-green">
              <p className="text-gray-400 text-sm uppercase font-semibold">Interviews Conducted</p>
              <h3 className="text-3xl font-bold text-white mt-1">{stats.totalInterviews}</h3>
          </div>
          <div className="glass-panel p-6 rounded-xl border-l-4 border-l-brand-purple">
              <p className="text-gray-400 text-sm uppercase font-semibold">CVs Created</p>
              <h3 className="text-3xl font-bold text-white mt-1">{stats.totalCVs}</h3>
          </div>
          <div className="glass-panel p-6 rounded-xl border-l-4 border-l-brand-yellow">
              <p className="text-gray-400 text-sm uppercase font-semibold">Portfolios Built</p>
              <h3 className="text-3xl font-bold text-white mt-1">{stats.totalPortfolios}</h3>
          </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

          {/* User Management */}
          <div className="glass-panel rounded-xl overflow-hidden col-span-1 lg:col-span-2">
              <div className="p-6 border-b border-white/5 flex justify-between items-center">
                  <h3 className="text-xl font-bold text-white">User Management</h3>
                  <div className="text-xs text-gray-500">Showing last 50 active users</div>
              </div>
              <div className="overflow-x-auto max-h-[600px] custom-scrollbar">
                  <table className="w-full text-sm text-left text-gray-400">
                      <thead className="text-xs text-gray-500 uppercase bg-black/20 sticky top-0 z-10">
                          <tr>
                              <th className="px-6 py-3">User</th>
                              <th className="px-6 py-3">Role</th>
                              <th className="px-6 py-3 text-center">Actions</th>
                              <th className="px-6 py-3 text-right">Last Active</th>
                          </tr>
                      </thead>
                      <tbody>
                          {users.map((user) => (
                              <tr key={user.id} className="border-b border-white/5 hover:bg-white/5 transition-colors">
                                  <td className="px-6 py-4 font-medium text-white">
                                    <div className="text-base font-bold text-white">{user.email || 'No Email'}</div>
                                    <div className="text-xs text-gray-400">{user.full_name || 'Anonymous'}</div>
                                    <div className="text-[10px] text-gray-600 font-mono mt-1">{user.id}</div>
                                  </td>
                                  <td className="px-6 py-4">
                                      <span className={`px-2 py-0.5 rounded text-xs font-bold uppercase
                                        ${user.role === 'admin' ? 'bg-brand-red/10 text-brand-red' : 
                                          user.role === 'interviewer' ? 'bg-brand-purple/10 text-brand-purple' :
                                          user.role === 'candidate' ? 'bg-brand-green/10 text-brand-green' :
                                          'bg-gray-700/50 text-gray-300'}
                                      `}>
                                          {user.role || (user.is_admin ? 'admin' : 'user')}
                                      </span>
                                  </td>
                                  <td className="px-6 py-4 text-center">
                                      <select 
                                        value={user.role || (user.is_admin ? 'admin' : 'user')}
                                        onChange={(e) => handleRoleChange(user.id, e.target.value as Role)}
                                        className="bg-black/30 border border-white/10 rounded px-2 py-1 text-xs text-white focus:ring-1 focus:ring-brand-blue outline-none cursor-pointer"
                                      >
                                          <option value="user">User</option>
                                          <option value="interviewer">Interviewer</option>
                                          <option value="candidate">Candidate</option>
                                          <option value="admin">Admin</option>
                                      </select>
                                  </td>
                                  <td className="px-6 py-4 text-right">{user.updated_at ? new Date(user.updated_at).toLocaleDateString() : 'N/A'}</td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
          </div>
      </div>
    </div>
  );
};

export default AdminDashboard;

