      <form onSubmit={handleRegister} className="w-full space-y-5">

        {/* Name Field */}
        <div className="space-y-1">
            <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 ml-1">Full Name</label>
            <input
            type="text"
            value={fullName}
            onChange={(e) => setFullName(e.target.value)}
            placeholder="John Doe"
            className="w-full bg-black/20 text-white px-4 py-3 rounded-xl border border-white/10 focus:outline-none focus:ring-2 focus:ring-brand-green focus:border-transparent transition-all"
            required
            />
        </div>

        {/* Birthday Field */}
        <div className="space-y-1">
            <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 ml-1">Date of Birth</label>
            <input
            type="date"
            value={birthday}
            onChange={(e) => setBirthday(e.target.value)}
            className="w-full bg-black/20 text-white px-4 py-3 rounded-xl border border-white/10 focus:outline-none focus:ring-2 focus:ring-brand-green focus:border-transparent transition-all"
            required
            />
        </div>

        <div className="space-y-1">
            <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 ml-1">Email</label>
            <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="name@company.com"
            className="w-full bg-black/20 text-white px-4 py-3 rounded-xl border border-white/10 focus:outline-none focus:ring-2 focus:ring-brand-green focus:border-transparent transition-all"
            required
            readOnly={!!inviteToken} // Lock email if invite token is present
            />
        </div>
        <div className="space-y-1">
            <label className="text-xs font-semibold uppercase tracking-wider text-gray-500 ml-1">Password</label>
            <div className="relative">
                <input
                type={showPassword ? "text" : "password"}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="At least 6 characters"
                className="w-full bg-black/20 text-white px-4 py-3 rounded-xl border border-white/10 focus:outline-none focus:ring-2 focus:ring-brand-green focus:border-transparent transition-all pr-10"
