const InterviewSetup: React.FC<InterviewSetupProps> = ({ onStart, onBack }) => {
  const [selectedDomain, setSelectedDomain] = useState<DomainKey | ''>('');
  const [selectedLevel, setSelectedLevel] = useState<LevelKey | null>(null);
  const [selectedPersona, setSelectedPersona] = useState<PersonaKey>('friendly');
  const [isPracticeMode, setIsPracticeMode] = useState(false);
  const [selectedTechnology, setSelectedTechnology] = useState<string | null>(null);
  const [customInstructions, setCustomInstructions] = useState('');

  // Resume Personalization State
  const [resumeContext, setResumeContext] = useState<string>('');
  const [extractedSkills, setExtractedSkills] = useState<string[]>([]);
  const [isAnalyzingResume, setIsAnalyzingResume] = useState(false);
  const [resumeFileName, setResumeFileName] = useState<string | null>(null);

  const selectedConfig = useMemo(() => {
    if (selectedDomain && selectedLevel) {
      return domains[selectedDomain].levels[selectedLevel];
    }
    return null;
  }, [selectedDomain, selectedLevel]);

  const handleResumeUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      if (!process.env.API_KEY) {
          alert("API Key missing");
          return;
      }

      setIsAnalyzingResume(true);
      setResumeFileName(file.name);

      try {
          const reader = new FileReader();
          reader.onload = async (event) => {
              const base64String = event.target?.result as string;
              // Support PDF (raw base64) or Text
              let contentPart: any;

              if (file.type === "application/pdf") {
                  const rawBase64 = base64String.split(',')[1];
                  contentPart = { inlineData: { mimeType: 'application/pdf', data: rawBase64 } };
              } else {
                  // For text files, just use text
                  contentPart = { text: base64String }; 
              }

              const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

              const prompt = `Analyze this resume. Return a JSON object with the following structure:
              {
                "summary": "Concise summary of the candidate's background, key roles, and major achievements (max 3 sentences).",
                "skills": ["Skill 1", "Skill 2", ...] (List of top 10 relevant skills)
              }
              Do not use markdown formatting for the JSON.`;

              const response = await ai.models.generateContent({
                  model: 'gemini-2.5-flash',
                  contents: [contentPart, { text: prompt }],
                  config: { responseMimeType: 'application/json' }
              });

              const data = JSON.parse(response.text || '{}');
              setResumeContext(data.summary || '');
              setExtractedSkills(data.skills || []);
              setIsAnalyzingResume(false);
          };

          if (file.type === "application/pdf") {
              reader.readAsDataURL(file);
          } else {
              reader.readAsText(file);
          }

      } catch (err) {
          console.error(err);
          alert("Failed to analyze resume.");
          setIsAnalyzingResume(false);
          setResumeFileName(null);
          setExtractedSkills([]);
      }
  };

  const handleStartClick = () => {
    if (!selectedConfig) return;

    let finalSystemInstruction = selectedConfig.systemInstruction;
    if (selectedDomain === 'software-engineering' && selectedTechnology && domains['software-engineering'].technologies) {
      const technologyName = domains['software-engineering'].technologies[selectedTechnology];
      finalSystemInstruction = finalSystemInstruction.replace(/{technology}/g, technologyName);
    }

    const personaModifier = personas[selectedPersona].modifier;

    let systemInstruction = `${finalSystemInstruction} In terms of your personality as an interviewer, please adhere to the following: ${personaModifier}`;

    // Add User Resume Context
    if (resumeContext) {
        systemInstruction += `\n\nCONTEXT FROM CANDIDATE RESUME:\nSUMMARY: ${resumeContext}\nSKILLS: ${extractedSkills.join(', ')}\nUse this context to tailor your questions and verify their skills.`;
    }

    if (customInstructions.trim()) {
      systemInstruction += ` Additionally, please follow these user-provided custom instructions: ${customInstructions.trim()}`;
    }

    const finalConfig: InterviewConfig = {
      ...selectedConfig,
      systemInstruction,
    };
    onStart(finalConfig, isPracticeMode);
  };

  const isSoftwareEngineering = selectedDomain === 'software-engineering';
  const isStartDisabled = !selectedConfig || (isSoftwareEngineering && !selectedTechnology) || isAnalyzingResume;

  // Helper to get step number logic
  const steps = [
      { id: 1, title: 'Domain', active: true, completed: !!selectedDomain },
      { id: 2, title: 'Details', active: !!selectedDomain, completed: (isSoftwareEngineering ? !!selectedTechnology : true) && !!selectedLevel },
      { id: 3, title: 'Persona', active: !!selectedDomain && !!selectedLevel, completed: !!selectedPersona },
  ];

  return (
    <div className="w-full glass-panel rounded-2xl shadow-2xl overflow-hidden animate-slide-up flex flex-col h-[90vh]">
      {/* Header / Progress */}
      <div className="bg-black/20 p-6 border-b border-white/5 relative shrink-0">
         <button onClick={onBack} className="absolute top-6 left-6 text-gray-400 hover:text-white transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
         </button>
         <div className="flex justify-between items-center mb-6 pl-10">
            <h2 className="text-3xl font-bold text-white tracking-tight">Configure Your Interview</h2>
            <div className="flex items-center gap-2">
                 <span className="text-sm font-medium text-gray-400">Step {steps.findIndex(s => !s.completed) === -1 ? 3 : steps.findIndex(s => !s.completed) + 1} of 3</span>
            </div>
         </div>
         <div className="flex items-center gap-4">
             {steps.map((step, idx) => (
                 <div key={step.id} className="flex-1 flex items-center gap-3">
                     <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold border ${step.active ? (step.completed ? 'bg-brand-green border-brand-green text-white' : 'bg-brand-blue border-brand-blue text-white') : 'bg-transparent border-gray-600 text-gray-500'}`}>
                         {step.completed ? '✓' : step.id}
                     </div>
                     <div className="h-1 flex-1 bg-gray-800 rounded-full overflow-hidden">
                         <div className={`h-full transition-all duration-500 ${step.completed ? 'bg-brand-green' : (step.active ? 'bg-brand-blue' : 'bg-transparent')}`} style={{ width: step.completed ? '100%' : (step.active ? '50%' : '0%') }}></div>
                     </div>
                 </div>
             ))}
         </div>
      </div>

      <div className="p-8 overflow-y-auto custom-scrollbar flex-1">

        {/* Step 1: Domain Selection */}
        <section className="mb-12">
            <h3 className="text-xl font-semibold mb-6 flex items-center gap-3 text-gray-100">
                <span className="w-1.5 h-6 bg-brand-blue rounded-full"></span>
                Select Your Field
            </h3>
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                {(Object.keys(domains) as DomainKey[]).map((key) => (
                <button
                    key={key}
                    onClick={() => {
                        setSelectedDomain(key);
                        setSelectedLevel(null);
                        setSelectedTechnology(null);
                    }}
                    className={`group relative p-4 rounded-xl text-left border transition-all duration-300 ${
                        selectedDomain === key 
                        ? 'bg-brand-blue/20 border-brand-blue shadow-[0_0_20px_rgba(66,133,244,0.3)]' 
                        : 'bg-black/20 border-white/5 hover:bg-white/5 hover:border-white/20'
                    }`}
                >
                    <div className="flex items-center justify-between mb-2">
                        <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${selectedDomain === key ? 'bg-brand-blue text-white' : 'bg-gray-800 text-gray-400'}`}>
                            {domainIcons[key]}
                        </div>
                        {selectedDomain === key && <div className="w-2 h-2 rounded-full bg-brand-blue shadow-[0_0_10px_#4285F4]"></div>}
                    </div>
                    <p className={`font-semibold text-sm ${selectedDomain === key ? 'text-white' : 'text-gray-300 group-hover:text-white'}`}>
                        {domains[key].name}
                    </p>
                </button>
                ))}
            </div>
        </section>

        {/* Step 2: Tech & Level */}
        {selectedDomain && (
            <div className="animate-fade-in space-y-12">
                {isSoftwareEngineering && (
                    <section>
                         <h3 className="text-xl font-semibold mb-6 flex items-center gap-3 text-gray-100">
                            <span className="w-1.5 h-6 bg-brand-purple rounded-full"></span>
                            Choose Technology Stack
                        </h3>
                        <div className="flex flex-wrap gap-3">
                            {Object.entries((domains[selectedDomain].technologies || {})).map(([key, name]) => (
                                <button
                                    key={key}
                                    onClick={() => setSelectedTechnology(key)}
                                    className={`px-5 py-2.5 rounded-full text-sm font-medium border transition-all duration-200 ${
                                        selectedTechnology === key 
                                        ? 'bg-brand-purple text-white border-brand-purple shadow-[0_0_15px_rgba(168,85,247,0.4)]' 
                                        : 'bg-black/20 text-gray-300 border-white/10 hover:bg-white/10 hover:border-white/30'
                                    }`}
                                >
                                    {name}
                                </button>
                            ))}
                        </div>
                    </section>
                )}

                <section>
                     <h3 className="text-xl font-semibold mb-6 flex items-center gap-3 text-gray-100">
                        <span className="w-1.5 h-6 bg-brand-green rounded-full"></span>
                        Experience Level
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        {(Object.keys(domains[selectedDomain].levels) as LevelKey[]).map((key) => {
                            const level = domains[selectedDomain!].levels[key];
                            return (
                                <button
                                    key={key}
                                    onClick={() => setSelectedLevel(key)}
                                    className={`p-6 rounded-xl text-left border transition-all duration-300 h-full flex flex-col ${
                                        selectedLevel === key 
                                        ? 'bg-brand-green/10 border-brand-green shadow-[0_0_20px_rgba(52,168,83,0.2)]' 
                                        : 'bg-black/20 border-white/5 hover:bg-white/5 hover:border-white/20'
                                    }`}
                                >
                                    <div className="flex items-center justify-between mb-3">
                                         <span className={`text-xs font-bold uppercase tracking-wider px-2 py-1 rounded ${selectedLevel === key ? 'bg-brand-green text-white' : 'bg-gray-700 text-gray-400'}`}>
                                            {key}
                                         </span>
                                    </div>
                                    <h4 className="text-lg font-bold text-white mb-2">{level.name}</h4>
                                    <p className="text-sm text-gray-400 leading-relaxed flex-grow">{level.description}</p>
                                </button>
                            );
                        })}
                    </div>
                </section>
            </div>
        )}

        {/* Step 3: Persona & Context */}
        {selectedDomain && selectedLevel && (!isSoftwareEngineering || selectedTechnology) && (
            <section className="mt-12 animate-fade-in">
                 <h3 className="text-xl font-semibold mb-6 flex items-center gap-3 text-gray-100">
                    <span className="w-1.5 h-6 bg-brand-yellow rounded-full"></span>
                    Interviewer Persona
                </h3>
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                    {(Object.keys(personas) as PersonaKey[]).map((key) => {
                    const persona = personas[key];
                    return (
                        <button
                        key={key}
                        onClick={() => setSelectedPersona(key)}
                        className={`p-6 rounded-xl text-left border transition-all duration-300 ${
                            selectedPersona === key 
                            ? 'bg-brand-yellow/10 border-brand-yellow shadow-[0_0_20px_rgba(251,188,5,0.2)]' 
                            : 'bg-black/20 border-white/5 hover:bg-white/5 hover:border-white/20'
                        }`}
                        >
                            <h4 className={`text-lg font-bold mb-2 ${selectedPersona === key ? 'text-brand-yellow' : 'text-gray-200'}`}>{persona.name}</h4>
                            <p className="text-sm text-gray-400 leading-relaxed">{persona.description}</p>
                        </button>
                    );
                    })}
                </div>

                {/* Personalize Section */}
                <div className="bg-black/20 rounded-xl p-6 border border-white/5">
                     <h4 className="text-lg font-bold text-white mb-4">Personalize Context</h4>

                     {/* Resume Upload */}
                     <div className="mb-6">
                         <label className="block text-sm font-semibold text-gray-300 mb-2">Upload Resume (PDF/Text)</label>
                         <p className="text-xs text-gray-500 mb-3">We will extract your skills and experience to tailor the interview.</p>

                         {resumeFileName ? (
                             <div className="flex flex-col gap-3">
                                 <div className="flex items-center gap-3 bg-brand-blue/10 border border-brand-blue/30 rounded-lg p-3">
                                     <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-brand-blue" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                                     <span className="text-sm text-white font-medium flex-1 truncate">{resumeFileName}</span>
                                     <button onClick={() => { setResumeContext(''); setExtractedSkills([]); setResumeFileName(null); }} className="text-gray-400 hover:text-white">
                                         <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                                     </button>
                                 </div>
                                 {extractedSkills.length > 0 && (
                                     <div className="flex flex-wrap gap-2">
                                         {extractedSkills.map((skill, i) => (
                                             <span key={i} className="px-2 py-1 bg-white/5 border border-white/10 rounded text-xs text-gray-300">
                                                 {skill}
                                             </span>
                                         ))}
                                     </div>
                                 )}
                             </div>
                         ) : (
                             <label className={`flex items-center justify-center gap-2 w-full p-4 border-2 border-dashed border-gray-600 rounded-lg cursor-pointer hover:border-gray-400 hover:bg-white/5 transition-all ${isAnalyzingResume ? 'opacity-50 cursor-not-allowed' : ''}`}>
                                 <input type="file" accept=".pdf,.txt,.md" className="hidden" onChange={handleResumeUpload} disabled={isAnalyzingResume} />
                                 {isAnalyzingResume ? (
                                     <>
                                        <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                                        <span className="text-sm text-gray-300">Extracting Skills...</span>
                                     </>
                                 ) : (
                                     <>
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                                        <span className="text-sm text-gray-300">Click to Upload Resume (PDF)</span>
                                     </>
                                 )}
                             </label>
                         )}
                     </div>

                     <label className="block text-sm font-semibold text-gray-300 mb-2">Custom Instructions (Optional)</label>
                     <textarea
                        value={customInstructions}
                        onChange={(e) => setCustomInstructions(e.target.value)}
                        className="w-full bg-black/30 border border-white/10 rounded-lg p-4 text-white focus:outline-none focus:ring-2 focus:ring-brand-blue focus:border-transparent transition-all placeholder-gray-600"
                        rows={2}
                        placeholder="E.g., 'Ask specific questions about system design scalability' or 'Be very critical about edge cases'."
                    />
                </div>
            </section>
        )}
      </div>

      {/* Footer Controls */}
      <div className="p-6 bg-black/20 border-t border-white/5 flex flex-col md:flex-row items-center justify-between gap-4 shrink-0">
        <label className="flex items-center cursor-pointer group">
            <div className="relative">
                <input type="checkbox" className="sr-only" checked={isPracticeMode} onChange={() => setIsPracticeMode(!isPracticeMode)} />
                <div className={`w-12 h-7 rounded-full transition-colors duration-300 ${isPracticeMode ? 'bg-brand-green' : 'bg-gray-700'}`}></div>
                <div className={`absolute left-1 top-1 w-5 h-5 bg-white rounded-full transition-transform duration-300 ${isPracticeMode ? 'translate-x-5' : ''}`}></div>
            </div>
            <div className="ml-3">
                <span className="block text-sm font-semibold text-white group-hover:text-brand-green transition-colors">Practice Mode</span>
                <span className="block text-xs text-gray-500">No scoring, just chat.</span>
            </div>
        </label>

        <button
            onClick={handleStartClick}
            disabled={isStartDisabled}
            className="w-full md:w-auto bg-gradient-to-r from-brand-blue to-blue-600 hover:from-blue-500 hover:to-blue-700 text-white font-bold py-3 px-10 rounded-xl transition-all shadow-lg hover:shadow-brand-blue/30 disabled:opacity-50 disabled:cursor-not-allowed disabled:shadow-none transform hover:-translate-y-0.5"
        >
            Start Interview
        </button>
      </div>
    </div>
  );
};

export default InterviewSetup;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Session } from '@supabase/supabase-js';
import { supabase } from '../services/supabaseClient';
import type { InterviewConfig, TranscriptionEntry, FeedbackEntry, InterviewReport, SuggestedResource, SavedCV, SavedLetter, SavedPortfolio, SubscriptionTier } from '../types';
import EndScreen from './EndScreen';

interface Profile {
  full_name: string;
  pronouns: string;
  avatar_url: string;
  is_admin?: boolean;
  subscription_tier?: SubscriptionTier;
}

interface InterviewHistoryItem {
  id: string;
  created_at: string;
  config: InterviewConfig;
  transcription: TranscriptionEntry[];
  feedback: FeedbackEntry[];
  report: InterviewReport | null;
  resources: SuggestedResource[] | null;
}

interface ProfileScreenProps {
  session: Session;
  onBack: () => void;
  onEditCV: (cv: SavedCV) => void;
  onEditPortfolio: (p: SavedPortfolio) => void;
  onManagePlan: () => void;
}

type TabView = 'history' | 'cvs' | 'letters' | 'portfolios';

// Extended type to handle viewing/editing
interface DocViewerState {
  id: string;
  type: 'cv' | 'letter' | 'portfolio';
  content: string;
  title: string;
  originalData?: any; 
}

const ProfileScreen: React.FC<ProfileScreenProps> = ({ session, onBack, onEditCV, onEditPortfolio, onManagePlan }) => {
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<Profile>({ full_name: '', pronouns: '', avatar_url: '', is_admin: false, subscription_tier: 'free' });
  const [interviews, setInterviews] = useState<InterviewHistoryItem[]>([]);
  const [savedCVs, setSavedCVs] = useState<SavedCV[]>([]);
  const [savedLetters, setSavedLetters] = useState<SavedLetter[]>([]);
  const [savedPortfolios, setSavedPortfolios] = useState<SavedPortfolio[]>([]);

  const [selectedInterview, setSelectedInterview] = useState<InterviewHistoryItem | null>(null);

  // Document Viewing/Editing State
  const [viewingDoc, setViewingDoc] = useState<DocViewerState | null>(null);
  const [isEditingDoc, setIsEditingDoc] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editContent, setEditContent] = useState('');
  const [isSavingDoc, setIsSavingDoc] = useState(false);

  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isChangingPassword, setIsChangingPassword] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordMessage, setPasswordMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const [activeTab, setActiveTab] = useState<TabView>('history');
  const [error, setError] = useState<string | null>(null);
  const [uploadingAvatar, setUploadingAvatar] = useState(false);

  const fetchProfileData = useCallback(async () => {
    if (!supabase || !session.user) {
        setLoading(false);
        return;
    }
    setLoading(true);
    setError(null);

    try {
      try {
        const { data, error } = await supabase
          .from('profiles')
          .select('full_name, pronouns, avatar_url, is_admin, subscription_tier')
          .eq('id', session.user.id)
          .maybeSingle(); 

        if (error) {
            if (error.code === '42703') {
                console.warn("Database missing avatar_url or subscription_tier. Falling back to basic profile. Run the 'Fix Database' script in README.md.");
                const { data: basicData, error: basicError } = await supabase
                    .from('profiles')
                    .select('full_name, pronouns')
                    .eq('id', session.user.id)
                    .maybeSingle();

                if (basicError) throw basicError;
                if (basicData) {
                    setProfile({ 
                        full_name: basicData.full_name || '', 
                        pronouns: basicData.pronouns || '',
                        avatar_url: '',
                        subscription_tier: 'free'
                    });
                }
            } else if (error.code === '42P17') {
                // Infinite recursion detected in DB policy
                console.error("Critical DB Error: Infinite recursion in 'profiles' policy. Run the fix SQL script.");
                setError("Database Config Error: Infinite recursion detected. Please run the FIX SQL script located in README.md");
                setLoading(false);
                return;
            } else {
                throw error;
            }
        } else if (data) {
             setProfile({ 
                full_name: data.full_name || '', 
                pronouns: data.pronouns || '',
                avatar_url: data.avatar_url || '',
                is_admin: data.is_admin || false,
                subscription_tier: data.subscription_tier as SubscriptionTier || 'free'
            });
        }
      } catch (profileErr) { 
          console.warn("Profile fetch warning:", profileErr); 
      }

      const { data: interviewData } = await supabase
        .from('interviews')
        .select('*')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false })
        .limit(10);
      setInterviews(interviewData || []);

      const { data: cvData } = await supabase
        .from('cvs')
        .select('*')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false });
      setSavedCVs(cvData || []);

      const { data: letterData } = await supabase
        .from('motivation_letters')
        .select('*')
        .eq('user_id', session.user.id)
        .order('created_at', { ascending: false });
      setSavedLetters(letterData || []);

      try {
        const { data: portfolioData, error: portfolioError } = await supabase
          .from('portfolios')
          .select('*')
          .eq('user_id', session.user.id)
          .order('created_at', { ascending: false });
        if(!portfolioError) setSavedPortfolios(portfolioData || []);
      } catch (e) { console.warn("Portfolios table might not exist yet"); }

    } catch (err: any) {
      console.error("Error fetching data:", err);
      if (!error) setError("Failed to load data. Please try again.");
    } finally {
      setLoading(false);
    }
  }, [session.user, error]);

  useEffect(() => {
    fetchProfileData();
  }, [fetchProfileData]);

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!supabase || !session.user) return;
    try {
      setLoading(true);
      const { error } = await supabase.from('profiles').upsert({
        id: session.user.id,
        full_name: profile.full_name,
        pronouns: profile.pronouns,
        avatar_url: profile.avatar_url,
        updated_at: new Date().toISOString(),
      });
      if (error) throw error;
      setIsEditingProfile(false);
    } catch (err: any) {
      console.error("Error updating profile:", err);
      if (err.code === '42703') {
          setError("Database Error: Missing 'avatar_url' column. Please run the migration script in README.md.");
      } else {
          setError(`Failed to update profile: ${err.message}`);
      }
    } finally {
      setLoading(false);
    }
  };

  const handlePasswordChange = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!supabase) return;
      setPasswordMessage(null);

      if (newPassword !== confirmPassword) {
          setPasswordMessage({ type: 'error', text: 'Passwords do not match.' });
          return;
      }
      if (newPassword.length < 6) {
          setPasswordMessage({ type: 'error', text: 'Password must be at least 6 characters.' });
          return;
      }

      try {
          const { error } = await supabase.auth.updateUser({ password: newPassword });
          if (error) throw error;
          setPasswordMessage({ type: 'success', text: 'Password updated successfully.' });
          setNewPassword('');
          setConfirmPassword('');
          setTimeout(() => setIsChangingPassword(false), 2000);
      } catch (err: any) {
          setPasswordMessage({ type: 'error', text: err.message });
      }
  };

  const handleAvatarUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    if (!event.target.files || event.target.files.length === 0 || !supabase) return;
    setUploadingAvatar(true);
    try {
        const file = event.target.files[0];
        const fileExt = file.name.split('.').pop();
        const fileName = `${session.user.id}.${fileExt}`;
        const filePath = `${fileName}`;

        const { error: uploadError } = await supabase.storage
            .from('avatars')
            .upload(filePath, file, { upsert: true });

        if (uploadError) throw uploadError;

        const { data: { publicUrl } } = supabase.storage
            .from('avatars')
            .getPublicUrl(filePath);

        setProfile(prev => ({ ...prev, avatar_url: publicUrl }));

        const { error: updateError } = await supabase.from('profiles').upsert({
            id: session.user.id,
            avatar_url: publicUrl,
            updated_at: new Date().toISOString(),
        });

        if (updateError) throw updateError;

    } catch (error: any) {
        if (error.message && (error.message.includes("Bucket not found") || error.statusCode === '404')) {
            alert("Configuration Error: The 'avatars' storage bucket does not exist. Please run the STORAGE SETUP SQL script found in README.md.");
        } else if (error.code === '42703' || (error.message && error.message.includes('avatar_url'))) {
            alert("Database Error: The 'avatar_url' column is missing. Please run the 'Fix Database Schema' script in README.md.");
        } else {
            alert('Error uploading avatar: ' + error.message);
        }
    } finally {
        setUploadingAvatar(false);
    }
  };

  // --- Document Management Functions ---

  const handleOpenDoc = (doc: DocViewerState) => {
      setViewingDoc(doc);
      setEditTitle(doc.title);
      setEditContent(doc.content);
      setIsEditingDoc(false);
  };

  const handleCloseDoc = () => {
      setViewingDoc(null);
      setIsEditingDoc(false);
  };

  const handleDownloadDoc = () => {
      if (!viewingDoc) return;

      if (viewingDoc.type === 'cv' || viewingDoc.type === 'portfolio') {
          // Download HTML via Print Window or Blob
          if (viewingDoc.type === 'portfolio') {
             const element = document.createElement("a");
             const file = new Blob([viewingDoc.content], {type: 'text/html'});
             element.href = URL.createObjectURL(file);
             element.download = `${viewingDoc.title.replace(/\s+/g, '_')}.html`;
             document.body.appendChild(element);
             element.click();
             document.body.removeChild(element);
             return;
          }

          const printWindow = window.open('', '', 'width=800,height=900');
          if (printWindow) {
              printWindow.document.write(`
                <html>
                  <head>
                    <title>${viewingDoc.title}</title>
                    <style>
                      body { margin: 0; padding: 0; background: white; -webkit-print-color-adjust: exact; font-family: sans-serif; }
                      @page { size: A4; margin: 0; }
                      @media print {
                        body { -webkit-print-color-adjust: exact; }
                      }
                    </style>
                  </head>
                  <body>
                    ${viewingDoc.content}
                  </body>
                </html>
              `);
              printWindow.document.close();
              printWindow.focus();
              printWindow.print();
          }
      } else {
          // Download Letter as .txt
          const element = document.createElement("a");
          const file = new Blob([viewingDoc.content], {type: 'text/plain'});
          element.href = URL.createObjectURL(file);
          element.download = `${viewingDoc.title.replace(/\s+/g, '_')}.txt`;
          document.body.appendChild(element);
          element.click();
          document.body.removeChild(element);
      }
  };

  const handleDeleteDoc = async () => {
      if (!viewingDoc || !supabase) return;
      if (!window.confirm("Are you sure you want to delete this document? This cannot be undone.")) return;

      try {
          let table = '';
          if (viewingDoc.type === 'cv') table = 'cvs';
          else if (viewingDoc.type === 'letter') table = 'motivation_letters';
          else if (viewingDoc.type === 'portfolio') table = 'portfolios';

          const { error } = await supabase.from(table).delete().eq('id', viewingDoc.id);

          if (error) throw error;

          // Update local state
          if (viewingDoc.type === 'cv') setSavedCVs(prev => prev.filter(cv => cv.id !== viewingDoc.id));
          else if (viewingDoc.type === 'letter') setSavedLetters(prev => prev.filter(letter => letter.id !== viewingDoc.id));
          else if (viewingDoc.type === 'portfolio') setSavedPortfolios(prev => prev.filter(p => p.id !== viewingDoc.id));

          handleCloseDoc();
      } catch (err: any) {
          alert("Error deleting document: " + err.message);
      }
  };

  const handleEditClick = () => {
    if (viewingDoc?.type === 'cv') {
        const fullCV = savedCVs.find(c => c.id === viewingDoc.id);
        if (fullCV) {
            onEditCV(fullCV);
            return;
        }
    } else if (viewingDoc?.type === 'portfolio') {
        const fullPort = savedPortfolios.find(p => p.id === viewingDoc.id);
        if (fullPort) {
            onEditPortfolio(fullPort);
            return;
        }
    }
    // For letters, or fallback, toggle in-place editor
    setIsEditingDoc(true);
  };

  const handleSaveDocUpdates = async () => {
      if (!viewingDoc || !supabase) return;
      setIsSavingDoc(true);

      try {
          let table = '';
          if (viewingDoc.type === 'cv') table = 'cvs';
          else if (viewingDoc.type === 'letter') table = 'motivation_letters';
          else if (viewingDoc.type === 'portfolio') table = 'portfolios';

          const updates = {
              title: editTitle,
              content: editContent,
          };

          const { error } = await supabase.from(table).update(updates).eq('id', viewingDoc.id);
          if (error) throw error;

          // Update local state list
          if (viewingDoc.type === 'cv') setSavedCVs(prev => prev.map(cv => cv.id === viewingDoc.id ? { ...cv, ...updates } : cv));
          else if (viewingDoc.type === 'letter') setSavedLetters(prev => prev.map(l => l.id === viewingDoc.id ? { ...l, ...updates } : l));
          else if (viewingDoc.type === 'portfolio') setSavedPortfolios(prev => prev.map(p => p.id === viewingDoc.id ? { ...p, ...updates } : p));

          // Update viewing doc state
          setViewingDoc(prev => prev ? { ...prev, title: editTitle, content: editContent } : null);
          setIsEditingDoc(false);

      } catch (err: any) {
          alert("Failed to update: " + err.message);
      } finally {
          setIsSavingDoc(false);
      }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-[50vh]">
        <div className="w-12 h-12 border-4 border-brand-blue border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  // Render Interview Report View
  if (selectedInterview) {
    return (
      <div className="w-full px-6 space-y-6">
        <button onClick={() => setSelectedInterview(null)} className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors font-medium">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" /></svg>
            Back to Dashboard
        </button>
        <EndScreen
          onRestart={() => setSelectedInterview(null)}
          transcription={selectedInterview.transcription || []}
          feedback={selectedInterview.feedback || []}
          config={selectedInterview.config}
          userEmail={session.user.email || ''}
          userId={session.user.id}
          existingReport={selectedInterview.report || undefined}
          existingResources={selectedInterview.resources || undefined}
          isHistoryView={true}
        />
      </div>
    );
  }

  // Render Saved Document Modal
  if (viewingDoc) {
      return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4 animate-fade-in">
            <div className="bg-white text-black w-full max-w-5xl max-h-[90vh] rounded-2xl overflow-hidden flex flex-col shadow-2xl relative">

                {/* Modal Header */}
                <div className="p-4 bg-gray-100 border-b flex justify-between items-center shrink-0">
                    <div className="flex-1 mr-4">
                        {isEditingDoc ? (
                            <input 
                                type="text" 
                                value={editTitle}
                                onChange={(e) => setEditTitle(e.target.value)}
                                className="w-full px-3 py-1.5 border border-gray-300 rounded focus:ring-2 focus:ring-brand-blue outline-none font-bold text-lg"
                                placeholder="Document Title"
                            />
                        ) : (
                            <h3 className="font-bold text-lg truncate">{viewingDoc.title}</h3>
                        )}
                    </div>
                    <button onClick={handleCloseDoc} className="p-2 hover:bg-gray-200 rounded-full transition-colors text-gray-600">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                {/* Modal Body */}
                <div className="flex-1 overflow-y-auto p-0 custom-scrollbar bg-gray-50 relative">
                    {isEditingDoc ? (
                         (viewingDoc.type === 'cv' || viewingDoc.type === 'portfolio') ? (
                            <div className="h-full flex flex-col gap-2 p-4">
                                <label className="text-sm font-semibold text-gray-500">HTML Source Code (Edit cautiously)</label>
                                <textarea 
                                    value={editContent}
                                    onChange={(e) => setEditContent(e.target.value)}
                                    className="flex-1 w-full p-4 font-mono text-sm border rounded-lg bg-white focus:ring-2 focus:ring-brand-blue outline-none resize-none"
                                />
                            </div>
                         ) : (
                            <textarea 
                                value={editContent}
                                onChange={(e) => setEditContent(e.target.value)}
                                className="w-full h-full p-6 font-serif text-lg leading-relaxed border rounded-lg bg-white focus:ring-2 focus:ring-brand-green outline-none resize-none"
                            />
                         )
                    ) : (
                        (viewingDoc.type === 'cv' || viewingDoc.type === 'portfolio') ? (
                            <iframe 
                                title="Preview"
                                srcDoc={viewingDoc.content}
                                className="w-full h-full border-none"
                                sandbox="allow-scripts"
                            />
                        ) : (
                            <div className="whitespace-pre-wrap font-serif text-lg leading-relaxed max-w-3xl mx-auto bg-white p-8 shadow-sm">{viewingDoc.content}</div>
                        )
                    )}
                </div>

                {/* Modal Footer (Actions) */}
                <div className="p-4 bg-white border-t flex justify-between items-center shrink-0">
                    <div className="flex items-center gap-2">
                         {!isEditingDoc && (
                             <button onClick={handleDeleteDoc} className="flex items-center gap-2 px-4 py-2 text-red-500 hover:bg-red-50 rounded-lg font-medium transition-colors border border-transparent hover:border-red-100">
                                 <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                 Delete
                             </button>
                         )}
                    </div>

                    <div className="flex items-center gap-3">
                         {isEditingDoc ? (
                             <>
                                <button 
                                    onClick={() => { setIsEditingDoc(false); setEditTitle(viewingDoc.title); setEditContent(viewingDoc.content); }}
                                    className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg font-medium"
                                >
                                    Cancel
                                </button>
                                <button 
                                    onClick={handleSaveDocUpdates}
                                    disabled={isSavingDoc}
                                    className={`px-6 py-2 rounded-lg font-bold text-white shadow-md transition-all ${viewingDoc.type === 'letter' ? 'bg-brand-green hover:bg-green-600' : 'bg-brand-blue hover:bg-blue-600'}`}
                                >
                                    {isSavingDoc ? 'Saving...' : 'Save Changes'}
                                </button>
                             </>
                         ) : (
                             <>
                                <button 
                                    onClick={handleDownloadDoc}
                                    className="flex items-center gap-2 px-4 py-2 text-gray-700 hover:bg-gray-100 rounded-lg font-medium transition-colors border border-gray-200"
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                    Download
                                </button>
                                <button 
                                    onClick={handleEditClick}
                                    className={`flex items-center gap-2 px-6 py-2 rounded-lg font-bold text-white shadow-md transition-all ${viewingDoc.type === 'letter' ? 'bg-brand-green hover:bg-green-600' : 'bg-brand-blue hover:bg-blue-600'}`}
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                                    Edit
                                </button>
                             </>
                         )}
                    </div>
                </div>
            </div>
        </div>
      );
  }

  return (
    <div className="w-full px-6 space-y-8 animate-fade-in pb-12">
      <div className="flex items-center gap-3">
          <button onClick={onBack} className="p-2 rounded-lg hover:bg-white/10 transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
          </button>
          <h2 className="text-3xl font-bold text-white">Your Profile</h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {/* User Card */}
          <div className="glass-panel p-8 rounded-2xl flex flex-col items-center text-center h-fit">
              <div className="relative group">
                  <div className="w-32 h-32 rounded-full bg-gradient-to-br from-brand-blue to-brand-purple flex items-center justify-center text-5xl font-bold text-white shadow-xl mb-6 ring-4 ring-white/10 overflow-hidden">
                      {profile.avatar_url ? (
                          <img src={profile.avatar_url} alt="Profile" className="w-full h-full object-cover" />
                      ) : (
                          <span>{profile.full_name ? profile.full_name.charAt(0).toUpperCase() : session.user.email?.charAt(0).toUpperCase()}</span>
                      )}
                  </div>
                  <label className="absolute inset-0 rounded-full bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer">
                      <span className="text-xs font-bold text-white">{uploadingAvatar ? '...' : 'Change'}</span>
                      <input type="file" accept="image/*" className="hidden" onChange={handleAvatarUpload} disabled={uploadingAvatar} />
                  </label>
              </div>

              {isEditingProfile ? (
                  <form onSubmit={handleUpdateProfile} className="w-full space-y-4 mb-4">
                      <input
                          type="text"
                          value={profile.full_name}
                          onChange={(e) => setProfile({ ...profile, full_name: e.target.value })}
                          className="w-full bg-black/20 border border-white/10 rounded-lg px-4 py-2 text-white focus:ring-2 focus:ring-brand-blue outline-none"
                          placeholder="Full Name"
                      />
                      <input
                          type="text"
                          value={profile.pronouns}
                          onChange={(e) => setProfile({ ...profile, pronouns: e.target.value })}
                          className="w-full bg-black/20 border border-white/10 rounded-lg px-4 py-2 text-white focus:ring-2 focus:ring-brand-blue outline-none"
                          placeholder="Pronouns"
                      />
                      <div className="flex gap-2 justify-center pt-2">
                          <button type="button" onClick={() => setIsEditingProfile(false)} className="px-4 py-2 text-sm text-gray-400 hover:text-white">Cancel</button>
                          <button type="submit" className="px-4 py-2 bg-brand-blue rounded-lg text-sm font-bold text-white shadow-lg">Save</button>
                      </div>
                  </form>
              ) : (
                  <>
                    <h3 className="text-xl font-bold text-white mb-1">{profile.full_name || 'Anonymous User'}</h3>
                    <p className="text-gray-400 text-sm mb-2">{session.user.email}</p>

                    <div className="flex flex-wrap justify-center gap-2 mb-4">
                        {profile.pronouns && <span className="px-3 py-1 rounded-full bg-white/5 text-xs text-gray-300 border border-white/10">{profile.pronouns}</span>}

                        {profile.is_admin && (
                            <div className="px-3 py-1 bg-brand-red/20 text-brand-red text-xs font-bold rounded-full border border-brand-red/30">
                                Administrator
                            </div>
                        )}
                        <div className={`px-3 py-1 text-xs font-bold rounded-full border flex items-center gap-2 ${profile.subscription_tier === 'pro' ? 'bg-brand-purple/20 text-brand-purple border-brand-purple/30' : profile.subscription_tier === 'recruiter' ? 'bg-brand-green/20 text-brand-green border-brand-green/30' : 'bg-gray-700/50 text-gray-400 border-gray-600'}`}>
                            {profile.subscription_tier === 'pro' ? 'Pro Plan' : profile.subscription_tier === 'recruiter' ? 'Recruiter' : 'Free Plan'}
                            <button onClick={onManagePlan} className="hover:text-white underline text-[10px] ml-1">Manage</button>
                        </div>
                    </div>

                    <div className="flex flex-col gap-2 w-full px-4">
                        <button onClick={() => setIsEditingProfile(true)} className="text-brand-blue hover:text-blue-300 text-sm font-semibold transition-colors py-2 bg-brand-blue/10 rounded-lg">Edit Profile</button>
                        <button onClick={() => setIsChangingPassword(!isChangingPassword)} className="text-gray-400 hover:text-white text-sm font-semibold transition-colors py-2 bg-white/5 rounded-lg">Change Password</button>
                    </div>
                  </>
              )}

              {/* Password Change Form */}
              {isChangingPassword && !isEditingProfile && (
                  <form onSubmit={handlePasswordChange} className="w-full space-y-3 mt-4 pt-4 border-t border-white/10 animate-fade-in">
                      <input
                          type="password"
                          value={newPassword}
                          onChange={(e) => setNewPassword(e.target.value)}
                          className="w-full bg-black/20 border border-white/10 rounded-lg px-4 py-2 text-white focus:ring-1 focus:ring-brand-blue outline-none text-sm"
                          placeholder="New Password"
                      />
                      <input
                          type="password"
                          value={confirmPassword}
                          onChange={(e) => setConfirmPassword(e.target.value)}
                          className="w-full bg-black/20 border border-white/10 rounded-lg px-4 py-2 text-white focus:ring-1 focus:ring-brand-blue outline-none text-sm"
                          placeholder="Confirm Password"
                      />
                      {passwordMessage && (
                          <p className={`text-xs ${passwordMessage.type === 'error' ? 'text-red-400' : 'text-green-400'}`}>{passwordMessage.text}</p>
                      )}
                      <div className="flex gap-2 justify-center">
                          <button type="button" onClick={() => setIsChangingPassword(false)} className="px-3 py-1.5 text-xs text-gray-400 hover:text-white">Cancel</button>
                          <button type="submit" className="px-3 py-1.5 bg-brand-blue rounded-lg text-xs font-bold text-white shadow-lg">Update</button>
                      </div>
                  </form>
              )}
          </div>

          {/* Tabs & Content */}
          <div className="md:col-span-2 space-y-6">
              <div className="flex gap-4 border-b border-white/10 pb-2 overflow-x-auto">
                  <button 
                    onClick={() => setActiveTab('history')}
                    className={`pb-2 text-sm font-bold transition-colors whitespace-nowrap ${activeTab === 'history' ? 'text-brand-blue border-b-2 border-brand-blue' : 'text-gray-400 hover:text-white'}`}
                  >
                      Session History
                  </button>
                  <button 
                    onClick={() => setActiveTab('cvs')}
                    className={`pb-2 text-sm font-bold transition-colors whitespace-nowrap ${activeTab === 'cvs' ? 'text-brand-purple border-b-2 border-brand-purple' : 'text-gray-400 hover:text-white'}`}
                  >
                      Saved CVs
                  </button>
                  <button 
                    onClick={() => setActiveTab('letters')}
                    className={`pb-2 text-sm font-bold transition-colors whitespace-nowrap ${activeTab === 'letters' ? 'text-brand-green border-b-2 border-brand-green' : 'text-gray-400 hover:text-white'}`}
                  >
                      Motivation Letters
                  </button>
                  <button 
                    onClick={() => setActiveTab('portfolios')}
                    className={`pb-2 text-sm font-bold transition-colors whitespace-nowrap ${activeTab === 'portfolios' ? 'text-brand-yellow border-b-2 border-brand-yellow' : 'text-gray-400 hover:text-white'}`}
                  >
                      Portfolios
                  </button>
              </div>

              {error && <p className="text-red-400 bg-red-500/10 p-4 rounded-xl border border-red-500/20">{error}</p>}

              <div className="space-y-4 min-h-[300px]">
                  {/* HISTORY TAB */}
                  {activeTab === 'history' && (
                      interviews.length > 0 ? interviews.map((interview) => (
                          <div 
                            key={interview.id} 
                            onClick={() => setSelectedInterview(interview)}
                            className="glass-panel p-6 rounded-xl hover:bg-white/5 transition-all cursor-pointer group border border-white/5 hover:border-brand-blue/30 relative overflow-hidden"
                          >
                              <div className="absolute inset-y-0 left-0 w-1 bg-gradient-to-b from-brand-blue to-brand-purple opacity-0 group-hover:opacity-100 transition-opacity"></div>
                              <div className="flex justify-between items-center">
                                  <div>
                                      <h4 className="text-lg font-bold text-white group-hover:text-brand-blue transition-colors mb-1">{interview.config?.name || 'Session'}</h4>
                                      <p className="text-sm text-gray-500">{new Date(interview.created_at).toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
                                  </div>
                                  <div className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center group-hover:bg-brand-blue/20 transition-colors">
                                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400 group-hover:text-brand-blue" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" /></svg>
                                  </div>
                              </div>
                          </div>
                      )) : (
                          <div className="glass-panel p-10 rounded-xl text-center">
                              <p className="text-gray-400 mb-4">No sessions recorded yet.</p>
                              <button onClick={onBack} className="bg-white text-black font-bold py-2 px-6 rounded-lg hover:bg-gray-200 transition-colors">Start Practice</button>
                          </div>
                      )
                  )}

                  {/* CVs TAB */}
                  {activeTab === 'cvs' && (
                      savedCVs.length > 0 ? savedCVs.map((cv) => (
                          <div 
                            key={cv.id} 
                            onClick={() => handleOpenDoc({ id: cv.id, type: 'cv', content: cv.content, title: cv.title, originalData: cv.data })}
                            className="glass-panel p-6 rounded-xl hover:bg-white/5 transition-all cursor-pointer group border border-white/5 hover:border-brand-purple/30 relative overflow-hidden"
                          >
                              <div className="absolute inset-y-0 left-0 w-1 bg-brand-purple opacity-0 group-hover:opacity-100 transition-opacity"></div>
                              <div className="flex justify-between items-center">
                                  <div>
                                      <h4 className="text-lg font-bold text-white group-hover:text-brand-purple transition-colors mb-1">{cv.title}</h4>
                                      <p className="text-sm text-gray-500">{new Date(cv.created_at).toLocaleDateString()}</p>
                                  </div>
                                  <button className="text-xs bg-white/10 hover:bg-brand-purple/50 px-3 py-1 rounded text-white transition-colors">View / Edit</button>
                              </div>
                          </div>
                      )) : (
                          <div className="glass-panel p-10 rounded-xl text-center">
                              <p className="text-gray-400">No saved resumes found.</p>
                          </div>
                      )
                  )}

                  {/* LETTERS TAB */}
                  {activeTab === 'letters' && (
                      savedLetters.length > 0 ? savedLetters.map((letter) => (
                          <div 
                            key={letter.id} 
                            onClick={() => handleOpenDoc({ id: letter.id, type: 'letter', content: letter.content, title: letter.company })}
                            className="glass-panel p-6 rounded-xl hover:bg-white/5 transition-all cursor-pointer group border border-white/5 hover:border-brand-green/30 relative overflow-hidden"
                          >
                              <div className="absolute inset-y-0 left-0 w-1 bg-brand-green opacity-0 group-hover:opacity-100 transition-opacity"></div>
                              <div className="flex justify-between items-center">
                                  <div>
                                      <h4 className="text-lg font-bold text-white group-hover:text-brand-green transition-colors mb-1">{letter.company}</h4>
                                      <p className="text-sm text-gray-300">{letter.job_title}</p>
                                      <p className="text-xs text-gray-500 mt-1">{new Date(letter.created_at).toLocaleDateString()}</p>
                                  </div>
                                  <button className="text-xs bg-white/10 hover:bg-brand-green/50 px-3 py-1 rounded text-white transition-colors">View / Edit</button>
                              </div>
                          </div>
                      )) : (
                          <div className="glass-panel p-10 rounded-xl text-center">
                              <p className="text-gray-400">No saved cover letters found.</p>
                          </div>
                      )
                  )}

                  {/* PORTFOLIOS TAB */}
                  {activeTab === 'portfolios' && (
                      savedPortfolios.length > 0 ? savedPortfolios.map((p) => (
                          <div 
                            key={p.id} 
                            onClick={() => handleOpenDoc({ id: p.id, type: 'portfolio', content: p.content, title: p.title, originalData: p.data })}
                            className="glass-panel p-6 rounded-xl hover:bg-white/5 transition-all cursor-pointer group border border-white/5 hover:border-brand-yellow/30 relative overflow-hidden"
                          >
                              <div className="absolute inset-y-0 left-0 w-1 bg-brand-yellow opacity-0 group-hover:opacity-100 transition-opacity"></div>
                              <div className="flex justify-between items-center">
                                  <div>
                                      <h4 className="text-lg font-bold text-white group-hover:text-brand-yellow transition-colors mb-1">{p.title}</h4>
                                      <p className="text-sm text-gray-500">{new Date(p.created_at).toLocaleDateString()}</p>
                                  </div>
                                  <button className="text-xs bg-white/10 hover:bg-brand-yellow/50 px-3 py-1 rounded text-white transition-colors">View / Edit</button>
                              </div>
                          </div>
                      )) : (
                          <div className="glass-panel p-10 rounded-xl text-center">
                              <p className="text-gray-400">No saved portfolios found.</p>
                          </div>
                      )
                  )}
              </div>
          </div>
      </div>
    </div>
  );
};

export default ProfileScreen;

import React, { useEffect, useState } from 'react';
import { GoogleGenAI, Type } from '@google/genai';
import { supabase } from '../services/supabaseClient';
import type { TranscriptionEntry, FeedbackEntry, InterviewConfig, SuggestedResource, InterviewReport } from '../types';

interface EndScreenProps {
  onRestart: () => void;
  transcription: TranscriptionEntry[];
  feedback: FeedbackEntry[];
  config: InterviewConfig;
  userEmail: string;
  userId: string;
  existingReport?: InterviewReport;
  existingResources?: SuggestedResource[];
  isHistoryView?: boolean;
}

const LANGUAGES = [
  "English", "Spanish", "French", "German", "Chinese (Simplified)", 
  "Japanese", "Korean", "Hindi", "Portuguese", "Russian", "Arabic", "Italian", "Dutch", "Turkish", "Polish"
];

interface UiLabels {
  performanceDashboard: string;
  overallSummary: string;
  keyStrengths: string;
  areasForImprovement: string;
  actionableAdvice: string;
  learningResources: string;
  tryAnotherInterview: string;
  reportReady: string;
  reportReadySubtext: string;
  generatedFor: string;
}

const DEFAULT_LABELS: UiLabels = {
  performanceDashboard: "Performance Dashboard",
  overallSummary: "Executive Summary",
  keyStrengths: "Key Strengths",
  areasForImprovement: "Growth Areas",
  actionableAdvice: "Action Plan",
  learningResources: "Curated Resources",
  tryAnotherInterview: "Start New Session",
  reportReady: "Analysis Complete",
  reportReadySubtext: "Your personalized performance report is ready.",
  generatedFor: "Assessment for",
};

const SkillMeter: React.FC<{ skill: string; rating: number; justification: string }> = ({ skill, rating, justification }) => {
  const percentage = Math.max(rating * 10, 5); 
  let color = 'from-red-500 to-red-600';
  let textCol = 'text-red-400';
  if (rating > 4) { color = 'from-yellow-400 to-yellow-600'; textCol = 'text-brand-yellow'; }
  if (rating > 7) { color = 'from-green-400 to-green-600'; textCol = 'text-brand-green'; }

  return (
    <div className="group bg-black/20 p-4 rounded-xl border border-white/5 hover:border-white/10 transition-colors">
      <div className="flex justify-between items-center mb-2">
        <p className="font-semibold text-gray-200 text-sm tracking-wide">{skill}</p>
        <span className={`font-bold text-lg ${textCol}`}>{rating}<span className="text-gray-600 text-sm">/10</span></span>
      </div>
      <div className="w-full bg-gray-800 rounded-full h-2 mb-3 overflow-hidden">
        <div className={`h-full rounded-full bg-gradient-to-r ${color} transition-all duration-1000 ease-out`} style={{ width: `${percentage}%` }}></div>
      </div>
      <p className="text-xs text-gray-400 leading-relaxed opacity-80 group-hover:opacity-100 transition-opacity">{justification}</p>
    </div>
  );
};

const FeedbackCard: React.FC<{ title: string; items: string[]; icon: React.ReactNode; color: 'green' | 'yellow' | 'blue'}> = ({title, items, icon, color}) => {
  const styles = {
    green: 'bg-green-500/10 border-green-500/20 text-green-100',
    yellow: 'bg-yellow-500/10 border-yellow-500/20 text-yellow-100',
    blue: 'bg-blue-500/10 border-blue-500/20 text-blue-100',
  };
  const titleColors = {
      green: 'text-brand-green',
      yellow: 'text-brand-yellow',
      blue: 'text-brand-blue'
  };

  return (
    <div className={`p-6 rounded-2xl border backdrop-blur-sm h-full ${styles[color]}`}>
      <div className="flex items-center gap-3 mb-4">
        <div className={`p-2 rounded-lg bg-black/20 ${titleColors[color]}`}>{icon}</div>
        <h4 className={`text-lg font-bold ${titleColors[color]}`}>{title}</h4>
      </div>
      <ul className="space-y-3">
        {items.map((item, i) => (
            <li key={i} className="flex items-start gap-2 text-sm leading-relaxed opacity-90">
                <span className={`mt-1.5 w-1.5 h-1.5 rounded-full flex-shrink-0 ${titleColors[color].replace('text-', 'bg-')}`}></span>
                {item}
            </li>
        ))}
      </ul>
    </div>
  );
};

const EndScreen: React.FC<EndScreenProps> = ({ 
  onRestart, 
  transcription, 
  feedback, 
  config, 
  userEmail, 
  userId, 
  existingReport, 
  existingResources,
  isHistoryView = false
}) => {
  const [report, setReport] = useState<InterviewReport | null>(null);
  const [resources, setResources] = useState<SuggestedResource[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [currentLanguage, setCurrentLanguage] = useState("English");
  const [translations, setTranslations] = useState<Record<string, { report: InterviewReport; labels: UiLabels }>>({});
  const [isTranslating, setIsTranslating] = useState(false);

  useEffect(() => {
    if (existingReport) {
        setReport(existingReport);
        setResources(existingResources || []);
        setIsLoading(false);
        return;
    }

    const generateAndSaveReport = async () => {
      try {
        if (!process.env.API_KEY) throw new Error("API_KEY is not configured.");
        if (!userId) throw new Error("User ID is not available.");

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const transcriptText = transcription.map(e => `${e.speaker.toUpperCase()}: ${e.text}`).join('\n');
        const feedbackText = feedback.map(f => `On answer "${f.userText}", feedback: "${f.feedbackText}"`).join('\n');
        const summaryPrompt = `You are an expert career coach. User role: ${config.name}. Transcript:\n${transcriptText}\n\nFeedback:\n${feedbackText}\n\nProvide a performance review JSON. Include 'Communication' and 3 relevant skills.`;

        const schema = {
            type: Type.OBJECT,
            properties: {
                overallSummary: { type: Type.STRING },
                keyStrengths: { type: Type.ARRAY, items: { type: Type.STRING } },
                areasForImprovement: { type: Type.ARRAY, items: { type: Type.STRING } },
                actionableAdvice: { type: Type.ARRAY, items: { type: Type.STRING } },
                skillRatings: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            skillName: { type: Type.STRING },
                            rating: { type: Type.INTEGER },
                            justification: { type: Type.STRING },
                        },
                        required: ['skillName', 'rating', 'justification'],
                    },
                }
            },
            required: ['overallSummary', 'keyStrengths', 'areasForImprovement', 'actionableAdvice', 'skillRatings']
        };

        const summaryResult = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: summaryPrompt,
            config: { responseMimeType: "application/json", responseSchema: schema },
        });

        const receivedReport: InterviewReport = JSON.parse(summaryResult.text.trim());

        const resourcesPrompt = `Based on: ${receivedReport.areasForImprovement.join(', ')}. Find 3 articles.`;
        const resourcesResult = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: resourcesPrompt,
            config: { tools: [{googleSearch: {}}] },
        });

        const groundingChunks = resourcesResult.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
        const receivedResources: SuggestedResource[] = groundingChunks
            .map((chunk: any) => chunk.web)
            .filter((web: any) => web && web.uri && web.title)
            .slice(0, 3)
            .map((web: any) => ({ uri: web.uri, title: web.title }));

        setReport(receivedReport);
        setResources(receivedResources);

        if (supabase && !isHistoryView) {
            await supabase.from('interviews').insert([
                { user_id: userId, config: config, transcription: transcription, feedback: feedback, report: receivedReport, resources: receivedResources }
            ]);
        }

      } catch (err) {
        console.error("Error generating report:", err);
        setError("Could not generate report. Please try again later.");
      } finally {
        setIsLoading(false);
      }
    };

    if (transcription.length > 0) {
        generateAndSaveReport();
    } else {
        if(!existingReport) {
            setError("No interview data recorded.");
            setIsLoading(false);
        }
    }
  }, [transcription, feedback, config, userEmail, userId, existingReport, existingResources, isHistoryView]);

  const handleLanguageChange = async (e: React.ChangeEvent<HTMLSelectElement>) => {
    const targetLang = e.target.value;
    if (targetLang === currentLanguage) return;
    setCurrentLanguage(targetLang);

    if (targetLang === "English" || translations[targetLang]) return;
    if (!report) return;

    setIsTranslating(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Translate this JSON to ${targetLang}: ${JSON.stringify({ report: report, uiLabels: DEFAULT_LABELS })}`;
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: { responseMimeType: 'application/json' }
        });
        const translatedData = JSON.parse(response.text);
        setTranslations(prev => ({ ...prev, [targetLang]: translatedData }));
    } catch (err) {
        console.error("Translation failed:", err);
        setCurrentLanguage("English");
    } finally {
        setIsTranslating(false);
    }
  };

  const activeReport = currentLanguage === "English" ? report : (translations[currentLanguage]?.report || report);
  const activeLabels = currentLanguage === "English" ? DEFAULT_LABELS : (translations[currentLanguage]?.labels || DEFAULT_LABELS);

  return (
    <div className="w-full px-6 space-y-8 pb-10">
      {/* Header */}
      <div className="glass-panel p-6 rounded-2xl flex flex-col md:flex-row justify-between items-center gap-4 animate-fade-in">
         <div>
             <h2 className="text-2xl font-bold text-white">{activeLabels.reportReady}</h2>
             <p className="text-gray-400 text-sm">{activeLabels.reportReadySubtext}</p>
         </div>
         {report && (
            <div className="flex items-center gap-3 bg-black/30 p-2 rounded-lg border border-white/5">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M7 2a1 1 0 011 1v1h3a1 1 0 110 2H9.578a18.89 18.89 0 01-.253 5.954l-.184 1.054A3.003 3.003 0 0112 17a3.001 3.001 0 01-5.748-1.077l.794-4.526a1.272 1.272 0 01.328-.686c.162-.187.35-.357.562-.511A18.88 18.88 0 017 6V3a1 1 0 011-1z" clipRule="evenodd" /></svg>
                <select
                    value={currentLanguage}
                    onChange={handleLanguageChange}
                    disabled={isTranslating}
                    className="bg-transparent text-sm text-white focus:outline-none cursor-pointer"
                >
                    {LANGUAGES.map(lang => <option key={lang} value={lang} className="bg-gray-800">{lang}</option>)}
                </select>
                {isTranslating && <div className="animate-spin h-4 w-4 border-2 border-brand-blue rounded-full border-t-transparent"></div>}
            </div>
         )}
      </div>

      {isLoading && (
        <div className="glass-panel p-20 rounded-2xl flex flex-col items-center justify-center text-center animate-pulse">
          <div className="w-20 h-20 border-4 border-brand-blue border-t-transparent rounded-full animate-spin mb-6"></div>
          <p className="text-xl text-gray-300">Generating comprehensive analysis...</p>
        </div>
      )}

      {error && (
        <div className="bg-red-500/10 border border-red-500/50 rounded-2xl p-8 text-center">
          <h3 className="text-xl font-bold mb-2 text-brand-red">Report Generation Failed</h3>
          <p className="text-gray-300">{error}</p>
        </div>
      )}

      {!isLoading && !error && activeReport && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-slide-up">
            {/* Left Column: Summary & Skills */}
            <div className="lg:col-span-8 space-y-6">

                {/* Executive Summary */}
                <div className="glass-panel p-8 rounded-2xl">
                    <h3 className="text-xl font-bold mb-4 text-white flex items-center gap-3">
                         <span className="w-1.5 h-6 bg-brand-purple rounded-full"></span>
                         {activeLabels.overallSummary}
                    </h3>
                    {isTranslating ? <p className="animate-pulse text-gray-500">Updating...</p> : <p className="text-gray-300 leading-relaxed text-lg">{activeReport.overallSummary}</p>}
                </div>

                {/* Skills Grid */}
                <div className="glass-panel p-8 rounded-2xl">
                    <h3 className="text-xl font-bold mb-6 text-white flex items-center gap-3">
                         <span className="w-1.5 h-6 bg-brand-blue rounded-full"></span>
                         {activeLabels.performanceDashboard}
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                         {isTranslating 
                            ? <div className="col-span-2 h-40 animate-pulse bg-white/5 rounded-xl"></div>
                            : activeReport.skillRatings.map((skill) => <SkillMeter key={skill.skillName} skill={skill.skillName} rating={skill.rating} justification={skill.justification} />)
                         }
                    </div>
                </div>

                {/* Feedback Cards */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                     <FeedbackCard 
