import React, { useState, useEffect } from 'react';
import { supabase } from './services/supabaseClient';
import { Session } from '@supabase/supabase-js';
import LandingPage from './components/LandingPage';
import AuthScreen from './components/AuthScreen';
import Dashboard from './components/WelcomeScreen';
import InterviewSetup from './components/InterviewSetup';
import InterviewScreen from './components/InterviewScreen';
import EndScreen from './components/EndScreen';
import CVBuilder from './components/CVBuilder';
import MotivationLetter from './components/MotivationLetter';
import PortfolioBuilder from './components/PortfolioBuilder';
import ProfileScreen from './components/ProfileScreen';
import AdminDashboard from './components/AdminDashboard';
import InterviewerDashboard from './components/InterviewerDashboard';
import PricingScreen from './components/PricingScreen';
import AboutUs from './components/AboutUs';
import PrivacyPolicy from './components/PrivacyPolicy';
import TermsOfService from './components/TermsOfService';
import CookieBanner from './components/CookieBanner';
import type { InterviewConfig, TranscriptionEntry, FeedbackEntry, SavedCV, SavedPortfolio, SubscriptionTier } from './types';

const App: React.FC = () => {
  const [session, setSession] = useState<Session | null>(null);
  const [view, setView] = useState('landing');
  const [interviewConfig, setInterviewConfig] = useState<InterviewConfig | null>(null);
  const [isPracticeMode, setIsPracticeMode] = useState(false);
  const [transcription, setTranscription] = useState<TranscriptionEntry[]>([]);
  const [feedback, setFeedback] = useState<FeedbackEntry[]>([]);

  const [inviteToken, setInviteToken] = useState<string | null>(null);
  const [pendingConfig, setPendingConfig] = useState<InterviewConfig | null>(null); // Assigned interview config

  const [userProfile, setUserProfile] = useState<any>(null);

  // Data for editing
  const [editingCV, setEditingCV] = useState<SavedCV | undefined>(undefined);
  const [editingPortfolio, setEditingPortfolio] = useState<SavedPortfolio | undefined>(undefined);

  // Check for Invite Token in URL
  useEffect(() => {
     const params = new URLSearchParams(window.location.search);
     const token = params.get('invite');
     if (token) {
         setInviteToken(token);
         setView('auth');
         // Clean URL
         window.history.replaceState({}, document.title, window.location.pathname);
     }
  }, []);

  useEffect(() => {
    if (!supabase) return;

    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) {
          fetchUserProfile(session.user.id);
      } else {
          // If not logged in and no invite token, show landing
          if (!inviteToken) setView('landing');
      }
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) {
         fetchUserProfile(session.user.id);
         if (view === 'landing' || view === 'auth') setView('dashboard');
      } else {
         setView(inviteToken ? 'auth' : 'landing');
         setUserProfile(null);
      }
    });

    return () => subscription.unsubscribe();
  }, [inviteToken]);

  const fetchUserProfile = async (userId: string) => {
      if(!supabase) return;
      const { data } = await supabase.from('profiles').select('*').eq('id', userId).single();
      if (data) {
          setUserProfile(data);
          // Check for pending assigned interviews if candidate
          if (data.role === 'candidate') {
              checkForAssignedInterviews(userId);
          }
      }
  };

  const checkForAssignedInterviews = async (userId: string) => {
      if(!supabase) return;
      // Check invites table for accepted invites linked to this candidate
      const { data } = await supabase.from('invites').select('config').eq('candidate_id', userId).eq('status', 'accepted').order('created_at', {ascending: false}).limit(1);

      if (data && data.length > 0) {
          setPendingConfig(data[0].config);
      }
  };

  const handleStartInterview = (config: InterviewConfig, practice: boolean) => {
    setInterviewConfig(config);
    setIsPracticeMode(practice);
    setTranscription([]);
    setFeedback([]);
    setView('interview');
  };

  const handleEndInterview = (t: TranscriptionEntry[], f: FeedbackEntry[]) => {
    setTranscription(t);
    setFeedback(f);
    setView('results');
  };

  const handleEditCV = (cv: SavedCV) => {
      setEditingCV(cv);
      setView('cv-builder');
  };

  const handleEditPortfolio = (p: SavedPortfolio) => {
      setEditingPortfolio(p);
      setView('portfolio-builder');
  };

  const handleUpgrade = (tier: SubscriptionTier) => {
      if (userProfile) {
          setUserProfile({ ...userProfile, subscription_tier: tier });
      }
  };

  // View Routing
  const renderView = () => {
    switch (view) {
      case 'landing':
        return (
          <LandingPage 
            onLogin={() => setView('auth')}
            onSignup={() => setView('auth')}
            onAbout={() => setView('about')}
            onPrivacy={() => setView('privacy')}
            onTerms={() => setView('terms')}
          />
        );
      case 'about':
        return <AboutUs onBack={() => setView('landing')} />;
      case 'privacy':
          return <PrivacyPolicy onBack={() => setView('landing')} />;
      case 'terms':
          return <TermsOfService onBack={() => setView('landing')} />;
      case 'auth':
        return (
          <div className="min-h-screen flex items-center justify-center bg-dark-bg p-4 bg-[url('https://grainy-gradients.vercel.app/noise.svg')]">
             <AuthScreen 
                inviteToken={inviteToken} 
                onBack={() => setView('landing')} 
             />
          </div>
        );
      case 'dashboard':
        return (
          <div className="min-h-screen bg-dark-bg bg-[url('https://grainy-gradients.vercel.app/noise.svg')]">
             <nav className="p-6 flex justify-between items-center max-w-7xl mx-auto">
                <h1 className="text-2xl font-display font-bold text-white tracking-tight">prepare<span className="text-brand-blue">AI</span></h1>
                <div className="flex items-center gap-4">
                    {userProfile?.role === 'interviewer' && (
                        <button onClick={() => setView('interviewer-dashboard')} className="text-sm font-bold text-gray-300 hover:text-white transition-colors">
                            Recruiter Panel
                        </button>
                    )}
                    <button onClick={() => setView('profile')} className="w-10 h-10 rounded-full bg-gradient-to-tr from-brand-blue to-brand-purple flex items-center justify-center text-white font-bold shadow-lg hover:scale-105 transition-transform">
                        {userProfile?.full_name?.charAt(0) || session?.user.email?.charAt(0).toUpperCase()}
                    </button>
                    <button onClick={() => supabase?.auth.signOut()} className="text-sm font-bold text-gray-400 hover:text-white transition-colors">Sign Out</button>
                </div>
             </nav>
             <div className="max-w-7xl mx-auto">
                 <Dashboard 
                    onNavigate={(v) => {
                        // Reset editing states when navigating from dashboard
                        if (v === 'cv-builder') setEditingCV(undefined);
                        if (v === 'portfolio-builder') setEditingPortfolio(undefined);
                        setView(v);
                    }} 
                    userName={userProfile?.full_name || session?.user.email} 
                    isAdmin={userProfile?.is_admin}
                    pendingConfig={pendingConfig}
                    onStartAssigned={() => handleStartInterview(pendingConfig!, false)}
                 />
             </div>
          </div>
        );
      case 'interview-setup':
        return (
            <div className="min-h-screen bg-dark-bg flex items-center justify-center p-4 bg-[url('https://grainy-gradients.vercel.app/noise.svg')]">
                <div className="w-full max-w-5xl">
                    <InterviewSetup onStart={handleStartInterview} onBack={() => setView('dashboard')} />
                </div>
            </div>
        );
      case 'interview':
        return (
            <div className="min-h-screen bg-black flex items-center justify-center p-4">
                 <div className="w-full max-w-7xl">
                    {interviewConfig && (
                        <InterviewScreen 
                            config={interviewConfig} 
                            onEnd={handleEndInterview} 
                            isPracticeMode={isPracticeMode}
                        />
                    )}
                 </div>
            </div>
        );
      case 'results':
        return (
            <div className="min-h-screen bg-dark-bg py-8 bg-[url('https://grainy-gradients.vercel.app/noise.svg')]">
                <div className="max-w-7xl mx-auto">
                    <div className="px-6 mb-6">
                         <button onClick={() => setView('dashboard')} className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" /></svg>
                            Back to Dashboard
                        </button>
                    </div>
                    {interviewConfig && session?.user && (
                        <EndScreen 
                            onRestart={() => setView('dashboard')} 
                            transcription={transcription} 
                            feedback={feedback} 
                            config={interviewConfig}
                            userEmail={session.user.email!}
                            userId={session.user.id}
                        />
                    )}
                </div>
            </div>
        );
      case 'cv-builder':
          return (
            <div className="min-h-screen bg-dark-bg p-4 flex items-center justify-center bg-[url('https://grainy-gradients.vercel.app/noise.svg')]">
                 <div className="w-full max-w-7xl">
                    <CVBuilder 
                        onBack={() => setView('dashboard')} 
                        initialData={editingCV?.data} 
                        cvId={editingCV?.id}
                        subscriptionTier={userProfile?.subscription_tier}
                    />
                 </div>
            </div>
          );
      case 'motivation-letter':
          return (
            <div className="min-h-screen bg-dark-bg p-4 flex items-center justify-center bg-[url('https://grainy-gradients.vercel.app/noise.svg')]">
                <MotivationLetter onBack={() => setView('dashboard')} />
            </div>
          );
      case 'portfolio-builder':
          return (
            <div className="min-h-screen bg-dark-bg p-4 flex items-center justify-center bg-[url('https://grainy-gradients.vercel.app/noise.svg')]">
                <div className="w-full max-w-7xl">
                    <PortfolioBuilder 
                        onBack={() => setView('dashboard')} 
                        initialData={editingPortfolio?.data} 
                        portfolioId={editingPortfolio?.id}
                        subscriptionTier={userProfile?.subscription_tier}
                    />
                </div>
            </div>
          );
      case 'profile':
          if (!session) return null;
          return (
            <div className="min-h-screen bg-dark-bg py-8 bg-[url('https://grainy-gradients.vercel.app/noise.svg')]">
                 <div className="max-w-7xl mx-auto">
                    <ProfileScreen 
                        session={session} 
                        onBack={() => setView('dashboard')}
                        onEditCV={handleEditCV}
                        onEditPortfolio={handleEditPortfolio}
                        onManagePlan={() => setView('pricing')}
                    />
                 </div>
            </div>
          );
      case 'admin-dashboard':
          return (
            <div className="min-h-screen bg-dark-bg py-8 bg-[url('https://grainy-gradients.vercel.app/noise.svg')]">
                 <div className="max-w-7xl mx-auto">
                    <AdminDashboard onBack={() => setView('dashboard')} />
                 </div>
            </div>
          );
      case 'interviewer-dashboard':
          if (!session) return null;
          return (
             <div className="min-h-screen bg-dark-bg py-8 bg-[url('https://grainy-gradients.vercel.app/noise.svg')]">
                 <div className="max-w-7xl mx-auto">
                    <InterviewerDashboard onBack={() => setView('dashboard')} userId={session.user.id} />
                 </div>
            </div>
          );
       case 'pricing':
           if (!session) return null;
           return (
               <div className="min-h-screen bg-dark-bg py-8 bg-[url('https://grainy-gradients.vercel.app/noise.svg')]">
                   <div className="max-w-7xl mx-auto">
                       <PricingScreen 
                            onBack={() => setView('dashboard')} 
                            currentTier={userProfile?.subscription_tier || 'free'} 
                            userId={session.user.id}
                            onUpgrade={handleUpgrade}
                        />
                   </div>
               </div>
           );
      default:
        return <div>404 Not Found</div>;
    }
  };

  return (
    <>
        {renderView()}
        <CookieBanner />
    </>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { supabase } from '../services/supabaseClient';
import type { Invite, DomainKey, LevelKey, PersonaKey, InterviewReport, SuggestedResource, TranscriptionEntry, FeedbackEntry, InterviewConfig } from '../types';
import { domains, personas } from '../types';
import EndScreen from './EndScreen';

interface InterviewerDashboardProps {
  onBack: () => void;
  userId: string;
}

// Extends Invite to include candidate progress
interface ExtendedInvite extends Invite {
    interviewData?: {
        id: string;
        created_at: string;
        report: InterviewReport;
        resources: SuggestedResource[];
        transcription: TranscriptionEntry[];
        feedback: FeedbackEntry[];
        config: InterviewConfig;
    } | null;
}

const InterviewerDashboard: React.FC<InterviewerDashboardProps> = ({ onBack, userId }) => {
  const [invites, setInvites] = useState<ExtendedInvite[]>([]);
  const [newEmail, setNewEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [creating, setCreating] = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  // Report Viewing State
  const [selectedReportInvite, setSelectedReportInvite] = useState<ExtendedInvite | null>(null);

  // Configuration State
  const [selectedDomain, setSelectedDomain] = useState<DomainKey>('software-engineering');
  const [selectedLevel, setSelectedLevel] = useState<LevelKey>('junior');
  const [selectedPersona, setSelectedPersona] = useState<PersonaKey>('friendly');
  const [selectedTechnology, setSelectedTechnology] = useState<string>('');

  const fetchInvites = async () => {
      if (!supabase) return;
      setLoading(true);

      // 1. Fetch Invites
      const { data: invitesData, error } = await supabase
        .from('invites')
        .select('*')
        .eq('interviewer_id', userId)
        .order('created_at', { ascending: false });

      if (error) {
          console.error("Error fetching invites", error);
          setLoading(false);
          return;
      }

      // 2. Fetch Interview Data for accepted invites
      const acceptedCandidateIds = invitesData
        .filter(inv => inv.status === 'accepted' && inv.candidate_id)
        .map(inv => inv.candidate_id);

      let interviewsMap: Record<string, any> = {};

      if (acceptedCandidateIds.length > 0) {
          const { data: interviewData } = await supabase
            .from('interviews')
            .select('*')
            .in('user_id', acceptedCandidateIds)
            .order('created_at', { ascending: false }); // Get latest first

          if (interviewData) {
              // Map latest interview to candidate_id
              interviewData.forEach(intrv => {
                  if (!interviewsMap[intrv.user_id]) {
                      interviewsMap[intrv.user_id] = intrv;
                  }
              });
          }
      }

      // 3. Merge Data
      const mergedInvites = invitesData.map(inv => ({
          ...inv,
          interviewData: inv.candidate_id ? interviewsMap[inv.candidate_id] : null
      }));

      setInvites(mergedInvites);
      setLoading(false);
  };

  useEffect(() => {
    fetchInvites();
  }, [userId]);

  const handleCreateInvite = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!newEmail || !supabase) return;

      const isSoftwareEngineering = selectedDomain === 'software-engineering';
      if (isSoftwareEngineering && !selectedTechnology) {
          alert("Please select a technology stack for Software Engineering.");
          return;
      }

      // LIMIT CHECK: Max 25 invites
      if (invites.length >= 25) {
          alert("Invitation Limit Reached: You are limited to 25 invitation links. Please remove existing candidates or unused links to create new ones.");
          return;
      }

      setCreating(true);

      // Build Config
      const baseConfig = domains[selectedDomain].levels[selectedLevel];
      let systemInstruction = baseConfig.systemInstruction;

      if (isSoftwareEngineering && domains['software-engineering'].technologies) {
          const techName = domains['software-engineering'].technologies[selectedTechnology];
          systemInstruction = systemInstruction.replace(/{technology}/g, techName);
      }

      const personaModifier = personas[selectedPersona].modifier;
      systemInstruction = `${systemInstruction} In terms of your personality as an interviewer, please adhere to the following: ${personaModifier}`;

      const finalConfig = {
          ...baseConfig,
          systemInstruction,
          name: `${baseConfig.name} (${personas[selectedPersona].name})`
      };

      // Generate invite link (token created by DB default)
      const { data, error } = await supabase.from('invites').insert({
          interviewer_id: userId,
          email: newEmail,
          config: finalConfig,
      }).select();

      if (error) {
          alert("Failed to invite: " + error.message);
      } else if (data && data[0]) {
          setNewEmail('');
          fetchInvites();
      }
      setCreating(false);
  };

  const handleDeleteInvite = async (inviteId: string, status: string) => {
      if (!supabase) return;

      const confirmMessage = status === 'pending' 
        ? "Revoke Invitation: This link will become invalid immediately. Are you sure?" 
        : "Remove Candidate: This will permanently remove the candidate and their interview report. Are you sure?";

      if (!window.confirm(confirmMessage)) return;

      setDeletingId(inviteId);
      const { error } = await supabase.from('invites').delete().eq('id', inviteId);

      if (error) {
          console.error("Error deleting invite:", error);
          alert("Failed to remove: " + error.message);
      } else {
          setInvites(prev => prev.filter(i => i.id !== inviteId));
      }
      setDeletingId(null);
  };

  const getInviteLink = (token: string) => {
      const baseUrl = window.location.origin + window.location.pathname;
      const cleanBase = baseUrl.endsWith('/') ? baseUrl.slice(0, -1) : baseUrl;
      return `${cleanBase}?invite=${token}`;
  };

  if (selectedReportInvite && selectedReportInvite.interviewData) {
      return (
          <div className="w-full space-y-6">
              <button onClick={() => setSelectedReportInvite(null)} className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors font-medium">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" /></svg>
                Back to Candidates
              </button>
              <div className="flex items-center gap-4 mb-4">
                  <div className="h-12 w-12 rounded-full bg-brand-green/20 flex items-center justify-center text-brand-green font-bold text-xl">
                      {selectedReportInvite.email.charAt(0).toUpperCase()}
                  </div>
                  <div>
                      <h2 className="text-2xl font-bold text-white">{selectedReportInvite.email}</h2>
                      <p className="text-gray-400 text-sm">Reviewing Report • {new Date(selectedReportInvite.interviewData.created_at).toLocaleDateString()}</p>
                  </div>
              </div>
              <EndScreen 
                 onRestart={() => setSelectedReportInvite(null)}
                 transcription={selectedReportInvite.interviewData.transcription}
                 feedback={selectedReportInvite.interviewData.feedback}
                 config={selectedReportInvite.interviewData.config}
                 userEmail={selectedReportInvite.email}
                 userId={selectedReportInvite.candidate_id!}
                 existingReport={selectedReportInvite.interviewData.report}
                 existingResources={selectedReportInvite.interviewData.resources}
                 isHistoryView={true}
              />
          </div>
      );
  }

  return (
    <div className="w-full px-6 space-y-8 animate-fade-in pb-12">
        <div className="flex items-center gap-3">
          <button onClick={onBack} className="p-2 rounded-lg hover:bg-white/10 transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
          </button>
          <h2 className="text-3xl font-bold text-white">Recruiter Dashboard</h2>
        </div>

        {/* Invite Generator */}
        <div className="glass-panel p-8 rounded-2xl border border-white/5 shadow-xl">
             <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-brand-blue" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z" /></svg>
                 Invite Candidate
             </h3>
             <form onSubmit={handleCreateInvite} className="space-y-6">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                     <div className="space-y-2">
                         <label className="text-sm font-semibold text-gray-400">Candidate Email</label>
                         <input 
                            type="email" 
                            required 
                            value={newEmail} 
                            onChange={(e) => setNewEmail(e.target.value)} 
                            className="w-full bg-black/30 border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-1 focus:ring-brand-blue outline-none"
                            placeholder="candidate@example.com"
                         />
                     </div>
                     <div className="space-y-2">
                         <label className="text-sm font-semibold text-gray-400">Role / Domain</label>
                         <select 
                            value={selectedDomain} 
                            onChange={(e) => setSelectedDomain(e.target.value as DomainKey)} 
                            className="w-full bg-black/30 border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-1 focus:ring-brand-blue outline-none cursor-pointer"
                         >
                             {Object.keys(domains).map(d => <option key={d} value={d}>{domains[d as DomainKey].name}</option>)}
                         </select>
                     </div>
                     <div className="space-y-2">
                         <label className="text-sm font-semibold text-gray-400">Experience Level</label>
                         <div className="flex bg-black/30 rounded-lg p-1 border border-white/10">
                             {['junior', 'mid-level', 'senior'].map((l) => (
                                 <button
                                    key={l}
                                    type="button"
                                    onClick={() => setSelectedLevel(l as LevelKey)}
                                    className={`flex-1 py-2 text-xs font-bold uppercase rounded-md transition-all ${selectedLevel === l ? 'bg-brand-blue text-white shadow' : 'text-gray-500 hover:text-white'}`}
                                 >
                                     {l}
                                 </button>
                             ))}
                         </div>
                     </div>
                     {selectedDomain === 'software-engineering' && (
                         <div className="space-y-2">
                             <label className="text-sm font-semibold text-gray-400">Tech Stack</label>
                             <select 
                                value={selectedTechnology}
                                onChange={(e) => setSelectedTechnology(e.target.value)}
                                className="w-full bg-black/30 border border-white/10 rounded-lg px-4 py-3 text-white focus:ring-1 focus:ring-brand-blue outline-none cursor-pointer"
                             >
                                 <option value="">-- Select Technology --</option>
                                 {Object.entries(domains['software-engineering'].technologies || {}).map(([k, v]) => (
                                     <option key={k} value={k}>{v}</option>
                                 ))}
                             </select>
                         </div>
                     )}
                     <div className="space-y-2 md:col-span-2">
                         <label className="text-sm font-semibold text-gray-400">Interviewer Persona</label>
                         <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                             {Object.keys(personas).map((p) => (
                                 <button
                                    key={p}
                                    type="button"
                                    onClick={() => setSelectedPersona(p as PersonaKey)}
                                    className={`p-3 rounded-lg border text-left transition-all ${selectedPersona === p ? 'bg-brand-purple/20 border-brand-purple text-white' : 'bg-black/20 border-white/5 text-gray-400 hover:bg-white/5'}`}
                                 >
                                     <div className="font-bold text-sm mb-1">{personas[p as PersonaKey].name}</div>
                                     <div className="text-xs opacity-70 truncate">{personas[p as PersonaKey].description}</div>
                                 </button>
                             ))}
                         </div>
                     </div>
                 </div>
                 <div className="flex justify-end pt-2">
                     <button 
                        type="submit" 
                        disabled={creating}
                        className="px-8 py-3 bg-white text-black font-bold rounded-xl hover:bg-gray-200 transition-colors shadow-lg disabled:opacity-50"
                     >
                         {creating ? 'Sending...' : 'Send Invitation'}
                     </button>
                 </div>
             </form>
        </div>

        {/* List */}
        <div className="space-y-4">
             <h3 className="text-xl font-bold text-white mb-4">Manage Candidates</h3>
             {loading ? (
                 <div className="text-center py-10 text-gray-500">Loading invites...</div>
             ) : invites.length === 0 ? (
                 <div className="text-center py-10 glass-panel rounded-xl text-gray-400">No active invitations found.</div>
             ) : (
                 <div className="grid gap-4">
                     {invites.map((invite) => (
                         <div key={invite.id} className="glass-panel p-5 rounded-xl flex flex-col md:flex-row items-center justify-between gap-4 border border-white/5 hover:border-white/10 transition-all">
                             <div className="flex items-center gap-4 w-full md:w-auto">
                                 <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-lg ${invite.status === 'accepted' ? 'bg-brand-green/20 text-brand-green' : 'bg-yellow-500/20 text-yellow-500'}`}>
                                     {invite.email.charAt(0).toUpperCase()}
                                 </div>
                                 <div>
                                     <h4 className="font-bold text-white">{invite.email}</h4>
                                     <p className="text-xs text-gray-400">
                                         {invite.config?.name} • Sent {new Date(invite.created_at).toLocaleDateString()}
                                     </p>
                                     {invite.status === 'pending' && (
                                         <div className="mt-2 flex items-center gap-2 bg-black/30 px-3 py-1.5 rounded text-xs text-gray-300 font-mono break-all">
                                             {getInviteLink(invite.token)}
                                             <button onClick={() => navigator.clipboard.writeText(getInviteLink(invite.token))} className="text-brand-blue hover:text-white ml-2">Copy</button>
                                         </div>
                                     )}
                                 </div>
                             </div>

                             <div className="flex items-center gap-3 w-full md:w-auto justify-end">
                                 {invite.status === 'accepted' ? (
                                     invite.interviewData ? (
                                         <button 
                                            onClick={() => setSelectedReportInvite(invite)}
                                            className="px-4 py-2 bg-brand-blue/20 text-brand-blue hover:bg-brand-blue/30 rounded-lg text-sm font-bold transition-colors"
                                         >
                                             View Report
                                         </button>
                                     ) : (
                                         <span className="text-sm text-gray-500 italic px-4">Interview Pending</span>
                                     )
                                 ) : (
                                     <span className="px-3 py-1 rounded bg-yellow-500/10 text-yellow-500 text-xs font-bold uppercase">Pending Accept</span>
                                 )}

                                 <button 
                                    onClick={() => handleDeleteInvite(invite.id, invite.status)}
                                    disabled={deletingId === invite.id}
                                    className="p-2 hover:bg-red-500/10 text-gray-500 hover:text-red-500 rounded-lg transition-colors"
                                    title="Revoke / Delete"
                                 >
                                     <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                 </button>
                             </div>
                         </div>
                     ))}
                 </div>
             )}
        </div>
    </div>
  );
};

export default InterviewerDashboard;

