  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    cardNumber: '',
    expiry: '',
    cvc: ''
  });

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    let formattedValue = value;

    // Simple masking logic
    if (name === 'cardNumber') {
        formattedValue = value.replace(/\D/g, '').slice(0, 16).replace(/(\d{4})(?=\d)/g, '$1 ');
    } else if (name === 'expiry') {
        formattedValue = value.replace(/\D/g, '').slice(0, 4).replace(/(\d{2})(?=\d)/g, '$1/');
    } else if (name === 'cvc') {
        formattedValue = value.replace(/\D/g, '').slice(0, 3);
    }

    setFormData(prev => ({ ...prev, [name]: formattedValue }));
  };

  const handlePayment = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
        // Mock Payment Delay
        await new Promise(resolve => setTimeout(resolve, 2000));

        // Update User Profile in Supabase
        const updates: any = { 
            subscription_tier: planId,
            subscription_status: 'active'
        };

        // If Recruiter plan, grant interviewer role
        if (planId === 'recruiter') {
            updates.role = 'interviewer';
