                name="Recruiter / Enterprise"
                price="$49"
                features={[
                    "Everything in Pro",
                    "Invite & Manage Candidates",
                    "View Candidate Reports",
                    "Custom Interview Configuration",
                    "Team Dashboard Access",
                    "Dedicated Support"
                ]}
            />
       </div>
    </div>
  );
};

export default PricingScreen;

import React, { useState, useCallback, useEffect } from 'react';
import type { Session } from '@supabase/supabase-js';
import { InterviewStatus, InterviewConfig, TranscriptionEntry, FeedbackEntry, SavedCV, SavedPortfolio, Role, SubscriptionTier } from './types';
import { supabase } from './services/supabaseClient';
import Dashboard from './components/WelcomeScreen'; 
import InterviewSetup from './components/InterviewSetup';
import InterviewScreen from './components/InterviewScreen';
import EndScreen from './components/EndScreen';
import AuthScreen from './components/AuthScreen';
import ProfileScreen from './components/ProfileScreen';
import CVBuilder from './components/CVBuilder';
import MotivationLetter from './components/MotivationLetter';
import PortfolioBuilder from './components/PortfolioBuilder';
import AdminDashboard from './components/AdminDashboard';
import InterviewerDashboard from './components/InterviewerDashboard';
import PricingScreen from './components/PricingScreen';
import CheckoutScreen from './components/CheckoutScreen';
import PaymentSuccessScreen from './components/PaymentSuccessScreen';
import LandingPage from './components/LandingPage';
import AboutUs from './components/AboutUs';
import PrivacyPolicy from './components/PrivacyPolicy';
import TermsOfService from './components/TermsOfService';
import CookieBanner from './components/CookieBanner';

type AppView = 'dashboard' | 'interview-setup' | 'cv-builder' | 'motivation-letter' | 'profile' | 'results' | 'portfolio-builder' | 'admin-dashboard' | 'interviewer-dashboard' | 'pricing' | 'checkout' | 'payment-success';
type PublicView = 'landing' | 'about' | 'auth' | 'privacy' | 'terms';

const App: React.FC = () => {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  // Public Navigation State
  const [publicView, setPublicView] = useState<PublicView>('landing');

  // Authenticated App State
  const [interviewStatus, setInterviewStatus] = useState<InterviewStatus>(InterviewStatus.NotStarted);
  const [interviewConfig, setInterviewConfig] = useState<InterviewConfig | null>(null);
  const [isPracticeMode, setIsPracticeMode] = useState(false);
  const [finalTranscription, setFinalTranscription] = useState<TranscriptionEntry[]>([]);
  const [finalFeedback, setFinalFeedback] = useState<FeedbackEntry[]>([]);
  const [currentView, setCurrentView] = useState<AppView>('dashboard');
  const [isDesktop, setIsDesktop] = useState(true);

  // Role & Limits
  const [userRole, setUserRole] = useState<Role>('user');
  const [subscriptionTier, setSubscriptionTier] = useState<SubscriptionTier>('free');
  const [sessionCount, setSessionCount] = useState(0);
  const [inviteToken, setInviteToken] = useState<string | null>(null);
  const [pendingInviteConfig, setPendingInviteConfig] = useState<InterviewConfig | null>(null);

  // User Display Info
  const [displayName, setDisplayName] = useState<string>('');

  // State for CV Editing
  const [editingCV, setEditingCV] = useState<SavedCV | null>(null);
  // State for Portfolio Editing
  const [editingPortfolio, setEditingPortfolio] = useState<SavedPortfolio | null>(null);

  // State for Checkout
  const [checkoutData, setCheckoutData] = useState<{ plan: SubscriptionTier; price: string; name: string } | null>(null);

  // Check for desktop screen size
  useEffect(() => {
    const checkScreenSize = () => {
      setIsDesktop(window.innerWidth >= 1024);
    };
    checkScreenSize();
    window.addEventListener('resize', checkScreenSize);
    return () => window.removeEventListener('resize', checkScreenSize);
  }, []);

  // Handle URL Invite Tokens
  useEffect(() => {
    const handleTokenParsing = () => {
        let token = null;

        // 1. Check Query Params (Standard)
        const searchParams = new URLSearchParams(window.location.search);
        token = searchParams.get('invite');

        // 2. Check Hash Params (Fallback for strict servers that 404 on query params)
        if (!token && window.location.hash) {
            // Remove leading #
            const hashString = window.location.hash.substring(1); 
            const hashParams = new URLSearchParams(hashString);
            token = hashParams.get('invite');
        }

        if (token) {
            setInviteToken(token);
            setPublicView('auth'); // Jump straight to auth if invited
        }
    };

    handleTokenParsing();
    window.addEventListener('hashchange', handleTokenParsing);
    return () => window.removeEventListener('hashchange', handleTokenParsing);
  }, []);

  useEffect(() => {
    if (!supabase) {
      console.warn("Supabase client not initialized.");
      setLoading(false);
      return;
    }

    setLoading(true);

    const fetchUserData = async (uid: string, email?: string, userMetadata?: any) => {
        try {
            // Get Profile
            // We select specific fields to avoid fetching everything if schema is large, but need full_name/avatar to check sync
            const { data: profile, error } = await supabase.from('profiles').select('role, is_admin, subscription_tier, email, full_name, avatar_url').eq('id', uid).maybeSingle();

            // Extract Metadata from Google Login
            const metaName = userMetadata?.full_name || userMetadata?.name;
            const metaAvatar = userMetadata?.avatar_url || userMetadata?.picture;

            // Determine Display Name (Profile > Metadata > Email)
            const resolvedName = profile?.full_name || metaName || email || '';
            setDisplayName(resolvedName);

            let currentRole: Role = 'user';

            if (profile) {
                 // SYNC LOGIC: Check if profile is missing info that we have in metadata
                 const updates: any = {};
                 let needsUpdate = false;

                 if (email && profile.email !== email) {
                     updates.email = email;
                     needsUpdate = true;
                 }
                 if (metaName && !profile.full_name) {
                     updates.full_name = metaName;
                     needsUpdate = true;
                 }
                 if (metaAvatar && !profile.avatar_url) {
                     updates.avatar_url = metaAvatar;
                     needsUpdate = true;
                 }

                 if (needsUpdate) {
                     // Try to update. If database columns are missing, this might fail, so we catch it.
                     const { error: updateError } = await supabase.from('profiles').update(updates).eq('id', uid);
                     if (updateError && updateError.code !== '42703') { // Ignore missing column error to avoid crash
                         console.error("Failed to sync user profile data:", updateError);
                     }
                 }

                 // Set Role & Tier
                 if (profile.is_admin || profile.role === 'admin') {
                     currentRole = 'admin';
                 } else if (profile.role) {
                     currentRole = profile.role as Role;
                 }

                 if (profile.subscription_tier) {
                     setSubscriptionTier(profile.subscription_tier as SubscriptionTier);
                 }
            } else {
                // Create basic profile if missing
                // Attempt to insert with full metadata. Fallback if columns missing.
                try {
                    await supabase.from('profiles').insert({ 
                        id: uid, 
                        email: email || '', 
                        role: 'user',
                        full_name: metaName || '',
                        avatar_url: metaAvatar || ''
                    });
                } catch (insertErr: any) {
                    // Fallback for missing columns schema
                    if (insertErr.code === '42703') {
                         await supabase.from('profiles').insert({ id: uid, role: 'user', email: email || '' });
                    }
                }
            }
            setUserRole(currentRole);

            // If Candidate, fetch their assigned interview config
            if (currentRole === 'candidate' && email) {
                const { data: invite } = await supabase.from('invites').select('config').eq('email', email).limit(1).maybeSingle();
                if (invite && invite.config) {
                    setPendingInviteConfig(invite.config);
                }
            }

            // Get Session Count (for normal users)
            const { count } = await supabase.from('interviews').select('*', { count: 'exact', head: true }).eq('user_id', uid);
            setSessionCount(count || 0);

        } catch (e) {
            console.error("Error fetching user data", e);
        }
    };

    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session?.user) {
          // Optimistic set for immediate feedback
          const initialName = session.user.user_metadata?.full_name || session.user.user_metadata?.name || session.user.email || '';
          setDisplayName(initialName);
          fetchUserData(session.user.id, session.user.email, session.user.user_metadata);
      }
      setLoading(false);
    }).catch(err => {
      console.error("Error getting session:", err);
      setLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session?.user) {
          const initialName = session.user.user_metadata?.full_name || session.user.user_metadata?.name || session.user.email || '';
          setDisplayName(initialName);
          fetchUserData(session.user.id, session.user.email, session.user.user_metadata);
      } else {
          setUserRole('user');
          setPendingInviteConfig(null);
          setSubscriptionTier('free');
          setDisplayName('');
      }

      if (_event === 'SIGNED_OUT') {
        setInterviewStatus(InterviewStatus.NotStarted);
        setInterviewConfig(null);
        setFinalTranscription([]);
        setFinalFeedback([]);
        setCurrentView('dashboard');
        setEditingCV(null);
        setEditingPortfolio(null);
        setUserRole('user');
        setSubscriptionTier('free');
        setPublicView('landing'); // Go back to landing page
      }
    });

    return () => subscription.unsubscribe();
  }, []);


  const handleStartInterview = useCallback((selectedConfig: InterviewConfig, practiceMode: boolean) => {
    // ENFORCE LIMITS BASED ON SUBSCRIPTION TIER
    // Free tier: 1 session limit (unless practice mode, or candidate)
    if (userRole !== 'admin' && userRole !== 'candidate' && subscriptionTier === 'free' && !practiceMode && sessionCount >= 1) {
        alert("Free Plan Limit Reached: You have used your 1 free interview session. Please upgrade to Pro for unlimited sessions or use 'Practice Mode'.");
        setCurrentView('pricing');
        return;
    }

    setInterviewConfig(selectedConfig);
    setIsPracticeMode(practiceMode);
    setInterviewStatus(InterviewStatus.InProgress);
  }, [userRole, subscriptionTier, sessionCount]);

  const handleEndInterview = useCallback((transcription: TranscriptionEntry[], feedback: FeedbackEntry[]) => {
    if (isPracticeMode) {
      setInterviewStatus(InterviewStatus.NotStarted);
      setInterviewConfig(null);
      setCurrentView('dashboard');
    } else {
      setFinalTranscription(transcription);
      setFinalFeedback(feedback);
      setInterviewStatus(InterviewStatus.Finished);
      setCurrentView('results');
      // Increment local session count so they hit the limit immediately without refresh
      setSessionCount(prev => prev + 1); 
    }
  }, [isPracticeMode]);

  const handleRestart = useCallback(() => {
    setInterviewStatus(InterviewStatus.NotStarted);
    setInterviewConfig(null);
    setFinalTranscription([]);
    setFinalFeedback([]);
    setIsPracticeMode(false);
    setCurrentView('dashboard');
  }, []);

  const handleEditCV = useCallback((cv: SavedCV) => {
      setEditingCV(cv);
      setCurrentView('cv-builder');
  }, []);

  const handleEditPortfolio = useCallback((portfolio: SavedPortfolio) => {
      setEditingPortfolio(portfolio);
      setCurrentView('portfolio-builder');
  }, []);

  const handleLogout = async () => {
    if (supabase) {
      await supabase.auth.signOut();
    }
  };

  const handlePlanSelection = (tier: SubscriptionTier, price: string, name: string) => {
      if (tier === 'free') {
          // Downgrade immediately logic could go here or in Checkout, but standard flow usually implies no payment.
          // For simplicity, treating free downgrade as a profile update directly in PricingScreen or alerting.
          // Or just route to checkout with $0 price if desired, but let's handle in Pricing logic itself or simple update.
          // Since the PricingScreen update logic was moved, let's treat "Free" as a checkout process of $0 or handle in checkout.
          setCheckoutData({ plan: tier, price: 'Free', name: name });
          setCurrentView('checkout');
      } else {
          setCheckoutData({ plan: tier, price, name });
          setCurrentView('checkout');
      }
  };

  if (!isDesktop) {
    return (
        <div className="min-h-screen bg-dark-bg flex flex-col items-center justify-center p-6 text-center relative overflow-hidden">
            <div className="glass-panel w-full max-w-md rounded-2xl p-8 border border-white/10 shadow-2xl backdrop-blur-xl">
                <h1 className="text-2xl font-bold text-white mb-3">Desktop Experience</h1>
                <p className="text-gray-300">Please access <strong>prepareAI</strong> on a desktop computer for the full interview simulation.</p>
            </div>
        </div>
    );
  }

  // --- Public View Rendering (No Session) ---
  if (!session) {
      if (loading) {
        return (
            <div className="min-h-screen bg-dark-bg flex flex-col items-center justify-center text-center">
                <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-brand-blue"></div>
            </div>
        );
      }

      const getPublicComponent = () => {
          if (publicView === 'privacy') return <PrivacyPolicy onBack={() => setPublicView('landing')} />;
          if (publicView === 'terms') return <TermsOfService onBack={() => setPublicView('landing')} />;
          if (publicView === 'about') return <AboutUs onBack={() => setPublicView('landing')} />;
          if (publicView === 'auth') return (
              <div className="min-h-screen relative flex flex-col items-center justify-center p-6 bg-dark-bg">
                  {/* Background Elements */}
                  <div className="fixed inset-0 overflow-hidden pointer-events-none -z-10">
                      <div className="absolute top-20 right-20 w-80 h-80 bg-brand-purple/20 rounded-full mix-blend-screen filter blur-[100px] animate-blob"></div>
                      <div className="absolute -bottom-40 left-1/2 w-96 h-96 bg-brand-blue/20 rounded-full mix-blend-screen filter blur-[100px] animate-blob animation-delay-4000"></div>
                  </div>
                  <AuthScreen inviteToken={inviteToken} onBack={() => setPublicView('landing')} />
              </div>
          );
          // Default: Landing Page
          return <LandingPage 
            onLogin={() => setPublicView('auth')} 
            onSignup={() => setPublicView('auth')} 
            onAbout={() => setPublicView('about')} 
            onPrivacy={() => setPublicView('privacy')}
            onTerms={() => setPublicView('terms')}
          />;
      };

      return (
          <>
            {getPublicComponent()}
            <CookieBanner />
          </>
      );
  }

  // --- Authenticated App Rendering ---

  const renderAuthenticatedContent = () => {
    // Active Interview overrides everything
    if (interviewStatus === InterviewStatus.InProgress) {
        if (!interviewConfig) return <Dashboard onNavigate={setCurrentView} userName={displayName} isAdmin={userRole === 'admin'} />;
        return <InterviewScreen onEnd={handleEndInterview} config={interviewConfig} isPracticeMode={isPracticeMode} />;
    }

    // Main Navigation
    switch (currentView) {
      case 'pricing':
        return <PricingScreen 
            onBack={() => setCurrentView('dashboard')} 
            currentTier={subscriptionTier} 
            userId={session.user.id} 
            onUpgrade={handlePlanSelection} 
        />;
      case 'checkout':
        if (!checkoutData) return <PricingScreen onBack={() => setCurrentView('dashboard')} currentTier={subscriptionTier} userId={session.user.id} onUpgrade={handlePlanSelection} />;
        return <CheckoutScreen 
            planId={checkoutData.plan}
            planName={checkoutData.name}
            price={checkoutData.price}
            userId={session.user.id}
            onBack={() => setCurrentView('pricing')}
            onSuccess={() => {
                // Update local state to reflect new tier immediately
                setSubscriptionTier(checkoutData.plan);
                if (checkoutData.plan === 'recruiter') setUserRole('interviewer');
                setCurrentView('payment-success');
            }}
        />;
      case 'payment-success':
        return <PaymentSuccessScreen 
            planName={checkoutData?.name || 'Pro Plan'} 
            onContinue={() => setCurrentView('dashboard')} 
        />;
      case 'admin-dashboard':
        return userRole === 'admin' ? <AdminDashboard onBack={() => setCurrentView('dashboard')} /> : <Dashboard onNavigate={setCurrentView} userName={displayName} isAdmin={false} />;
      case 'interviewer-dashboard':
          return userRole === 'interviewer' || userRole === 'admin' ? <InterviewerDashboard onBack={() => setCurrentView('dashboard')} userId={session.user.id} /> : <Dashboard onNavigate={setCurrentView} userName={displayName} />;
      case 'results':
         if (!interviewConfig) return <Dashboard onNavigate={setCurrentView} userName={displayName} isAdmin={userRole === 'admin'} />;
         return <EndScreen 
           onRestart={handleRestart} 
           transcription={finalTranscription} 
           feedback={finalFeedback} 
           config={interviewConfig} 
           userEmail={session.user.email || ''} 
           userId={session.user.id}
         />;
      case 'interview-setup':
        // If candidate has a pending config, they shouldn't see setup, but if they navigated here manually or if config is missing:
        if (pendingInviteConfig) {
             // Immediately start the interview with the pending config
             handleStartInterview(pendingInviteConfig, false); 
             return null; 
        }
        return <InterviewSetup onStart={handleStartInterview} onBack={() => setCurrentView('dashboard')} />;
      case 'cv-builder':
        return <CVBuilder 
            onBack={() => { setCurrentView('dashboard'); setEditingCV(null); }} 
            initialData={editingCV?.data}
            cvId={editingCV?.id}
            subscriptionTier={subscriptionTier}
        />;
      case 'portfolio-builder':
        return <PortfolioBuilder
            onBack={() => { setCurrentView('dashboard'); setEditingPortfolio(null); }}
            initialData={editingPortfolio?.data}
            portfolioId={editingPortfolio?.id}
            subscriptionTier={subscriptionTier}
        />;
      case 'motivation-letter':
        return <MotivationLetter onBack={() => setCurrentView('dashboard')} />;
      case 'profile':
        return <ProfileScreen 
            session={session} 
            onBack={() => setCurrentView('dashboard')} 
            onEditCV={handleEditCV}
            onEditPortfolio={handleEditPortfolio}
            onManagePlan={() => setCurrentView('pricing')}
        />;
      case 'dashboard':
      default:
        // Pass extra props for candidate UI
        return <Dashboard 
          onNavigate={setCurrentView} 
          userName={displayName} 
          isAdmin={userRole === 'admin'}
          pendingConfig={pendingInviteConfig}
          onStartAssigned={() => handleStartInterview(pendingInviteConfig!, false)}
        />;
    }
  };

  return (
    <div className="min-h-screen relative flex flex-col items-center bg-dark-bg">
       {/* Global Background Elements */}
       <div className="fixed inset-0 overflow-hidden pointer-events-none -z-10">
          <div className="absolute -top-40 -left-40 w-96 h-96 bg-brand-blue/30 rounded-full mix-blend-screen filter blur-[100px] opacity-30 animate-blob"></div>
          <div className="absolute top-20 right-20 w-80 h-80 bg-brand-purple/30 rounded-full mix-blend-screen filter blur-[100px] opacity-30 animate-blob animation-delay-2000"></div>
          <div className="absolute -bottom-40 left-1/2 w-96 h-96 bg-brand-green/20 rounded-full mix-blend-screen filter blur-[100px] opacity-30 animate-blob animation-delay-4000"></div>
          <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10"></div>
       </div>

       <header className="w-full sticky top-0 z-50 backdrop-blur-xl bg-dark-bg/60 border-b border-white/5 shadow-lg">
         <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
            <div className="flex items-center gap-3 cursor-pointer" onClick={() => setCurrentView('dashboard')}>
                <div className="relative">
                  <div className="absolute inset-0 bg-brand-blue blur-lg opacity-40 rounded-full"></div>
                  <svg xmlns="http://www.w3.org/2000/svg" className="relative h-8 w-8 text-white" viewBox="0 0 24 24" fill="currentColor">
                      <path d="M19 9l1.25-2.75L23 5l-2.75-1.25L19 1l-1.25 2.75L15 5l2.75 1.25L19 9zm-7.5 2.5L9 4 6.5 11.5 0 14l6.5 2.5L9 24l2.5-7.5L18 14l-6.5-2.5z"/>
                  </svg>
                </div>
                <div>
                  <h1 className="text-2xl font-extrabold text-white tracking-tight leading-none">
                    prepare<span className="text-brand-blue">AI</span>
                  </h1>
                  <p className="text-[10px] uppercase tracking-widest text-gray-400 font-semibold">
                      {userRole === 'admin' ? 'Admin Mode' : userRole === 'interviewer' ? 'Recruiter Mode' : userRole === 'candidate' ? 'Candidate Mode' : (subscriptionTier === 'pro' ? 'Pro Plan' : 'Free Tier')}
                  </p>
                </div>
            </div>

            {session && (
              <div className="flex items-center gap-6">
                <div className="text-right hidden sm:block">
                  <p className="text-gray-300 text-sm font-medium">{session.user.email}</p>
                </div>
                <div className="h-6 w-px bg-gray-700 hidden sm:block"></div>
                <div className="flex gap-4">
                    <button 
                         onClick={() => setCurrentView('pricing')}
                         className={`text-sm font-bold transition-all px-3 py-1.5 rounded-full border ${currentView === 'pricing' ? 'bg-brand-yellow text-black border-brand-yellow' : 'bg-transparent text-brand-yellow border-brand-yellow hover:bg-brand-yellow/10'}`}
                    >
                        {subscriptionTier === 'free' ? 'Upgrade' : 'Plans'}
                    </button>

                    {/* Admin Link */}
                    {userRole === 'admin' && (
                        <button 
                            onClick={() => setCurrentView('admin-dashboard')}
                            className={`text-sm font-bold transition-colors relative group ${currentView === 'admin-dashboard' ? 'text-brand-red' : 'text-gray-300 hover:text-brand-red'}`}
                        >
                            Admin
                            <span className={`absolute -bottom-1 left-0 h-0.5 bg-brand-red transition-all ${currentView === 'admin-dashboard' ? 'w-full' : 'w-0 group-hover:w-full'}`}></span>
                        </button>
                    )}
                    {/* Interviewer Link */}
                    {(userRole === 'interviewer' || userRole === 'admin') && (
                        <button 
                            onClick={() => setCurrentView('interviewer-dashboard')}
                            className={`text-sm font-bold transition-colors relative group ${currentView === 'interviewer-dashboard' ? 'text-brand-purple' : 'text-gray-300 hover:text-brand-purple'}`}
                        >
                            Candidates
                            <span className={`absolute -bottom-1 left-0 h-0.5 bg-brand-purple transition-all ${currentView === 'interviewer-dashboard' ? 'w-full' : 'w-0 group-hover:w-full'}`}></span>
                        </button>
                    )}

                    <button 
                      onClick={() => setCurrentView('profile')} 
                      className={`text-sm font-medium transition-colors relative group ${currentView === 'profile' ? 'text-brand-blue' : 'text-gray-300 hover:text-brand-blue'}`}
                    >
                        Profile
                        <span className={`absolute -bottom-1 left-0 h-0.5 bg-brand-blue transition-all ${currentView === 'profile' ? 'w-full' : 'w-0 group-hover:w-full'}`}></span>
                    </button>
                    <button 
                      onClick={handleLogout} 
                      className="text-gray-300 hover:text-brand-red font-medium text-sm transition-colors relative group"
                    >
                      Log out
                      <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-brand-red transition-all group-hover:w-full"></span>
                    </button>
                </div>
              </div>
            )}
         </div>
      </header>

      <main className="w-full max-w-7xl mx-auto p-6 flex-grow flex items-center justify-center animate-fade-in">
        {renderAuthenticatedContent()}
      </main>

      <footer className="w-full py-6 text-center text-gray-500 text-xs">
         &copy; {new Date().getFullYear()} prepareAI. All rights reserved.
      </footer>
      <CookieBanner />
    </div>
  );
};

export default App;

