};

const InterviewSetup: React.FC<InterviewSetupProps> = ({ onStart, onBack }) => {
  const [selectedDomain, setSelectedDomain] = useState<DomainKey | 'custom' | ''>('');
  const [customDomainName, setCustomDomainName] = useState('');
  const [customRoleTitle, setCustomRoleTitle] = useState('');
  const [selectedLevel, setSelectedLevel] = useState<LevelKey | null>(null);
  const [selectedPersona, setSelectedPersona] = useState<PersonaKey>('friendly');
  const [isPracticeMode, setIsPracticeMode] = useState(false);
  const [selectedTechnology, setSelectedTechnology] = useState<string | null>(null);
  const [customInstructions, setCustomInstructions] = useState('');

  // Resume Personalization State
  const [resumeContext, setResumeContext] = useState<string>('');
  const [extractedSkills, setExtractedSkills] = useState<string[]>([]);
  const [isAnalyzingResume, setIsAnalyzingResume] = useState(false);
  const [resumeFileName, setResumeFileName] = useState<string | null>(null);

  const selectedConfig = useMemo(() => {
    if (selectedDomain === 'custom') {
        if (customDomainName && customRoleTitle && selectedLevel) {
             const baseInstruction = GENERIC_LEVEL_INSTRUCTIONS[selectedLevel];
             return {
                 name: customRoleTitle,
                 description: `Custom interview for ${customRoleTitle} in ${customDomainName}`,
                 systemInstruction: `You are an expert interviewer for a ${selectedLevel} ${customRoleTitle} role in the field of ${customDomainName}. ${baseInstruction}`
             };
        }
        return null;
    }
    if (selectedDomain && selectedLevel && selectedDomain !== 'custom') {
      return domains[selectedDomain].levels[selectedLevel];
    }
    return null;
  }, [selectedDomain, selectedLevel, customDomainName, customRoleTitle]);

  const handleResumeUpload = async (e: React.ChangeEvent<HTMLInputElement>, isAutofill: boolean = false) => {
      const file = e.target.files?.[0];
      if (!file) return;
      if (!process.env.API_KEY) {
          alert("API Key missing");
          return;
      }

      setIsAnalyzingResume(true);
      setResumeFileName(file.name);

      try {
          const reader = new FileReader();
          reader.onload = async (event) => {
              const base64String = event.target?.result as string;
              // Support PDF (raw base64) or Text
              let contentPart: any;

              if (file.type === "application/pdf") {
                  const rawBase64 = base64String.split(',')[1];
                  contentPart = { inlineData: { mimeType: 'application/pdf', data: rawBase64 } };
              } else {
                  // For text files, just use text
                  contentPart = { text: base64String }; 
              }

              const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

              const prompt = `Analyze this resume. Return a JSON object with the following structure:
              {
                "summary": "Concise summary of the candidate's background, key roles, and major achievements (max 3 sentences).",
                "skills": ["Skill 1", "Skill 2", ...],
                "suggestedRole": "The most fitting Job Title for this candidate (e.g. Senior Product Manager)",
                "suggestedIndustry": "The primary industry (e.g. FinTech, Healthcare, E-commerce)"
              }
              Do not use markdown formatting for the JSON.`;

              const response = await ai.models.generateContent({
                  model: 'gemini-2.5-flash',
                  contents: [contentPart, { text: prompt }],
                  config: { responseMimeType: 'application/json' }
              });

              const data = JSON.parse(response.text || '{}');
              setResumeContext(data.summary || '');
              setExtractedSkills(data.skills || []);

              if (isAutofill && selectedDomain === 'custom') {
                  if (data.suggestedRole) setCustomRoleTitle(data.suggestedRole);
                  if (data.suggestedIndustry) setCustomDomainName(data.suggestedIndustry);
              }

              setIsAnalyzingResume(false);
          };

          if (file.type === "application/pdf") {
              reader.readAsDataURL(file);
          } else {
              reader.readAsText(file);
          }

      } catch (err) {
          console.error(err);
          alert("Failed to analyze resume.");
          setIsAnalyzingResume(false);
          setResumeFileName(null);
          setExtractedSkills([]);
      }
  };

  const handleStartClick = () => {
    if (!selectedConfig) return;

    let finalSystemInstruction = selectedConfig.systemInstruction;
    if (selectedDomain === 'software-engineering' && selectedTechnology && domains['software-engineering'].technologies) {
      const technologyName = domains['software-engineering'].technologies[selectedTechnology];
      finalSystemInstruction = finalSystemInstruction.replace(/{technology}/g, technologyName);
    }

    const personaModifier = personas[selectedPersona].modifier;

    let systemInstruction = `${finalSystemInstruction} In terms of your personality as an interviewer, please adhere to the following: ${personaModifier}`;

    // Add User Resume Context
    if (resumeContext) {
        systemInstruction += `\n\nCONTEXT FROM CANDIDATE RESUME:\nSUMMARY: ${resumeContext}\nSKILLS: ${extractedSkills.join(', ')}\nUse this context to tailor your questions and verify their skills.`;
    }

    if (customInstructions.trim()) {
      systemInstruction += ` Additionally, please follow these user-provided custom instructions: ${customInstructions.trim()}`;
    }

    const finalConfig: InterviewConfig = {
      ...selectedConfig,
      systemInstruction,
    };
    onStart(finalConfig, isPracticeMode);
  };

  const isSoftwareEngineering = selectedDomain === 'software-engineering';
  const isStartDisabled = !selectedConfig || (isSoftwareEngineering && !selectedTechnology) || isAnalyzingResume;

  // Helper to get step number logic
  const steps = [
      { id: 1, title: 'Domain', active: true, completed: !!selectedDomain },
      { id: 2, title: 'Details', active: !!selectedDomain, completed: (isSoftwareEngineering ? !!selectedTechnology : true) && !!selectedLevel && (selectedDomain === 'custom' ? !!(customDomainName && customRoleTitle) : true) },
      { id: 3, title: 'Persona', active: !!selectedDomain && !!selectedLevel, completed: !!selectedPersona },
  ];

  return (
    <div className="w-full max-w-5xl glass-panel rounded-2xl shadow-2xl overflow-hidden animate-slide-up">
      {/* Header / Progress */}
      <div className="bg-black/20 p-6 border-b border-white/5 relative">
         <button onClick={onBack} className="absolute top-6 left-6 text-gray-400 hover:text-white transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
         </button>
         <div className="flex justify-between items-center mb-6 pl-10">
            <h2 className="text-3xl font-bold text-white tracking-tight">Configure Your Interview</h2>
            <div className="flex items-center gap-2">
                 <span className="text-sm font-medium text-gray-400">Step {steps.findIndex(s => !s.completed) === -1 ? 3 : steps.findIndex(s => !s.completed) + 1} of 3</span>
            </div>
         </div>
         <div className="flex items-center gap-4">
             {steps.map((step, idx) => (
                 <div key={step.id} className="flex-1 flex items-center gap-3">
                     <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold border ${step.active ? (step.completed ? 'bg-brand-green border-brand-green text-white' : 'bg-brand-blue border-brand-blue text-white') : 'bg-transparent border-gray-600 text-gray-500'}`}>
                         {step.completed ? '✓' : step.id}
                     </div>
                     <div className="h-1 flex-1 bg-gray-800 rounded-full overflow-hidden">
                         <div className={`h-full transition-all duration-500 ${step.completed ? 'bg-brand-green' : (step.active ? 'bg-brand-blue' : 'bg-transparent')}`} style={{ width: step.completed ? '100%' : (step.active ? '50%' : '0%') }}></div>
                     </div>
                 </div>
             ))}
         </div>
      </div>

      <div className="p-8 max-h-[70vh] overflow-y-auto custom-scrollbar">

        {/* Step 1: Domain Selection */}
        <section className="mb-12">
            <h3 className="text-xl font-semibold mb-6 flex items-center gap-3 text-gray-100">
                <span className="w-1.5 h-6 bg-brand-blue rounded-full"></span>
                Select Your Field
            </h3>
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                {(Object.keys(domains) as DomainKey[]).map((key) => (
                <button
                    key={key}
                    onClick={() => {
                        setSelectedDomain(key);
                        setSelectedLevel(null);
                        setSelectedTechnology(null);
                    }}
                    className={`group relative p-4 rounded-xl text-left border transition-all duration-300 ${
                        selectedDomain === key 
                        ? 'bg-brand-blue/20 border-brand-blue shadow-[0_0_20px_rgba(66,133,244,0.3)]' 
                        : 'bg-black/20 border-white/5 hover:bg-white/5 hover:border-white/20'
                    }`}
                >
                    <div className="flex items-center justify-between mb-2">
                        <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${selectedDomain === key ? 'bg-brand-blue text-white' : 'bg-gray-800 text-gray-400'}`}>
                            {domainIcons[key]}
                        </div>
                        {selectedDomain === key && <div className="w-2 h-2 rounded-full bg-brand-blue shadow-[0_0_10px_#4285F4]"></div>}
                    </div>
                    <p className={`font-semibold text-sm ${selectedDomain === key ? 'text-white' : 'text-gray-300 group-hover:text-white'}`}>
                        {domains[key].name}
                    </p>
                </button>
                ))}

                {/* Custom Option */}
                <button
                    onClick={() => {
                        setSelectedDomain('custom');
                        setSelectedLevel(null);
                        setSelectedTechnology(null);
                        setCustomDomainName('');
                        setCustomRoleTitle('');
                        setExtractedSkills([]);
                        setResumeFileName(null);
                    }}
                    className={`group relative p-4 rounded-xl text-left border transition-all duration-300 ${
                        selectedDomain === 'custom'
                        ? 'bg-brand-blue/20 border-brand-blue shadow-[0_0_20px_rgba(66,133,244,0.3)]' 
                        : 'bg-black/20 border-white/5 hover:bg-white/5 hover:border-white/20'
                    }`}
                >
                    <div className="flex items-center justify-between mb-2">
                        <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${selectedDomain === 'custom' ? 'bg-brand-blue text-white' : 'bg-gray-800 text-gray-400'}`}>
                            <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </div>
                        {selectedDomain === 'custom' && <div className="w-2 h-2 rounded-full bg-brand-blue shadow-[0_0_10px_#4285F4]"></div>}
                    </div>
                    <p className={`font-semibold text-sm ${selectedDomain === 'custom' ? 'text-white' : 'text-gray-300 group-hover:text-white'}`}>
                        Other / Custom
                    </p>
                </button>
            </div>
        </section>

        {/* Step 2: Tech & Level */}
        {selectedDomain && (
            <div className="animate-fade-in space-y-12">

                {/* Tech Stack (Only for SWE) */}
                {isSoftwareEngineering && (
                    <section>
                         <h3 className="text-xl font-semibold mb-6 flex items-center gap-3 text-gray-100">
                            <span className="w-1.5 h-6 bg-brand-purple rounded-full"></span>
                            Choose Technology Stack
                        </h3>
                        <div className="flex flex-wrap gap-3">
                            {Object.entries((domains[selectedDomain].technologies || {})).map(([key, name]) => (
                                <button
                                    key={key}
                                    onClick={() => setSelectedTechnology(key)}
                                    className={`px-5 py-2.5 rounded-full text-sm font-medium border transition-all duration-200 ${
                                        selectedTechnology === key 
                                        ? 'bg-brand-purple text-white border-brand-purple shadow-[0_0_15px_rgba(168,85,247,0.4)]' 
                                        : 'bg-black/20 text-gray-300 border-white/10 hover:bg-white/10 hover:border-white/30'
                                    }`}
                                >
                                    {name}
                                </button>
                            ))}
                        </div>
                    </section>
                )}

                {/* Custom Inputs (Only for Custom) */}
                {selectedDomain === 'custom' && (
                    <section>
                        <h3 className="text-xl font-semibold mb-6 flex items-center gap-3 text-gray-100">
                            <span className="w-1.5 h-6 bg-brand-purple rounded-full"></span>
                            Custom Role Details
                        </h3>

                        {/* Autofill from CV CTA */}
                        <div className="mb-6 p-4 bg-gradient-to-r from-brand-purple/10 to-brand-blue/10 border border-brand-purple/20 rounded-xl flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
                            <div>
                                <h4 className="font-bold text-white text-sm flex items-center gap-2">
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-brand-purple" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                                    Autofill from Resume
                                </h4>
                                <p className="text-xs text-gray-400 mt-1">Upload your CV (PDF) and we'll automatically extract your target Role, Industry, and Skills.</p>
                            </div>
                            <label className={`cursor-pointer bg-white/10 hover:bg-white/20 text-white px-4 py-2 rounded-lg text-xs font-bold transition-colors flex items-center gap-2 border border-white/10 ${isAnalyzingResume ? 'opacity-50 cursor-not-allowed' : ''}`}>
                                {isAnalyzingResume ? (
                                    <>
                                        <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                                        Analyzing...
                                    </>
                                ) : (
                                    'Select PDF File'
                                )}
                                <input type="file" accept=".pdf,.txt,.md" className="hidden" onChange={(e) => handleResumeUpload(e, true)} disabled={isAnalyzingResume} />
                            </label>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div>
                                <label className="block text-sm font-semibold text-gray-400 mb-2">Industry / Field</label>
                                <input 
                                    type="text" 
                                    placeholder="e.g. Architecture, Marine Biology"
                                    value={customDomainName}
                                    onChange={(e) => setCustomDomainName(e.target.value)}
                                    className="w-full bg-black/30 border border-white/10 rounded-lg p-4 text-white focus:ring-2 focus:ring-brand-blue outline-none placeholder-gray-600"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-semibold text-gray-400 mb-2">Job Title</label>
                                <input 
                                    type="text" 
                                    placeholder="e.g. Senior Architect"
                                    value={customRoleTitle}
                                    onChange={(e) => setCustomRoleTitle(e.target.value)}
                                    className="w-full bg-black/30 border border-white/10 rounded-lg p-4 text-white focus:ring-2 focus:ring-brand-blue outline-none placeholder-gray-600"
                                />
                            </div>
                        </div>

                        {/* Extracted Skills Selection */}
                        {extractedSkills.length > 0 && (
                            <div className="mt-6 animate-fade-in">
                                <label className="block text-sm font-semibold text-gray-400 mb-2">Select a Skill to Focus On (Optional)</label>
                                <div className="flex flex-wrap gap-2">
                                    {extractedSkills.map((skill, index) => (
                                        <button
                                            key={index}
                                            onClick={() => {
                                                if (customRoleTitle.includes(skill)) return;
                                                setCustomRoleTitle(`${customRoleTitle ? customRoleTitle + ' - ' : ''}${skill}`);
                                            }}
                                            className="px-3 py-1.5 bg-black/40 border border-white/10 rounded-full text-xs text-gray-300 hover:bg-brand-blue/20 hover:text-brand-blue hover:border-brand-blue/30 transition-all"
                                        >
                                            + {skill}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        )}
                    </section>
                )}

                <section>
                     <h3 className="text-xl font-semibold mb-6 flex items-center gap-3 text-gray-100">
                        <span className="w-1.5 h-6 bg-brand-green rounded-full"></span>
                        Experience Level
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        {(['junior', 'mid-level', 'senior'] as LevelKey[]).map((key) => {
                            let name = key.charAt(0).toUpperCase() + key.slice(1);
                            let desc = GENERIC_LEVEL_INSTRUCTIONS[key];

                            if (selectedDomain !== 'custom') {
                                 const level = domains[selectedDomain].levels[key];
                                 name = level.name;
                                 desc = level.description;
                            } else {
                                if (key === 'junior') { name = 'Junior / Entry'; desc = 'Focuses on fundamentals and core concepts.'; }
                                if (key === 'mid-level') { name = 'Mid-Level'; desc = 'Covers practical application and problem solving.'; }
                                if (key === 'senior') { name = 'Senior / Lead'; desc = 'Deep dive into strategy, complexity, and leadership.'; }
                            }

                            return (
                                <button
                                    key={key}
                                    onClick={() => setSelectedLevel(key)}
                                    className={`p-6 rounded-xl text-left border transition-all duration-300 h-full flex flex-col ${
                                        selectedLevel === key 
                                        ? 'bg-brand-green/10 border-brand-green shadow-[0_0_20px_rgba(52,168,83,0.2)]' 
                                        : 'bg-black/20 border-white/5 hover:bg-white/5 hover:border-white/20'
                                    }`}
                                >
                                    <div className="flex items-center justify-between mb-3">
                                         <span className={`text-xs font-bold uppercase tracking-wider px-2 py-1 rounded ${selectedLevel === key ? 'bg-brand-green text-white' : 'bg-gray-700 text-gray-400'}`}>
                                            {key}
                                         </span>
                                    </div>
                                    <h4 className="text-lg font-bold text-white mb-2">{name}</h4>
                                    <p className="text-sm text-gray-400 leading-relaxed flex-grow">{desc}</p>
                                </button>
                            );
                        })}
                    </div>
                </section>
            </div>
        )}

        {/* Step 3: Persona & Context */}
        {selectedDomain && selectedLevel && (!isSoftwareEngineering || selectedTechnology) && (
            <section className="mt-12 animate-fade-in">
                 <h3 className="text-xl font-semibold mb-6 flex items-center gap-3 text-gray-100">
                    <span className="w-1.5 h-6 bg-brand-yellow rounded-full"></span>
                    Interviewer Persona
                </h3>
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                    {(Object.keys(personas) as PersonaKey[]).map((key) => {
                    const persona = personas[key];
                    return (
                        <button
                        key={key}
                        onClick={() => setSelectedPersona(key)}
                        className={`p-6 rounded-xl text-left border transition-all duration-300 ${
                            selectedPersona === key 
                            ? 'bg-brand-yellow/10 border-brand-yellow shadow-[0_0_20px_rgba(251,188,5,0.2)]' 
                            : 'bg-black/20 border-white/5 hover:bg-white/5 hover:border-white/20'
                        }`}
                        >
                            <h4 className={`text-lg font-bold mb-2 ${selectedPersona === key ? 'text-brand-yellow' : 'text-gray-200'}`}>{persona.name}</h4>
                            <p className="text-sm text-gray-400 leading-relaxed">{persona.description}</p>
                        </button>
                    );
                    })}
                </div>

                {/* Personalize Section */}
                <div className="bg-black/20 rounded-xl p-6 border border-white/5">
                     <h4 className="text-lg font-bold text-white mb-4">Personalize Context</h4>

                     {/* Resume Upload */}
                     <div className="mb-6">
                         <label className="block text-sm font-semibold text-gray-300 mb-2">
                             {resumeFileName ? 'Resume Uploaded' : 'Upload Resume (PDF/Text)'}
                         </label>
                         <p className="text-xs text-gray-500 mb-3">We will extract your skills and experience to tailor the interview.</p>

                         {resumeFileName ? (
                             <div className="flex flex-col gap-3">
                                 <div className="flex items-center gap-3 bg-brand-blue/10 border border-brand-blue/30 rounded-lg p-3">
                                     <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-brand-blue" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                                     <span className="text-sm text-white font-medium flex-1 truncate">{resumeFileName}</span>
                                     <button onClick={() => { setResumeContext(''); setExtractedSkills([]); setResumeFileName(null); }} className="text-gray-400 hover:text-white">
                                         <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                                     </button>
                                 </div>
                                 {extractedSkills.length > 0 && (
                                     <div className="flex flex-wrap gap-2">
                                         {extractedSkills.map((skill, i) => (
                                             <span key={i} className="px-2 py-1 bg-white/5 border border-white/10 rounded text-xs text-gray-300">
                                                 {skill}
                                             </span>
                                         ))}
                                     </div>
                                 )}
                             </div>
                         ) : (
                             <label className={`flex items-center justify-center gap-2 w-full p-4 border-2 border-dashed border-gray-600 rounded-lg cursor-pointer hover:border-gray-400 hover:bg-white/5 transition-all ${isAnalyzingResume ? 'opacity-50 cursor-not-allowed' : ''}`}>
                                 <input type="file" accept=".pdf,.txt,.md" className="hidden" onChange={(e) => handleResumeUpload(e, false)} disabled={isAnalyzingResume} />
                                 {isAnalyzingResume ? (
                                     <>
                                        <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                                        <span className="text-sm text-gray-300">Extracting Skills...</span>
                                     </>
                                 ) : (
                                     <>
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                                        <span className="text-sm text-gray-300">Click to Upload Resume (PDF)</span>
                                     </>
                                 )}
                             </label>
                         )}
                     </div>

                     <label className="block text-sm font-semibold text-gray-300 mb-2">Custom Instructions (Optional)</label>
                     <textarea
                        value={customInstructions}
                        onChange={(e) => setCustomInstructions(e.target.value)}
                        className="w-full bg-black/30 border border-white/10 rounded-lg p-4 text-white focus:outline-none focus:ring-2 focus:ring-brand-blue focus:border-transparent transition-all placeholder-gray-600"
                        rows={2}
                        placeholder="E.g., 'Ask specific questions about system design scalability' or 'Be very critical about edge cases'."
                    />
                </div>
            </section>
        )}
      </div>

      {/* Footer Controls */}
      <div className="p-6 bg-black/20 border-t border-white/5 flex flex-col md:flex-row items-center justify-between gap-4">
        <label className="flex items-center cursor-pointer group">
            <div className="relative">
                <input type="checkbox" className="sr-only" checked={isPracticeMode} onChange={() => setIsPracticeMode(!isPracticeMode)} />
                <div className={`w-12 h-7 rounded-full transition-colors duration-300 ${isPracticeMode ? 'bg-brand-green' : 'bg-gray-700'}`}></div>
                <div className={`absolute left-1 top-1 w-5 h-5 bg-white rounded-full transition-transform duration-300 ${isPracticeMode ? 'translate-x-5' : ''}`}></div>
            </div>
            <div className="ml-3">
                <span className="block text-sm font-semibold text-white group-hover:text-brand-green transition-colors">Practice Mode</span>
                <span className="block text-xs text-gray-500">No scoring, just chat.</span>
            </div>
        </label>

        <button
            onClick={handleStartClick}
            disabled={isStartDisabled}
            className="w-full md:w-auto bg-gradient-to-r from-brand-blue to-blue-600 hover:from-blue-500 hover:to-blue-700 text-white font-bold py-3 px-10 rounded-xl transition-all shadow-lg hover:shadow-brand-blue/30 disabled:opacity-50 disabled:cursor-not-allowed disabled:shadow-none transform hover:-translate-y-0.5"
        >
            Start Interview
        </button>
      </div>
    </div>
  );
};

export default InterviewSetup;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI, Type } from '@google/genai';
import { supabase } from '../services/supabaseClient';
import type { SavedCV, SubscriptionTier } from '../types';

interface CVBuilderProps {
  onBack: () => void;
  initialData?: any;
  cvId?: string;
  subscriptionTier?: SubscriptionTier;
  isAdmin?: boolean;
}

interface CustomSection {
    id: string;
    title: string;
    content: string;
}

interface AtsResult {
    score: number;
    missingKeywords: string[];
    suggestions: string[];
    summary: string;
}

type TemplateType = 'modern' | 'classic' | 'creative' | 'minimalist';

const TEMPLATES: Record<TemplateType, { name: string; desc: string; promptInstruction: string }> = {
    modern: {
        name: "Modern Tech",
        desc: "Clean, sans-serif, optimized for readability.",
        promptInstruction: "STYLE: Modern. Font: Helvetica/Inter. Header: Left-aligned with subtle bottom border. Accent Color: #3B82F6 (Blue). Layout: Single column or hybrid. Use light gray backgrounds for section headers."
    },
    classic: {
        name: "Classic Professional",
        desc: "Traditional serif, perfect for Finance/Law.",
        promptInstruction: "STYLE: Classic. Font: Georgia/Times New Roman. Header: Centered. No accent colors (Black/White only). Layout: Single column. Use horizontal lines (hr) to separate sections. Formal tone."
    },
    creative: {
        name: "Creative Studio",
        desc: "Bold layout with sidebar, good for Design/Marketing.",
        promptInstruction: "STYLE: Creative. Font: Lato/Poppins. Layout: TWO COLUMNS (Sidebar for contact/skills, Main for exp). Sidebar Background: #f3f4f6 (Light Gray) or #e0e7ff (Light Indigo). Accent Color: #8B5CF6 (Purple). Headers should be bold and uppercase."
    },
    minimalist: {
        name: "Minimalist",
        desc: "High whitespace, simple, sophisticated.",
        promptInstruction: "STYLE: Minimalist. Font: Arial or Courier New. Layout: Single column. Very high whitespace. No borders, no background colors. Use uppercase spacing for headers. Color: Dark Gray text."
    }
};

const CVBuilder: React.FC<CVBuilderProps> = ({ onBack, initialData, cvId, subscriptionTier = 'free', isAdmin = false }) => {
  // --- Core Data State ---
  const [personalInfo, setPersonalInfo] = useState({
    fullName: '',
    email: '',
    phone: '',
    linkedin: '',
    location: '',
    photo: null as string | null
  });
  const [targetRole, setTargetRole] = useState('');
  const [experience, setExperience] = useState('');
  const [education, setEducation] = useState('');
  const [skills, setSkills] = useState('');
  const [customSections, setCustomSections] = useState<CustomSection[]>([]);

  // --- UI/Generation State ---
  const [generatedCV, setGeneratedCV] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [zoom, setZoom] = useState(0.65); 
  const previewRef = useRef<HTMLDivElement>(null);
  const [currentCvId, setCurrentCvId] = useState<string | undefined>(cvId);
  const [selectedTemplate, setSelectedTemplate] = useState<TemplateType>('modern');

  // --- Import State ---
  const [isImporting, setIsImporting] = useState(false);
  const [importText, setImportText] = useState('');
  const [importFileBase64, setImportFileBase64] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // --- ATS Analyzer State ---
  const [showAtsModal, setShowAtsModal] = useState(false);
  const [jobDescription, setJobDescription] = useState('');
  const [atsResult, setAtsResult] = useState<AtsResult | null>(null);
  const [isScanningAts, setIsScanningAts] = useState(false);

  useEffect(() => {
    if (initialData) {
        setPersonalInfo(initialData.personalInfo || {
            fullName: '', email: '', phone: '', linkedin: '', location: '', photo: null
        });
        setTargetRole(initialData.targetRole || '');
        setExperience(initialData.experience || '');
        setEducation(initialData.education || '');
        setSkills(initialData.skills || '');
        setCustomSections(initialData.customSections || []);
    }
  }, [initialData]);

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPersonalInfo(prev => ({ ...prev, photo: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddSection = () => {
      const newSection: CustomSection = {
          id: Date.now().toString(),
          title: '',
          content: ''
      };
      setCustomSections([...customSections, newSection]);
  };

  const handleRemoveSection = (id: string) => {
      setCustomSections(customSections.filter(s => s.id !== id));
  };

  const handleUpdateSection = (id: string, field: 'title' | 'content', value: string) => {
      setCustomSections(customSections.map(s => s.id === id ? { ...s, [field]: value } : s));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();

        if (file.type === "application/pdf") {
            reader.onload = (event) => {
                const base64String = event.target?.result as string;
                // Strip the Data URL prefix to get raw base64
                const rawBase64 = base64String.split(',')[1];
                setImportFileBase64(rawBase64);
                setImportText(''); // Clear text if PDF is loaded
            };
            reader.readAsDataURL(file);
        } else {
            // Assume text/markdown/json
            reader.onload = (event) => {
                const text = event.target?.result as string;
                setImportText(text);
                setImportFileBase64(null); // Clear PDF if text is loaded
            };
            reader.readAsText(file);
        }
  };

  const handleAnalyzeResume = async () => {
      if (!importText.trim() && !importFileBase64) return;
      if (!process.env.API_KEY) {
          alert("API Key missing");
          return;
      }
      setIsAnalyzing(true);

      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

          let contentPart: any;
          if (importFileBase64) {
              contentPart = { inlineData: { mimeType: 'application/pdf', data: importFileBase64 } };
          } else {
              contentPart = { text: importText };
          }

          const prompt = `
            Act as an expert Resume Writer and Parser. 
            Analyze the resume provided. Your task is to:
            1. Parse the information into structured fields.
            2. IMPROVE the content: Use stronger action verbs, clarify achievements, and fix grammar (e.g. change "Worked on API" to "Designed and implemented scalable RESTful APIs").
            3. Return a JSON object matching the exact structure below.

            REQUIRED JSON STRUCTURE:
            {
              "personalInfo": {
                "fullName": "string",
                "email": "string",
                "phone": "string",
                "linkedin": "string",
                "location": "string"
              },
              "targetRole": "string (infer from content if not explicit)",
              "experience": "string (formatted as bullet points)",
              "education": "string (formatted as text/bullets)",
              "skills": "string (comma separated list, extract all relevant skills)",
              "customSections": [
                { "title": "string", "content": "string" }
              ]
            }
          `;

          const response = await ai.models.generateContent({
              model: 'gemini-2.5-flash',
              contents: [contentPart, { text: prompt }],
              config: { responseMimeType: 'application/json' }
          });

          const data = JSON.parse(response.text || '{}');

          if (data.personalInfo) setPersonalInfo(prev => ({ ...prev, ...data.personalInfo }));
          if (data.targetRole) setTargetRole(data.targetRole);
          if (data.experience) setExperience(data.experience);
          if (data.education) setEducation(data.education);
          if (data.skills) setSkills(data.skills);
          if (data.customSections && Array.isArray(data.customSections)) {
              const mappedSections = data.customSections.map((s: any) => ({
                  id: Date.now().toString() + Math.random(),
                  title: s.title,
                  content: s.content
              }));
              setCustomSections(mappedSections);
          }

          setIsImporting(false);
          setImportText('');
          setImportFileBase64(null);

      } catch (error) {
          console.error("Parsing failed", error);
          alert("Failed to analyze resume. Please ensure the file is readable.");
      } finally {
          setIsAnalyzing(false);
      }
  };

  const handleGenerate = async () => {
    if (!process.env.API_KEY) {
        alert("API Key missing");
        return;
    }
    setIsGenerating(true);
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const photoInstruction = personalInfo.photo 
            ? "The user has provided a profile photo. Include an <img src='{{PHOTO_SRC}}' alt='Profile Photo' class='profile-photo' /> in the header or sidebar. Style it to be circular or rounded-square, max width 100px, with appropriate margins."
            : "Do not include a photo.";

        const customSectionsPrompt = customSections.map(s => `
            SECTION TITLE: ${s.title}
            CONTENT:
            ${s.content}
        `).join('\n\n');

        const styleInstruction = TEMPLATES[selectedTemplate].promptInstruction;

        const prompt = `
          You are an expert Resume Writer and Designer. Create a professional, ATS-optimized resume for the following candidate.

          VISUAL STYLE INSTRUCTIONS:
          ${styleInstruction}

          STRICT REQUIREMENT: The resume MUST fit on a single A4 page.
          - Prioritize a compact, high-density layout.
          - Use a 10pt or 11pt font size for body text.
          - Reduce margins and padding where appropriate (e.g. 15-20px margins).
          - Be concise with bullet points. 

          CANDIDATE PROFILE:
          Name: ${personalInfo.fullName}
          Contact: ${personalInfo.email} | ${personalInfo.phone} | ${personalInfo.location}
          Links: ${personalInfo.linkedin}
          Target Role: ${targetRole}

          ${photoInstruction}

          EXPERIENCE NOTES:
          ${experience}

          EDUCATION NOTES:
          ${education}

          SKILLS LIST:
          ${skills}

          ADDITIONAL SECTIONS (Format these to fit naturally into the design):
          ${customSectionsPrompt}

          INSTRUCTIONS:
          1. Return ONLY the HTML code for the resume. 
          2. Use modern, clean, professional inline CSS styles. 
          3. The container div should have a white background, black text (#000000), and simulate an A4 page (width: 100%; height: 100%; box-sizing: border-box;).
          4. Ensure text is crisp and high contrast.
          5. Structure: 
             - Header (Name, Contact, Photo if applicable).
             - Professional Summary (Keep it short, max 3 lines).
             - Skills (Consider a sidebar or multi-column grid to save vertical space).
             - Experience (Rewrite notes into strong, concise STAR-method bullet points).
             - Education.
             - Custom Sections (Insert where appropriate).
          6. Do not include markdown code blocks (like \`\`\`html). Just return the raw HTML string.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
        });

        let cleanHtml = response.text || '';
        // Cleanup potential markdown formatting
        cleanHtml = cleanHtml.replace(/^```html\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '');

        // Inject photo if available
        if (personalInfo.photo) {
            cleanHtml = cleanHtml.replace('{{PHOTO_SRC}}', personalInfo.photo);
        }

        setGeneratedCV(cleanHtml);
    } catch (error) {
        console.error(error);
        alert("Failed to generate CV. Please try again.");
    } finally {
        setIsGenerating(false);
    }
  };

  const handleScanAts = async () => {
      if (!jobDescription.trim()) return;
      if (!process.env.API_KEY) return;

      setIsScanningAts(true);
      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

          // Construct Resume Context
          const resumeContext = `
            Name: ${personalInfo.fullName}
            Role: ${targetRole}
            Experience: ${experience}
            Education: ${education}
            Skills: ${skills}
            Custom Sections: ${JSON.stringify(customSections)}
          `;

          const prompt = `
            You are an expert Applicant Tracking System (ATS) simulator and Recruiter.
            Compare the following Resume Content against the Job Description.

            RESUME CONTENT:
            ${resumeContext}

            JOB DESCRIPTION:
            ${jobDescription}

            Analyze the match. Return a JSON object with:
            {
                "score": integer (0-100),
                "summary": "1 sentence overview of the match quality.",
                "missingKeywords": ["keyword1", "keyword2"],
                "suggestions": ["specific advice to improve match", "rewrite this bullet point...", "add this skill..."]
            }
          `;

          const response = await ai.models.generateContent({
              model: 'gemini-2.5-flash',
              contents: prompt,
              config: { responseMimeType: 'application/json' }
          });

          setAtsResult(JSON.parse(response.text || '{}'));

      } catch (e: any) {
          console.error("ATS Scan failed", e);
          alert("Scan failed: " + e.message);
      } finally {
          setIsScanningAts(false);
      }
  };

  const handleSave = async () => {
      if (!generatedCV) return;
      if (!supabase) {
          alert("Database connection not available.");
          return;
      }

      setIsSaving(true);
      try {
          const { data: { user } } = await supabase.auth.getUser();
          if (!user) {
              alert("You must be logged in to save.");
              return;
          }

          // Check Limits for Free Tier (Only 1 Resume Allowed) - Admins bypass
          if (!currentCvId && subscriptionTier === 'free' && !isAdmin) {
              const { count } = await supabase.from('cvs').select('*', { count: 'exact', head: true }).eq('user_id', user.id);
              if (count && count >= 1) {
                  alert("Free Plan Limit: You can only save 1 Resume. Please upgrade to Pro for unlimited saves.");
                  setIsSaving(false);
                  return;
              }
          }

          const payload = {
              title: `${targetRole || 'Resume'} - ${new Date().toLocaleDateString()}`,
              content: generatedCV,
              data: { personalInfo, targetRole, experience, education, skills, customSections }
          };

          if (currentCvId) {
              const { error } = await supabase.from('cvs').update(payload).eq('id', currentCvId);
              if (error) throw error;
              alert("Resume updated successfully!");
          } else {
              const { data, error } = await supabase.from('cvs').insert({ ...payload, user_id: user.id }).select();
              if (error) throw error;
              if (data && data[0]) {
                  setCurrentCvId(data[0].id);
              }
              alert("Resume saved successfully to your profile!");
          }

      } catch (err: any) {
          console.error("Error saving CV:", err);
          if (err.code === 'PGRST205' || err.message?.includes('does not exist') || err.code === '42P01') {
              alert("Configuration Error: The 'cvs' table does not exist in your database.\n\nPlease go to the README.md file, copy the SQL script under 'Database Setup', and run it in your Supabase SQL Editor.");
          } else {
              alert("Failed to save resume: " + err.message);
          }
      } finally {
          setIsSaving(false);
      }
  };

  const handlePrint = () => {
    if (!previewRef.current) return;
    const printWindow = window.open('', '', 'width=800,height=900');
    if (printWindow) {
      printWindow.document.write(`
        <html>
          <head>
            <title>Resume - ${personalInfo.fullName || 'Candidate'}</title>
            <style>
              body { margin: 0; padding: 0; background: white; -webkit-print-color-adjust: exact; font-family: sans-serif; }
              @page { size: A4; margin: 0; }
              @media print {
                body { -webkit-print-color-adjust: exact; }
              }
            </style>
          </head>
          <body>
            ${generatedCV}
          </body>
        </html>
      `);
      printWindow.document.close();
      printWindow.focus();
      printWindow.print();
    }
  };

  return (
    <div className="w-full max-w-[1600px] h-[90vh] flex flex-col glass-panel rounded-2xl overflow-hidden animate-fade-in shadow-2xl relative">

        {/* ATS Modal */}
        {showAtsModal && (
            <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
                <div className="bg-[#1a1a1a] w-full max-w-4xl rounded-2xl border border-white/10 flex flex-col max-h-[85vh] shadow-2xl overflow-hidden">
                    <div className="p-6 border-b border-white/10 flex justify-between items-center bg-black/40">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-lg bg-brand-blue/20 flex items-center justify-center text-brand-blue">
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                            </div>
                            <h3 className="text-xl font-bold text-white">ATS Compatibility Checker</h3>
                        </div>
                        <button onClick={() => { setShowAtsModal(false); setAtsResult(null); }} className="text-gray-400 hover:text-white transition-colors">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                    </div>

                    <div className="flex-1 overflow-hidden flex flex-col md:flex-row">
                        {/* Input Side */}
                        <div className="w-full md:w-1/2 p-6 flex flex-col border-r border-white/10">
                            <p className="text-gray-400 text-sm mb-4">Paste the job description below. We'll check your current resume data for keywords and relevance.</p>
                            <textarea 
                                value={jobDescription}
                                onChange={(e) => setJobDescription(e.target.value)}
                                className="flex-1 bg-black/30 border border-white/10 rounded-xl p-4 text-white focus:border-brand-blue outline-none resize-none custom-scrollbar mb-4 text-sm"
                                placeholder="Paste Job Description here..."
                            />
                            <button 
                                onClick={handleScanAts}
                                disabled={isScanningAts || !jobDescription}
                                className="w-full py-3 bg-brand-blue hover:bg-blue-600 text-white font-bold rounded-xl transition-all shadow-lg flex items-center justify-center gap-2 disabled:opacity-50"
                            >
                                {isScanningAts ? (
                                    <><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> Scanning...</>
                                ) : (
                                    <>Scan & Analyze</>
                                )}
                            </button>
                        </div>

                        {/* Result Side */}
                        <div className="w-full md:w-1/2 p-6 bg-black/20 overflow-y-auto custom-scrollbar">
                            {atsResult ? (
                                <div className="space-y-6">
                                    <div className="flex items-center gap-6">
                                        <div className="relative w-24 h-24 flex items-center justify-center">
                                            <svg className="w-full h-full transform -rotate-90">
                                                <circle cx="48" cy="48" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-gray-800" />
                                                <circle cx="48" cy="48" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" 
                                                    className={atsResult.score > 75 ? 'text-brand-green' : atsResult.score > 50 ? 'text-brand-yellow' : 'text-brand-red'}
                                                    strokeDasharray={2 * Math.PI * 40}
                                                    strokeDashoffset={2 * Math.PI * 40 * (1 - atsResult.score / 100)}
                                                />
                                            </svg>
                                            <div className="absolute flex flex-col items-center">
                                                <span className="text-2xl font-bold text-white">{atsResult.score}%</span>
                                                <span className="text-[10px] uppercase text-gray-500 font-bold">Match</span>
                                            </div>
                                        </div>
                                        <div className="flex-1">
                                            <h4 className="text-white font-bold mb-1">Analysis Summary</h4>
                                            <p className="text-sm text-gray-400 leading-relaxed">{atsResult.summary}</p>
                                        </div>
                                    </div>

                                    {atsResult.missingKeywords.length > 0 && (
                                        <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-4">
                                            <h5 className="text-red-400 font-bold text-xs uppercase tracking-wider mb-3">Missing Keywords</h5>
                                            <div className="flex flex-wrap gap-2">
                                                {atsResult.missingKeywords.map((kw, i) => (
                                                    <span key={i} className="px-2 py-1 bg-red-500/20 text-red-300 rounded text-xs border border-red-500/20">{kw}</span>
                                                ))}
                                            </div>
                                        </div>
                                    )}

                                    <div>
                                        <h5 className="text-brand-blue font-bold text-xs uppercase tracking-wider mb-3">Improvement Plan</h5>
                                        <ul className="space-y-3">
                                            {atsResult.suggestions.map((sugg, i) => (
                                                <li key={i} className="flex gap-3 text-sm text-gray-300 bg-white/5 p-3 rounded-lg border border-white/5">
                                                    <span className="text-brand-blue font-bold mt-0.5">→</span>
                                                    {sugg}
                                                </li>
                                            ))}
                                        </ul>
                                    </div>
                                </div>
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center text-gray-500 opacity-60">
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
                                    <p>Results will appear here after scanning</p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* Import Modal */}
        {isImporting && (
            <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
                <div className="bg-[#1a1a1a] w-full max-w-2xl rounded-2xl border border-white/10 p-6 shadow-2xl flex flex-col max-h-[80vh]">
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="text-xl font-bold text-white">Import & Improve Existing CV</h3>
                        <button onClick={() => setIsImporting(false)} className="text-gray-400 hover:text-white">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                    </div>
                    <p className="text-gray-400 text-sm mb-4">Upload a PDF or paste the text content of your current resume below. Our AI will analyze, format, and improve the descriptions for you.</p>

                    <div className="flex justify-between items-center mb-2">
                        <label className="text-sm font-semibold text-gray-300">Resume Content</label>
                        <label className="text-xs text-brand-purple hover:text-purple-400 cursor-pointer flex items-center gap-1">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                            Upload File (PDF/TXT)
                            <input type="file" accept=".pdf,.txt,.md,.json" className="hidden" onChange={handleFileUpload} />
                        </label>
                    </div>

                    {importFileBase64 ? (
                        <div className="flex-1 bg-black/30 border border-white/10 rounded-lg p-4 flex items-center justify-center mb-4">
                            <div className="text-center">
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 text-red-500 mx-auto mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                                <p className="text-white font-medium">PDF File Selected</p>
                                <button onClick={() => setImportFileBase64(null)} className="text-sm text-gray-400 hover:text-white underline mt-2">Remove and Paste Text</button>
                            </div>
                        </div>
                    ) : (
                        <textarea 
                            className="flex-1 bg-black/30 border border-white/10 rounded-lg p-4 text-gray-300 focus:border-brand-purple outline-none resize-none mb-4 custom-scrollbar"
                            placeholder="Paste your resume text here..."
                            value={importText}
                            onChange={(e) => setImportText(e.target.value)}
                        />
                    )}

                    <div className="flex justify-end gap-3">
                        <button onClick={() => setIsImporting(false)} className="px-4 py-2 text-gray-400 hover:text-white">Cancel</button>
                        <button 
                            onClick={handleAnalyzeResume}
                            disabled={isAnalyzing || (!importText.trim() && !importFileBase64)}
                            className="px-6 py-2 bg-brand-purple hover:bg-purple-600 text-white rounded-lg font-bold transition-colors disabled:opacity-50"
                        >
                            {isAnalyzing ? 'Analyzing...' : 'Analyze & Import'}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {/* Header */}
        <div className="h-16 border-b border-white/10 bg-black/20 flex items-center justify-between px-6 shrink-0 backdrop-blur-md">
            <div className="flex items-center gap-4">
                <button onClick={onBack} className="p-2 rounded-lg hover:bg-white/10 transition-colors text-gray-400 hover:text-white">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" /></svg>
                </button>
                <div className="flex flex-col">
                    <h2 className="text-lg font-bold text-white tracking-tight leading-none">{currentCvId ? 'Edit Resume' : 'AI Resume Builder'}</h2>
                    <span className="text-[10px] text-gray-400 uppercase tracking-widest">{TEMPLATES[selectedTemplate].name} Mode</span>
                </div>
            </div>

            <div className="flex items-center gap-3">
                 {/* Template Selector */}
                 <div className="relative group">
                     <select 
                        value={selectedTemplate}
                        onChange={(e) => setSelectedTemplate(e.target.value as TemplateType)}
                        className="appearance-none bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg pl-3 pr-8 py-2 text-sm font-medium text-white transition-colors cursor-pointer outline-none focus:border-brand-purple"
                     >
                         <option value="modern">Modern Tech</option>
                         <option value="classic">Classic Pro</option>
                         <option value="creative">Creative</option>
                         <option value="minimalist">Minimalist</option>
                     </select>
                     <div className="absolute right-3 top-1/2 transform -translate-y-1/2 pointer-events-none">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                     </div>
                 </div>

                 <button 
                    onClick={() => setShowAtsModal(true)}
                    className="flex items-center gap-2 px-4 py-2 bg-brand-blue/10 hover:bg-brand-blue/20 border border-brand-blue/30 rounded-lg text-sm font-medium transition-colors text-brand-blue"
                 >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    ATS Check
                 </button>

                 <button 
                    onClick={() => setIsImporting(true)}
                    className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg text-sm font-medium transition-colors text-gray-300"
                 >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                    Import
                 </button>

                 {generatedCV && (
                    <>
                        <button 
                            onClick={handleSave}
                            disabled={isSaving}
                            className="flex items-center gap-2 px-4 py-2 bg-brand-green/20 hover:bg-brand-green/30 border border-brand-green/50 rounded-lg text-sm font-medium transition-colors text-brand-green"
                        >
                            {isSaving ? 'Saving...' : (currentCvId ? 'Update' : 'Save')}
                        </button>
                        <button 
                            onClick={handlePrint}
                            className="flex items-center gap-2 px-4 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-sm font-medium transition-colors text-white"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                            Print
                        </button>
                    </>
                 )}
                 <button 
                    onClick={handleGenerate}
                    disabled={isGenerating || !personalInfo.fullName}
                    className="flex items-center gap-2 px-6 py-2 bg-gradient-to-r from-brand-purple to-purple-600 hover:from-purple-500 hover:to-purple-700 rounded-lg text-sm font-bold text-white shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                 >
                    {isGenerating ? (
                        <>
                         <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                         Generating...
                        </>
                    ) : (
                        <>
                         <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                         Generate
                        </>
                    )}
                 </button>
            </div>
        </div>

        {/* Main Content */}
        <div className="flex-1 flex flex-col lg:flex-row overflow-hidden bg-black/40">

            {/* Input Panel (Left) */}
            <div className="lg:w-[400px] xl:w-[450px] flex flex-col border-r border-white/5 bg-black/20 overflow-y-auto custom-scrollbar p-6 space-y-8">

                {/* Personal Info Section */}
                <div className="space-y-4">
                    <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-brand-blue"></span>
                        Personal Details
                    </h3>
                    <div className="flex items-center gap-4 mb-2">
                        <div className="w-16 h-16 rounded-full bg-white/5 border border-white/10 flex items-center justify-center overflow-hidden shrink-0">
                            {personalInfo.photo ? (
                                <img src={personalInfo.photo} alt="Preview" className="w-full h-full object-cover" />
                            ) : (
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                            )}
                        </div>
                        <div>
                             <label className="block text-xs text-gray-400 mb-1 cursor-pointer hover:text-white transition-colors">
                                 Upload Photo
                                 <input type="file" accept="image/*" className="hidden" onChange={handlePhotoUpload} />
                             </label>
                             <p className="text-[10px] text-gray-600">Recommended: Square JPG/PNG</p>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 gap-4">
                        <input 
                            type="text" 
                            placeholder="Full Name" 
                            value={personalInfo.fullName}
                            onChange={(e) => setPersonalInfo({...personalInfo, fullName: e.target.value})}
                            className="bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple focus:border-brand-purple outline-none transition-all"
                        />
                         <div className="grid grid-cols-2 gap-3">
                            <input 
                                type="text" 
                                placeholder="Email" 
                                value={personalInfo.email}
                                onChange={(e) => setPersonalInfo({...personalInfo, email: e.target.value})}
                                className="bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none"
                            />
                            <input 
                                type="text" 
                                placeholder="Phone" 
                                value={personalInfo.phone}
                                onChange={(e) => setPersonalInfo({...personalInfo, phone: e.target.value})}
                                className="bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none"
                            />
                        </div>
                        <input 
                            type="text" 
                            placeholder="Location (City, Country)" 
                            value={personalInfo.location}
                            onChange={(e) => setPersonalInfo({...personalInfo, location: e.target.value})}
                            className="bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none"
                        />
                        <input 
                            type="text" 
                            placeholder="LinkedIn / Portfolio URL" 
                            value={personalInfo.linkedin}
                            onChange={(e) => setPersonalInfo({...personalInfo, linkedin: e.target.value})}
                            className="bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none"
                        />
                    </div>
                </div>

                {/* Target Role */}
                <div className="space-y-4">
                     <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-brand-purple"></span>
                        Target Role
                    </h3>
                    <input 
                        type="text" 
                        placeholder="e.g. Senior Frontend Engineer" 
                        value={targetRole}
                        onChange={(e) => setTargetRole(e.target.value)}
                        className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none"
                    />
                </div>

                {/* Experience */}
                <div className="space-y-4">
                     <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-brand-green"></span>
                        Professional Experience
                    </h3>
                    <textarea 
                        placeholder="Paste your work history here. Don't worry about formatting.&#10;&#10;e.g.&#10;Google - Software Engineer (2020-Present)&#10;- Built a scalable API&#10;- Led a team of 5" 
                        value={experience}
                        onChange={(e) => setExperience(e.target.value)}
                        className="w-full h-40 bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none resize-none custom-scrollbar leading-relaxed"
                    />
                </div>

                 {/* Education */}
                 <div className="space-y-4">
                     <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-brand-yellow"></span>
                        Education
                    </h3>
                    <textarea 
                        placeholder="e.g.&#10;Stanford University&#10;BS Computer Science, 2018" 
                        value={education}
                        onChange={(e) => setEducation(e.target.value)}
                        className="w-full h-24 bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none resize-none custom-scrollbar"
                    />
                </div>

                {/* Skills */}
                <div className="space-y-4">
                     <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-brand-red"></span>
                        Skills
                    </h3>
                    <textarea 
                        placeholder="e.g. JavaScript, React, Node.js, Project Management, Agile" 
                        value={skills}
                        onChange={(e) => setSkills(e.target.value)}
                        className="w-full h-24 bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-gray-500 focus:ring-1 focus:ring-brand-purple outline-none resize-none custom-scrollbar"
                    />
                </div>

                {/* Custom Sections */}
                <div className="space-y-4 border-t border-white/5 pt-4">
                    <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                        <span className="w-2 h-2 rounded-full bg-white"></span>
                        Additional Sections
                    </h3>

                    {customSections.map((section) => (
                        <div key={section.id} className="bg-black/20 rounded-lg p-3 border border-white/5 space-y-3 relative group">
                            <input 
                                type="text" 
                                value={section.title}
                                onChange={(e) => handleUpdateSection(section.id, 'title', e.target.value)}
                                placeholder="Section Title (e.g. Projects, Languages)"
                                className="w-full bg-transparent border-b border-white/10 px-2 py-1 text-sm font-bold text-white placeholder-gray-600 focus:border-brand-purple outline-none"
                            />
                            <textarea 
                                value={section.content}
                                onChange={(e) => handleUpdateSection(section.id, 'content', e.target.value)}
                                placeholder="Details for this section..."
                                className="w-full h-20 bg-transparent px-2 py-1 text-sm text-gray-300 placeholder-gray-600 outline-none resize-none"
                            />
                            <button 
                                onClick={() => handleRemoveSection(section.id)}
                                className="absolute top-2 right-2 text-gray-600 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                title="Remove Section"
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                            </button>
                        </div>
                    ))}

                    <button 
                        onClick={handleAddSection}
                        className="w-full py-2 border border-dashed border-gray-600 rounded-lg text-gray-400 text-sm hover:text-white hover:border-gray-400 transition-colors flex items-center justify-center gap-2"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                        Add Custom Section
                    </button>
                </div>
            </div>

            {/* Preview Panel (Right) */}
            <div className="flex-1 bg-[#1a1a1a] p-8 overflow-y-auto flex justify-center items-start custom-scrollbar relative">

                {/* Zoom Controls */}
                {generatedCV && (
                    <div className="absolute top-6 right-6 z-10 flex items-center gap-2 bg-black/60 backdrop-blur-md p-1.5 rounded-lg border border-white/10 shadow-lg">
                        <button onClick={() => setZoom(z => Math.max(0.3, z - 0.1))} className="p-1.5 hover:bg-white/10 rounded text-white transition-colors" title="Zoom Out">
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" /></svg>
                        </button>
                        <span className="text-xs font-mono text-gray-300 w-12 text-center select-none">{Math.round(zoom * 100)}%</span>
                        <button onClick={() => setZoom(z => Math.min(2, z + 0.1))} className="p-1.5 hover:bg-white/10 rounded text-white transition-colors" title="Zoom In">
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                        </button>
                    </div>
                )}

                {generatedCV ? (
                     <div 
                        style={{ transform: `scale(${zoom})`, transformOrigin: 'top center' }}
                        className="transition-transform duration-200 ease-out origin-top"
                    >
                         <div 
                            ref={previewRef}
                            className="w-[210mm] min-h-[297mm] bg-white text-black shadow-2xl p-[15mm] box-border resume-preview"
                            dangerouslySetInnerHTML={{ __html: generatedCV }}
                        />
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center h-full text-gray-500 opacity-60">
                        <div className="w-24 h-32 border-2 border-dashed border-gray-600 rounded-lg flex items-center justify-center mb-4">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                            </svg>
                        </div>
                        <p className="text-lg font-medium">Your resume preview will appear here</p>
                        <p className="text-sm">Select a template, fill details, and click Generate</p>
                    </div>
                )}
            </div>
        </div>
    </div>
  );
};

export default CVBuilder;

